class SchedulePrincipalAuthorityStoreError(ValueError):
    """A write lost the race with principal schedule-authority revocation."""


class WorkerClosedStoreError(ValueError):
    """A run reservation lost the race with permanent workspace closure."""


class AllowedAiPolicyRevisionConflict(ValueError):
    """An Allowed AI policy update lost the independent revision race."""

    def __init__(self, current_revision: int) -> None:
        super().__init__("Allowed AI policy changed; reload before saving")
        self.current_revision = int(current_revision)


class AllowedAiStartFenceConflict(ValueError):
    """A native start lost the cross-process Allowed AI policy fence."""

    def __init__(self, message: str = "Allowed AI policy changed before native start") -> None:
        super().__init__(message)


def _canonical_origin_scope(
    value: dict[str, Any] | None,
    *,
    tenant_id: str,
    owner_id: str,
) -> tuple[dict[str, Any], str]:
    """Validate the owner-bound origin scope copied into durable child lineage."""

    if value in (None, {}):
        return {}, "{}"
    if not isinstance(value, dict):
        raise ValueError("Origin scope must be a structured object")
    allowed = {
        "version", "tenant_id", "owner_id", "project_id", "workspace_id",
        "connection_id", "execution_mode",
        "ref", "source_event_id", "source_revision", "surface",
    }
    if set(value) - allowed:
        raise ValueError("Origin scope contains unsupported fields")
    version = value.get("version", 1)
    if isinstance(version, bool) or int(version) != 1:
        raise ValueError("Origin scope version is invalid")
    origin_tenant = str(value.get("tenant_id") or tenant_id).strip()
    origin_owner = str(value.get("owner_id") or owner_id).strip()
    project_id = str(value.get("project_id") or "").strip()
    workspace_id = str(value.get("workspace_id") or "").strip()
    if not project_id:
        raise ValueError("Origin scope project is required")
    if not origin_tenant or not origin_owner:
        raise ValueError("Origin scope owner is required")
    if origin_tenant != str(tenant_id or "local") or origin_owner != str(owner_id or ""):
        raise ValueError("Origin scope owner mismatch")
    clean: dict[str, Any] = {
        "version": 1,
        "tenant_id": origin_tenant,
        "owner_id": origin_owner,
        "project_id": project_id,
        "workspace_id": workspace_id,
        "connection_id": str(value.get("connection_id") or "").strip(),
        "execution_mode": str(value.get("execution_mode") or "host").strip(),
        "ref": str(value.get("ref") or "").strip(),
        "source_event_id": str(value.get("source_event_id") or "").strip(),
        "source_revision": value.get("source_revision", 0),
        "surface": str(value.get("surface") or "internal").strip(),
    }
    revision = clean["source_revision"]
    if isinstance(revision, bool) or not isinstance(revision, int) or revision < 0:
        raise ValueError("Origin scope source revision is invalid")
    if clean["execution_mode"] not in {"host", "docker"}:
        raise ValueError("Origin scope execution mode is invalid")
    for key in (
        "project_id", "workspace_id", "connection_id", "execution_mode",
        "ref", "source_event_id", "surface",
    ):
        item = clean[key]
        if len(item) > 512 or any(ord(char) < 32 or ord(char) == 127 for char in item):
            raise ValueError("Origin scope value is invalid")
    encoded = json.dumps(clean, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    if len(encoded.encode("utf-8")) > 16 * 1024:
        raise ValueError("Origin scope is too large")
    return clean, encoded


