def work_artifact_observation(
    worker: dict | None,
    run: dict | None,
    *,
    output_text: str,
    error_text: str,
) -> dict[str, object]:
    """Project one public-safe artifact observation at terminal commit time."""

    if not worker or not run:
        return {"available": False, "refs": [], "overflowCount": 0}
    projected_run = {
        **run,
        "output_text": str(output_text or ""),
        "error_text": str(error_text or ""),
    }
    deliverable = deliverable_payload(
        worker,
        projected_run,
        str(output_text or ""),
        str(output_text or ""),
        str(error_text or ""),
    )
    if not isinstance(deliverable, dict):
        return {"available": False, "refs": [], "overflowCount": 0}
    kind = str(deliverable.get("kind") or "file").strip().lower()
    state = str(deliverable.get("state") or "available").strip().lower()
    if kind not in {
        "artifact", "archive", "audio", "code", "document", "file", "html",
        "image", "json", "report", "text", "video", "webpage",
    } or state not in {"available", "completed", "missing", "ready", "unavailable"}:
        return {"available": False, "refs": [], "overflowCount": 0}

    digest = hashlib.sha256()
    size_bytes: int | None = None
    workspace_path = str(deliverable.get("workspace_path") or "").strip()
    if workspace_path:
        relative = Path(workspace_path)
        root_raw = str(worker.get("workspace_dir") or "").strip()
        if (
            not root_raw
            or relative.is_absolute()
            or ".." in relative.parts
            or not is_user_deliverable_relative_path(relative)
        ):
            return {"available": False, "refs": [], "overflowCount": 0}
        root = Path(root_raw).resolve()
        target = (root / relative).resolve()
        try:
            target.relative_to(root)
            size_bytes = max(0, int(target.stat().st_size))
            with target.open("rb") as handle:
                while chunk := handle.read(1024 * 1024):
                    digest.update(chunk)
        except (OSError, ValueError):
            return {"available": False, "refs": [], "overflowCount": 0}
    else:
        browser_url = str(deliverable.get("browser_url") or "").strip()
        if not browser_url:
            return {"available": False, "refs": [], "overflowCount": 0}
        digest.update(
            json.dumps(
                {
                    "kind": str(deliverable.get("kind") or ""),
                    "source": str(deliverable.get("source") or ""),
                    "browserUrl": browser_url,
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        )
    fingerprint = digest.hexdigest()
    return {
        "available": True,
        "refs": [
            {
                "artifactRef": f"artifact_sha256:{fingerprint}",
                "fingerprint": f"sha256:{fingerprint}",
                "kind": kind,
                "state": state,
                "sizeBytes": size_bytes,
            }
        ],
        "overflowCount": 0,
    }

