def _worker_resource_values(
    resource_class: object,
    resource_memory_bytes: int | None,
) -> tuple[str, int]:
    clean_resource_class = normalize_worker_resource_class(resource_class)
    if resource_memory_bytes is None:
        try:
            standard_memory_mib = int(
                str(os.environ.get("WPR_DOCKER_MEMORY_RESERVATION_MB", "3072"))
            )
        except ValueError:
            standard_memory_mib = 3072
        standard_memory_mib = max(1, min(standard_memory_mib, 1048576))
        clean_resource_memory_bytes = worker_resource_memory_bytes(
            clean_resource_class,
            standard_memory_mib=standard_memory_mib,
        )
    elif isinstance(resource_memory_bytes, bool) or int(resource_memory_bytes) <= 0:
        raise ValueError("Worker resource memory must be a positive byte count")
    else:
        clean_resource_memory_bytes = int(resource_memory_bytes)
    if (
        clean_resource_class == "light"
        and clean_resource_memory_bytes != worker_resource_memory_bytes("light")
    ):
        raise ValueError("Light worker memory must use the trusted server value")
    return clean_resource_class, clean_resource_memory_bytes

def _allowlisted_dict(value: object, keys: frozenset[str]) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    return {key: value[key] for key in keys if key in value}

def _string_list(value: object) -> list[str]:
    if not isinstance(value, list):
        return []
    return [item for item in value if isinstance(item, str) and item.strip()]

def _scalar_fields(
    value: object,
    schema: dict[str, type | tuple[type, ...]],
) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    projected: dict[str, Any] = {}
    for key, expected_type in schema.items():
        item = value.get(key)
        if isinstance(item, expected_type) and not (
            expected_type is int and isinstance(item, bool)
        ):
            projected[key] = item
    return projected

def is_parallel_clean_room_bootstrap(
    bootstrap_profile: object,
    bootstrap_bundle: object,
) -> bool:
    profile = str(bootstrap_profile or "").strip()
    bundle = bootstrap_bundle if isinstance(bootstrap_bundle, dict) else {}
    return bool(
        profile in {"clean-room", "viventium-parallel-clean-room-v1"}
        or bundle.get("execution_policy") == PARALLEL_CLEAN_ROOM_EXECUTION_POLICY
        or isinstance(bundle.get("viventium_launch_authority"), dict)
    )

def _liveness_mode_from_bootstrap_json(value: object) -> str:
    try:
        bundle = json.loads(str(value or "{}"))
    except (TypeError, ValueError, json.JSONDecodeError):
        return "standard"
    if not isinstance(bundle, dict):
        return "standard"
    declaration = bundle.get("viventium_run_liveness")
    if declaration == {"version": 1, "long_mission": True}:
        return "declared_long"
    return "standard"

def canonical_parallel_clean_room_bootstrap(value: object) -> dict[str, Any]:
    """Project only reviewed clean-room task and capability fields.

    The service validates authority-bearing values before calling this helper.
    This projection is also applied at public normalization and storage so an
    unknown context field cannot become durable merely because one boundary
    forgot to reject or remove it.
    """

    if not isinstance(value, dict):
        return {}
    result = {
        key: value[key]
        for key in PARALLEL_CLEAN_ROOM_BOOTSTRAP_KEYS
        if key in value
    }
    for key in (
        "agents_md",
        "claude_md",
        "codex_config_append",
        "codex_md",
        "developer_instructions",
        "project_definition",
        "provider_model",
        "system_instructions",
    ):
        if key in result and not isinstance(result[key], str):
            result.pop(key, None)
    if result.get("execution_policy") != PARALLEL_CLEAN_ROOM_EXECUTION_POLICY:
        result.pop("execution_policy", None)

    if "viventium_run_liveness" in result:
        liveness = result["viventium_run_liveness"]
        if (
            not isinstance(liveness, dict)
            or set(liveness) != {"version", "long_mission"}
            or isinstance(liveness.get("version"), bool)
            or liveness.get("version") != 1
            or not isinstance(liveness.get("long_mission"), bool)
        ):
            raise ValueError("Run liveness declaration is invalid")
        if liveness["long_mission"] is True:
            result["viventium_run_liveness"] = {
                "version": 1,
                "long_mission": True,
            }
        else:
            result.pop("viventium_run_liveness", None)

    if "env" in result:
        effort_values = {
            "WPR_CODEX_CLI_REASONING_EFFORT": {
                "none",
                "minimal",
                "low",
                "medium",
                "high",
                "xhigh",
                "max",
                "ultra",
            },
            "WPR_CLAUDE_CODE_EFFORT": frozenset(CLAUDE_CODE_EFFORT_LEVELS),
        }
        result["env"] = {
            key: item
            for key, item in _scalar_fields(
                result.get("env"),
                {key: str for key in effort_values},
            ).items()
            if item in effort_values[key]
        }
    nested_keys = {
        "callbacks": frozenset(
            {"origin_ref", "events_webhook_url", "hmac_secret"}
        ),
        "glasshive_capability_authorization": frozenset(
            {
                "version",
                "status",
                "authorization_ref",
                "origin_ref",
                "max_expires_at",
                "scope_fingerprint",
            }
        ),
        "glasshive_capability_broker": frozenset(
            {
                "version",
                "status",
                "name",
                "url",
                "allowed_servers",
                "allowed_host_tools",
                "scopes",
                "projection",
            }
        ),
        "glasshive_capability_requirement": frozenset(
            {"version", "required", "status", "reason"}
        ),
        "viventium_constraint_source": frozenset({"version", "instruction"}),
        "viventium_delegation_context": frozenset(
            {
                "version",
                "source_event_id",
                "source_revision",
                "logical_turn_id",
                "surface",
                "triggering_source_segments",
            }
        ),
        "viventium_delegation_identity": frozenset(
            {
                "version",
                "idempotency_key",
                "goal_digest",
                "launch_payload_digest",
                "call_identity_digest",
                "source_event_id",
                "objective_ordinal",
            }
        ),
        "viventium_feelings_projection": frozenset(
            {
                "version",
                "enabled",
                "scope",
                "canonical_instruction_field",
                "snapshot_sha256",
                "expected_capsule_count",
            }
        ),
        "viventium_launch_authority": frozenset(
            {"version", "kind", "execution_mode", "fallback_worker_profile",
             "worker_model", "worker_reasoning_effort",
             "fallback_worker_model", "fallback_worker_reasoning_effort"}
        ),
        "viventium_run_liveness": frozenset({"version", "long_mission"}),
    }
    for key, allowed in nested_keys.items():
        if key in result:
            result[key] = _allowlisted_dict(result[key], allowed)

    broker = result.get("glasshive_capability_broker")
    if isinstance(broker, dict):
        broker = {
            **_scalar_fields(
                broker,
                {
                    "version": int,
                    "status": str,
                    "name": str,
                    "url": str,
                    "projection": str,
                },
            ),
            "allowed_servers": _string_list(broker.get("allowed_servers")),
            "allowed_host_tools": _string_list(
                broker.get("allowed_host_tools")
            ),
            "scopes": _scalar_fields(
                broker.get("scopes"), {"content_read": bool}
            ),
        }
        result["glasshive_capability_broker"] = broker

    callbacks = result.get("callbacks")
    if isinstance(callbacks, dict):
        result["callbacks"] = _scalar_fields(
            callbacks,
            {
                "origin_ref": str,
                "events_webhook_url": str,
                "hmac_secret": str,
            },
        )

    scalar_nested_schemas: dict[
        str, dict[str, type | tuple[type, ...]]
    ] = {
        "glasshive_capability_authorization": {
            "version": int,
            "status": str,
            "authorization_ref": str,
            "origin_ref": str,
            "max_expires_at": (str, int, float),
            "scope_fingerprint": str,
        },
        "glasshive_capability_requirement": {
            "version": int,
            "required": bool,
            "status": str,
            "reason": str,
        },
        "viventium_constraint_source": {"version": int, "instruction": str},
        "viventium_delegation_identity": {
            "version": int,
            "idempotency_key": str,
            "goal_digest": str,
            "launch_payload_digest": str,
            "call_identity_digest": str,
            "source_event_id": str,
            "objective_ordinal": int,
        },
        "viventium_feelings_projection": {
            "version": int,
            "enabled": bool,
            "scope": str,
            "canonical_instruction_field": str,
            "snapshot_sha256": str,
            "expected_capsule_count": int,
        },
        "viventium_launch_authority": {
            "version": int,
            "kind": str,
            "execution_mode": str,
            "fallback_worker_profile": str,
            "worker_model": str,
            "worker_reasoning_effort": str,
            "fallback_worker_model": str,
            "fallback_worker_reasoning_effort": str,
        },
        "viventium_run_liveness": {
            "version": int,
            "long_mission": bool,
        },
    }
    for key, schema in scalar_nested_schemas.items():
        if key in result:
            result[key] = _scalar_fields(result.get(key), schema)

    context = result.get("viventium_delegation_context")
    if isinstance(context, dict):
        projected_context = _scalar_fields(
            context,
            {
                "version": int,
                "source_event_id": str,
                "source_revision": int,
                "logical_turn_id": str,
                "surface": str,
            },
        )
        segment_keys = frozenset(
            {
                "ordinal",
                "source_event_id",
                "source_index",
                "text",
                "truncated",
                "original_sha256",
            }
        )
        projected_context["triggering_source_segments"] = [
            _allowlisted_dict(segment, segment_keys)
            for segment in context.get("triggering_source_segments", [])
            if isinstance(segment, dict)
        ]
        result["viventium_delegation_context"] = projected_context

    packet = result.get("viventium_delegation_packet")
    if isinstance(packet, dict):
        packet = _allowlisted_dict(
            packet,
            frozenset(
                {
                    "version",
                    "task",
                    "explicit_constraints",
                    "selected_files",
                    "authorized_tool_context",
                }
            ),
        )
        packet["task"] = _allowlisted_dict(
            packet.get("task"),
            frozenset({"title", "instruction", "goal", "source_segments"}),
        )
        if isinstance(packet["task"].get("source_segments"), list):
            packet["task"]["source_segments"] = [
                _allowlisted_dict(
                    segment,
                    frozenset({"ordinal", "text", "truncated", "original_sha256"}),
                )
                for segment in packet["task"]["source_segments"]
                if isinstance(segment, dict)
            ]
        if isinstance(packet.get("explicit_constraints"), list):
            packet["explicit_constraints"] = [
                _allowlisted_dict(item, frozenset({"kind", "text"}))
                for item in packet["explicit_constraints"]
                if isinstance(item, dict)
            ]
        if isinstance(packet.get("selected_files"), list):
            packet["selected_files"] = [
                _allowlisted_dict(item, frozenset({"ordinal", "name", "ref"}))
                for item in packet["selected_files"]
                if isinstance(item, dict)
            ]
        if "authorized_tool_context" in packet:
            authority = _scalar_fields(
                packet.get("authorized_tool_context"),
                {"broker": str, "status": str, "content_read": bool},
            )
            raw_authority = packet.get("authorized_tool_context")
            if isinstance(raw_authority, dict):
                authority["servers"] = _string_list(raw_authority.get("servers"))
                authority["host_tools"] = _string_list(
                    raw_authority.get("host_tools")
                )
            packet["authorized_tool_context"] = authority
        result["viventium_delegation_packet"] = packet

    project_mcp = result.get("claude_project_mcp")
    if isinstance(project_mcp, dict):
        server = project_mcp.get("glasshive-user-capabilities")
        projected_server = _scalar_fields(
            server,
            {"type": str, "transport": str, "url": str},
        )
        if isinstance(server, dict):
            projected_server["headers"] = _scalar_fields(
                server.get("headers"), {"Authorization": str}
            )
        result["claude_project_mcp"] = {
            "glasshive-user-capabilities": projected_server
        } if projected_server else {}

    if isinstance(result.get("files"), list):
        file_keys = frozenset(
            {
                "scope",
                "path",
                "filename",
                "file_id",
                "content",
                "source_path",
                "source_path_token",
                "source",
                "type",
                "bytes",
                "media_group_index",
                "upload_blocker",
            }
        )
        result["files"] = [
            _allowlisted_dict(item, file_keys)
            for item in result["files"]
            if isinstance(item, dict)
        ]
    return result

