class ProviderFamilyStoppedError(RuntimeError):
    """Raised when a durable graph-family Stop fence rejects a late start."""

class ProviderAdmissionConflictError(RuntimeError):
    """Raised when a provider request tries to reserve an already-owned visible input."""

class ProviderInvocationConflictError(RuntimeError):
    """An exact host invocation disagrees with an existing native request binding."""

class DelegationIdempotencyConflictError(RuntimeError):
    """Raised when a delegation key is reused for a different canonical request."""

class IsolatedParallelAdmissionConflictError(RuntimeError):
    """Raised when durable host work blocks an automatic isolated launch."""

class ActiveWorkActionConflictError(RuntimeError):
    """Raised when an active-work action key is reused for a different action."""

    def __init__(
        self,
        message: str,
        *,
        code: str = "active_work_idempotency_conflict",
    ) -> None:
        super().__init__(message)
        self.code = str(code)

class CallbackIntentGenerationConflictError(ValueError):
    """Raised when callback construction raced with a newer run attempt."""

class WorkAdmissionError(RuntimeError):
    """Public-safe stable reason a work-producing mutation was fenced."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = str(code)

class HostRunLeaseCapacityError(RuntimeError):
    """Atomic persisted host admission rejection with a machine-readable class."""

    code = "host_capacity"

    def __init__(
        self,
        message: str,
        *,
        capacity_class: str,
        dimension: str = "",
        configured: dict[str, int] | None = None,
        used: dict[str, int] | None = None,
        available: dict[str, int] | None = None,
        required: dict[str, int] | None = None,
        shortage: dict[str, int] | None = None,
        reservation: dict[str, int] | None = None,
        next_retry_at: str = "",
    ) -> None:
        super().__init__(message)
        self.capacity_class = str(capacity_class or "host")
        self.dimension = str(dimension or "")
        self.configured = {
            str(key): max(0, int(value))
            for key, value in (configured or {}).items()
        }
        self.used = {
            str(key): max(0, int(value)) for key, value in (used or {}).items()
        }
        self.available = {
            str(key): max(0, int(value)) for key, value in (available or {}).items()
        }
        self.required = {
            str(key): max(0, int(value)) for key, value in (required or {}).items()
        }
        self.shortage = {
            str(key): max(0, int(value)) for key, value in (shortage or {}).items()
        }
        self.reservation = {
            str(key): max(0, int(value))
            for key, value in (reservation or {}).items()
        }
        self.next_retry_at = str(next_retry_at or "")

