def _slot_capacity_facts(
    dimension: str,
    *,
    configured: int,
    used: int,
) -> dict[str, object]:
    clean_dimension = str(dimension)
    clean_configured = max(0, int(configured))
    clean_used = max(0, int(used))
    return {
        "dimension": clean_dimension,
        "configured": {clean_dimension: clean_configured},
        "used": {clean_dimension: clean_used},
        "available": {clean_dimension: max(0, clean_configured - clean_used)},
        "required": {clean_dimension: 1},
        "shortage": {
            clean_dimension: max(0, clean_used + 1 - clean_configured)
        },
        "reservation": {clean_dimension: 1},
    }

QUEUE_WAIT_TIMEOUT_ENV = "GLASSHIVE_QUEUE_WAIT_TIMEOUT_S"

QUEUE_STATUS_REFRESH_INTERVAL_ENV = "GLASSHIVE_QUEUE_STATUS_REFRESH_INTERVAL_S"

ACTIVE_WORK_TERMINAL_RECENCY_ENV = "GLASSHIVE_ACTIVE_WORK_TERMINAL_RECENCY_S"

ACTIVE_WORK_TERMINAL_PER_STATE_ENV = "GLASSHIVE_ACTIVE_WORK_TERMINAL_RECENT_PER_STATE"

def _bounded_env_seconds(
    name: str,
    default: int,
    *,
    minimum: int,
    maximum: int,
) -> int:
    try:
        value = int(str(os.environ.get(name, default) or default).strip())
    except (TypeError, ValueError):
        value = default
    return max(minimum, min(value, maximum))

def _queue_wait_timeout_seconds() -> int:
    return _bounded_env_seconds(
        QUEUE_WAIT_TIMEOUT_ENV,
        30 * 60,
        minimum=60,
        maximum=7 * 24 * 60 * 60,
    )

def _queue_status_refresh_interval_seconds() -> int:
    return _bounded_env_seconds(
        QUEUE_STATUS_REFRESH_INTERVAL_ENV,
        2 * 60,
        minimum=10,
        maximum=24 * 60 * 60,
    )

def _active_work_terminal_recency_seconds() -> int:
    return _bounded_env_seconds(
        ACTIVE_WORK_TERMINAL_RECENCY_ENV,
        3 * 24 * 60 * 60,
        minimum=60,
        maximum=365 * 24 * 60 * 60,
    )

def _active_work_terminal_per_state_limit() -> int:
    return _bounded_env_seconds(
        ACTIVE_WORK_TERMINAL_PER_STATE_ENV,
        3,
        minimum=1,
        maximum=20,
    )

def _parse_utc(value: str) -> datetime:
    parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

def _queue_callback_id(
    kind: str,
    *,
    run_id: str,
    generation: int,
    deadline: str,
    sequence: int = 0,
) -> str:
    material = ":".join(
        (str(kind), str(run_id), str(generation), str(sequence), str(deadline))
    )
    return f"cb_queue_{kind}_" + hashlib.sha256(material.encode("utf-8")).hexdigest()

def _terminal_callback_id(
    *,
    run_id: str,
    state: str,
    ended_at: str,
    attempt_number: int,
    result_revision: int,
    result_digest: str,
) -> str:
    material = ":".join(
        (
            str(run_id),
            str(state),
            str(ended_at),
            str(max(0, int(attempt_number))),
            str(max(0, int(result_revision))),
            str(result_digest),
        )
    )
    return "cb_terminal_" + hashlib.sha256(material.encode("utf-8")).hexdigest()

def _terminal_callback_wire_state(durable_state: str, event_type: str) -> str:
    state = str(durable_state or "").strip()
    event = str(event_type or "").strip()
    if state == "interrupted" and event == "run.interrupted":
        return "cancelled"
    if state in {"completed", "failed", "cancelled"} and event == f"run.{state}":
        return state
    return ""

TERMINAL_RESULT_DIGEST_FIELDS = (
    "state",
    "ended_at",
    "active_attempt_id",
    "output_text",
    "error_text",
    "failure_class",
    "failure_retryable",
    "failure_structured",
    "failure_user_message",
    "failure_recommended_recovery",
    "failure_diagnostic_summary",
)

def _terminal_result_digest(result: Any) -> str:
    keys = set(result.keys()) if hasattr(result, "keys") else set()
    canonical = {
        field: str(result[field] or "") if field in keys else ""
        for field in TERMINAL_RESULT_DIGEST_FIELDS
    }
    encoded = json.dumps(
        canonical,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return "sha256:" + hashlib.sha256(encoded).hexdigest()

def _terminal_result_digest_values(*values: Any) -> str:
    return _terminal_result_digest(dict(zip(TERMINAL_RESULT_DIGEST_FIELDS, values)))

def _text_sha256(value: Any) -> str:
    return hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()

