    def list_pending_callbacks(
        self, limit: int = 50, *, created_before: str | None = None
    ) -> list[dict[str, Any]]:
        clean_created_before = str(created_before or "").strip()
        created_clause = " AND created_at <= ?" if clean_created_before else ""
        params: list[Any] = []
        if clean_created_before:
            params.append(clean_created_before)
        params.append(limit)
        with self._connect() as conn:
            rows = conn.execute(
                f"""
                SELECT * FROM callback_outbox
                WHERE status = 'pending'
                {created_clause}
                ORDER BY updated_at ASC
                LIMIT ?
                """,
                params,
            ).fetchall()
        return self._rows(rows)

    def reclaim_stale_delivering_callbacks(self, *, stale_before: str, limit: int = 50) -> int:
        reclaimed_at = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = conn.execute(
                """
                SELECT callback_id FROM callback_outbox
                WHERE status = 'delivering'
                  AND (
                    (delivery_lease_expires_at IS NOT NULL
                     AND delivery_lease_expires_at <= ?)
                    OR (delivery_lease_expires_at IS NULL AND updated_at < ?)
                  )
                ORDER BY updated_at ASC
                LIMIT ?
                """,
                (reclaimed_at, stale_before, limit),
            ).fetchall()
            callback_ids = [str(row["callback_id"]) for row in rows]
            if not callback_ids:
                conn.execute("COMMIT")
                return 0
            placeholders = ",".join("?" for _ in callback_ids)
            cur = conn.execute(
                f"""
                UPDATE callback_outbox
                SET status = 'pending',
                    last_error = CASE
                        WHEN last_error = '' THEN 'callback delivery was interrupted and reclaimed'
                        ELSE last_error
                    END,
                    updated_at = ?, delivery_lease_token = '',
                    delivery_lease_expires_at = NULL
                WHERE callback_id IN ({placeholders}) AND status = 'delivering'
                """,
                (reclaimed_at, *callback_ids),
            )
            for callback_id in callback_ids:
                self._append_callback_trace_conn(
                    conn, callback_id=callback_id
                )
            conn.execute("COMMIT")
        return cur.rowcount

    def metrics(self, tenant_id: str | None = None, owner_id: str | None = None) -> dict[str, int]:
        project_clause = ""
        worker_clause = ""
        project_params: list[Any] = []
        worker_params: list[Any] = []
        run_params: list[Any] = []
        event_params: list[Any] = []
        clauses: list[str] = []
        if tenant_id:
            clauses.append("tenant_id = ?")
            project_params.append(tenant_id)
            worker_params.append(tenant_id)
        if owner_id:
            clauses.append("owner_id = ?")
            project_params.append(owner_id)
            worker_params.append(owner_id)
        if clauses:
            project_clause = " WHERE " + " AND ".join(clauses)
            worker_clause = " WHERE " + " AND ".join(clauses)
        run_join = ""
        run_clause = ""
        event_join = ""
        event_clause = ""
        callback_join = ""
        callback_clause = ""
        callback_params: list[Any] = []
        if tenant_id or owner_id:
            run_join = " JOIN workers ON workers.worker_id = runs.worker_id"
            event_join = " JOIN workers ON workers.worker_id = events.worker_id"
            callback_join = " JOIN workers ON workers.worker_id = callback_outbox.worker_id"
            run_filters: list[str] = []
            event_filters: list[str] = []
            callback_filters: list[str] = []
            if tenant_id:
                run_filters.append("runs.tenant_id = ?")
                event_filters.append("events.tenant_id = ?")
                callback_filters.append("callback_outbox.tenant_id = ?")
                run_params.append(tenant_id)
                event_params.append(tenant_id)
                callback_params.append(tenant_id)
            if owner_id:
                run_filters.append("workers.owner_id = ?")
                event_filters.append("workers.owner_id = ?")
                callback_filters.append("workers.owner_id = ?")
                run_params.append(owner_id)
                event_params.append(owner_id)
                callback_params.append(owner_id)
            run_clause = " WHERE " + " AND ".join(run_filters)
            event_clause = " WHERE " + " AND ".join(event_filters)
            callback_clause = " WHERE " + " AND ".join(callback_filters)
        with self._connect() as conn:
            projects = conn.execute(f"SELECT COUNT(*) FROM projects{project_clause}", project_params).fetchone()[0]
            workers = conn.execute(f"SELECT COUNT(*) FROM workers{worker_clause}", worker_params).fetchone()[0]
            runs = conn.execute(f"SELECT COUNT(*) FROM runs{run_join}{run_clause}", run_params).fetchone()[0]
            queued_runs_query = f"SELECT COUNT(*) FROM runs{run_join}"
            active_runs_query = f"SELECT COUNT(*) FROM runs{run_join}"
            queued_filters = ["runs.state = 'queued'"]
            active_filters = ["runs.state = 'running'"]
            queued_params = list(run_params)
            active_params = list(run_params)
            if run_clause:
                extra = run_clause.removeprefix(" WHERE ")
                queued_filters.append(extra)
                active_filters.append(extra)
            queued_runs_query += " WHERE " + " AND ".join(queued_filters)
            active_runs_query += " WHERE " + " AND ".join(active_filters)
            queued_runs = conn.execute(queued_runs_query, queued_params).fetchone()[0]
            active_runs = conn.execute(active_runs_query, active_params).fetchone()[0]
            events = conn.execute(f"SELECT COUNT(*) FROM events{event_join}{event_clause}", event_params).fetchone()[0]
            callback_from = f"callback_outbox{callback_join}"
            callback_pending_query = f"SELECT COUNT(*) FROM {callback_from}"
            callback_delivering_query = f"SELECT COUNT(*) FROM {callback_from}"
            callback_dead_lettered_query = f"SELECT COUNT(*) FROM {callback_from}"
            callback_max_attempts_query = f"SELECT COALESCE(MAX(callback_outbox.attempts), 0) FROM {callback_from}"
            callback_oldest_pending_query = f"SELECT MIN(callback_outbox.updated_at) FROM {callback_from}"
            pending_filters = ["callback_outbox.status = 'pending'"]
            delivering_filters = ["callback_outbox.status = 'delivering'"]
            active_callback_filters = ["callback_outbox.status IN ('pending', 'delivering')"]
            dead_lettered_filters = ["callback_outbox.status = 'dead_lettered'"]
            pending_params = list(callback_params)
            delivering_params = list(callback_params)
            max_attempts_params = list(callback_params)
            dead_lettered_params = list(callback_params)
            if callback_clause:
                extra = callback_clause.removeprefix(" WHERE ")
                pending_filters.append(extra)
                delivering_filters.append(extra)
                active_callback_filters.append(extra)
                dead_lettered_filters.append(extra)
            callback_pending_query += " WHERE " + " AND ".join(pending_filters)
            callback_delivering_query += " WHERE " + " AND ".join(delivering_filters)
            callback_dead_lettered_query += " WHERE " + " AND ".join(dead_lettered_filters)
            callback_oldest_pending_query += " WHERE " + " AND ".join(pending_filters)
            callback_max_attempts_query += " WHERE " + " AND ".join(active_callback_filters)
            callback_pending = conn.execute(callback_pending_query, pending_params).fetchone()[0]
            callback_delivering = conn.execute(callback_delivering_query, delivering_params).fetchone()[0]
            callback_dead_lettered = conn.execute(callback_dead_lettered_query, dead_lettered_params).fetchone()[0]
            callback_max_attempts = conn.execute(callback_max_attempts_query, max_attempts_params).fetchone()[0]
            oldest_pending = conn.execute(callback_oldest_pending_query, pending_params).fetchone()[0]
        callback_oldest_pending_age_seconds = 0
        if oldest_pending:
            try:
                oldest_dt = datetime.fromisoformat(str(oldest_pending))
                if oldest_dt.tzinfo is None:
                    oldest_dt = oldest_dt.replace(tzinfo=timezone.utc)
                callback_oldest_pending_age_seconds = max(
                    0,
                    int((datetime.now(timezone.utc) - oldest_dt).total_seconds()),
                )
            except ValueError:
                callback_oldest_pending_age_seconds = 0
        return {
            "projects": projects,
            "workers": workers,
            "runs": runs,
            "queued_runs": queued_runs,
            "active_runs": active_runs,
            "events": events,
            "callback_pending": callback_pending,
            "callback_delivering": callback_delivering,
            "callback_dead_lettered": callback_dead_lettered,
            "callback_max_attempts": callback_max_attempts,
            "callback_oldest_pending_age_seconds": callback_oldest_pending_age_seconds,
        }


    def _harden_database_files(self) -> None:
        """Keep local runtime state private even when upgrading an older database."""

        for candidate in (
            self.db_path,
            Path(f"{self.db_path}-wal"),
            Path(f"{self.db_path}-shm"),
            Path(f"{self.db_path}-journal"),
        ):
            try:
                if candidate.exists():
                    os.chmod(candidate, 0o600)
            except OSError:
                # A later connection will still fail normally if the database is
                # unreadable. Permission hardening must not mask that root error.
                continue

    @staticmethod
    def _assert_preaccept_host_lease_capacity(
        conn: sqlite3.Connection,
        *,
        runtime_family: str,
        lane: str,
        tenant_id: str,
        owner_id: str,
        run_id: str,
        conversation_limit: int,
        mission_limit: int,
        account_mission_limit: int,
        tenant_mission_limit: int,
        mutation_scope: str,
        capacity_available: dict[str, int] | None,
        capacity_required: dict[str, int] | None,
        capacity_reservation: dict[str, int] | None,
        capacity_observed_lease_ids: Iterable[str] | None,
        capacity_next_retry_at: str,
        exclude_preflight_reservation_id: str = "",
        capacity_now: str = "",
    ) -> None:
        """Check one measured launch reservation inside the acceptance transaction."""

        clean_family = str(runtime_family or "host").strip().lower()
        clean_lane = (
            "conversation"
            if str(lane).strip().lower() == "conversation"
            else "mission"
        )
        active_at = capacity_now or utc_now()
        excluded_reservation = str(exclude_preflight_reservation_id or "")
        lane_limit = max(
            1,
            int(
                conversation_limit
                if clean_lane == "conversation"
                else mission_limit
            ),
        )
        family_lane_count = int(
            conn.execute(
                """
                SELECT COUNT(*) FROM (
                    SELECT lease_id AS capacity_id FROM host_run_leases
                    WHERE status = 'active' AND expires_at > ?
                      AND runtime_family = ? AND lane = ? AND run_id != ?
                    UNION ALL
                    SELECT reservation_id AS capacity_id
                    FROM preflight_capacity_reservations
                    WHERE status = 'active' AND expires_at > ?
                      AND runtime_family = ? AND lane = ?
                      AND reservation_id != ?
                )
                """,
                (
                    active_at,
                    clean_family,
                    clean_lane,
                    run_id,
                    active_at,
                    clean_family,
                    clean_lane,
                    excluded_reservation,
                ),
            ).fetchone()[0]
        )
        if family_lane_count >= lane_limit:
            dimension = f"{clean_family}{clean_lane.title()}Slots"
            raise HostRunLeaseCapacityError(
                f"The {clean_family} {clean_lane} host lane is at its configured capacity.",
                capacity_class="family_lane",
                **_slot_capacity_facts(
                    dimension, configured=lane_limit, used=family_lane_count
                ),
                next_retry_at=capacity_next_retry_at,
            )

        if clean_lane == "mission":
            account_count = int(
                conn.execute(
                    """
                    SELECT COUNT(*) FROM (
                        SELECT lease_id AS capacity_id FROM host_run_leases
                        WHERE status = 'active' AND expires_at > ?
                          AND lane = 'mission' AND tenant_id = ?
                          AND owner_id = ? AND run_id != ?
                        UNION ALL
                        SELECT reservation_id AS capacity_id
                        FROM preflight_capacity_reservations
                        WHERE status = 'active' AND expires_at > ?
                          AND lane = 'mission' AND tenant_id = ? AND owner_id = ?
                          AND reservation_id != ?
                    )
                    """,
                    (
                        active_at,
                        tenant_id,
                        owner_id,
                        run_id,
                        active_at,
                        tenant_id,
                        owner_id,
                        excluded_reservation,
                    ),
                ).fetchone()[0]
            )
            account_limit = max(1, int(account_mission_limit))
            if account_count >= account_limit:
                raise HostRunLeaseCapacityError(
                    "The account is at its configured active mission capacity.",
                    capacity_class="account",
                    **_slot_capacity_facts(
                        "accountMissionSlots",
                        configured=account_limit,
                        used=account_count,
                    ),
                    next_retry_at=capacity_next_retry_at,
                )
            tenant_count = int(
                conn.execute(
                    """
                    SELECT COUNT(*) FROM (
                        SELECT lease_id AS capacity_id FROM host_run_leases
                        WHERE status = 'active' AND expires_at > ?
                          AND lane = 'mission' AND tenant_id = ? AND run_id != ?
                        UNION ALL
                        SELECT reservation_id AS capacity_id
                        FROM preflight_capacity_reservations
                        WHERE status = 'active' AND expires_at > ?
                          AND lane = 'mission' AND tenant_id = ?
                          AND reservation_id != ?
                    )
                    """,
                    (
                        active_at,
                        tenant_id,
                        run_id,
                        active_at,
                        tenant_id,
                        excluded_reservation,
                    ),
                ).fetchone()[0]
            )
            tenant_limit = max(1, int(tenant_mission_limit))
            if tenant_count >= tenant_limit:
                raise HostRunLeaseCapacityError(
                    "The tenant is at its configured active mission capacity.",
                    capacity_class="tenant",
                    **_slot_capacity_facts(
                        "tenantMissionSlots",
                        configured=tenant_limit,
                        used=tenant_count,
                    ),
                    next_retry_at=capacity_next_retry_at,
                )
            clean_mutation_scope = str(mutation_scope or "").strip()
            if clean_mutation_scope:
                mutation_owner = conn.execute(
                    """
                    SELECT capacity_id FROM (
                        SELECT run_id AS capacity_id FROM host_run_leases
                        WHERE status = 'active' AND expires_at > ?
                          AND mutation_scope = ? AND run_id != ?
                        UNION ALL
                        SELECT reservation_id AS capacity_id
                        FROM preflight_capacity_reservations
                        WHERE status = 'active' AND expires_at > ?
                          AND mutation_scope = ? AND reservation_id != ?
                    )
                    LIMIT 1
                    """,
                    (
                        active_at,
                        clean_mutation_scope,
                        run_id,
                        active_at,
                        clean_mutation_scope,
                        excluded_reservation,
                    ),
                ).fetchone()
                if mutation_owner is not None:
                    raise HostRunLeaseCapacityError(
                        "The target repository already has an active host mutation mission.",
                        capacity_class="mutation_scope",
                        **_slot_capacity_facts(
                            "mutationScopeSlots", configured=1, used=1
                        ),
                        next_retry_at=capacity_next_retry_at,
                    )

        available = _capacity_vector(capacity_available)
        required_headroom = _capacity_vector(capacity_required)
        reservation = _capacity_vector(capacity_reservation)
        observed_lease_ids = {
            str(lease_id).strip()
            for lease_id in (capacity_observed_lease_ids or [])
            if str(lease_id).strip()
        }
        pending_rows = conn.execute(
            """
            SELECT capacity_id AS lease_id, reserved_child_processes,
                   reserved_threads, reserved_memory_bytes, reserved_disk_bytes
            FROM (
                SELECT lease_id AS capacity_id, reserved_child_processes,
                       reserved_threads, reserved_memory_bytes,
                       reserved_disk_bytes
                FROM host_run_leases
                WHERE status = 'active' AND expires_at > ? AND run_id != ?
                UNION ALL
                SELECT reservation_id AS capacity_id, reserved_child_processes,
                       reserved_threads, reserved_memory_bytes,
                       reserved_disk_bytes
                FROM preflight_capacity_reservations
                WHERE status = 'active' AND expires_at > ?
                  AND reservation_id != ?
            )
            """,
            (active_at, run_id, active_at, excluded_reservation),
        ).fetchall()
        unobserved = [
            row
            for row in pending_rows
            if str(row["lease_id"] or "") not in observed_lease_ids
        ]
        reserved_since_probe = {
            "childProcesses": sum(
                max(0, int(row["reserved_child_processes"] or 0))
                for row in unobserved
            ),
            "threads": sum(
                max(0, int(row["reserved_threads"] or 0)) for row in unobserved
            ),
            "memoryBytes": sum(
                max(0, int(row["reserved_memory_bytes"] or 0))
                for row in unobserved
            ),
            "diskBytes": sum(
                max(0, int(row["reserved_disk_bytes"] or 0))
                for row in unobserved
            ),
        }
        effective_available = {
            key: max(0, available[key] - reserved_since_probe[key])
            for key in CAPACITY_RESOURCE_KEYS
        }
        total_required = {
            key: required_headroom[key] + reservation[key]
            for key in CAPACITY_RESOURCE_KEYS
        }
        shortage = {
            key: max(0, total_required[key] - effective_available[key])
            for key in CAPACITY_RESOURCE_KEYS
        }
        if any(shortage.values()):
            raise HostRunLeaseCapacityError(
                "Host resource headroom cannot cover this admission reservation.",
                capacity_class="resource_pressure",
                available=effective_available,
                required=total_required,
                shortage=shortage,
                reservation=reservation,
                next_retry_at=capacity_next_retry_at,
            )

    def acquire_preflight_capacity_reservation(
        self,
        *,
        runtime_family: str,
        lane: str,
        tenant_id: str,
        owner_id: str,
        profile: str,
        execution_mode: str,
        executor_id: str,
        conversation_limit: int,
        mission_limit: int,
        account_mission_limit: int,
        tenant_mission_limit: int,
        mutation_scope: str = "",
        lease_ttl_s: float,
        capacity_available: dict[str, int] | None = None,
        capacity_required: dict[str, int] | None = None,
        capacity_reservation: dict[str, int] | None = None,
        capacity_observed_lease_ids: Iterable[str] | None = None,
        capacity_next_retry_at: str = "",
        now: datetime | None = None,
    ) -> dict[str, Any]:
        """Reserve durable capacity before a runtime adapter may run CLI preflight."""

        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
        now_iso = current.isoformat()
        expires_at = (
            current + timedelta(seconds=max(1.0, float(lease_ttl_s)))
        ).isoformat()
        reservation_id = f"preflight_{uuid.uuid4().hex}"
        reservation = _capacity_vector(capacity_reservation)
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            conn.execute(
                """
                UPDATE preflight_capacity_reservations
                SET status = 'released', released_at = ?,
                    release_reason = 'expired_before_preflight'
                WHERE status = 'active' AND expires_at <= ?
                """,
                (now_iso, now_iso),
            )
            self._assert_preaccept_host_lease_capacity(
                conn,
                runtime_family=runtime_family,
                lane=lane,
                tenant_id=tenant_id,
                owner_id=owner_id,
                run_id="",
                conversation_limit=conversation_limit,
                mission_limit=mission_limit,
                account_mission_limit=account_mission_limit,
                tenant_mission_limit=tenant_mission_limit,
                mutation_scope=mutation_scope,
                capacity_available=capacity_available,
                capacity_required=capacity_required,
                capacity_reservation=reservation,
                capacity_observed_lease_ids=capacity_observed_lease_ids,
                capacity_next_retry_at=capacity_next_retry_at,
                capacity_now=now_iso,
            )
            conn.execute(
                """
                INSERT INTO preflight_capacity_reservations (
                    reservation_id, runtime_family, lane, tenant_id, owner_id,
                    profile, execution_mode, executor_id, mutation_scope,
                    reserved_child_processes, reserved_threads,
                    reserved_memory_bytes, reserved_disk_bytes, status,
                    acquired_at, heartbeat_at, expires_at, released_at, release_reason
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, NULL, '')
                """,
                (
                    reservation_id,
                    str(runtime_family or "host").strip().lower(),
                    "conversation" if str(lane).strip().lower() == "conversation" else "mission",
                    tenant_id,
                    owner_id,
                    profile,
                    execution_mode,
                    executor_id,
                    str(mutation_scope or "").strip(),
                    reservation["childProcesses"],
                    reservation["threads"],
                    reservation["memoryBytes"],
                    reservation["diskBytes"],
                    now_iso,
                    now_iso,
                    expires_at,
                ),
            )
            row = conn.execute(
                "SELECT * FROM preflight_capacity_reservations WHERE reservation_id = ?",
                (reservation_id,),
            ).fetchone()
            conn.execute("COMMIT")
        return dict(row) if row is not None else {}

    def get_preflight_capacity_reservation(
        self, reservation_id: str
    ) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM preflight_capacity_reservations WHERE reservation_id = ?",
                (reservation_id,),
            ).fetchone()
        return dict(row) if row is not None else None

    def release_preflight_capacity_reservation(
        self, reservation_id: str, *, reason: str
    ) -> bool:
        now = utc_now()
        with self._connect() as conn:
            updated = conn.execute(
                """
                UPDATE preflight_capacity_reservations
                SET status = 'released', released_at = ?, release_reason = ?
                WHERE reservation_id = ? AND status = 'active'
                """,
                (now, str(reason or "released"), reservation_id),
            ).rowcount
        return bool(updated)

    def preflight_capacity_reservation_is_live(
        self,
        reservation_id: str,
        *,
        executor_id: str,
        profile: str,
        execution_mode: str,
        now: datetime | None = None,
    ) -> bool:
        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc).isoformat()
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT 1 FROM preflight_capacity_reservations
                WHERE reservation_id = ? AND executor_id = ? AND profile = ?
                  AND execution_mode = ? AND status = 'active' AND expires_at > ?
                """,
                (reservation_id, executor_id, profile, execution_mode, current),
            ).fetchone()
        return row is not None

    def renew_preflight_capacity_reservation(
        self,
        reservation_id: str,
        *,
        executor_id: str,
        profile: str,
        execution_mode: str,
        expected_expires_at: str,
        lease_ttl_s: float,
        now: datetime | None = None,
    ) -> dict[str, Any] | None:
        """Renew one exact live preflight owner with an expiry CAS."""

        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
        now_iso = current.isoformat()
        expires_at = (
            current + timedelta(seconds=max(1.0, float(lease_ttl_s)))
        ).isoformat()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            updated = conn.execute(
                """
                UPDATE preflight_capacity_reservations
                SET heartbeat_at = ?, expires_at = ?
                WHERE reservation_id = ? AND executor_id = ? AND profile = ?
                  AND execution_mode = ? AND status = 'active'
                  AND expires_at = ? AND expires_at > ?
                """,
                (
                    now_iso,
                    expires_at,
                    reservation_id,
                    executor_id,
                    profile,
                    execution_mode,
                    str(expected_expires_at),
                    now_iso,
                ),
            ).rowcount
            row = conn.execute(
                "SELECT * FROM preflight_capacity_reservations WHERE reservation_id = ?",
                (reservation_id,),
            ).fetchone()
            conn.execute("COMMIT")
        if updated != 1 or row is None:
            return None
        return dict(row)

    def acquire_host_run_lease(
        self,
        *,
        runtime_family: str,
        lane: str,
        tenant_id: str,
        owner_id: str,
        worker_id: str,
        run_id: str,
        executor_id: str,
        conversation_limit: int,
        mission_limit: int,
        account_mission_limit: int,
        tenant_mission_limit: int,
        mutation_scope: str = "",
        lease_ttl_s: float,
        now: datetime | None = None,
        capacity_available: dict[str, int] | None = None,
        capacity_required: dict[str, int] | None = None,
        capacity_reservation: dict[str, int] | None = None,
        capacity_observed_lease_ids: Iterable[str] | None = None,
        capacity_next_retry_at: str = "",
    ) -> dict[str, Any]:
        """Atomically admit one exact host run across every service process."""

        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
        now_iso = current.isoformat()
        expires_at = (current + timedelta(seconds=max(1.0, float(lease_ttl_s)))).isoformat()
        clean_family = str(runtime_family or "host").strip().lower()
        clean_lane = "conversation" if str(lane).strip().lower() == "conversation" else "mission"
        clean_mutation_scope = str(mutation_scope or "").strip()
        available = _capacity_vector(capacity_available)
        required_headroom = _capacity_vector(capacity_required)
        reservation = _capacity_vector(capacity_reservation)
        observed_lease_ids = {
            str(lease_id).strip()
            for lease_id in (capacity_observed_lease_ids or [])
            if str(lease_id).strip()
        }
        quantitative_capacity = capacity_available is not None
        startup_token = f"start_{uuid.uuid4().hex}"
        lane_limit = max(
            1,
            int(conversation_limit if clean_lane == "conversation" else mission_limit),
        )
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            existing = conn.execute(
                "SELECT * FROM host_run_leases WHERE run_id = ?",
                (run_id,),
            ).fetchone()
            if existing is not None and str(existing["status"] or "") == "active":
                if str(existing["executor_id"] or "") != str(executor_id):
                    transfer_run = conn.execute(
                        "SELECT state, active_attempt_id FROM runs "
                        "WHERE run_id = ? AND worker_id = ?",
                        (run_id, worker_id),
                    ).fetchone()
                    lease_expired = False
                    try:
                        lease_expired = bool(
                            str(existing["expires_at"] or "").strip()
                        ) and _parse_utc(str(existing["expires_at"])) <= current
                    except (OverflowError, TypeError, ValueError):
                        lease_expired = False
                    transferable_preaccept = bool(
                        str(executor_id or "").strip()
                        and str(existing["worker_id"] or "") == str(worker_id)
                        and str(existing["startup_state"] or "") == "reserved"
                        and not str(existing["attempt_id"] or "")
                        and not int(existing["pid"] or 0)
                        and not int(existing["process_group"] or 0)
                        and not str(existing["process_start_identity"] or "")
                        and not str(existing["startup_identity_kind"] or "")
                        and not str(existing["startup_container_id"] or "")
                        and not str(existing["startup_session_id"] or "")
                        and lease_expired
                        and transfer_run is not None
                        and str(transfer_run["state"] or "") == "queued"
                        and not str(transfer_run["active_attempt_id"] or "")
                    )
                    if not transferable_preaccept:
                        conn.execute("ROLLBACK")
                        raise HostRunLeaseCapacityError(
                            "The exact host run is already owned by another live executor.",
                            capacity_class="exact_run_owned",
                            **_slot_capacity_facts(
                                "exactRunOwnerSlots", configured=1, used=1
                            ),
                            next_retry_at=capacity_next_retry_at,
                        )
                    transferred = conn.execute(
                        """
                        UPDATE host_run_leases
                        SET executor_id = ?, heartbeat_at = ?, expires_at = ?
                        WHERE lease_id = ? AND run_id = ? AND worker_id = ?
                          AND status = 'active' AND executor_id = ?
                          AND expires_at = ? AND startup_state = 'reserved'
                          AND attempt_id = '' AND pid IS NULL
                          AND process_group IS NULL AND process_start_identity = ''
                          AND startup_identity_kind = ''
                          AND startup_container_id = ''
                          AND startup_session_id = ''
                        """,
                        (
                            str(executor_id),
                            now_iso,
                            expires_at,
                            str(existing["lease_id"] or ""),
                            run_id,
                            worker_id,
                            str(existing["executor_id"] or ""),
                            str(existing["expires_at"] or ""),
                        ),
                    )
                    if transferred.rowcount != 1:
                        conn.execute("ROLLBACK")
                        raise HostRunLeaseCapacityError(
                            "The exact host run changed during restart handoff.",
                            capacity_class="exact_run_owned",
                            **_slot_capacity_facts(
                                "exactRunOwnerSlots", configured=1, used=1
                            ),
                            next_retry_at=capacity_next_retry_at,
                        )
                    existing = conn.execute(
                        "SELECT * FROM host_run_leases WHERE lease_id = ?",
                        (str(existing["lease_id"] or ""),),
                    ).fetchone()
                    conn.execute("COMMIT")
                    return {
                        **dict(existing),
                        "idempotent_replay": True,
                        "recovery_takeover": True,
                    }
                conn.execute("COMMIT")
                return {**dict(existing), "idempotent_replay": True}

            run = conn.execute(
                "SELECT state, active_attempt_id FROM runs WHERE run_id = ? AND worker_id = ?",
                (run_id, worker_id),
            ).fetchone()
            if run is None:
                conn.execute("ROLLBACK")
                raise ValueError("Host admission requires an existing run")
            active_attempt_id = str(run["active_attempt_id"] or "").strip()
            if active_attempt_id and str(run["state"] or "") != "claimed":
                conn.execute("ROLLBACK")
                raise WorkAdmissionError(
                    "run_not_claimed",
                    "Host admission requires a currently claimed run attempt",
                )

            family_lane_count = int(
                conn.execute(
                    """
                    SELECT COUNT(*) FROM host_run_leases
                    WHERE status = 'active' AND runtime_family = ? AND lane = ?
                    """,
                    (clean_family, clean_lane),
                ).fetchone()[0]
            )
            if family_lane_count >= lane_limit:
                conn.execute("ROLLBACK")
                dimension = f"{clean_family}{clean_lane.title()}Slots"
                raise HostRunLeaseCapacityError(
                    f"The {clean_family} {clean_lane} host lane is at its configured capacity.",
                    capacity_class="family_lane",
                    **_slot_capacity_facts(
                        dimension, configured=lane_limit, used=family_lane_count
                    ),
                    next_retry_at=capacity_next_retry_at,
                )

            if clean_lane == "mission":
                account_count = int(
                    conn.execute(
                        """
                        SELECT COUNT(*) FROM host_run_leases
                        WHERE status = 'active' AND lane = 'mission'
                          AND tenant_id = ? AND owner_id = ?
                        """,
                        (tenant_id, owner_id),
                    ).fetchone()[0]
                )
                account_limit = max(1, int(account_mission_limit))
                if account_count >= account_limit:
                    conn.execute("ROLLBACK")
                    raise HostRunLeaseCapacityError(
                        "The account is at its configured active mission capacity.",
                        capacity_class="account",
                        **_slot_capacity_facts(
                            "accountMissionSlots",
                            configured=account_limit,
                            used=account_count,
                        ),
                        next_retry_at=capacity_next_retry_at,
                    )
                tenant_count = int(
                    conn.execute(
                        """
                        SELECT COUNT(*) FROM host_run_leases
                        WHERE status = 'active' AND lane = 'mission' AND tenant_id = ?
                        """,
                        (tenant_id,),
                    ).fetchone()[0]
                )
                tenant_limit = max(1, int(tenant_mission_limit))
                if tenant_count >= tenant_limit:
                    conn.execute("ROLLBACK")
                    raise HostRunLeaseCapacityError(
                        "The tenant is at its configured active mission capacity.",
                        capacity_class="tenant",
                        **_slot_capacity_facts(
                            "tenantMissionSlots",
                            configured=tenant_limit,
                            used=tenant_count,
                        ),
                        next_retry_at=capacity_next_retry_at,
                    )
                if clean_mutation_scope:
                    mutation_owner = conn.execute(
                        """
                        SELECT run_id FROM host_run_leases
                        WHERE status = 'active' AND mutation_scope = ? AND run_id != ?
                        LIMIT 1
                        """,
                        (clean_mutation_scope, run_id),
                    ).fetchone()
                    if mutation_owner is not None:
                        conn.execute("ROLLBACK")
                        raise HostRunLeaseCapacityError(
                            "The target repository already has an active host mutation mission.",
                            capacity_class="mutation_scope",
                            **_slot_capacity_facts(
                                "mutationScopeSlots", configured=1, used=1
                            ),
                            next_retry_at=capacity_next_retry_at,
                        )

            if quantitative_capacity:
                pending_rows = conn.execute(
                    """
                    SELECT lease_id, reserved_child_processes, reserved_threads,
                           reserved_memory_bytes, reserved_disk_bytes
                    FROM host_run_leases
                    WHERE status = 'active' AND run_id != ?
                    """,
                    (run_id,),
                ).fetchall()
                unobserved = [
                    row
                    for row in pending_rows
                    if str(row["lease_id"] or "") not in observed_lease_ids
                ]
                reserved_since_probe = {
                    "childProcesses": sum(
                        max(0, int(row["reserved_child_processes"] or 0))
                        for row in unobserved
                    ),
                    "threads": sum(
                        max(0, int(row["reserved_threads"] or 0))
                        for row in unobserved
                    ),
                    "memoryBytes": sum(
                        max(0, int(row["reserved_memory_bytes"] or 0))
                        for row in unobserved
                    ),
                    "diskBytes": sum(
                        max(0, int(row["reserved_disk_bytes"] or 0))
                        for row in unobserved
                    ),
                }
                effective_available = {
                    key: max(0, available[key] - reserved_since_probe[key])
                    for key in CAPACITY_RESOURCE_KEYS
                }
                total_required = {
                    key: required_headroom[key] + reservation[key]
                    for key in CAPACITY_RESOURCE_KEYS
                }
                shortage = {
                    key: max(0, total_required[key] - effective_available[key])
                    for key in CAPACITY_RESOURCE_KEYS
                }
                if any(shortage.values()):
                    conn.execute("ROLLBACK")
                    raise HostRunLeaseCapacityError(
                        "Host resource headroom cannot cover this admission reservation.",
                        capacity_class="resource_pressure",
                        available=effective_available,
                        required=total_required,
                        shortage=shortage,
                        reservation=reservation,
                        next_retry_at=capacity_next_retry_at,
                    )

            if existing is None:
                data = {
                    "lease_id": f"hrl_{uuid.uuid4().hex}",
                    "runtime_family": clean_family,
                    "lane": clean_lane,
                    "tenant_id": tenant_id,
                    "owner_id": owner_id,
                    "worker_id": worker_id,
                    "run_id": run_id,
                    "executor_id": executor_id,
                    "pid": None,
                    "process_group": None,
                    "process_start_identity": "",
                    "startup_token": startup_token,
                    "startup_state": "reserved",
                    "startup_confirmed_at": None,
                    "startup_identity_kind": "",
                    "startup_container_id": "",
                    "startup_session_id": "",
                    "mutation_scope": clean_mutation_scope,
                    "attempt_id": active_attempt_id,
                    "reserved_child_processes": reservation["childProcesses"],
                    "reserved_threads": reservation["threads"],
                    "reserved_memory_bytes": reservation["memoryBytes"],
                    "reserved_disk_bytes": reservation["diskBytes"],
                    "status": "active",
                    "acquired_at": now_iso,
                    "heartbeat_at": now_iso,
                    "expires_at": expires_at,
                    "reconciled_at": None,
                    "released_at": None,
                    "release_reason": "",
                }
                conn.execute(
                    """
                    INSERT INTO host_run_leases (
                        lease_id, runtime_family, lane, tenant_id, owner_id,
                        worker_id, run_id, executor_id, pid, process_group,
                        process_start_identity, startup_token, startup_state,
                        startup_confirmed_at, startup_identity_kind,
                        startup_container_id, startup_session_id,
                        mutation_scope, attempt_id, reserved_child_processes,
                        reserved_threads, reserved_memory_bytes,
                        reserved_disk_bytes, status, acquired_at, heartbeat_at,
                        expires_at, reconciled_at, released_at, release_reason
                    ) VALUES (
                        :lease_id, :runtime_family, :lane, :tenant_id, :owner_id,
                        :worker_id, :run_id, :executor_id, :pid, :process_group,
                        :process_start_identity, :startup_token, :startup_state,
                        :startup_confirmed_at, :startup_identity_kind,
                        :startup_container_id, :startup_session_id,
                        :mutation_scope, :attempt_id, :reserved_child_processes,
                        :reserved_threads, :reserved_memory_bytes,
                        :reserved_disk_bytes, :status, :acquired_at, :heartbeat_at,
                        :expires_at, :reconciled_at, :released_at, :release_reason
                    )
                    """,
                    data,
                )
            else:
                data = {
                    **dict(existing),
                    "runtime_family": clean_family,
                    "lane": clean_lane,
                    "tenant_id": tenant_id,
                    "owner_id": owner_id,
                    "worker_id": worker_id,
                    "executor_id": executor_id,
                    "pid": None,
                    "process_group": None,
                    "process_start_identity": "",
                    "startup_token": startup_token,
                    "startup_state": "reserved",
                    "startup_confirmed_at": None,
                    "startup_identity_kind": "",
                    "startup_container_id": "",
                    "startup_session_id": "",
                    "mutation_scope": clean_mutation_scope,
                    "attempt_id": active_attempt_id,
                    "reserved_child_processes": reservation["childProcesses"],
                    "reserved_threads": reservation["threads"],
                    "reserved_memory_bytes": reservation["memoryBytes"],
                    "reserved_disk_bytes": reservation["diskBytes"],
                    "status": "active",
                    "acquired_at": now_iso,
                    "heartbeat_at": now_iso,
                    "expires_at": expires_at,
                    "reconciled_at": None,
                    "released_at": None,
                    "release_reason": "",
                }
                conn.execute(
                    """
                    UPDATE host_run_leases
                    SET runtime_family = :runtime_family, lane = :lane,
                        tenant_id = :tenant_id, owner_id = :owner_id,
                        worker_id = :worker_id, executor_id = :executor_id,
                        pid = :pid, process_group = :process_group,
                        process_start_identity = :process_start_identity,
                        startup_token = :startup_token,
                        startup_state = :startup_state,
                        startup_confirmed_at = :startup_confirmed_at,
                        startup_identity_kind = :startup_identity_kind,
                        startup_container_id = :startup_container_id,
                        startup_session_id = :startup_session_id,
                        mutation_scope = :mutation_scope,
                        attempt_id = :attempt_id,
                        reserved_child_processes = :reserved_child_processes,
                        reserved_threads = :reserved_threads,
                        reserved_memory_bytes = :reserved_memory_bytes,
                        reserved_disk_bytes = :reserved_disk_bytes,
                        status = :status, acquired_at = :acquired_at,
                        heartbeat_at = :heartbeat_at, expires_at = :expires_at,
                        reconciled_at = :reconciled_at, released_at = :released_at,
                        release_reason = :release_reason
                    WHERE lease_id = :lease_id
                    """,
                    data,
                )
            if quantitative_capacity:
                capacity_sequence = int(
                    conn.execute(
                        "SELECT COALESCE(MAX(sequence), 0) + 1 "
                        "FROM capacity_attempts WHERE run_id = ?",
                        (str(run_id),),
                    ).fetchone()[0]
                )
                capacity_attempt_id = "cap_" + hashlib.sha256(
                    f"{run_id}:{capacity_sequence}".encode("utf-8")
                ).hexdigest()
                conn.execute(
                    """
                    INSERT INTO capacity_attempts (
                        capacity_attempt_id, run_id, sequence, attempt_id,
                        capacity_class, available_json, required_json,
                        shortage_json, reservation_json, next_retry_at, observed_at
                    ) VALUES (?, ?, ?, ?, 'admission_reserved', ?, ?, ?, ?, NULL, ?)
                    """,
                    (
                        capacity_attempt_id,
                        str(run_id),
                        capacity_sequence,
                        active_attempt_id,
                        _capacity_json(effective_available),
                        _capacity_json(total_required),
                        _capacity_json({key: 0 for key in CAPACITY_RESOURCE_KEYS}),
                        _capacity_json(reservation),
                        now_iso,
                    ),
                )
                self._append_capacity_trace_conn(
                    conn, capacity_attempt_id=capacity_attempt_id
                )
            conn.execute("COMMIT")
        return {**data, "idempotent_replay": False}

    def get_host_run_lease(self, lease_id: str) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ?",
                (lease_id,),
            ).fetchone()
        return self._row(row)

    @staticmethod
    def _running_generation_is_exact_conn(
        conn: sqlite3.Connection,
        run_id: str,
        *,
        now: str,
    ) -> bool:
        row = conn.execute(
            """
            SELECT 1
            FROM runs
            JOIN run_attempts
              ON run_attempts.attempt_id = runs.active_attempt_id
             AND run_attempts.run_id = runs.run_id
            WHERE runs.run_id = ?
              AND runs.runtime_invoked_at IS NOT NULL
              AND runs.runtime_invoked_at != ''
              AND runs.ended_at IS NULL
              AND runs.active_attempt_id != ''
              AND run_attempts.state = 'running'
              AND run_attempts.runtime_invoked_at = runs.runtime_invoked_at
              AND run_attempts.ended_at IS NULL
              AND EXISTS (
                  SELECT 1
                  FROM host_run_leases
                  WHERE host_run_leases.run_id = runs.run_id
                    AND host_run_leases.attempt_id = runs.active_attempt_id
                    AND host_run_leases.lease_id = run_attempts.lease_id
                    AND host_run_leases.status = 'active'
                    AND host_run_leases.expires_at > ?
              )
            LIMIT 1
            """,
            (str(run_id), str(now)),
        ).fetchone()
        return row is not None

    def _downgrade_unproven_running_conn(
        self,
        conn: sqlite3.Connection,
        run: sqlite3.Row,
        *,
        now: str,
        reason: str,
    ) -> None:
        """Move one unproven running row back to durable pre-dispatch truth."""

        run_id = str(run["run_id"])
        active_attempt_id = str(run["active_attempt_id"] or "")
        downgraded_attempt_id = active_attempt_id
        if active_attempt_id:
            attempt_cursor = conn.execute(
                """
                UPDATE run_attempts
                SET state = 'retry_queued', ended_at = COALESCE(ended_at, ?),
                    terminal_reason = CASE
                        WHEN terminal_reason = '' THEN ? ELSE terminal_reason END
                WHERE attempt_id = ? AND run_id = ? AND ended_at IS NULL
                """,
                (str(now), str(reason), active_attempt_id, run_id),
            )
        else:
            latest_attempt = conn.execute(
                """
                SELECT attempt_id FROM run_attempts
                WHERE run_id = ? AND ended_at IS NULL
                ORDER BY attempt_number DESC LIMIT 1
                """,
                (run_id,),
            ).fetchone()
            downgraded_attempt_id = (
                str(latest_attempt["attempt_id"] or "") if latest_attempt else ""
            )
            attempt_cursor = conn.execute(
                """
                UPDATE run_attempts
                SET state = 'retry_queued', ended_at = COALESCE(ended_at, ?),
                    terminal_reason = CASE
                        WHEN terminal_reason = '' THEN ? ELSE terminal_reason END
                WHERE attempt_id = (
                    SELECT attempt_id FROM run_attempts
                    WHERE run_id = ? AND ended_at IS NULL
                    ORDER BY attempt_number DESC LIMIT 1
                )
                """,
                (str(now), str(reason), run_id),
            )
        if attempt_cursor.rowcount and downgraded_attempt_id:
            self._append_attempt_trace_conn(
                conn,
                attempt_id=downgraded_attempt_id,
                created_at=str(now),
            )
        # A lease this executor released on purpose during a managed shutdown is
        # not lost dispatch ownership: the same run is re-queued and resumes on
        # its own, so the user-facing wording must say exactly that.
        managed_restart = (
            conn.execute(
                """
                SELECT 1 FROM host_run_leases
                WHERE run_id = ? AND status = 'released' AND release_reason = ?
                  AND (? = '' OR attempt_id = ?)
                ORDER BY acquired_at DESC, lease_id DESC
                LIMIT 1
                """,
                (
                    run_id,
                    MANAGED_SHUTDOWN_LEASE_RELEASE_REASON,
                    active_attempt_id,
                    active_attempt_id,
                ),
            ).fetchone()
            is not None
        )
        if managed_restart:
            failure_user_message = MANAGED_RESTART_FAILURE_USER_MESSAGE
            failure_recommended_recovery = (
                MANAGED_RESTART_FAILURE_RECOMMENDED_RECOVERY
            )
            failure_diagnostic_summary = MANAGED_RESTART_FAILURE_DIAGNOSTIC_SUMMARY
        else:
            failure_user_message = (
                "The prior execution state lacked exact durable dispatch ownership."
            )
            failure_recommended_recovery = (
                "Retry the preserved work through normal admission."
            )
            failure_diagnostic_summary = (
                "Running state was downgraded because its invocation lease or "
                "attempt was not exact."
            )
        conn.execute(
            """
            UPDATE host_run_leases
            SET status = 'released', released_at = ?,
                release_reason = ?, reconciled_at = COALESCE(reconciled_at, ?)
            WHERE run_id = ? AND status = 'active'
            """,
            (str(now), str(reason), str(now), run_id),
        )
        wait_open = bool(run["queue_wait_open"])
        generation = max(1, int(run["queue_wait_generation"] or 0))
        wait_started_at = str(run["queue_wait_started_at"] or run["first_queued_at"])
        deadline = str(run["queue_deadline_at"] or "")
        if not wait_open:
            generation += 1
            wait_started_at = str(now)
            deadline = (
                _parse_utc(str(now))
                + timedelta(seconds=_queue_wait_timeout_seconds())
            ).isoformat()
        conn.execute(
            """
            UPDATE runs
            SET state = 'queued', claimed_at = NULL, admitted_at = NULL,
                runtime_invoked_at = NULL, active_attempt_id = '', ended_at = NULL,
                retry_after = ?, last_retry_class = ?, error_text = ?,
                failure_class = ?, failure_retryable = 1,
                failure_structured = 1,
                failure_user_message = ?,
                failure_recommended_recovery = ?,
                failure_diagnostic_summary = ?,
                queue_wait_open = 1, queue_wait_generation = ?,
                queue_wait_episode = ?, queue_wait_started_at = ?,
                queue_wait_closed_at = NULL, queue_wait_duration_seconds = NULL,
                queue_deadline_at = ?, queue_next_status_at = NULL,
                queue_blocker_class = ?
            WHERE run_id = ? AND state = 'running'
            """,
            (
                str(now),
                str(reason),
                str(reason),
                str(reason),
                failure_user_message,
                failure_recommended_recovery,
                failure_diagnostic_summary,
                generation,
                generation,
                wait_started_at,
                deadline,
                str(reason),
                run_id,
            ),
        )
        conn.execute(
            """
            UPDATE workers
            SET state = 'starting', updated_at = ?
            WHERE worker_id = ? AND state = 'running'
            """,
            (str(now), str(run["worker_id"])),
        )

    def reconcile_invalid_running_runs(self, *, now: str | None = None) -> int:
        """Downgrade every running row that lacks one live exact invocation generation."""

        observed_at = str(now or utc_now())
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = conn.execute(
                "SELECT * FROM runs WHERE state = 'running' ORDER BY queued_at, run_id"
            ).fetchall()
            repaired = 0
            for run in rows:
                if self._running_generation_is_exact_conn(
                    conn, str(run["run_id"]), now=observed_at
                ):
                    continue
                self._downgrade_unproven_running_conn(
                    conn,
                    run,
                    now=observed_at,
                    reason="running_invariant_reconciled",
                )
                repaired += 1
            conn.execute("COMMIT")
        return repaired

    def validate_host_run_start_reservation(
        self,
        *,
        worker_id: str,
        run_id: str,
        run_started_at: str,
        lease_id: str,
        startup_token: str,
        executor_id: str,
    ) -> dict[str, Any] | None:
        """Re-read the exact pre-launch tuple while its worker lifecycle lock is held."""

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                (run_id, worker_id),
            ).fetchone()
            lease = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ? AND run_id = ?",
                (lease_id, run_id),
            ).fetchone()
            active_attempt_id = (
                str(run["active_attempt_id"] or "") if run is not None else ""
            )
            attempt = (
                conn.execute(
                    "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                    (active_attempt_id, run_id),
                ).fetchone()
                if active_attempt_id
                else None
            )
            exact_lifecycle = bool(
                run is not None
                and lease is not None
                and active_attempt_id
                and str(run["state"] or "") == "admitted"
                and str(lease["attempt_id"] or "") == active_attempt_id
                and attempt is not None
                and str(attempt["state"] or "") == "admitted"
                and str(attempt["lease_id"] or "") == str(lease_id)
                and not str(attempt["runtime_invoked_at"] or "")
                and attempt["ended_at"] is None
                and not str(run["runtime_invoked_at"] or "")
            )
            exact = bool(
                worker is not None
                and run is not None
                and lease is not None
                and exact_lifecycle
                and str(lease["status"] or "") == "active"
                and str(lease["worker_id"] or "") == str(worker_id)
                and str(lease["executor_id"] or "") == str(executor_id)
                and str(lease["startup_token"] or "") == str(startup_token)
                and str(lease["startup_state"] or "") == "reserved"
                and str(lease["expires_at"] or "") > utc_now()
                and not str(worker["compute_release_token"] or "")
                and not str(worker["work_stop_id"] or "")
                and str(worker["state"] or "")
                not in {"paused", "needs_input", "stopping", "terminated"}
            )
            result = (
                {
                    "worker": self._row(worker),
                    "run": self._row(run),
                    "lease": self._row(lease),
                }
                if exact
                else None
            )
            conn.execute("COMMIT")
        return result

    def mark_host_run_start_termination_unconfirmed(
        self,
        *,
        lease_id: str,
        run_id: str,
        executor_id: str,
        startup_token: str,
    ) -> dict[str, Any] | None:
        """Fence an ambiguous spawned identity so it cannot be reused as pre-launch."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            lease = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ? AND run_id = ?",
                (lease_id, run_id),
            ).fetchone()
            attempt_id = str(run["active_attempt_id"] or "") if run else ""
            attempt = (
                conn.execute(
                    "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                    (attempt_id, run_id),
                ).fetchone()
                if attempt_id
                else None
            )
            exact_running = bool(
                run is not None
                and lease is not None
                and attempt is not None
                and str(run["state"] or "") == "running"
                and str(run["runtime_invoked_at"] or "")
                and str(lease["attempt_id"] or "") == attempt_id
                and str(attempt["state"] or "") == "running"
                and str(attempt["lease_id"] or "") == str(lease_id)
                and str(attempt["runtime_invoked_at"] or "")
                == str(run["runtime_invoked_at"] or "")
                and attempt["ended_at"] is None
            )
            cursor = conn.execute(
                """
                UPDATE host_run_leases
                SET startup_state = 'termination_unconfirmed', heartbeat_at = ?
                WHERE lease_id = ? AND run_id = ? AND executor_id = ?
                  AND startup_token = ? AND status = 'active'
                  AND startup_state = 'reserved'
                """,
                (now, lease_id, run_id, executor_id, startup_token),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            if exact_running:
                run_cursor = conn.execute(
                    """
                    UPDATE runs SET state = 'settling'
                    WHERE run_id = ? AND state = 'running'
                      AND active_attempt_id = ? AND runtime_invoked_at = ?
                    """,
                    (run_id, attempt_id, str(run["runtime_invoked_at"] or "")),
                )
                attempt_cursor = conn.execute(
                    """
                    UPDATE run_attempts SET state = 'settling'
                    WHERE attempt_id = ? AND run_id = ? AND state = 'running'
                      AND lease_id = ? AND runtime_invoked_at = ? AND ended_at IS NULL
                    """,
                    (
                        attempt_id,
                        run_id,
                        lease_id,
                        str(run["runtime_invoked_at"] or ""),
                    ),
                )
                if run_cursor.rowcount != 1 or attempt_cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                self._append_attempt_trace_conn(
                    conn, attempt_id=attempt_id, created_at=now
                )
            row = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ?", (lease_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def confirm_host_run_start(
        self,
        *,
        worker_id: str,
        run_id: str,
        run_started_at: str,
        lease_id: str,
        startup_token: str,
        executor_id: str,
        identity_kind: str,
        pid: int | None,
        process_group: int | None,
        process_start_identity: str,
        container_id: str,
        session_id: str,
        allow_runtime_invocation: bool = False,
        callback_record: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Publish exact startup identity and its started evidence in one CAS.

        Only the live runtime observer may establish the admitted-to-running
        invocation boundary. Restart confirmation can confirm an invocation
        that is already durable, but cannot synthesize one.
        """

        clean_kind = str(identity_kind or "").strip().lower()
        clean_start_identity = str(process_start_identity or "").strip()
        clean_container_id = str(container_id or "").strip()
        clean_session_id = str(session_id or "").strip()
        clean_pid = int(pid or 0)
        clean_group = int(process_group or 0)
        if clean_kind == "host_process":
            valid_identity = bool(
                clean_pid > 0 and clean_start_identity and clean_session_id
            )
        elif clean_kind == "docker_session":
            valid_identity = bool(
                clean_container_id
                and clean_session_id
                and clean_pid > 0
                and clean_start_identity.startswith(
                    f"docker:{clean_container_id}:{clean_session_id}:{run_id}:"
                )
            )
        elif clean_kind == "in_process":
            valid_identity = bool(
                not clean_container_id
                and clean_pid == 0
                and clean_group == 0
                and not clean_start_identity
                and clean_session_id == "in-process"
            )
        else:
            valid_identity = False
        if not valid_identity:
            raise ValueError("Run startup confirmation requires an exact identity")

        fingerprint_material = "\0".join(
            (
                "glasshive.run-start.v1",
                clean_kind,
                clean_container_id,
                clean_session_id,
                str(clean_pid),
                clean_start_identity,
            )
        )
        fingerprint = hashlib.sha256(
            fingerprint_material.encode("utf-8")
        ).hexdigest()
        event_id = "evt_start_" + hashlib.sha256(
            str(startup_token).encode("utf-8")
        ).hexdigest()
        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                (run_id, worker_id),
            ).fetchone()
            lease = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ? AND run_id = ?",
                (lease_id, run_id),
            ).fetchone()
            if worker is None or run is None or lease is None:
                conn.execute("COMMIT")
                return None
            exact_lease = bool(
                str(lease["status"] or "") == "active"
                and str(lease["expires_at"] or "") > now
                and str(lease["worker_id"] or "") == str(worker_id)
                and str(lease["executor_id"] or "") == str(executor_id)
                and str(lease["startup_token"] or "") == str(startup_token)
            )
            active_attempt_id = str(run["active_attempt_id"] or "")
            attempt = (
                conn.execute(
                    "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                    (active_attempt_id, run_id),
                ).fetchone()
                if active_attempt_id
                else None
            )
            admitted_generation = bool(
                allow_runtime_invocation
                and active_attempt_id
                and str(run["state"] or "") == "admitted"
                and not str(run["runtime_invoked_at"] or "")
                and str(lease["attempt_id"] or "") == active_attempt_id
                and attempt is not None
                and str(attempt["state"] or "") == "admitted"
                and str(attempt["lease_id"] or "") == str(lease_id)
                and not str(attempt["runtime_invoked_at"] or "")
                and attempt["ended_at"] is None
                and bool(run["queue_wait_open"])
                and str(run["queue_deadline_at"] or "") > now
            )
            running_generation = bool(
                active_attempt_id
                and str(run["state"] or "") == "running"
                and str(run["runtime_invoked_at"] or "")
                == str(run_started_at or "")
                and run["ended_at"] is None
                and str(lease["attempt_id"] or "") == active_attempt_id
                and attempt is not None
                and str(attempt["state"] or "") == "running"
                and str(attempt["lease_id"] or "") == str(lease_id)
                and str(attempt["runtime_invoked_at"] or "")
                == str(run["runtime_invoked_at"] or "")
                and attempt["ended_at"] is None
            )
            exact_run = bool(admitted_generation or running_generation)
            worker_allows_start = bool(
                not str(worker["compute_release_token"] or "")
                and not str(worker["work_stop_id"] or "")
                and str(worker["state"] or "")
                not in {"paused", "needs_input", "stopping", "terminated"}
            )
            if not exact_lease or not exact_run or not worker_allows_start:
                if str(run["state"] or "") == "running" and not running_generation:
                    self._downgrade_unproven_running_conn(
                        conn,
                        run,
                        now=now,
                        reason="running_invariant_reconciled",
                    )
                conn.execute("COMMIT")
                return None
            if str(lease["startup_state"] or "") == "confirmed":
                same_identity = bool(
                    str(lease["startup_identity_kind"] or "") == clean_kind
                    and int(lease["pid"] or 0) == clean_pid
                    and int(lease["process_group"] or 0) == clean_group
                    and str(lease["process_start_identity"] or "")
                    == clean_start_identity
                    and str(lease["startup_container_id"] or "")
                    == clean_container_id
                    and str(lease["startup_session_id"] or "") == clean_session_id
                )
                if not same_identity:
                    conn.execute("COMMIT")
                    return None
                event = conn.execute(
                    "SELECT * FROM events WHERE event_id = ?", (event_id,)
                ).fetchone()
                conn.execute("COMMIT")
                return {
                    "lease": self._row(lease),
                    "run": self._row(run),
                    "event": self._row(event),
                    "idempotent_replay": True,
                }
            if str(lease["startup_state"] or "") != "reserved":
                conn.execute("COMMIT")
                return None
            if admitted_generation:
                wait_duration = max(
                    0,
                    int(
                        (
                            _parse_utc(now)
                            - _parse_utc(
                                str(
                                    run["queue_wait_started_at"]
                                    or run["first_queued_at"]
                                )
                            )
                        ).total_seconds()
                    ),
                )
                run_cursor = conn.execute(
                    """
                    UPDATE runs
                    SET state = 'running',
                        started_at = COALESCE(started_at, ?),
                        runtime_invoked_at = ?,
                        queue_wait_open = 0, queue_wait_closed_at = ?,
                        queue_wait_duration_seconds = ?,
                        queue_next_status_at = NULL,
                        failure_class = '', failure_retryable = 0,
                        failure_structured = 0, failure_user_message = '',
                        failure_recommended_recovery = '',
                        failure_diagnostic_summary = '', last_retry_class = ''
                    WHERE run_id = ? AND state = 'admitted'
                      AND active_attempt_id = ?
                      AND runtime_invoked_at IS NULL
                      AND queue_wait_open = 1 AND queue_deadline_at > ?
                    """,
                    (
                        now,
                        now,
                        now,
                        wait_duration,
                        run_id,
                        active_attempt_id,
                        now,
                    ),
                )
                attempt_cursor = conn.execute(
                    """
                    UPDATE run_attempts
                    SET state = 'running', runtime_invoked_at = ?
                    WHERE attempt_id = ? AND run_id = ?
                      AND state = 'admitted' AND lease_id = ?
                      AND runtime_invoked_at IS NULL AND ended_at IS NULL
                    """,
                    (now, active_attempt_id, run_id, lease_id),
                )
                if run_cursor.rowcount != 1 or attempt_cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                run = conn.execute(
                    "SELECT * FROM runs WHERE run_id = ?", (run_id,)
                ).fetchone()
                if run is None:
                    conn.execute("ROLLBACK")
                    return None
                self._append_runtime_invocation_trace_conn(
                    conn,
                    run=run,
                    attempt_id=active_attempt_id,
                    invoked_at=now,
                )
                self._append_attempt_trace_conn(
                    conn, attempt_id=active_attempt_id, created_at=now
                )
            cursor = conn.execute(
                """
                UPDATE host_run_leases
                SET startup_state = 'confirmed', startup_confirmed_at = ?,
                    startup_identity_kind = ?, startup_container_id = ?,
                    startup_session_id = ?, pid = ?, process_group = ?,
                    process_start_identity = ?, heartbeat_at = ?
                WHERE lease_id = ? AND run_id = ? AND worker_id = ?
                  AND executor_id = ? AND startup_token = ?
                  AND status = 'active' AND startup_state = 'reserved'
                  AND expires_at > ?
                """,
                (
                    now,
                    clean_kind,
                    clean_container_id,
                    clean_session_id,
                    clean_pid or None,
                    clean_group or None,
                    clean_start_identity,
                    now,
                    lease_id,
                    run_id,
                    worker_id,
                    executor_id,
                    startup_token,
                    now,
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            conn.execute(
                "UPDATE workers SET state = 'running', updated_at = ? WHERE worker_id = ?",
                (now, worker_id),
            )
            conn.execute(
                """
                INSERT OR IGNORE INTO events (
                    event_id, project_id, worker_id, tenant_id, run_id,
                    event_type, message, payload_json, created_at
                ) VALUES (?, ?, ?, ?, ?, 'run.started', ?, ?, ?)
                """,
                (
                    event_id,
                    run["project_id"],
                    worker_id,
                    run["tenant_id"],
                    run_id,
                    str(run["instruction"] or ""),
                    json.dumps(
                        {
                            "identityKind": clean_kind,
                            "identityFingerprint": fingerprint,
                        },
                        sort_keys=True,
                    ),
                    now,
                ),
            )
            callback = None
            if callback_record:
                callback_id = "cb_start_" + hashlib.sha256(
                    str(startup_token).encode("utf-8")
                ).hexdigest()
                callback_data = {
                    **callback_record,
                    "callback_id": callback_id,
                    "project_id": str(run["project_id"] or ""),
                    "worker_id": worker_id,
                    "tenant_id": str(run["tenant_id"] or "local"),
                    "run_id": run_id,
                    "attempt_number": int(attempt["attempt_number"] or 0),
                    "event_type": "run.started",
                }
                callback = self._insert_callback_intent_conn(
                    conn, callback_data, now=now
                )
            confirmed_lease = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ?", (lease_id,)
            ).fetchone()
            event = conn.execute(
                "SELECT * FROM events WHERE event_id = ?", (event_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return {
            "lease": self._row(confirmed_lease),
            "run": self._row(run),
            "event": self._row(event),
            "callback": self._row(callback),
            "idempotent_replay": False,
        }

    def requeue_unconfirmed_host_run_start(
        self,
        *,
        worker_id: str,
        run_id: str,
        lease_id: str,
        startup_token: str,
        retry_after: str,
        error_text: str,
    ) -> dict[str, Any] | None:
        """Atomically retire one proven-absent startup generation and requeue its run."""

        now = utc_now()
        event_id = "evt_start_requeue_" + hashlib.sha256(
            str(startup_token).encode("utf-8")
        ).hexdigest()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                (run_id, worker_id),
            ).fetchone()
            lease = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ? AND run_id = ?",
                (lease_id, run_id),
            ).fetchone()
            exact = bool(
                worker is not None
                and run is not None
                and lease is not None
                and str(run["state"] or "")
                in {"claimed", "admitted", "running", "settling", "queued"}
                and str(lease["worker_id"] or "") == worker_id
                and str(lease["status"] or "") == "active"
                and str(lease["startup_state"] or "")
                in {"reserved", "termination_unconfirmed"}
                and str(lease["startup_token"] or "") == str(startup_token)
            )
            if not exact:
                conn.execute("COMMIT")
                return None
            wait_open = bool(run["queue_wait_open"])
            generation = max(1, int(run["queue_wait_generation"] or 0))
            if not wait_open:
                generation += 1
                wait_started_at = now
                deadline = (
                    _parse_utc(now)
                    + timedelta(seconds=_queue_wait_timeout_seconds())
                ).isoformat()
                next_status_at = (
                    _parse_utc(now)
                    + timedelta(seconds=_queue_status_refresh_interval_seconds())
                ).isoformat()
                transition_emitted = 0
                status_sequence = 0
                callback_state = "unknown"
            else:
                wait_started_at = str(
                    run["queue_wait_started_at"] or run["first_queued_at"]
                )
                deadline = str(run["queue_deadline_at"] or "")
                next_status_at = run["queue_next_status_at"]
                transition_emitted = int(run["queue_transition_emitted"] or 0)
                status_sequence = int(run["queue_status_sequence"] or 0)
                callback_state = str(run["queue_callback_state"] or "unknown")
            conn.execute(
                """
                UPDATE host_run_leases
                SET status = 'released', released_at = ?, release_reason = ?,
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE lease_id = ? AND run_id = ? AND status = 'active'
                  AND startup_state IN ('reserved', 'termination_unconfirmed')
                  AND startup_token = ?
                """,
                (
                    now,
                    "startup_generation_cleaned",
                    now,
                    lease_id,
                    run_id,
                    startup_token,
                ),
            )
            conn.execute(
                """
                UPDATE runs
                SET state = 'queued', claimed_at = NULL, admitted_at = NULL,
                    runtime_invoked_at = NULL,
                    active_attempt_id = '', ended_at = NULL, retry_after = ?,
                    retry_attempts = COALESCE(retry_attempts, 0) + 1,
                    last_retry_class = 'service_startup_fenced', error_text = ?,
                    failure_class = 'service_startup_fenced', failure_retryable = 1,
                    failure_structured = 1,
                    failure_user_message = ?, failure_recommended_recovery = ?,
                    failure_diagnostic_summary = ?,
                    queue_wait_episode = ?, queue_wait_open = 1,
                    queue_wait_generation = ?, queue_wait_started_at = ?,
                    queue_wait_closed_at = NULL,
                    queue_wait_duration_seconds = NULL,
                    queue_deadline_at = ?, queue_next_status_at = ?,
                    queue_transition_emitted = ?, queue_status_sequence = ?,
                    queue_callback_state = ?, queue_terminal_callback_id = ?
                WHERE run_id = ? AND worker_id = ?
                  AND state IN ('claimed', 'admitted', 'running', 'settling', 'queued')
                """,
                (
                    retry_after,
                    error_text,
                    "GlassHive safely recovered an interrupted worker startup and will retry.",
                    "No action is required unless this work remains queued.",
                    "Restart recovery cleaned the exact unconfirmed startup generation.",
                    generation,
                    generation,
                    wait_started_at,
                    deadline,
                    next_status_at,
                    transition_emitted,
                    status_sequence,
                    callback_state,
                    _queue_callback_id(
                        "timeout",
                        run_id=str(run_id),
                        generation=generation,
                        deadline=deadline,
                    ),
                    run_id,
                    worker_id,
                ),
            )
            if str(run["active_attempt_id"] or ""):
                attempt_cursor = conn.execute(
                    """
                    UPDATE run_attempts
                    SET state = 'retry_queued', ended_at = ?,
                        terminal_reason = 'service_startup_fenced'
                    WHERE attempt_id = ? AND ended_at IS NULL
                    """,
                    (now, str(run["active_attempt_id"] or "")),
                )
                if attempt_cursor.rowcount:
                    self._append_attempt_trace_conn(
                        conn,
                        attempt_id=str(run["active_attempt_id"] or ""),
                        created_at=now,
                    )
            conn.execute(
                """
                UPDATE workers
                SET state = CASE
                        WHEN state IN ('paused', 'needs_input', 'stopping', 'terminated')
                        THEN state ELSE 'starting' END,
                    last_error = '', updated_at = ?
                WHERE worker_id = ?
                """,
                (now, worker_id),
            )
            conn.execute(
                """
                INSERT OR IGNORE INTO events (
                    event_id, project_id, worker_id, tenant_id, run_id,
                    event_type, message, payload_json, created_at
                ) VALUES (?, ?, ?, ?, ?, 'run.requeued', ?, ?, ?)
                """,
                (
                    event_id,
                    run["project_id"],
                    worker_id,
                    run["tenant_id"],
                    run_id,
                    "Interrupted startup generation was safely cleaned; retry queued",
                    json.dumps(
                        {"failureClass": "service_startup_fenced"},
                        sort_keys=True,
                    ),
                    now,
                ),
            )
            recovered = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(recovered)

    def get_active_host_run_lease_for_run(self, run_id: str) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM host_run_leases WHERE run_id = ? AND status = 'active'",
                (run_id,),
            ).fetchone()
        return self._row(row)

    def get_run_retry_generation(self, run_id: str) -> dict[str, str] | None:
        """Return the exact attempt and lease generation required by retry CAS."""

        with self._connect() as conn:
            run = conn.execute(
                "SELECT active_attempt_id FROM runs WHERE run_id = ?",
                (str(run_id),),
            ).fetchone()
            if run is None:
                return None
            attempt_id = str(run["active_attempt_id"] or "")
            lease = conn.execute(
                "SELECT * FROM host_run_leases WHERE run_id = ? AND attempt_id = ?",
                (str(run_id), attempt_id),
            ).fetchone()
        return {
            "expected_attempt_id": attempt_id,
            "expected_lease_id": str(lease["lease_id"] or "") if lease else "",
            "expected_executor_id": str(lease["executor_id"] or "") if lease else "",
            "expected_startup_token": str(lease["startup_token"] or "") if lease else "",
        }

    def has_unconfirmed_host_run_start(self, worker_id: str) -> bool:
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT 1 FROM host_run_leases
                WHERE worker_id = ? AND status = 'active'
                  AND startup_state = 'termination_unconfirmed'
                LIMIT 1
                """,
                (worker_id,),
            ).fetchone()
        return row is not None

    def latest_host_run_lease_for_run(self, run_id: str) -> dict[str, Any] | None:
        """The most recently acquired host run lease for a run, whatever its status."""
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT * FROM host_run_leases
                WHERE run_id = ?
                ORDER BY acquired_at DESC, lease_id DESC
                LIMIT 1
                """,
                (str(run_id or ""),),
            ).fetchone()
        return self._row(row) if row else None

    def list_active_host_run_leases(self) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM host_run_leases
                WHERE status = 'active'
                ORDER BY acquired_at ASC, lease_id ASC
                """
            ).fetchall()
        return self._rows(rows)

    def list_stale_host_run_leases(
        self,
        *,
        heartbeat_before: str,
    ) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM host_run_leases
                WHERE status = 'active'
                  AND (heartbeat_at <= ? OR expires_at <= ?)
                ORDER BY heartbeat_at ASC, lease_id ASC
                """,
                (heartbeat_before, utc_now()),
            ).fetchall()
        return self._rows(rows)

    def heartbeat_host_run_lease(
        self,
        lease_id: str,
        *,
        executor_id: str | None,
        pid: int | None = None,
        process_group: int | None = None,
        process_start_identity: str = "",
        startup_identity_kind: str = "",
        startup_container_id: str = "",
        startup_session_id: str = "",
        lease_ttl_s: float = 30.0,
        reconciled: bool = False,
        allow_expired: bool = False,
        now: datetime | None = None,
    ) -> dict[str, Any] | None:
        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
        now_iso = current.isoformat()
        expires_at = (current + timedelta(seconds=max(1.0, float(lease_ttl_s)))).isoformat()
        # ``allow_expired`` is reserved for startup reconciliation that has verified the
        # exact live generation identity recorded on this lease: the executor died, its
        # lease timed out, but the durable worker process it fenced is provably still
        # running. Every other heartbeat keeps the expiry fence.
        clauses = [
            "lease_id = ?",
            "status = 'active'",
            *([] if allow_expired else ["expires_at > ?"]),
            """NOT EXISTS (
                SELECT 1 FROM runs
                WHERE runs.run_id = host_run_leases.run_id
                  AND runs.state IN ('completed', 'failed', 'cancelled')
            )""",
        ]
        params: list[Any] = [lease_id, *([] if allow_expired else [now_iso])]
        if executor_id is not None:
            clauses.append("executor_id = ?")
            params.append(executor_id)
        with self._connect() as conn:
            cursor = conn.execute(
                f"""
                UPDATE host_run_leases
                SET heartbeat_at = ?, expires_at = ?,
                    pid = COALESCE(?, pid),
                    process_group = COALESCE(?, process_group),
                    process_start_identity = CASE
                        WHEN ? != '' THEN ? ELSE process_start_identity END,
                    startup_identity_kind = CASE
                        WHEN startup_state = 'reserved' AND ? != ''
                        THEN ? ELSE startup_identity_kind END,
                    startup_container_id = CASE
                        WHEN startup_state = 'reserved' AND ? != ''
                        THEN ? ELSE startup_container_id END,
                    startup_session_id = CASE
                        WHEN startup_state = 'reserved' AND ? != ''
                        THEN ? ELSE startup_session_id END,
                    reconciled_at = CASE WHEN ? THEN ? ELSE reconciled_at END
                WHERE {' AND '.join(clauses)}
                """,
                (
                    now_iso,
                    expires_at,
                    pid,
                    process_group,
                    process_start_identity,
                    process_start_identity,
                    startup_identity_kind,
                    startup_identity_kind,
                    startup_container_id,
                    startup_container_id,
                    startup_session_id,
                    startup_session_id,
                    1 if reconciled else 0,
                    now_iso,
                    *params,
                ),
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ?",
                (lease_id,),
            ).fetchone()
        return self._row(row)

    def release_host_run_lease(
        self,
        lease_id: str,
        *,
        executor_id: str | None,
        reason: str,
    ) -> dict[str, Any] | None:
        now = utc_now()
        clauses = ["lease_id = ?", "status = 'active'"]
        params: list[Any] = [lease_id]
        if executor_id is not None:
            clauses.append("executor_id = ?")
            params.append(executor_id)
        with self._connect() as conn:
            cursor = conn.execute(
                f"""
                UPDATE host_run_leases
                SET status = 'released', released_at = ?, release_reason = ?,
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE {' AND '.join(clauses)}
                """,
                (now, str(reason or "released"), now, *params),
            )
            if cursor.rowcount == 0:
                row = conn.execute(
                    "SELECT * FROM host_run_leases WHERE lease_id = ?",
                    (lease_id,),
                ).fetchone()
                return self._row(row)
            row = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ?",
                (lease_id,),
            ).fetchone()
        return self._row(row)

    def reconcile_dead_host_run_lease(
        self,
        *,
        lease_id: str,
        run_id: str,
        expected_attempt_id: str,
        expected_executor_id: str,
        reason: str,
    ) -> dict[str, Any] | None:
        """Release one dead lease and repair its exact running generation atomically."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            lease = conn.execute(
                """
                SELECT * FROM host_run_leases
                WHERE lease_id = ? AND run_id = ? AND status = 'active'
                  AND attempt_id = ? AND executor_id = ?
                """,
                (
                    str(lease_id),
                    str(run_id),
                    str(expected_attempt_id),
                    str(expected_executor_id),
                ),
            ).fetchone()
            if lease is None:
                conn.execute("ROLLBACK")
                return None
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            if (
                run is not None
                and str(run["state"] or "") == "running"
                and str(run["active_attempt_id"] or "")
                == str(expected_attempt_id)
            ):
                self._downgrade_unproven_running_conn(
                    conn,
                    run,
                    now=now,
                    reason=str(reason or "dead_host_run_lease"),
                )
            else:
                conn.execute(
                    """
                    UPDATE host_run_leases
                    SET status = 'released', released_at = ?, release_reason = ?,
                        reconciled_at = COALESCE(reconciled_at, ?)
                    WHERE lease_id = ? AND run_id = ? AND status = 'active'
                      AND attempt_id = ? AND executor_id = ?
                    """,
                    (
                        now,
                        str(reason or "dead_host_run_lease"),
                        now,
                        str(lease_id),
                        str(run_id),
                        str(expected_attempt_id),
                        str(expected_executor_id),
                    ),
                )
            row = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ?",
                (str(lease_id),),
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def release_expired_preaccept_host_run_lease(
        self,
        *,
        lease_id: str,
        run_id: str,
        reason: str,
    ) -> dict[str, Any] | None:
        """Release only a still-unclaimed, identity-free startup reservation."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            cursor = conn.execute(
                """
                UPDATE host_run_leases
                SET status = 'released', released_at = ?, release_reason = ?,
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE lease_id = ? AND run_id = ?
                  AND status = 'active' AND startup_state = 'reserved'
                  AND attempt_id = '' AND pid IS NULL AND process_group IS NULL
                  AND process_start_identity = ''
                  AND startup_identity_kind = ''
                  AND startup_container_id = ''
                  AND startup_session_id = ''
                  AND EXISTS (
                      SELECT 1 FROM runs
                      WHERE runs.run_id = host_run_leases.run_id
                        AND runs.state = 'queued'
                        AND runs.active_attempt_id = ''
                  )
                """,
                (now, str(reason or "expired_preaccept"), now, lease_id, run_id),
            )
            if cursor.rowcount != 1:
                conn.execute("COMMIT")
                return None
            row = conn.execute(
                "SELECT * FROM host_run_leases WHERE lease_id = ?",
                (lease_id,),
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def consume_service_assertion_nonce(
        self,
        *,
        audience: str,
        tenant_id: str,
        owner_id: str,
        nonce: str,
        issued_at_epoch: int,
        expires_at_epoch: int,
        request_method: str,
        request_path: str,
        now_epoch: int | None = None,
    ) -> bool:
        current_epoch = int(datetime.now(timezone.utc).timestamp()) if now_epoch is None else int(now_epoch)
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            conn.execute(
                "DELETE FROM service_assertion_nonces WHERE expires_at_epoch < ?",
                (current_epoch,),
            )
            cursor = conn.execute(
                """
                INSERT OR IGNORE INTO service_assertion_nonces (
                    audience, tenant_id, owner_id, nonce, issued_at_epoch,
                    expires_at_epoch, request_method, request_path, consumed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    audience,
                    tenant_id,
                    owner_id,
                    nonce,
                    int(issued_at_epoch),
                    int(expires_at_epoch),
                    str(request_method or "").upper(),
                    request_path,
                    utc_now(),
                ),
            )
            conn.execute("COMMIT")
        return cursor.rowcount == 1

    @staticmethod
    def _delegation_select() -> str:
        return """
            SELECT
                delegations.*,
                projects.status AS project_status,
                workers.state AS worker_state,
                workers.profile AS worker_profile,
                workers.execution_mode AS worker_execution_mode,
                workers.resource_class AS worker_resource_class,
                workers.resource_memory_bytes AS worker_resource_memory_bytes,
                workers.bootstrap_bundle_json AS worker_bootstrap_bundle_json,
                workers.workspace_dir AS worker_workspace_dir,
                workers.last_error AS worker_last_error,
                runs.run_id AS run_id,
                runs.state AS run_state,
                runs.queued_at AS run_queued_at,
                runs.first_queued_at AS run_first_queued_at,
                runs.queue_deadline_at AS run_queue_deadline_at,
                runs.queue_blocker_class AS run_queue_blocker_class,
                runs.queue_next_status_at AS run_queue_next_status_at,
                runs.queue_wait_episode AS run_queue_wait_episode,
                runs.queue_wait_open AS run_queue_wait_open,
                runs.queue_wait_generation AS run_queue_wait_generation,
                runs.queue_wait_started_at AS run_queue_wait_started_at,
                runs.queue_wait_closed_at AS run_queue_wait_closed_at,
                runs.queue_wait_duration_seconds AS run_queue_wait_duration_seconds,
                runs.queue_status_sequence AS run_queue_status_sequence,
                runs.queue_callback_state AS run_queue_callback_state,
                runs.queue_terminal_callback_id AS run_queue_terminal_callback_id,
                runs.claimed_at AS run_claimed_at,
                runs.admitted_at AS run_admitted_at,
                runs.started_at AS run_started_at,
                runs.runtime_invoked_at AS run_runtime_invoked_at,
                runs.ended_at AS run_ended_at,
                runs.output_text AS run_output_text,
                runs.error_text AS run_error_text,
                runs.failure_class AS run_failure_class,
                runs.failure_retryable AS run_failure_retryable,
                runs.failure_user_message AS run_failure_user_message,
                runs.failure_recommended_recovery AS run_failure_recommended_recovery
                , runs.retry_after AS run_retry_after
                , runs.native_session_id AS run_native_session_id
                , runs.native_capabilities_json AS run_native_capabilities_json
                , runs.native_child_summary_json AS run_native_child_summary_json
                , runs.capacity_class AS run_capacity_class
                , runs.capacity_available_json AS run_capacity_available_json
                , runs.capacity_required_json AS run_capacity_required_json
                , runs.capacity_shortage_json AS run_capacity_shortage_json
                , runs.capacity_reservation_json AS run_capacity_reservation_json
                , runs.capacity_next_retry_at AS run_capacity_next_retry_at
                , runs.provider_route_profile AS run_provider_route_profile
                , runs.provider_route_runtime AS run_provider_route_runtime
                , runs.provider_route_model AS run_provider_route_model
                , runs.provider_route_decision AS run_provider_route_decision
                , runs.provider_route_from_profile AS run_provider_route_from_profile
                , runs.provider_route_from_runtime AS run_provider_route_from_runtime
                , runs.provider_route_from_model AS run_provider_route_from_model
                , runs.provider_route_failure_class AS run_provider_route_failure_class
                , runs.provider_route_cooldown_until AS run_provider_route_cooldown_until
                , current_attempt.attempt_number AS run_attempt_number
                , current_attempt.claimed_at AS run_attempt_claimed_at
                , current_attempt.admitted_at AS run_attempt_admitted_at
                , current_attempt.runtime_invoked_at AS run_attempt_runtime_invoked_at
            FROM delegations
            JOIN projects ON projects.project_id = delegations.project_id
            JOIN workers ON workers.worker_id = delegations.worker_id
            LEFT JOIN runs ON runs.run_id = COALESCE(
                (
                    SELECT active_run.run_id
                    FROM runs AS active_run
                    WHERE active_run.worker_id = delegations.worker_id
                      AND active_run.state IN (
                          'running', 'admitted', 'claimed', 'settling',
                          'queued', 'paused', 'needs_input'
                      )
                    ORDER BY
                        CASE active_run.state
                            WHEN 'running' THEN 0
                            WHEN 'admitted' THEN 1
                            WHEN 'claimed' THEN 2
                            WHEN 'settling' THEN 3
                            WHEN 'paused' THEN 4
                            WHEN 'needs_input' THEN 5
                            ELSE 6
                        END,
                        active_run.queued_at DESC
                    LIMIT 1
                ),
                delegations.current_run_id
            )
            LEFT JOIN run_attempts AS current_attempt
              ON current_attempt.attempt_id = COALESCE(
                  NULLIF(runs.active_attempt_id, ''),
                  (
                      SELECT latest_attempt.attempt_id
                      FROM run_attempts AS latest_attempt
                      WHERE latest_attempt.run_id = runs.run_id
                      ORDER BY latest_attempt.attempt_number DESC
                      LIMIT 1
                  )
              )
        """

    @staticmethod
    def _work_trace_event_sha256(
        *,
        trace_event_id: str,
        run_id: str,
        work_ref: str,
        sequence: int,
        event_type: str,
        payload: dict[str, Any],
        previous_event_sha256: str,
        created_at: str,
    ) -> str:
        canonical = json.dumps(
            {
                "createdAt": str(created_at),
                "eventType": str(event_type),
                "payload": payload,
                "previousEventSha256": str(previous_event_sha256),
                "runId": str(run_id),
                "sequence": int(sequence),
                "traceEventId": str(trace_event_id),
                "workRef": str(work_ref),
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    def _append_work_trace_event_conn(
        self,
        conn: sqlite3.Connection,
        *,
        trace_event_id: str,
        run_id: str,
        work_ref: str,
        tenant_id: str,
        owner_id: str,
        event_type: str,
        payload: dict[str, Any],
        created_at: str,
    ) -> sqlite3.Row:
        existing = conn.execute(
            "SELECT * FROM work_trace_events WHERE trace_event_id = ?",
            (str(trace_event_id),),
        ).fetchone()
        if existing is not None:
            return existing
        previous = conn.execute(
            """
            SELECT sequence, event_sha256 FROM work_trace_events
            WHERE run_id = ? ORDER BY sequence DESC LIMIT 1
            """,
            (str(run_id),),
        ).fetchone()
        sequence = int(previous["sequence"] or 0) + 1 if previous else 1
        previous_sha = str(previous["event_sha256"] or "") if previous else ""
        payload_json = json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        event_sha = self._work_trace_event_sha256(
            trace_event_id=str(trace_event_id),
            run_id=str(run_id),
            work_ref=str(work_ref),
            sequence=sequence,
            event_type=str(event_type),
            payload=payload,
            previous_event_sha256=previous_sha,
            created_at=str(created_at),
        )
        conn.execute(
            """
            INSERT INTO work_trace_events (
                trace_event_id, run_id, work_ref, tenant_id, owner_id,
                sequence, event_type, payload_json, previous_event_sha256,
                event_sha256, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                str(trace_event_id),
                str(run_id),
                str(work_ref),
                str(tenant_id),
                str(owner_id),
                sequence,
                str(event_type),
                payload_json,
                previous_sha,
                event_sha,
                str(created_at),
            ),
        )
        inserted = conn.execute(
            "SELECT * FROM work_trace_events WHERE trace_event_id = ?",
            (str(trace_event_id),),
        ).fetchone()
        if inserted is None:
            raise RuntimeError("Work trace event insertion failed")
        return inserted

    def _work_trace_contract_version_conn(
        self, conn: sqlite3.Connection, run_id: str
    ) -> int:
        row = conn.execute(
            """
            SELECT payload_json FROM work_trace_events
            WHERE run_id = ? AND event_type = 'work.origin'
            ORDER BY sequence ASC LIMIT 1
            """,
            (str(run_id),),
        ).fetchone()
        if row is None:
            return 1
        try:
            payload = json.loads(str(row["payload_json"] or "{}"))
        except (TypeError, json.JSONDecodeError):
            return 1
        return 2 if payload.get("traceContractVersion") == 2 else 1

    def _append_runtime_invocation_trace_conn(
        self,
        conn: sqlite3.Connection,
        *,
        run: sqlite3.Row,
        attempt_id: str,
        invoked_at: str,
    ) -> None:
        scope = conn.execute(
            """
            SELECT delegations.work_ref, delegations.owner_id,
                   workers.profile, workers.runtime, workers.model
            FROM delegations
            JOIN workers ON workers.worker_id = delegations.worker_id
            WHERE delegations.worker_id = ?
              AND delegations.tenant_id = ?
            ORDER BY delegations.created_at ASC
            LIMIT 1
            """,
            (str(run["worker_id"]), str(run["tenant_id"] or "local")),
        ).fetchone()
        attempt = conn.execute(
            "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
            (str(attempt_id), str(run["run_id"])),
        ).fetchone()
        if scope is None or attempt is None:
            return
        profile = str(scope["profile"] or "")
        runtime = str(scope["runtime"] or "")
        model = str(scope["model"] or "")
        correlation = "\0".join(
            (
                str(run["run_id"]),
                str(attempt_id),
                str(attempt["attempt_number"] or 0),
                profile,
                runtime,
                model,
                str(invoked_at),
            )
        )
        invocation_ref = hashlib.sha256(correlation.encode("utf-8")).hexdigest()
        contract_version = self._work_trace_contract_version_conn(
            conn, str(run["run_id"])
        )
        trace_event_id = (
            "trace_runtime_" if contract_version == 2 else "trace_provider_"
        ) + hashlib.sha256(
            f"{run['run_id']}\0{attempt_id}".encode("utf-8")
        ).hexdigest()
        reference_key = (
            "runtimeInvocationRef"
            if contract_version == 2
            else "providerAttemptRef"
        )
        reference_prefix = (
            "runtime_invocation_sha256:"
            if contract_version == 2
            else "provider_attempt_sha256:"
        )
        self._append_work_trace_event_conn(
            conn,
            trace_event_id=trace_event_id,
            run_id=str(run["run_id"]),
            work_ref=str(scope["work_ref"]),
            tenant_id=str(run["tenant_id"] or "local"),
            owner_id=str(scope["owner_id"]),
            event_type=(
                "runtime.invoked" if contract_version == 2 else "provider.invoked"
            ),
            payload={
                "attemptNumber": int(attempt["attempt_number"] or 0),
                "model": model,
                "profile": profile,
                reference_key: f"{reference_prefix}{invocation_ref}",
                "runtime": runtime,
                "runtimeInvokedAt": str(invoked_at),
            },
            created_at=str(invoked_at),
        )

    def record_provider_authorization_preflight(
        self,
        run_id: str,
        *,
        provider: str,
        status: str,
        failure_class: str,
    ) -> dict[str, Any] | None:
        normalized_provider = str(provider or "").strip().lower()
        normalized_status = str(status or "").strip().lower()
        normalized_failure = str(failure_class or "").strip()
        if normalized_provider not in {"openai", "anthropic"}:
            raise ValueError("Provider authorization preflight provider is invalid")
        if normalized_status not in {
            "authorized",
            "needs_input",
            "retryable_failure",
            "rejected",
        }:
            raise ValueError("Provider authorization preflight status is invalid")
        if (normalized_status == "authorized") != (not normalized_failure):
            raise ValueError("Provider authorization preflight failure class is invalid")
        if len(normalized_failure) > 128 or any(
            ord(character) < 32 or ord(character) == 127
            for character in normalized_failure
        ):
            raise ValueError("Provider authorization preflight failure class is invalid")
        observed_at = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            if run is None or self._work_trace_contract_version_conn(conn, run_id) != 2:
                conn.execute("COMMIT")
                return None
            attempt_id = str(run["active_attempt_id"] or "")
            attempt = conn.execute(
                "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                (attempt_id, str(run_id)),
            ).fetchone()
            scope = self._work_trace_scope_conn(conn, str(run_id))
            if attempt is None or scope is None or attempt["ended_at"] is not None:
                conn.execute("ROLLBACK")
                return None
            correlation = "\0".join(
                (
                    str(run_id),
                    attempt_id,
                    str(attempt["attempt_number"] or 0),
                    normalized_provider,
                )
            )
            digest = hashlib.sha256(correlation.encode("utf-8")).hexdigest()
            trace_event_id = "trace_provider_preflight_" + digest
            preflight_ref = f"provider_authorization_preflight_sha256:{digest}"
            existing = conn.execute(
                "SELECT * FROM work_trace_events WHERE trace_event_id = ?",
                (trace_event_id,),
            ).fetchone()
            if existing is not None:
                try:
                    existing_payload = json.loads(str(existing["payload_json"]))
                except (TypeError, ValueError, json.JSONDecodeError):
                    existing_payload = None
                expected_payload = {
                    "attemptNumber": int(attempt["attempt_number"] or 0),
                    "failureClass": normalized_failure or None,
                    "provider": normalized_provider,
                    "providerAuthorizationPreflightRef": preflight_ref,
                    "status": normalized_status,
                }
                if (
                    str(existing["run_id"]) != str(run_id)
                    or str(existing["work_ref"]) != str(scope["work_ref"])
                    or str(existing["tenant_id"]) != str(run["tenant_id"] or "local")
                    or str(existing["owner_id"]) != str(scope["owner_id"])
                    or str(existing["event_type"])
                    != "provider.authorization_preflight"
                    or not isinstance(existing_payload, dict)
                    or any(
                        existing_payload.get(key) != value
                        for key, value in expected_payload.items()
                    )
                ):
                    conn.execute("ROLLBACK")
                    raise RuntimeError(
                        "Provider authorization preflight conflicts with immutable evidence"
                    )
                conn.execute("COMMIT")
                return self._row(existing)
            inserted = self._append_work_trace_event_conn(
                conn,
                trace_event_id=trace_event_id,
                run_id=str(run_id),
                work_ref=str(scope["work_ref"]),
                tenant_id=str(run["tenant_id"] or "local"),
                owner_id=str(scope["owner_id"]),
                event_type="provider.authorization_preflight",
                payload={
                    "attemptNumber": int(attempt["attempt_number"] or 0),
                    "failureClass": normalized_failure or None,
                    "observedAt": observed_at,
                    "provider": normalized_provider,
                    "providerAuthorizationPreflightRef": preflight_ref,
                    "status": normalized_status,
                },
                created_at=observed_at,
            )
            conn.execute("COMMIT")
        return self._row(inserted)

    @staticmethod
    def _work_trace_scope_conn(
        conn: sqlite3.Connection, run_id: str
    ) -> sqlite3.Row | None:
        return conn.execute(
            """
            SELECT delegations.work_ref, delegations.tenant_id,
                   delegations.owner_id
            FROM runs
            JOIN delegations
              ON delegations.worker_id = runs.worker_id
             AND delegations.project_id = runs.project_id
             AND delegations.tenant_id = runs.tenant_id
            WHERE runs.run_id = ?
            ORDER BY delegations.created_at ASC
            LIMIT 1
            """,
            (str(run_id),),
        ).fetchone()

    def _append_attempt_trace_conn(
        self,
        conn: sqlite3.Connection,
        *,
        attempt_id: str,
        created_at: str,
    ) -> None:
        attempt = conn.execute(
            "SELECT * FROM run_attempts WHERE attempt_id = ?", (str(attempt_id),)
        ).fetchone()
        if attempt is None:
            return
        scope = self._work_trace_scope_conn(conn, str(attempt["run_id"]))
        if scope is None:
            return
        lease_id = str(attempt["lease_id"] or "")
        payload = {
            "attemptRef": "attempt_sha256:"
            + hashlib.sha256(str(attempt_id).encode("utf-8")).hexdigest(),
            "attemptNumber": int(attempt["attempt_number"] or 0),
            "state": str(attempt["state"] or ""),
            "claimedAt": str(attempt["claimed_at"] or "") or None,
            "admittedAt": str(attempt["admitted_at"] or "") or None,
            "runtimeInvokedAt": str(attempt["runtime_invoked_at"] or "") or None,
            "endedAt": str(attempt["ended_at"] or "") or None,
            "terminalReason": str(attempt["terminal_reason"] or "") or None,
            "providerHealthObservedLastFailedAt": str(
                attempt["provider_health_observed_last_failed_at"] or ""
            )
            or None,
            "providerHealthObservedGeneration": (
                int(attempt["provider_health_observed_generation"])
                if attempt["provider_health_observed_generation"] is not None
                else None
            ),
            "leaseRef": (
                "lease_sha256:"
                + hashlib.sha256(lease_id.encode("utf-8")).hexdigest()
                if lease_id
                else None
            ),
        }
        identity = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        self._append_work_trace_event_conn(
            conn,
            trace_event_id="trace_attempt_"
            + hashlib.sha256(identity.encode("utf-8")).hexdigest(),
            run_id=str(attempt["run_id"]),
            work_ref=str(scope["work_ref"]),
            tenant_id=str(scope["tenant_id"] or "local"),
            owner_id=str(scope["owner_id"] or ""),
            event_type="lifecycle.attempt",
            payload=payload,
            created_at=str(created_at),
        )

    def _append_capacity_trace_conn(
        self,
        conn: sqlite3.Connection,
        *,
        capacity_attempt_id: str,
    ) -> None:
        row = conn.execute(
            "SELECT * FROM capacity_attempts WHERE capacity_attempt_id = ?",
            (str(capacity_attempt_id),),
        ).fetchone()
        if row is None:
            return
        scope = self._work_trace_scope_conn(conn, str(row["run_id"]))
        if scope is None:
            return

        def vector(raw: object) -> dict[str, int]:
            try:
                decoded = json.loads(str(raw or "{}"))
            except (TypeError, json.JSONDecodeError):
                decoded = {}
            return _capacity_vector(decoded if isinstance(decoded, dict) else {})

        payload = {
            "sequence": int(row["sequence"] or 0),
            "class": str(row["capacity_class"] or ""),
            "available": vector(row["available_json"]),
            "required": vector(row["required_json"]),
            "shortage": vector(row["shortage_json"]),
            "reservation": vector(row["reservation_json"]),
            "nextRetryAt": str(row["next_retry_at"] or "") or None,
            "observedAt": str(row["observed_at"] or ""),
        }
        self._append_work_trace_event_conn(
            conn,
            trace_event_id="trace_capacity_"
            + hashlib.sha256(str(capacity_attempt_id).encode("utf-8")).hexdigest(),
            run_id=str(row["run_id"]),
            work_ref=str(scope["work_ref"]),
            tenant_id=str(scope["tenant_id"] or "local"),
            owner_id=str(scope["owner_id"] or ""),
            event_type="capacity.observed",
            payload=payload,
            created_at=str(row["observed_at"] or utc_now()),
        )

    def _append_callback_trace_conn(
        self,
        conn: sqlite3.Connection,
        *,
        callback_id: str,
    ) -> None:
        row = conn.execute(
            "SELECT * FROM callback_outbox WHERE callback_id = ?",
            (str(callback_id),),
        ).fetchone()
        if row is None or not str(row["run_id"] or ""):
            return
        scope = self._work_trace_scope_conn(conn, str(row["run_id"]))
        if scope is None:
            return
        ledger = conn.execute(
            """
            SELECT * FROM callback_trace_events
            WHERE callback_id = ?
            ORDER BY callback_sequence DESC LIMIT 1
            """,
            (str(callback_id),),
        ).fetchone()
        if ledger is None:
            raise RuntimeError("Callback mutation has no immutable trace event")
        try:
            snapshot = json.loads(str(ledger["snapshot_json"] or "{}"))
        except (TypeError, json.JSONDecodeError) as exc:
            raise RuntimeError("Callback trace integrity check failed") from exc
        if not isinstance(snapshot, dict):
            raise RuntimeError("Callback trace integrity check failed")
        callback_ref = "callback_sha256:" + hashlib.sha256(
            str(callback_id).encode("utf-8")
        ).hexdigest()
        payload = {
            "callbackRef": callback_ref,
            "callbackRevision": int(ledger["callback_sequence"] or 0),
            "ledgerSequence": int(ledger["run_sequence"] or 0),
            "previousEventSha256": (
                "sha256:" + str(ledger["previous_event_sha256"])
                if str(ledger["previous_event_sha256"] or "")
                else None
            ),
            "eventSha256": "sha256:" + str(ledger["event_sha256"] or ""),
            "attemptNumber": (
                int(snapshot["attemptNumber"])
                if int(snapshot["attemptNumber"] or 0) > 0
                else None
            ),
            "event": str(snapshot["event"] or ""),
            "status": str(snapshot["status"] or ""),
            "attempts": int(snapshot["attempts"] or 0),
            "createdAt": str(snapshot["createdAt"] or ""),
            "updatedAt": str(snapshot["updatedAt"] or ""),
            "acceptedAt": str(snapshot["httpAcceptedAt"] or "") or None,
            "payloadSha256": str(ledger["payload_sha256"] or ""),
            "resultRevision": int(snapshot["resultRevision"] or 0),
            "resultDigest": str(snapshot["resultDigest"] or "") or None,
            "deliveryGeneration": int(snapshot["deliveryGeneration"] or 0),
            "authoritySha256": str(ledger["authority_sha256"] or ""),
        }
        self._append_work_trace_event_conn(
            conn,
            trace_event_id="trace_callback_"
            + str(ledger["event_sha256"] or ""),
            run_id=str(row["run_id"]),
            work_ref=str(scope["work_ref"]),
            tenant_id=str(scope["tenant_id"] or "local"),
            owner_id=str(scope["owner_id"] or ""),
            event_type="callback.delivery",
            payload=payload,
            created_at=str(row["updated_at"] or utc_now()),
        )

    @staticmethod
    def _canonical_artifact_refs(artifact_refs: dict[str, Any]) -> dict[str, Any]:
        if set(artifact_refs) != {"available", "refs", "overflowCount"}:
            raise ValueError("Artifact trace shape is invalid")
        available = artifact_refs.get("available")
        refs = artifact_refs.get("refs")
        overflow = artifact_refs.get("overflowCount")
        if (
            not isinstance(available, bool)
            or not isinstance(refs, list)
            or len(refs) > 16
            or isinstance(overflow, bool)
            or not isinstance(overflow, int)
            or overflow < 0
        ):
            raise ValueError("Artifact trace shape is invalid")
        canonical_refs: list[dict[str, Any]] = []
        for item in refs:
            if not isinstance(item, dict) or set(item) != {
                "artifactRef",
                "fingerprint",
                "kind",
                "state",
                "sizeBytes",
            }:
                raise ValueError("Artifact trace shape is invalid")
            artifact_ref = str(item.get("artifactRef") or "")
            fingerprint = str(item.get("fingerprint") or "")
            size_bytes = item.get("sizeBytes")
            if (
                len(artifact_ref) != len("artifact_sha256:") + 64
                or not artifact_ref.startswith("artifact_sha256:")
                or len(fingerprint) != len("sha256:") + 64
                or not fingerprint.startswith("sha256:")
                or artifact_ref.removeprefix("artifact_sha256:")
                != fingerprint.removeprefix("sha256:")
                or any(
                    character not in "0123456789abcdef"
                    for character in fingerprint.removeprefix("sha256:")
                )
                or str(item.get("kind") or "") not in {
                    "artifact", "archive", "audio", "code", "document", "file",
                    "html", "image", "json", "report", "text", "video", "webpage",
                }
                or str(item.get("state") or "") not in {
                    "available", "completed", "missing", "ready", "unavailable"
                }
                or (
                    size_bytes is not None
                    and (
                        isinstance(size_bytes, bool)
                        or not isinstance(size_bytes, int)
                        or size_bytes < 0
                    )
                )
            ):
                raise ValueError("Artifact trace shape is invalid")
            canonical_refs.append(dict(item))
        return {
            "available": available,
            "refs": canonical_refs,
            "overflowCount": overflow,
        }

    def _record_artifact_trace_conn(
        self,
        conn: sqlite3.Connection,
        *,
        run_id: str,
        artifact_refs: dict[str, Any],
        observed_at: str,
        only_if_missing: bool = False,
        terminal: bool = False,
    ) -> dict[str, Any] | None:
        artifact_refs = self._canonical_artifact_refs(artifact_refs)
        scope = self._work_trace_scope_conn(conn, str(run_id))
        if scope is None:
            return None
        latest = conn.execute(
            """
            SELECT payload_json FROM work_trace_events
            WHERE run_id = ? AND event_type = 'artifact.observed'
            ORDER BY sequence DESC LIMIT 1
            """,
            (str(run_id),),
        ).fetchone()
        if latest is not None:
            try:
                previous = json.loads(str(latest["payload_json"] or "{}"))
            except (TypeError, json.JSONDecodeError):
                previous = None
            previous_terminal = bool(
                isinstance(previous, dict) and previous.get("terminal") is True
            )
            if (
                only_if_missing
                and previous_terminal == bool(terminal)
            ) or (
                isinstance(previous, dict)
                and previous.get("artifactRefs") == artifact_refs
                and previous_terminal == bool(terminal)
            ):
                return dict(previous) if isinstance(previous, dict) else None
        previous_head = conn.execute(
            "SELECT event_sha256 FROM work_trace_events WHERE run_id = ? "
            "ORDER BY sequence DESC LIMIT 1",
            (str(run_id),),
        ).fetchone()
        payload = {
            "artifactRefs": artifact_refs,
            "observedAt": observed_at,
            "terminal": bool(terminal),
        }
        identity = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        event = self._append_work_trace_event_conn(
            conn,
            trace_event_id="trace_artifact_"
            + hashlib.sha256(
                (
                    str(previous_head["event_sha256"] if previous_head else "")
                    + "\0"
                    + identity
                ).encode("utf-8")
            ).hexdigest(),
            run_id=str(run_id),
            work_ref=str(scope["work_ref"]),
            tenant_id=str(scope["tenant_id"] or "local"),
            owner_id=str(scope["owner_id"] or ""),
            event_type="artifact.observed",
            payload=payload,
            created_at=observed_at,
        )
        return json.loads(str(event["payload_json"]))

    def _record_terminal_artifact_trace_conn(
        self,
        conn: sqlite3.Connection,
        *,
        run_id: str,
        observed_at: str,
        artifact_refs: dict[str, Any] | None = None,
        only_if_missing: bool = False,
    ) -> dict[str, Any] | None:
        run = conn.execute(
            "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
        ).fetchone()
        if run is None or str(run["state"] or "") not in TERMINAL_RUN_STATES:
            return None
        worker = conn.execute(
            "SELECT * FROM workers WHERE worker_id = ?", (run["worker_id"],)
        ).fetchone()
        final_refs = (
            artifact_refs
            if artifact_refs is not None
            else work_artifact_observation(
                artifact_worker_context(conn, self._row(worker), files=getattr(self, "_workspace_files_adapter", None)),
                self._row(run),
                output_text=str(run["output_text"] or ""),
                error_text=str(run["error_text"] or ""),
            )
        )
        return self._record_artifact_trace_conn(
            conn,
            run_id=str(run_id),
            artifact_refs=final_refs,
            observed_at=str(observed_at),
            only_if_missing=only_if_missing,
            terminal=True,
        )

    def record_artifact_trace(
        self,
        *,
        run_id: str,
        tenant_id: str,
        owner_id: str,
        artifact_refs: dict[str, Any],
    ) -> dict[str, Any]:
        """Append one explicit observation outside a lifecycle transition."""

        observed_at = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            scope = self._work_trace_scope_conn(conn, str(run_id))
            if (
                scope is None
                or str(scope["tenant_id"] or "local") != str(tenant_id)
                or str(scope["owner_id"] or "") != str(owner_id)
            ):
                conn.execute("ROLLBACK")
                raise KeyError("Active work not found")
            payload = self._record_artifact_trace_conn(
                conn,
                run_id=str(run_id),
                artifact_refs=artifact_refs,
                observed_at=observed_at,
            )
            conn.execute("COMMIT")
        if payload is None:
            raise RuntimeError("Artifact observation could not be persisted")
        return payload

    def list_terminal_runs_missing_artifact_observation(
        self, *, limit: int = 100
    ) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT runs.run_id, runs.worker_id
                FROM runs
                WHERE runs.state IN ('completed', 'failed', 'cancelled', 'interrupted')
                  AND EXISTS (
                      SELECT 1 FROM delegations
                      WHERE delegations.worker_id = runs.worker_id
                        AND delegations.project_id = runs.project_id
                        AND delegations.tenant_id = runs.tenant_id
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM work_trace_events
                      WHERE work_trace_events.run_id = runs.run_id
                        AND work_trace_events.event_type = 'artifact.observed'
                        AND COALESCE(
                            json_extract(work_trace_events.payload_json, '$.terminal'),
                            0
                        ) = 1
                  )
                ORDER BY runs.ended_at ASC, runs.run_id ASC
                LIMIT ?
                """,
                (max(1, min(int(limit), 1000)),),
            ).fetchall()
        return self._rows(rows)

    def reconcile_terminal_artifact_observation(
        self, *, run_id: str, artifact_refs: dict[str, Any]
    ) -> bool:
        observed_at = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT state, ended_at FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            if run is None or str(run["state"] or "") not in TERMINAL_RUN_STATES:
                conn.execute("COMMIT")
                return False
            if str(run["ended_at"] or "") > observed_at:
                observed_at = str(run["ended_at"])
            existing = conn.execute(
                "SELECT 1 FROM work_trace_events WHERE run_id = ? "
                "AND event_type = 'artifact.observed' "
                "AND COALESCE(json_extract(payload_json, '$.terminal'), 0) = 1 "
                "LIMIT 1",
                (str(run_id),),
            ).fetchone()
            if existing is not None:
                conn.execute("COMMIT")
                return False
            payload = self._record_terminal_artifact_trace_conn(
                conn,
                run_id=str(run_id),
                artifact_refs=artifact_refs,
                observed_at=observed_at,
                only_if_missing=True,
            )
            conn.execute("COMMIT")
        return payload is not None

    def reserve_delegation(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        idempotency_key: str,
        request_digest: str,
        origin_ref: str,
        title: str,
        goal: str,
        instruction: str,
        origin_surface: str,
        origin_scope: dict[str, Any] | None = None,
        worker_name: str,
        worker_role: str,
        profile: str,
        backend: str,
        runtime: str,
        model: str,
        execution_mode: str,
        resource_class: str = "standard",
        resource_memory_bytes: int | None = None,
        alias: str | None = None,
        workspace_root: str | None = None,
        bootstrap_profile: str | None = None,
        bootstrap_bundle: dict[str, Any] | None = None,
        file_manifest: list[dict] | None = None,
        require_isolated_parallel_ready: bool = False,
        preaccept_host_lease: dict[str, Any] | None = None,
        queue_on_capacity: bool = False,
        trace_context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        origin_scope_payload, origin_scope_json = _canonical_origin_scope(
            origin_scope,
            tenant_id=tenant_id,
            owner_id=owner_id,
        )
        clean_resource_class, clean_resource_memory_bytes = _worker_resource_values(
            resource_class,
            resource_memory_bytes,
        )
        if is_parallel_clean_room_bootstrap(
            bootstrap_profile, bootstrap_bundle
        ):
            bootstrap_bundle = canonical_parallel_clean_room_bootstrap(
                bootstrap_bundle
            )
        trace_bundle = bootstrap_bundle if isinstance(bootstrap_bundle, dict) else {}
        trace_identity = trace_bundle.get("viventium_delegation_identity")
        if not isinstance(trace_identity, dict):
            trace_identity = {}
        trace_delegation_context = trace_bundle.get("viventium_delegation_context")
        if not isinstance(trace_delegation_context, dict):
            trace_delegation_context = {}
        source_event_id = str(
            trace_delegation_context.get("source_event_id")
            or trace_identity.get("source_event_id")
            or ""
        ).strip()
        source_revision_value = trace_delegation_context.get("source_revision", 1)
        source_revision = (
            int(source_revision_value)
            if isinstance(source_revision_value, int)
            and not isinstance(source_revision_value, bool)
            and source_revision_value > 0
            else 1
        )
        prompt_layers = (
            trace_context.get("promptLayers")
            if isinstance(trace_context, dict)
            else None
        )
        if not isinstance(prompt_layers, dict):
            prompt_layers = {
                "contractVersion": 1,
                "producerScope": "glasshive.worker_prompt_registry",
                "layerNames": [],
                "unknownLayerNames": ["unrecorded"],
            }
        now = utc_now()
        work_ref = f"work_{uuid.uuid4().hex}"
        project_id = f"prj_{uuid.uuid4().hex[:10]}"
        worker_id = f"wrk_{uuid.uuid4().hex[:10]}"
        run_id = f"run_{uuid.uuid4().hex[:10]}"
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            if require_isolated_parallel_ready:
                active_host = int(
                    conn.execute(
                        """
                        SELECT COUNT(DISTINCT worker_id)
                        FROM (
                            SELECT workers.worker_id AS worker_id
                            FROM workers
                            JOIN runs ON runs.worker_id = workers.worker_id
                            WHERE workers.execution_mode = 'host'
                              AND workers.trusted_run_lane = 'mission'
                              AND runs.state IN (
                                  'queued', 'running', 'settling', 'paused', 'needs_input'
                              )
                            UNION
                            SELECT leases.worker_id AS worker_id
                            FROM host_run_leases AS leases
                            JOIN workers ON workers.worker_id = leases.worker_id
                            WHERE leases.status = 'active'
                              AND workers.execution_mode = 'host'
                              AND workers.trusted_run_lane = 'mission'
                        ) AS active_host_missions
                        """
                    ).fetchone()[0]
                    or 0
                )
                if active_host:
                    conn.execute("ROLLBACK")
                    raise IsolatedParallelAdmissionConflictError(
                        "Existing host-native mission work blocks isolated Parallel admission."
                    )
            existing = conn.execute(
                """
                SELECT * FROM delegations
                WHERE tenant_id = ? AND owner_id = ? AND idempotency_key = ?
                """,
                (tenant_id, owner_id, idempotency_key),
            ).fetchone()
            if existing is not None:
                if str(existing["request_digest"] or "") != request_digest:
                    conn.execute("ROLLBACK")
                    raise DelegationIdempotencyConflictError(
                        "The delegation idempotency key was reused with a different request."
                    )
                existing_ref = str(existing["work_ref"])
                conn.execute("COMMIT")
                record = self.get_delegation(existing_ref, tenant_id=tenant_id, owner_id=owner_id)
                if not record:
                    raise RuntimeError("The prior delegation reservation is unavailable")
                return {**record, "idempotent_replay": True}

            if origin_ref:
                origin_binding = conn.execute(
                    """
                    SELECT work_ref FROM delegations
                    WHERE tenant_id = ? AND owner_id = ? AND origin_ref = ?
                    """,
                    (tenant_id, owner_id, origin_ref),
                ).fetchone()
                if origin_binding is not None:
                    conn.execute("ROLLBACK")
                    raise DelegationIdempotencyConflictError(
                        "The delegation origin reference is already bound to other work."
                    )

            if origin_scope_payload:
                origin_project = conn.execute(
                    "SELECT project_id FROM projects WHERE project_id = ? "
                    "AND tenant_id = ? AND owner_id = ?",
                    (
                        origin_scope_payload["project_id"],
                        tenant_id,
                        owner_id,
                    ),
                ).fetchone()
                if origin_project is None:
                    conn.execute("ROLLBACK")
                    raise ValueError("Origin project scope is unavailable")
                origin_workspace_id = str(
                    origin_scope_payload.get("workspace_id") or ""
                )
                if origin_workspace_id:
                    origin_workspace = conn.execute(
                        "SELECT workspace_id FROM execution_workspaces "
                        "WHERE workspace_id = ? AND project_id = ? "
                        "AND tenant_id = ? AND owner_id = ?",
                        (
                            origin_workspace_id,
                            origin_scope_payload["project_id"],
                            tenant_id,
                            owner_id,
                        ),
                    ).fetchone()
                    if origin_workspace is None:
                        conn.execute("ROLLBACK")
                        raise ValueError("Origin workspace scope is unavailable")

            host_lease: dict[str, Any] | None = None
            initial_capacity_attempt: dict[str, Any] | None = None
            if preaccept_host_lease is not None:
                current = datetime.now(timezone.utc)
                lease_ttl_s = max(
                    1.0, float(preaccept_host_lease.get("lease_ttl_s") or 1.0)
                )
                next_retry_at = str(
                    preaccept_host_lease.get("capacity_next_retry_at") or ""
                ).strip()
                try:
                    self._assert_preaccept_host_lease_capacity(
                        conn,
                        runtime_family=str(
                            preaccept_host_lease.get("runtime_family") or "host"
                        ),
                        lane=str(preaccept_host_lease.get("lane") or "mission"),
                        tenant_id=tenant_id,
                        owner_id=owner_id,
                        run_id=run_id,
                        conversation_limit=int(
                            preaccept_host_lease.get("conversation_limit") or 1
                        ),
                        mission_limit=int(
                            preaccept_host_lease.get("mission_limit") or 1
                        ),
                        account_mission_limit=int(
                            preaccept_host_lease.get("account_mission_limit") or 1
                        ),
                        tenant_mission_limit=int(
                            preaccept_host_lease.get("tenant_mission_limit") or 1
                        ),
                        mutation_scope=str(
                            preaccept_host_lease.get("mutation_scope") or ""
                        ),
                        capacity_available=preaccept_host_lease.get(
                            "capacity_available"
                        ),
                        capacity_required=preaccept_host_lease.get(
                            "capacity_required"
                        ),
                        capacity_reservation=preaccept_host_lease.get(
                            "capacity_reservation"
                        ),
                        capacity_observed_lease_ids=preaccept_host_lease.get(
                            "capacity_observed_lease_ids"
                        ),
                        capacity_next_retry_at=next_retry_at,
                    )
                except HostRunLeaseCapacityError:
                    if not queue_on_capacity:
                        raise
                    preaccept_host_lease = None
            if preaccept_host_lease is not None:
                reservation = _capacity_vector(
                    preaccept_host_lease.get("capacity_reservation")
                )
                available = _capacity_vector(
                    preaccept_host_lease.get("capacity_available")
                )
                required = _capacity_vector(
                    preaccept_host_lease.get("capacity_required")
                )
                shortage = {
                    key: max(0, required[key] + reservation[key] - available[key])
                    for key in CAPACITY_RESOURCE_KEYS
                }
                acquired_at = current.isoformat()
                host_lease = {
                    "lease_id": f"hrl_{uuid.uuid4().hex}",
                    "runtime_family": str(
                        preaccept_host_lease.get("runtime_family") or "host"
                    ).strip().lower(),
                    "lane": (
                        "conversation"
                        if str(preaccept_host_lease.get("lane") or "")
                        .strip()
                        .lower()
                        == "conversation"
                        else "mission"
                    ),
                    "tenant_id": tenant_id,
                    "owner_id": owner_id,
                    "worker_id": worker_id,
                    "run_id": run_id,
                    "executor_id": str(
                        preaccept_host_lease.get("executor_id") or ""
                    ),
                    "pid": None,
                    "process_group": None,
                    "process_start_identity": "",
                    "startup_token": f"start_{uuid.uuid4().hex}",
                    "startup_state": "reserved",
                    "startup_confirmed_at": None,
                    "startup_identity_kind": "",
                    "startup_container_id": "",
                    "startup_session_id": "",
                    "mutation_scope": str(
                        preaccept_host_lease.get("mutation_scope") or ""
                    ).strip(),
                    "attempt_id": "",
                    "reserved_child_processes": reservation["childProcesses"],
                    "reserved_threads": reservation["threads"],
                    "reserved_memory_bytes": reservation["memoryBytes"],
                    "reserved_disk_bytes": reservation["diskBytes"],
                    "status": "active",
                    "acquired_at": acquired_at,
                    "heartbeat_at": acquired_at,
                    "expires_at": (
                        current + timedelta(seconds=lease_ttl_s)
                    ).isoformat(),
                    "reconciled_at": None,
                    "released_at": None,
                    "release_reason": "",
                }
                initial_capacity_attempt = {
                    "capacity_attempt_id": "cap_"
                    + hashlib.sha256(f"{run_id}:1".encode("utf-8")).hexdigest(),
                    "run_id": run_id,
                    "sequence": 1,
                    "attempt_id": "",
                    "capacity_class": "worker_launch",
                    "available_json": _capacity_json(available),
                    "required_json": _capacity_json(required),
                    "shortage_json": _capacity_json(shortage),
                    "reservation_json": _capacity_json(reservation),
                    "next_retry_at": next_retry_at or None,
                    "observed_at": acquired_at,
                }

            project = {
                "project_id": project_id,
                "tenant_id": tenant_id,
                "owner_id": owner_id,
                "title": title,
                "goal": goal,
                "status": "active",
                "summary": "",
                "default_worker_profile": profile,
                "origin_scope_json": origin_scope_json,
                "created_at": now,
                "updated_at": now,
            }
            conn.execute(
                """
                INSERT INTO projects (
                    project_id, tenant_id, owner_id, title, goal, status, summary,
                    default_worker_profile, origin_scope_json, created_at, updated_at
                ) VALUES (
                    :project_id, :tenant_id, :owner_id, :title, :goal, :status, :summary,
                    :default_worker_profile, :origin_scope_json, :created_at, :updated_at
                )
                """,
                project,
            )
            worker = {
                "worker_id": worker_id,
                "workspace_id": f"wsp_{worker_id}",
                "project_id": project_id,
                "tenant_id": tenant_id,
                "owner_id": owner_id,
                "name": worker_name,
                "role": worker_role,
                "profile": profile,
                "backend": backend,
                "execution_mode": execution_mode,
                "trusted_run_lane": "mission",
                "resource_class": clean_resource_class,
                "resource_memory_bytes": clean_resource_memory_bytes,
                "alias": alias,
                "runtime": runtime,
                "model": model,
                "origin_scope_json": origin_scope_json,
                "state": "created",
                "bootstrap_profile": bootstrap_profile,
                "bootstrap_bundle_json": json.dumps(bootstrap_bundle) if bootstrap_bundle else None,
                "gateway_url": None,
                "takeover_url": f"/ui/workers/{worker_id}",
                "control_url": f"/ui/workers/{worker_id}",
                "gateway_port": None,
                "gateway_token": None,
                "session_key": None,
                "state_dir": None,
                "workspace_dir": None,
                "workspace_root": workspace_root,
                "favorite": 0,
                "compute_released_at": None,
                "pid": None,
                "last_run_id": run_id,
                "last_error": None,
                "created_at": now,
                "updated_at": now,
            }
            self._insert_isolated_workspace(conn, worker)
            conn.execute(
                """
                INSERT INTO workers (
                    worker_id, workspace_id, project_id, tenant_id, owner_id, name, role, profile,
                    backend, execution_mode, trusted_run_lane, resource_class,
                    resource_memory_bytes, alias, runtime, model, state,
                    bootstrap_profile, bootstrap_bundle_json, gateway_url, takeover_url,
                    control_url, gateway_port, gateway_token, session_key, state_dir,
                    workspace_dir, workspace_root, favorite, origin_scope_json, compute_released_at, pid,
                    last_run_id, last_error, created_at, updated_at
                ) VALUES (
                    :worker_id, :workspace_id, :project_id, :tenant_id, :owner_id, :name, :role, :profile,
                    :backend, :execution_mode, :trusted_run_lane, :resource_class,
                    :resource_memory_bytes, :alias, :runtime, :model, :state,
                    :bootstrap_profile, :bootstrap_bundle_json, :gateway_url, :takeover_url,
                    :control_url, :gateway_port, :gateway_token, :session_key, :state_dir,
                    :workspace_dir, :workspace_root, :favorite, :origin_scope_json, :compute_released_at, :pid,
                    :last_run_id, :last_error, :created_at, :updated_at
                )
                """,
                worker,
            )
            accepted_files = [dict(item) for item in (file_manifest or [])]
            if accepted_files:
                from .workspace_files import WorkspaceFiles
                file_adapter = getattr(self, "_workspace_files_adapter", None) or WorkspaceFiles(self)
                for item in accepted_files:
                    item["path"] = f"inputs/{run_id}/{item['upload_id']}/{item.get('relative_path') or item['name']}"
                file_adapter.scope_manifest(worker, accepted_files, connection=conn)
                file_adapter.reserve_projection_manifest(conn, tenant_id, owner_id, accepted_files)
                pin_file_manifest(conn, kind="run", reference_id=run_id,
                    tenant_id=tenant_id, owner_id=owner_id, manifest=accepted_files)
                conn.execute("INSERT INTO workspace_file_run_inputs (run_id,manifest_json) VALUES (?,?)",
                    (run_id, json.dumps(accepted_files, sort_keys=True)))
            run = {
                **_queue_defaults(now, run_id=run_id),
                "run_id": run_id,
                "worker_id": worker_id,
                "project_id": project_id,
                "tenant_id": tenant_id,
                "instruction": instruction,
                "state": "queued",
                "origin_scope_json": origin_scope_json,
                "queued_at": now,
                "started_at": None,
                "ended_at": None,
                "output_text": "",
                "error_text": "",
                "failure_class": "",
                "failure_retryable": 0,
                "failure_structured": 0,
                "failure_user_message": "",
                "failure_recommended_recovery": "",
                "failure_diagnostic_summary": "",
                "retry_after": None,
                "retry_attempts": 0,
                "last_retry_class": "",
            }
            conn.execute(
                """
                INSERT INTO runs (
                    run_id, worker_id, project_id, tenant_id, instruction, state,
                    origin_scope_json,
                    queued_at, first_queued_at, queue_deadline_at,
                    queue_blocker_class, queue_next_status_at, queue_wait_episode,
                    queue_wait_open, queue_wait_generation, queue_wait_started_at,
                    queue_wait_closed_at, queue_wait_duration_seconds,
                    queue_transition_emitted,
                    queue_status_sequence, queue_callback_state,
                    queue_terminal_callback_id,
                    started_at, ended_at, output_text, error_text,
                    failure_class, failure_retryable, failure_structured,
                    failure_user_message, failure_recommended_recovery,
                    failure_diagnostic_summary, retry_after, retry_attempts,
                    last_retry_class
                ) VALUES (
                    :run_id, :worker_id, :project_id, :tenant_id, :instruction, :state,
                    :origin_scope_json,
                    :queued_at, :first_queued_at, :queue_deadline_at,
                    :queue_blocker_class, :queue_next_status_at,
                    :queue_wait_episode, :queue_wait_open,
                    :queue_wait_generation, :queue_wait_started_at,
                    :queue_wait_closed_at, :queue_wait_duration_seconds,
                    :queue_transition_emitted, :queue_status_sequence,
                    :queue_callback_state, :queue_terminal_callback_id,
                    :started_at, :ended_at, :output_text, :error_text,
                    :failure_class, :failure_retryable, :failure_structured,
                    :failure_user_message, :failure_recommended_recovery,
                    :failure_diagnostic_summary, :retry_after, :retry_attempts,
                    :last_retry_class
                )
                """,
                run,
            )
            delegation = {
                "work_ref": work_ref,
                "tenant_id": tenant_id,
                "owner_id": owner_id,
                "idempotency_key": idempotency_key,
                "request_digest": request_digest,
                "origin_ref": origin_ref,
                "origin_scope_json": origin_scope_json,
                "title": title,
                "origin_surface": origin_surface,
                "project_id": project_id,
                "worker_id": worker_id,
                "initial_run_id": run_id,
                "current_run_id": run_id,
                "dismissed_at": None,
                "created_at": now,
                "updated_at": now,
            }
            conn.execute(
                """
                INSERT INTO delegations (
                    work_ref, tenant_id, owner_id, idempotency_key, request_digest,
                    origin_ref, origin_scope_json, title, origin_surface, project_id, worker_id, initial_run_id,
                    current_run_id, dismissed_at, created_at, updated_at
                ) VALUES (
                    :work_ref, :tenant_id, :owner_id, :idempotency_key, :request_digest,
                    :origin_ref, :origin_scope_json, :title, :origin_surface, :project_id, :worker_id, :initial_run_id,
                    :current_run_id, :dismissed_at, :created_at, :updated_at
                )
                """,
                delegation,
            )
            origin_payload: dict[str, Any] = {
                "surface": str(origin_surface or "web"),
                "sourceRevision": source_revision,
                "resourceClass": clean_resource_class,
                "resourceReservation": {
                    "memoryBytes": clean_resource_memory_bytes,
                },
            }
            if origin_ref:
                origin_payload["originRef"] = "origin_sha256:" + hashlib.sha256(
                    str(origin_ref).encode("utf-8")
                ).hexdigest()
            if source_event_id:
                origin_payload["sourceEventRef"] = (
                    "source_sha256:"
                    + hashlib.sha256(source_event_id.encode("utf-8")).hexdigest()
                )
            self._append_work_trace_event_conn(
                conn,
                trace_event_id="trace_origin_"
                + hashlib.sha256(str(run_id).encode("utf-8")).hexdigest(),
                run_id=run_id,
                work_ref=work_ref,
                tenant_id=tenant_id,
                owner_id=owner_id,
                event_type="work.origin",
                payload={
                    "traceContractVersion": 2,
                    "origin": origin_payload,
                    "promptLayers": prompt_layers,
                },
                created_at=now,
            )
            if host_lease is not None:
                conn.execute(
                    """
                    INSERT INTO host_run_leases (
                        lease_id, runtime_family, lane, tenant_id, owner_id,
                        worker_id, run_id, executor_id, pid, process_group,
                        process_start_identity, startup_token, startup_state,
                        startup_confirmed_at, startup_identity_kind,
                        startup_container_id, startup_session_id,
                        mutation_scope, attempt_id, reserved_child_processes,
                        reserved_threads, reserved_memory_bytes,
                        reserved_disk_bytes, status, acquired_at, heartbeat_at,
                        expires_at, reconciled_at, released_at, release_reason
                    ) VALUES (
                        :lease_id, :runtime_family, :lane, :tenant_id, :owner_id,
                        :worker_id, :run_id, :executor_id, :pid, :process_group,
                        :process_start_identity, :startup_token, :startup_state,
                        :startup_confirmed_at, :startup_identity_kind,
                        :startup_container_id, :startup_session_id,
                        :mutation_scope, :attempt_id, :reserved_child_processes,
                        :reserved_threads, :reserved_memory_bytes,
                        :reserved_disk_bytes, :status, :acquired_at, :heartbeat_at,
                        :expires_at, :reconciled_at, :released_at, :release_reason
                    )
                    """,
                    host_lease,
                )
            if initial_capacity_attempt is not None:
                conn.execute(
                    """
                    INSERT INTO capacity_attempts (
                        capacity_attempt_id, run_id, sequence, attempt_id,
                        capacity_class, available_json, required_json,
                        shortage_json, reservation_json, next_retry_at, observed_at
                    ) VALUES (
                        :capacity_attempt_id, :run_id, :sequence, :attempt_id,
                        :capacity_class, :available_json, :required_json,
                        :shortage_json, :reservation_json, :next_retry_at, :observed_at
                    )
                    """,
                    initial_capacity_attempt,
                )
                self._append_capacity_trace_conn(
                    conn,
                    capacity_attempt_id=str(
                        initial_capacity_attempt["capacity_attempt_id"]
                    ),
                )
            for event_type, event_run_id, message in (
                ("worker.created", None, f"Worker {worker_name} created"),
                ("run.queued", run_id, instruction),
            ):
                conn.execute(
                    """
                    INSERT INTO events (
                        event_id, project_id, worker_id, tenant_id, run_id,
                        event_type, message, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        f"evt_{uuid.uuid4().hex[:12]}",
                        project_id,
                        worker_id,
                        tenant_id,
                        event_run_id,
                        event_type,
                        message,
                        now,
                    ),
                )
            conn.execute("COMMIT")
        record = self.get_delegation(work_ref, tenant_id=tenant_id, owner_id=owner_id)
        if not record:
            raise RuntimeError("The delegation reservation was not readable after commit")
        return {**record, "idempotent_replay": False}

    def get_delegation(
        self,
        work_ref: str,
        *,
        tenant_id: str,
        owner_id: str,
    ) -> dict[str, Any] | None:
        query = self._delegation_select() + """
            WHERE delegations.work_ref = ?
              AND delegations.tenant_id = ?
              AND delegations.owner_id = ?
            LIMIT 1
        """
        with self._connect() as conn:
            row = conn.execute(query, (work_ref, tenant_id, owner_id)).fetchone()
        return self._row(row)

    def get_delegation_by_idempotency_key(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        idempotency_key: str,
    ) -> dict[str, Any] | None:
        """Read one committed reservation without consulting mutable admission state."""

        query = self._delegation_select() + """
            WHERE delegations.tenant_id = ?
              AND delegations.owner_id = ?
              AND delegations.idempotency_key = ?
            LIMIT 1
        """
        with self._connect() as conn:
            row = conn.execute(
                query,
                (tenant_id, owner_id, idempotency_key),
            ).fetchone()
        return self._row(row)

    def list_active_delegations(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        limit: int = 50,
        before: tuple[str, str, str] | None = None,
    ) -> list[dict[str, Any]]:
        terminal_cutoff = (
            datetime.now(timezone.utc)
            - timedelta(seconds=_active_work_terminal_recency_seconds())
        ).isoformat()
        terminal_per_state = _active_work_terminal_per_state_limit()
        query = self._delegation_select() + """
            WHERE delegations.tenant_id = ?
              AND delegations.owner_id = ?
              AND delegations.dismissed_at IS NULL
              AND (
                    COALESCE(runs.state, 'queued') NOT IN ('completed', 'failed', 'cancelled')
                 OR (
                        COALESCE(runs.ended_at, delegations.updated_at) >= ?
                    AND (
                        SELECT COUNT(*)
                        FROM delegations AS newer_delegations
                        JOIN runs AS newer_runs
                          ON newer_runs.run_id = newer_delegations.current_run_id
                        WHERE newer_delegations.tenant_id = delegations.tenant_id
                          AND newer_delegations.owner_id = delegations.owner_id
                          AND newer_delegations.dismissed_at IS NULL
                          AND newer_runs.state = runs.state
                          AND (
                                newer_delegations.updated_at > delegations.updated_at
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at > delegations.created_at
                             )
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at = delegations.created_at
                                AND newer_delegations.work_ref > delegations.work_ref
                             )
                          )
                    ) < ?
                 )
              )
        """
        params: list[Any] = [tenant_id, owner_id, terminal_cutoff, terminal_per_state]
        if before is not None:
            updated_at, created_at, work_ref = before
            query += """
              AND (
                    delegations.updated_at < ?
                 OR (delegations.updated_at = ? AND delegations.created_at < ?)
                 OR (
                        delegations.updated_at = ?
                    AND delegations.created_at = ?
                    AND delegations.work_ref < ?
                 )
              )
            """
            params.extend(
                [updated_at, updated_at, created_at, updated_at, created_at, work_ref]
            )
        query += """
            ORDER BY delegations.updated_at DESC, delegations.created_at DESC,
                     delegations.work_ref DESC
            LIMIT ?
        """
        params.append(max(1, min(int(limit), 100)))
        with self._connect() as conn:
            rows = conn.execute(query, params).fetchall()
        return self._rows(rows)

    def count_active_delegations(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        before: tuple[str, str, str] | None = None,
    ) -> int:
        terminal_cutoff = (
            datetime.now(timezone.utc)
            - timedelta(seconds=_active_work_terminal_recency_seconds())
        ).isoformat()
        terminal_per_state = _active_work_terminal_per_state_limit()
        query = """
            SELECT COUNT(*)
            FROM delegations
            JOIN runs ON runs.run_id = delegations.current_run_id
            WHERE delegations.tenant_id = ?
              AND delegations.owner_id = ?
              AND delegations.dismissed_at IS NULL
              AND (
                    runs.state NOT IN ('completed', 'failed', 'cancelled')
                 OR (
                        COALESCE(runs.ended_at, delegations.updated_at) >= ?
                    AND (
                        SELECT COUNT(*)
                        FROM delegations AS newer_delegations
                        JOIN runs AS newer_runs
                          ON newer_runs.run_id = newer_delegations.current_run_id
                        WHERE newer_delegations.tenant_id = delegations.tenant_id
                          AND newer_delegations.owner_id = delegations.owner_id
                          AND newer_delegations.dismissed_at IS NULL
                          AND newer_runs.state = runs.state
                          AND (
                                newer_delegations.updated_at > delegations.updated_at
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at > delegations.created_at
                             )
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at = delegations.created_at
                                AND newer_delegations.work_ref > delegations.work_ref
                             )
                          )
                    ) < ?
                 )
              )
        """
        params: list[Any] = [tenant_id, owner_id, terminal_cutoff, terminal_per_state]
        if before is not None:
            updated_at, created_at, work_ref = before
            query += """
              AND (
                    delegations.updated_at < ?
                 OR (delegations.updated_at = ? AND delegations.created_at < ?)
                 OR (
                        delegations.updated_at = ?
                    AND delegations.created_at = ?
                    AND delegations.work_ref < ?
                 )
              )
            """
            params.extend(
                [updated_at, updated_at, created_at, updated_at, created_at, work_ref]
            )
        with self._connect() as conn:
            row = conn.execute(query, params).fetchone()
        return int(row[0] if row else 0)

    def list_delegation_history(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        limit: int = 50,
        before: tuple[str, str, str] | None = None,
    ) -> list[dict[str, Any]]:
        terminal_cutoff = (
            datetime.now(timezone.utc)
            - timedelta(seconds=_active_work_terminal_recency_seconds())
        ).isoformat()
        terminal_per_state = _active_work_terminal_per_state_limit()
        query = self._delegation_select() + """
            WHERE delegations.tenant_id = ?
              AND delegations.owner_id = ?
              AND runs.state IN ('completed', 'failed', 'cancelled')
              AND (
                    delegations.dismissed_at IS NOT NULL
                 OR COALESCE(runs.ended_at, delegations.updated_at) < ?
                 OR (
                        SELECT COUNT(*)
                        FROM delegations AS newer_delegations
                        JOIN runs AS newer_runs
                          ON newer_runs.run_id = newer_delegations.current_run_id
                        WHERE newer_delegations.tenant_id = delegations.tenant_id
                          AND newer_delegations.owner_id = delegations.owner_id
                          AND newer_delegations.dismissed_at IS NULL
                          AND newer_runs.state = runs.state
                          AND (
                                newer_delegations.updated_at > delegations.updated_at
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at > delegations.created_at
                             )
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at = delegations.created_at
                                AND newer_delegations.work_ref > delegations.work_ref
                             )
                          )
                    ) >= ?
              )
        """
        params: list[Any] = [tenant_id, owner_id, terminal_cutoff, terminal_per_state]
        if before is not None:
            updated_at, created_at, work_ref = before
            query += """
              AND (
                    delegations.updated_at < ?
                 OR (delegations.updated_at = ? AND delegations.created_at < ?)
                 OR (
                        delegations.updated_at = ?
                    AND delegations.created_at = ?
                    AND delegations.work_ref < ?
                 )
              )
            """
            params.extend(
                [updated_at, updated_at, created_at, updated_at, created_at, work_ref]
            )
        query += """
            ORDER BY delegations.updated_at DESC, delegations.created_at DESC,
                     delegations.work_ref DESC
            LIMIT ?
        """
        params.append(max(1, min(int(limit), 100)))
        with self._connect() as conn:
            rows = conn.execute(query, params).fetchall()
        return self._rows(rows)

    def count_delegation_history(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        before: tuple[str, str, str] | None = None,
    ) -> int:
        terminal_cutoff = (
            datetime.now(timezone.utc)
            - timedelta(seconds=_active_work_terminal_recency_seconds())
        ).isoformat()
        terminal_per_state = _active_work_terminal_per_state_limit()
        query = """
            SELECT COUNT(*)
            FROM delegations
            JOIN runs ON runs.run_id = delegations.current_run_id
            WHERE delegations.tenant_id = ?
              AND delegations.owner_id = ?
              AND runs.state IN ('completed', 'failed', 'cancelled')
              AND (
                    delegations.dismissed_at IS NOT NULL
                 OR COALESCE(runs.ended_at, delegations.updated_at) < ?
                 OR (
                        SELECT COUNT(*)
                        FROM delegations AS newer_delegations
                        JOIN runs AS newer_runs
                          ON newer_runs.run_id = newer_delegations.current_run_id
                        WHERE newer_delegations.tenant_id = delegations.tenant_id
                          AND newer_delegations.owner_id = delegations.owner_id
                          AND newer_delegations.dismissed_at IS NULL
                          AND newer_runs.state = runs.state
                          AND (
                                newer_delegations.updated_at > delegations.updated_at
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at > delegations.created_at
                             )
                             OR (
                                    newer_delegations.updated_at = delegations.updated_at
                                AND newer_delegations.created_at = delegations.created_at
                                AND newer_delegations.work_ref > delegations.work_ref
                             )
                          )
                    ) >= ?
              )
        """
        params: list[Any] = [tenant_id, owner_id, terminal_cutoff, terminal_per_state]
        if before is not None:
            updated_at, created_at, work_ref = before
            query += """
              AND (
                    delegations.updated_at < ?
                 OR (delegations.updated_at = ? AND delegations.created_at < ?)
                 OR (
                        delegations.updated_at = ?
                    AND delegations.created_at = ?
                    AND delegations.work_ref < ?
                 )
              )
            """
            params.extend(
                [updated_at, updated_at, created_at, updated_at, created_at, work_ref]
            )
        with self._connect() as conn:
            row = conn.execute(query, params).fetchone()
        return int(row[0] if row else 0)

    def get_delegation_for_worker(
        self,
        worker_id: str,
        *,
        tenant_id: str,
        owner_id: str,
    ) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT * FROM delegations
                WHERE worker_id = ? AND tenant_id = ? AND owner_id = ?
                LIMIT 1
                """,
                (worker_id, tenant_id, owner_id),
            ).fetchone()
        return self._row(row)

    def get_delegation_by_origin(
        self,
        origin_ref: str,
        *,
        tenant_id: str,
        owner_id: str,
    ) -> dict[str, Any] | None:
        query = self._delegation_select() + """
            WHERE delegations.origin_ref = ?
              AND delegations.tenant_id = ?
              AND delegations.owner_id = ?
            LIMIT 1
        """
        with self._connect() as conn:
            row = conn.execute(query, (origin_ref, tenant_id, owner_id)).fetchone()
        return self._row(row)

    def verify_callback_association(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        origin_ref: str,
        work_ref: str,
        worker_id: str,
        run_id: str,
    ) -> dict[str, Any] | None:
        """Resolve an exact mission/run binding without exposing partial matches."""

        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT delegations.origin_ref, delegations.work_ref
                FROM delegations
                JOIN runs
                  ON runs.run_id = ?
                 AND runs.worker_id = delegations.worker_id
                 AND runs.project_id = delegations.project_id
                 AND runs.tenant_id = delegations.tenant_id
                WHERE delegations.tenant_id = ?
                  AND delegations.owner_id = ?
                  AND delegations.origin_ref = ?
                  AND delegations.work_ref = ?
                  AND delegations.worker_id = ?
                LIMIT 1
                """,
                (run_id, tenant_id, owner_id, origin_ref, work_ref, worker_id),
            ).fetchone()
        return self._row(row)

    def update_delegation_current_run(
        self,
        work_ref: str,
        *,
        tenant_id: str,
        owner_id: str,
        run_id: str,
    ) -> dict[str, Any] | None:
        with self._connect() as conn:
            conn.execute(
                """
                UPDATE delegations
                SET current_run_id = ?, dismissed_at = NULL, updated_at = ?
                WHERE work_ref = ? AND tenant_id = ? AND owner_id = ?
                """,
                (run_id, utc_now(), work_ref, tenant_id, owner_id),
            )
        return self.get_delegation(work_ref, tenant_id=tenant_id, owner_id=owner_id)

    def dismiss_delegation(
        self,
        work_ref: str,
        *,
        tenant_id: str,
        owner_id: str,
    ) -> dict[str, Any] | None:
        with self._connect() as conn:
            conn.execute(
                """
                UPDATE delegations
                SET dismissed_at = COALESCE(dismissed_at, ?), updated_at = ?
                WHERE work_ref = ? AND tenant_id = ? AND owner_id = ?
                """,
                (utc_now(), utc_now(), work_ref, tenant_id, owner_id),
            )
        return self.get_delegation(work_ref, tenant_id=tenant_id, owner_id=owner_id)

    def reserve_active_work_action(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        work_ref: str,
        idempotency_key: str,
        action: str,
        payload_digest: str,
        source_context: dict[str, Any] | None = None,
        expected_current_run_id: str = "",
        expected_source_run_id: str = "",
        expected_source_state: str = "",
        expected_source_started_at: str = "",
        executor_id: str = "",
        lease_seconds: float = 30.0,
    ) -> dict[str, Any]:
        current = datetime.now(timezone.utc)
        now = current.isoformat()
        normalized_executor_id = str(executor_id or "").strip()
        source_context_json = json.dumps(
            source_context if isinstance(source_context, dict) else {},
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        lease_expires_at = (
            current + timedelta(seconds=max(1.0, float(lease_seconds)))
        ).isoformat()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            delegation = conn.execute(
                """
                SELECT current_run_id, worker_id FROM delegations
                WHERE work_ref = ? AND tenant_id = ? AND owner_id = ?
                """,
                (work_ref, tenant_id, owner_id),
            ).fetchone()
            if delegation is None:
                conn.execute("ROLLBACK")
                raise KeyError("Active work not found")
            selected_run = conn.execute(
                """
                SELECT * FROM runs
                WHERE worker_id = ?
                  AND state IN (
                      'claimed', 'admitted', 'running', 'settling',
                      'queued', 'paused', 'needs_input'
                  )
                ORDER BY
                    CASE state
                        WHEN 'running' THEN 0
                        WHEN 'admitted' THEN 1
                        WHEN 'claimed' THEN 2
                        WHEN 'settling' THEN 3
                        WHEN 'paused' THEN 4
                        WHEN 'needs_input' THEN 5
                        ELSE 6
                    END,
                    queued_at DESC
                LIMIT 1
                """,
                (delegation["worker_id"],),
            ).fetchone()
            if selected_run is None and str(delegation["current_run_id"] or ""):
                # `_delegation_select()` falls back to the delegation's current
                # run when no controllable generation remains.  Keep action
                # reservation bound to that same terminal generation so Retry
                # and Dismiss reach their normal action policy, and a stale
                # nonterminal action reports "not available" rather than a
                # synthetic generation race.
                selected_run = conn.execute(
                    "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                    (
                        delegation["current_run_id"],
                        delegation["worker_id"],
                    ),
                ).fetchone()
            selected_source_run_id = str(
                (selected_run["run_id"] if selected_run is not None else None)
                or delegation["current_run_id"]
                or ""
            )
            clean_expected_current = str(expected_current_run_id or "").strip()
            clean_expected_source = str(expected_source_run_id or "").strip()
            clean_expected_state = str(expected_source_state or "").strip()
            clean_expected_started_at = str(expected_source_started_at or "").strip()
            source_generation_changed = bool(
                (
                    clean_expected_current
                    and clean_expected_current
                    != str(delegation["current_run_id"] or "")
                )
                or (
                    clean_expected_source
                    and clean_expected_source != selected_source_run_id
                )
                or (
                    clean_expected_state
                    and (
                        selected_run is None
                        or clean_expected_state != str(selected_run["state"] or "")
                    )
                )
                or (
                    clean_expected_source
                    and clean_expected_started_at
                    != str(
                        selected_run["started_at"] or ""
                        if selected_run is not None
                        else ""
                    )
                )
            )
            existing = conn.execute(
                """
                SELECT * FROM active_work_action_uses
                WHERE tenant_id = ? AND owner_id = ? AND work_ref = ? AND idempotency_key = ?
                """,
                (tenant_id, owner_id, work_ref, idempotency_key),
            ).fetchone()
            if existing is not None:
                if (
                    str(existing["action"] or "") != action
                    or str(existing["payload_digest"] or "") != payload_digest
                ):
                    conn.execute("ROLLBACK")
                    raise ActiveWorkActionConflictError(
                        "The active-work action idempotency key was reused with a different request."
                    )
                if str(existing["status"] or "") == "completed":
                    conn.execute("COMMIT")
                    return {
                        **self._row(existing),
                        "idempotent_replay": True,
                        "should_execute": False,
                        "recovery_takeover": False,
                    }
                if (
                    str(existing["status"] or "") == "failed"
                    and str(existing["response_json"] or "").strip()
                ):
                    conn.execute("COMMIT")
                    return {
                        **self._row(existing),
                        "idempotent_replay": True,
                        "should_execute": False,
                        "recovery_takeover": False,
                    }
                # Stop's permanent work tombstone fences every operation that can
                # create or control work. Dismiss is metadata-only and must remain
                # available after that tombstone so an acknowledged terminal card
                # can be hidden without reviving or deleting the work history.
                if action not in {"stop", "dismiss"}:
                    try:
                        self._require_worker_work_admission(
                            conn.execute(
                                "SELECT * FROM workers WHERE worker_id = ?",
                                (delegation["worker_id"],),
                            ).fetchone()
                        )
                    except WorkAdmissionError as exc:
                        conn.execute("ROLLBACK")
                        raise ActiveWorkActionConflictError(
                            str(exc), code=exc.code
                        ) from exc
                if not str(existing["source_run_id"] or ""):
                    conn.execute(
                        """
                        UPDATE active_work_action_uses
                        SET source_run_id = ?, updated_at = ?
                        WHERE action_use_id = ? AND source_run_id = ''
                        """,
                        (
                            selected_source_run_id,
                            now,
                            existing["action_use_id"],
                        ),
                    )
                    existing = conn.execute(
                        "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                        (existing["action_use_id"],),
                    ).fetchone()
                if str(existing["status"] or "") == "failed":
                    conn.execute(
                        """
                        UPDATE active_work_action_uses
                        SET status = 'pending', last_error = '', executor_id = ?,
                            lease_expires_at = ?, updated_at = ?
                        WHERE action_use_id = ?
                        """,
                        (
                            normalized_executor_id,
                            lease_expires_at,
                            now,
                            existing["action_use_id"],
                        ),
                    )
                    existing = conn.execute(
                        "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                        (existing["action_use_id"],),
                    ).fetchone()
                    conn.execute("COMMIT")
                    return {
                        **self._row(existing),
                        "idempotent_replay": True,
                        "should_execute": True,
                        "recovery_takeover": False,
                    }
                existing_executor = str(existing["executor_id"] or "")
                raw_expiry = str(existing["lease_expires_at"] or "")
                try:
                    lease_is_live = bool(raw_expiry) and datetime.fromisoformat(
                        raw_expiry
                    ) > current
                except ValueError:
                    lease_is_live = False
                can_take_over = bool(normalized_executor_id) and (
                    not existing_executor
                    or (existing_executor != normalized_executor_id and not lease_is_live)
                )
                if can_take_over:
                    conn.execute(
                        """
                        UPDATE active_work_action_uses
                        SET executor_id = ?, lease_expires_at = ?, updated_at = ?
                        WHERE action_use_id = ? AND status = 'pending'
                        """,
                        (
                            normalized_executor_id,
                            lease_expires_at,
                            now,
                            existing["action_use_id"],
                        ),
                    )
                    existing = conn.execute(
                        "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                        (existing["action_use_id"],),
                    ).fetchone()
                    conn.execute("COMMIT")
                    return {
                        **self._row(existing),
                        "idempotent_replay": True,
                        "should_execute": True,
                        "recovery_takeover": True,
                    }
                conn.execute("COMMIT")
                return {
                    **self._row(existing),
                    "idempotent_replay": True,
                    "should_execute": False,
                    "recovery_takeover": False,
                }
            if source_generation_changed:
                conn.execute("ROLLBACK")
                raise ActiveWorkActionConflictError(
                    "The active-work run generation changed; refresh before retrying.",
                    code="active_work_generation_changed",
                )
            if action not in {"stop", "dismiss"}:
                try:
                    self._require_worker_work_admission(
                        conn.execute(
                            "SELECT * FROM workers WHERE worker_id = ?",
                            (delegation["worker_id"],),
                        ).fetchone()
                    )
                except WorkAdmissionError as exc:
                    conn.execute("ROLLBACK")
                    raise ActiveWorkActionConflictError(
                        str(exc), code=exc.code
                    ) from exc
            data = {
                "action_use_id": f"awu_{uuid.uuid4().hex}",
                "tenant_id": tenant_id,
                "owner_id": owner_id,
                "work_ref": work_ref,
                "source_run_id": selected_source_run_id,
                "effect_phase": "",
                "lifecycle_operation_id": "",
                "lifecycle_operation_kind": "",
                "lifecycle_target_run_id": "",
                "executor_id": normalized_executor_id,
                "lease_expires_at": lease_expires_at,
                "idempotency_key": idempotency_key,
                "action": action,
                "payload_digest": payload_digest,
                "source_context_json": source_context_json,
                "status": "pending",
                "response_json": "",
                "last_error": "",
                "created_at": now,
                "updated_at": now,
            }
            conn.execute(
                """
                INSERT INTO active_work_action_uses (
                    action_use_id, tenant_id, owner_id, work_ref, source_run_id,
                    effect_phase, lifecycle_operation_id, lifecycle_operation_kind,
                    lifecycle_target_run_id, executor_id, lease_expires_at, idempotency_key,
                    action, payload_digest, source_context_json, status, response_json, last_error,
                    created_at, updated_at
                ) VALUES (
                    :action_use_id, :tenant_id, :owner_id, :work_ref, :source_run_id,
                    :effect_phase, :lifecycle_operation_id, :lifecycle_operation_kind,
                    :lifecycle_target_run_id, :executor_id, :lease_expires_at, :idempotency_key,
                    :action, :payload_digest, :source_context_json, :status, :response_json, :last_error,
                    :created_at, :updated_at
                )
                """,
                data,
            )
            conn.execute("COMMIT")
        return {
            **data,
            "idempotent_replay": False,
            "should_execute": True,
            "recovery_takeover": False,
        }

    def bind_active_work_action_lifecycle(
        self,
        action_use_id: str,
        *,
        operation_id: str,
        operation_kind: str,
        target_run_id: str,
        executor_id: str,
    ) -> dict[str, Any] | None:
        """Bind a receipt once to the exact durable lifecycle operation it owns."""

        with self._connect() as conn:
            cursor = self._bind_active_work_action_lifecycle_in_transaction(
                conn,
                action_use_id=action_use_id,
                operation_id=operation_id,
                operation_kind=operation_kind,
                target_run_id=target_run_id,
                executor_id=executor_id,
            )
            if cursor != 1:
                return None
            row = conn.execute(
                "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                (action_use_id,),
            ).fetchone()
        return self._row(row)

    @staticmethod
    def _bind_active_work_action_lifecycle_in_transaction(
        conn: sqlite3.Connection,
        *,
        action_use_id: str,
        operation_id: str,
        operation_kind: str,
        target_run_id: str,
        executor_id: str,
    ) -> int:
        """CAS-bind an owned receipt inside its lifecycle claim transaction."""

        clean_operation = str(operation_id or "").strip()
        clean_kind = str(operation_kind or "").strip().lower()
        clean_target = str(target_run_id or "").strip()
        expected_action = {
            "pause_run": "pause",
            "resume_run": "resume",
            "steer_run": "steer",
            "stop_run": "stop",
        }.get(clean_kind, "")
        if (
            not clean_operation
            or not expected_action
            or not clean_target
            or not str(executor_id or "").strip()
        ):
            raise ValueError("Action lifecycle binding requires an exact owned operation")
        cursor = conn.execute(
            """
            UPDATE active_work_action_uses
            SET lifecycle_operation_id = ?, lifecycle_operation_kind = ?,
                lifecycle_target_run_id = ?, updated_at = ?
            WHERE action_use_id = ? AND status = 'pending' AND executor_id = ?
              AND action = ? AND source_run_id = ?
              AND (
                    lifecycle_operation_id = ''
                    OR (
                        lifecycle_operation_id = ?
                        AND lifecycle_operation_kind = ?
                        AND lifecycle_target_run_id = ?
                    )
              )
            """,
            (
                clean_operation,
                clean_kind,
                clean_target,
                utc_now(),
                action_use_id,
                str(executor_id),
                expected_action,
                clean_target,
                clean_operation,
                clean_kind,
                clean_target,
            ),
        )
        return int(cursor.rowcount)

    def checkpoint_active_work_action(
        self,
        action_use_id: str,
        effect_phase: str,
        *,
        executor_id: str = "",
    ) -> dict[str, Any] | None:
        """Persist a completed subeffect before the next non-atomic action step."""

        with self._connect() as conn:
            owner_clause = " AND executor_id = ?" if executor_id else ""
            params: list[Any] = [str(effect_phase or "")[:100], utc_now(), action_use_id]
            if executor_id:
                params.append(str(executor_id))
            cursor = conn.execute(
                f"""
                UPDATE active_work_action_uses
                SET effect_phase = ?, updated_at = ?
                WHERE action_use_id = ? AND status = 'pending'
                {owner_clause}
                """,
                params,
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                (action_use_id,),
            ).fetchone()
        return self._row(row)

    def resume_needs_input_active_work_action(
        self,
        action_use_id: str,
        *,
        worker_id: str,
        run_id: str,
        executor_id: str,
    ) -> dict[str, Any] | None:
        """Atomically re-admit an attention-blocked run and its action proof."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            action = conn.execute(
                "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                (action_use_id,),
            ).fetchone()
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                (run_id, worker_id),
            ).fetchone()
            if (
                action is None
                or worker is None
                or run is None
                or str(action["status"] or "") != "pending"
                or str(action["executor_id"] or "") != str(executor_id)
                or str(action["action"] or "") != "resume"
                or str(action["source_run_id"] or "") != str(run_id)
            ):
                conn.execute("ROLLBACK")
                return None
            operation_id = str(action["lifecycle_operation_id"] or "").strip()
            if operation_id:
                if (
                    str(action["lifecycle_operation_kind"] or "") != "resume_run"
                    or str(action["lifecycle_target_run_id"] or "") != str(run_id)
                ):
                    conn.execute("ROLLBACK")
                    return None
            else:
                operation_id = "op_" + uuid.uuid4().hex
            provider_attention = bool(
                str(run["failure_class"] or "") == "provider_progress_stalled"
            )
            effect_phase = (
                "provider_progress_re_admitted"
                if provider_attention
                else "authorization_re_admitted"
            )
            event_type = (
                "run.resumed" if provider_attention else "run.authorization_resumed"
            )
            event_message = (
                "Provider attention cleared; exact run queued for execution restart"
                if provider_attention
                else "Authorization attention cleared; exact run queued for re-admission"
            )
            if provider_attention and worker["compute_released_at"] is None:
                conn.execute("ROLLBACK")
                return None
            if str(run["state"] or "") == "needs_input":
                resume_fields: dict[str, Any] = {
                    "state": "queued",
                    "ended_at": None,
                    "error_text": "",
                    "retry_after": None,
                    "run_id": run_id,
                    "worker_id": worker_id,
                }
                if not bool(run["queue_wait_open"]):
                    generation = max(
                        1, int(run["queue_wait_generation"] or 0)
                    ) + 1
                    deadline = (
                        _parse_utc(now)
                        + timedelta(seconds=_queue_wait_timeout_seconds())
                    ).isoformat()
                    resume_fields.update(
                        {
                            "queue_wait_episode": generation,
                            "queue_wait_open": 1,
                            "queue_wait_generation": generation,
                            "queue_wait_started_at": now,
                            "queue_wait_closed_at": None,
                            "queue_wait_duration_seconds": None,
                            "queue_deadline_at": deadline,
                            "queue_next_status_at": (
                                _parse_utc(now)
                                + timedelta(
                                    seconds=_queue_status_refresh_interval_seconds()
                                )
                            ).isoformat(),
                            "queue_transition_emitted": 0,
                            "queue_status_sequence": 0,
                            "queue_callback_state": "unknown",
                            "queue_terminal_callback_id": _queue_callback_id(
                                "timeout",
                                run_id=str(run_id),
                                generation=generation,
                                deadline=deadline,
                            ),
                        }
                    )
                resume_assignments = ", ".join(
                    f"{field} = :{field}"
                    for field in resume_fields
                    if field not in {"run_id", "worker_id"}
                )
                cursor = conn.execute(
                    f"""
                    UPDATE runs SET {resume_assignments}
                    WHERE run_id = :run_id AND worker_id = :worker_id
                      AND state = 'needs_input'
                    """,
                    resume_fields,
                )
                if cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                conn.execute(
                    "UPDATE workers SET state = 'starting', last_error = '', updated_at = ? "
                    "WHERE worker_id = ?",
                    (now, worker_id),
                )
            elif not (
                str(run["state"] or "") == "queued"
                and str(action["effect_phase"] or "") == effect_phase
            ):
                conn.execute("ROLLBACK")
                return None
            conn.execute(
                """
                UPDATE active_work_action_uses
                SET lifecycle_operation_id = ?, lifecycle_operation_kind = 'resume_run',
                    lifecycle_target_run_id = ?,
                    effect_phase = ?, updated_at = ?
                WHERE action_use_id = ? AND status = 'pending' AND executor_id = ?
                """,
                (
                    operation_id,
                    run_id,
                    effect_phase,
                    now,
                    action_use_id,
                    str(executor_id),
                ),
            )
            self._insert_lifecycle_event(
                conn,
                operation_token=operation_id,
                operation_epoch=0,
                operation_kind="resume_run",
                worker=worker,
                run_id=run_id,
                event_type=event_type,
                message=event_message,
                payload={"operation_kind": "resume_run"},
            )
            self._enqueue_lifecycle_effects(
                conn,
                operation_token=operation_id,
                operation_epoch=0,
                operation_kind="resume_run",
                worker_id=worker_id,
                run_id=run_id,
                effect_kinds=("callback.run_resumed_queued",),
            )
            updated_run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            updated_worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return {"run": self._row(updated_run), "worker": self._row(updated_worker)}

    def get_active_work_action(self, action_use_id: str) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                (action_use_id,),
            ).fetchone()
        return self._row(row)

    def get_pending_active_work_action_for_lifecycle(
        self,
        *,
        operation_id: str,
        operation_kind: str,
        target_run_id: str,
    ) -> dict[str, Any] | None:
        """Return one exact pending control receipt, never an ambiguous match."""

        clean_operation = str(operation_id or "").strip()
        clean_kind = str(operation_kind or "").strip().lower()
        clean_target = str(target_run_id or "").strip()
        expected_action = {
            "pause_run": "pause",
            "resume_run": "resume",
            "steer_run": "steer",
            "stop_run": "stop",
        }.get(clean_kind, "")
        if not clean_operation or not expected_action or not clean_target:
            return None
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM active_work_action_uses
                WHERE status = 'pending' AND action = ?
                  AND lifecycle_operation_id = ?
                  AND lifecycle_operation_kind = ?
                  AND lifecycle_target_run_id = ?
                LIMIT 2
                """,
                (expected_action, clean_operation, clean_kind, clean_target),
            ).fetchall()
        if len(rows) != 1:
            return None
        return self._row(rows[0])

    def release_active_work_action_leases(self, executor_id: str) -> int:
        """Make unfinished actions recoverable when this service exits cleanly."""

        normalized = str(executor_id or "").strip()
        if not normalized:
            return 0
        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE active_work_action_uses
                SET lease_expires_at = ?, updated_at = ?
                WHERE executor_id = ? AND status = 'pending'
                """,
                (now, now, normalized),
            )
        return int(cursor.rowcount)

    def finish_active_work_action(
        self,
        action_use_id: str,
        *,
        response: dict[str, Any],
        current_run_id: str | None = None,
        executor_id: str = "",
    ) -> dict[str, Any] | None:
        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                (action_use_id,),
            ).fetchone()
            if row is None:
                conn.execute("ROLLBACK")
                return None
            if executor_id and str(row["executor_id"] or "") != str(executor_id):
                conn.execute("ROLLBACK")
                return None
            if executor_id and str(row["status"] or "") == "completed":
                # Startup recovery and its concurrent HTTP replay can finish the
                # same owned effect. Return the first durable receipt unchanged.
                conn.execute("ROLLBACK")
                return self._row(row)
            if str(row["status"] or "") != "pending":
                conn.execute("ROLLBACK")
                return None
            delegation = conn.execute(
                """
                SELECT current_run_id, updated_at FROM delegations
                WHERE work_ref = ? AND tenant_id = ? AND owner_id = ?
                """,
                (row["work_ref"], row["tenant_id"], row["owner_id"]),
            ).fetchone()
            canonical_response = dict(response)
            if (
                current_run_id
                and delegation is not None
                and str(delegation["current_run_id"] or "") != str(current_run_id)
            ):
                conn.execute(
                    """
                    UPDATE delegations
                    SET current_run_id = ?, updated_at = ?
                    WHERE work_ref = ? AND tenant_id = ? AND owner_id = ?
                    """,
                    (
                        current_run_id,
                        now,
                        row["work_ref"],
                        row["tenant_id"],
                        row["owner_id"],
                    ),
                )
                canonical_response["updatedAt"] = now
            elif delegation is not None:
                canonical_response["updatedAt"] = str(delegation["updated_at"] or "")
            cursor = conn.execute(
                """
                UPDATE active_work_action_uses
                SET status = 'completed', response_json = ?, last_error = '', updated_at = ?
                WHERE action_use_id = ? AND status = 'pending'
                """,
                (
                    json.dumps(
                        canonical_response, sort_keys=True, separators=(",", ":")
                    ),
                    now,
                    action_use_id,
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            finished = conn.execute(
                "SELECT * FROM active_work_action_uses WHERE action_use_id = ?",
                (action_use_id,),
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(finished)

    def fail_active_work_action(
        self,
        action_use_id: str,
        error: str,
        *,
        executor_id: str = "",
        failure_response: dict[str, Any] | None = None,
    ) -> bool:
        with self._connect() as conn:
            owner_clause = " AND executor_id = ?" if executor_id else ""
            serialized_response = (
                json.dumps(failure_response, sort_keys=True, separators=(",", ":"))
                if failure_response is not None
                else ""
            )
            params: list[Any] = [
                str(error or "")[:1000],
                serialized_response,
                utc_now(),
                action_use_id,
            ]
            if executor_id:
                params.append(str(executor_id))
            cursor = conn.execute(
                f"""
                UPDATE active_work_action_uses
                SET status = CASE
                        WHEN effect_phase <> '' OR lifecycle_operation_id <> ''
                            THEN 'pending'
                        ELSE 'failed'
                    END,
                    last_error = ?,
                    response_json = CASE
                        WHEN effect_phase = '' AND lifecycle_operation_id = '' THEN ?
                        ELSE response_json
                    END,
                    updated_at = ?
                WHERE action_use_id = ? AND status = 'pending'{owner_clause}
                """,
                params,
            )
        return cursor.rowcount == 1

    def fail_unbound_active_work_control(
        self,
        action_use_id: str,
        *,
        executor_id: str,
    ) -> bool:
        """Permanently fail one owned legacy control receipt with no causal binding."""

        clean_executor = str(executor_id or "").strip()
        if not clean_executor:
            return False
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE active_work_action_uses
                SET status = 'failed',
                    last_error = 'active_work_action_binding_unavailable',
                    response_json = ?,
                    lease_expires_at = NULL, updated_at = ?
                WHERE action_use_id = ? AND status = 'pending'
                  AND executor_id = ?
                  AND lifecycle_operation_id = ''
                  AND action IN ('pause', 'resume', 'steer', 'stop')
                """,
                (
                    json.dumps(
                        {
                            "detail": {
                                "code": "active_work_action_binding_unavailable",
                                "message": (
                                    "This unfinished control predates durable lifecycle binding. "
                                    "Refresh and reissue it with a new idempotency key."
                                ),
                            },
                            "statusCode": 409,
                        },
                        sort_keys=True,
                        separators=(",", ":"),
                    ),
                    utc_now(),
                    action_use_id,
                    clean_executor,
                ),
            )
        return cursor.rowcount == 1

    def get_provider_main_context(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        agent_id: str,
        continuity_domain_id: str,
    ) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT * FROM provider_main_contexts
                WHERE tenant_id = ? AND owner_id = ? AND agent_id = ?
                  AND continuity_domain_id = ?
                """,
                (tenant_id or "local", owner_id, agent_id, continuity_domain_id),
            ).fetchone()
        return self._row(row)

    def append_provider_main_context_turn(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        agent_id: str,
        continuity_domain_id: str,
        request_id: str,
        turn: dict[str, Any],
        max_turns: int = 3,
    ) -> dict[str, Any]:
        """Append one accepted interactive turn exactly once to the bounded Main context."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            existing = conn.execute(
                """
                SELECT * FROM provider_main_contexts
                WHERE tenant_id = ? AND owner_id = ? AND agent_id = ?
                """,
                (tenant_id or "local", owner_id, agent_id),
            ).fetchone()
            if existing and str(existing["continuity_domain_id"] or "") != continuity_domain_id:
                conn.execute("ROLLBACK")
                raise ValueError("Main context continuity domain does not match the owner agent")
            try:
                context = json.loads(str(existing["context_json"] or "{}")) if existing else {}
            except json.JSONDecodeError:
                context = {}
            turns = list(context.get("turns") or []) if isinstance(context, dict) else []
            if any(str(item.get("request_id") or "") == request_id for item in turns if isinstance(item, dict)):
                conn.execute("COMMIT")
                return self._row(existing) or {}
            logical_turn_id = str(turn.get("logical_turn_id") or "").strip()
            logical_turn_revision = max(1, int(turn.get("logical_turn_revision") or 1))
            if logical_turn_id:
                matching_revisions = [
                    max(1, int(item.get("logical_turn_revision") or 1))
                    for item in turns
                    if isinstance(item, dict)
                    and str(item.get("logical_turn_id") or "") == logical_turn_id
                ]
                if matching_revisions and max(matching_revisions) >= logical_turn_revision:
                    conn.execute("COMMIT")
                    return self._row(existing) or {}
                turns = [
                    item
                    for item in turns
                    if not (
                        isinstance(item, dict)
                        and str(item.get("logical_turn_id") or "") == logical_turn_id
                    )
                ]
            version = int(existing["version"] or 0) + 1 if existing else 1
            accepted_turn = {
                **turn,
                "request_id": request_id,
                **(
                    {
                        "logical_turn_id": logical_turn_id,
                        "logical_turn_revision": logical_turn_revision,
                    }
                    if logical_turn_id
                    else {}
                ),
                "version": version,
                "accepted_at": now,
            }
            turns = [*turns, accepted_turn][-max(1, int(max_turns)) :]
            data = {
                "tenant_id": tenant_id or "local",
                "owner_id": owner_id,
                "agent_id": agent_id,
                "continuity_domain_id": continuity_domain_id,
                "version": version,
                "context_json": json.dumps(
                    {"version": 1, "turns": turns}, separators=(",", ":"), sort_keys=True
                ),
                "created_at": str(existing["created_at"] or now) if existing else now,
                "updated_at": now,
            }
            conn.execute(
                """
                INSERT INTO provider_main_contexts (
                    tenant_id, owner_id, agent_id, continuity_domain_id,
                    version, context_json, created_at, updated_at
                ) VALUES (
                    :tenant_id, :owner_id, :agent_id, :continuity_domain_id,
                    :version, :context_json, :created_at, :updated_at
                )
                ON CONFLICT(tenant_id, owner_id, agent_id) DO UPDATE SET
                    continuity_domain_id = excluded.continuity_domain_id,
                    version = excluded.version,
                    context_json = excluded.context_json,
                    updated_at = excluded.updated_at
                """,
                data,
            )
            row = conn.execute(
                """
                SELECT * FROM provider_main_contexts
                WHERE tenant_id = ? AND owner_id = ? AND agent_id = ?
                """,
                (tenant_id or "local", owner_id, agent_id),
            ).fetchone()
            conn.execute("COMMIT")
        return dict(row)

    def get_provider_session_by_worker(self, worker_id: str) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM provider_sessions WHERE worker_id = ? ORDER BY updated_at DESC LIMIT 1",
                (worker_id,),
            ).fetchone()
        return self._row(row)

    def record_provider_session_usage_calibration(
        self,
        session_id: str,
        *,
        request_id: str,
        prompt_tokens: int,
        total_tokens: int,
        observed_chars_per_token: float,
        measurement_epoch: str | None = None,
        measurement_scope: str | None = None,
        measurement_created_at: str | None = None,
    ) -> dict[str, Any] | None:
        """Record a comparable full-source chars/token calibration sample."""

        return self._record_provider_session_native_measurement(
            session_id,
            request_id=request_id,
            prompt_tokens=prompt_tokens,
            total_tokens=total_tokens,
            observed_chars_per_token=observed_chars_per_token,
            measurement_epoch=measurement_epoch,
            measurement_scope=measurement_scope,
            measurement_created_at=measurement_created_at,
            calibrate_chars_per_token=True,
        )

    def record_provider_session_native_occupancy(
        self,
        session_id: str,
        *,
        request_id: str,
        prompt_tokens: int,
        total_tokens: int,
        measurement_epoch: str | None = None,
        measurement_scope: str | None = None,
        measurement_created_at: str | None = None,
    ) -> dict[str, Any] | None:
        """Record current native prompt occupancy without recalibrating the ratio."""

        return self._record_provider_session_native_measurement(
            session_id,
            request_id=request_id,
            prompt_tokens=prompt_tokens,
            total_tokens=total_tokens,
            observed_chars_per_token=None,
            measurement_epoch=measurement_epoch,
            measurement_scope=measurement_scope,
            measurement_created_at=measurement_created_at,
            calibrate_chars_per_token=False,
        )

    def _record_provider_session_native_measurement(
        self,
        session_id: str,
        *,
        request_id: str,
        prompt_tokens: int,
        total_tokens: int,
        observed_chars_per_token: float | None,
        measurement_epoch: str | None,
        measurement_scope: str | None,
        measurement_created_at: str | None,
        calibrate_chars_per_token: bool,
    ) -> dict[str, Any] | None:
        """Apply one epoch/order-fenced native measurement to a session manifest."""

        clean_request_id = str(request_id or "").strip()
        if not clean_request_id:
            return self.get_provider_session_by_id(session_id)
        if calibrate_chars_per_token and observed_chars_per_token is None:
            raise ValueError("Native calibration requires an observed ratio")
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT * FROM provider_sessions WHERE session_id = ?", (session_id,)
            ).fetchone()
            if row is None:
                conn.execute("COMMIT")
                return None
            try:
                manifest = json.loads(str(row["context_manifest_json"] or "{}"))
            except (json.JSONDecodeError, TypeError):
                manifest = {}
            if not isinstance(manifest, dict):
                manifest = {}
            if measurement_epoch is not None and str(measurement_epoch) != str(
                manifest.get("native_context_epoch") or ""
            ):
                conn.execute("COMMIT")
                return self._row(row)
            scope_field = (
                "usage_calibration_scope"
                if calibrate_chars_per_token
                else "native_occupancy_scope"
            )
            request_ids_field = (
                "usage_calibration_request_ids"
                if calibrate_chars_per_token
                else "native_occupancy_request_ids"
            )
            created_at_field = (
                "usage_calibration_latest_created_at"
                if calibrate_chars_per_token
                else "native_occupancy_latest_created_at"
            )
            requested_scope = str(
                measurement_scope
                or (
                    "admitted_instruction_bytes/native_prompt_tokens"
                    if calibrate_chars_per_token
                    else "native_prompt_tokens"
                )
            )
            current_scope = str(manifest.get(scope_field) or "")
            if requested_scope and current_scope and requested_scope != current_scope:
                conn.execute("COMMIT")
                return self._row(row)
            latest_created_at = str(manifest.get(created_at_field) or "")
            requested_created_at = str(measurement_created_at or "")
            if (
                latest_created_at
                and requested_created_at
                and requested_created_at <= latest_created_at
            ):
                conn.execute("COMMIT")
                return self._row(row)
            calibrated_requests = [
                str(value)
                for value in list(manifest.get(request_ids_field) or [])
                if str(value).strip()
            ]
            if clean_request_id not in calibrated_requests:
                # Occupancy is the live pressure signal.  A comparable bootstrap
                # calibration may arrive after it (for example, when a worker's
                # usage receipt is persisted out of order), so calibration must
                # never replace the newer shared occupancy sample.  The direct
                # legacy calibration API still seeds the shared fields when no
                # occupancy sample has the new metadata yet.
                try:
                    legacy_prompt_sample = int(
                        manifest.get("latest_native_prompt_tokens") or 0
                    ) > 0
                    legacy_total_sample = int(
                        manifest.get("latest_native_total_tokens") or 0
                    ) > 0
                except (TypeError, ValueError):
                    legacy_prompt_sample = False
                    legacy_total_sample = False
                occupancy_metadata_present = bool(
                    str(manifest.get("native_occupancy_scope") or "").strip()
                    or str(manifest.get("native_occupancy_latest_created_at") or "").strip()
                    or list(manifest.get("native_occupancy_request_ids") or [])
                    # Pre-seam manifests only had the shared fields. Treat a positive
                    # existing value as an occupancy sample so a late calibration cannot
                    # overwrite that legacy pressure signal; zero is the epoch-reset state.
                    or legacy_prompt_sample
                    or legacy_total_sample
                )
                measurement_fields = {
                    request_ids_field: [
                        *calibrated_requests,
                        clean_request_id,
                    ][-128:],
                }
                if not calibrate_chars_per_token or not occupancy_metadata_present:
                    measurement_fields.update(
                        {
                            "latest_native_prompt_tokens": max(0, int(prompt_tokens)),
                            "latest_native_total_tokens": max(
                                max(0, int(prompt_tokens)), max(0, int(total_tokens))
                            ),
                        }
                    )
                manifest.update(measurement_fields)
                if calibrate_chars_per_token:
                    sample = min(8.0, max(1.0, float(observed_chars_per_token)))
                    previous = manifest.get("observed_chars_per_token")
                    observed = (
                        sample
                        if previous is None
                        else min(8.0, max(1.0, (float(previous) * 3 + sample) / 4))
                    )
                    manifest["observed_chars_per_token"] = round(observed, 3)
                    manifest["usage_calibration_scope"] = requested_scope
                    if measurement_epoch is not None:
                        manifest["usage_calibration_native_context_epoch"] = str(
                            measurement_epoch
                        )
                else:
                    manifest["native_occupancy_scope"] = requested_scope
                    if measurement_epoch is not None:
                        manifest["native_occupancy_native_context_epoch"] = str(
                            measurement_epoch
                        )
                if requested_created_at:
                    manifest[created_at_field] = requested_created_at
                conn.execute(
                    """
                    UPDATE provider_sessions
                    SET context_manifest_json = ?, updated_at = ?
                    WHERE session_id = ?
                    """,
                    (json.dumps(manifest, sort_keys=True), utc_now(), session_id),
                )
                row = conn.execute(
                    "SELECT * FROM provider_sessions WHERE session_id = ?", (session_id,)
                ).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def advance_provider_session_history(
        self,
        session_id: str,
        *,
        request_id: str,
        advancement_key: str,
        expected_history_count: int,
        history_count: int,
        context_manifest: dict[str, Any],
    ) -> dict[str, Any]:
        """Advance one accepted provider cursor exactly once.

        The request state transition is the authoring boundary. The session cursor advances only
        when the accepted request still owns the cursor it used to build ReplayDecisionV1. A retry
        for the same logical turn is idempotent. Concurrent accepted turns merge their stable
        message keys even when their legacy numeric cursors overlap.
        """

        clean_key = str(advancement_key or "").strip()
        if not clean_key:
            raise ValueError("Provider session advancement requires an advancement key")
        expected = max(0, int(expected_history_count))
        target = max(0, int(history_count))
        if target < expected:
            raise ValueError("Provider session history cannot move backwards")

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            request_row = conn.execute(
                """
                SELECT session_id, state, replay_decision_json, restore_hold
                FROM provider_requests WHERE request_id = ?
                """,
                (request_id,),
            ).fetchone()
            session_row = conn.execute(
                "SELECT * FROM provider_sessions WHERE session_id = ?",
                (session_id,),
            ).fetchone()
            if (
                request_row is None
                or str(request_row["session_id"] or "") != session_id
                or str(request_row["state"] or "") != "completed"
                or session_row is None
            ):
                conn.execute("ROLLBACK")
                raise ValueError("Provider session advancement requires an accepted matching request")
            if bool(request_row["restore_hold"]):
                conn.execute("COMMIT")
                result = dict(session_row)
                result["advance_status"] = "restore_held"
                return result
            try:
                current_manifest = json.loads(
                    str(session_row["context_manifest_json"] or "{}")
                )
            except json.JSONDecodeError:
                current_manifest = {}
            if not isinstance(current_manifest, dict):
                current_manifest = {}
            try:
                request_decision = json.loads(
                    str(request_row["replay_decision_json"] or "{}")
                )
            except (json.JSONDecodeError, TypeError):
                request_decision = {}
            if not isinstance(request_decision, dict):
                request_decision = {}
            accepted_keys = [
                str(value)
                for value in list(current_manifest.get("accepted_advancement_keys") or [])
                if str(value).strip()
            ]
            if clean_key in accepted_keys:
                accepted_decision = dict(request_decision)
                if isinstance(accepted_decision, dict):
                    accepted_decision["admission_state"] = "accepted"
                    conn.execute(
                        """
                        UPDATE provider_requests
                        SET replay_decision_json = ?, updated_at = ?
                        WHERE request_id = ? AND restore_hold = 0
                        """,
                        (
                            json.dumps(
                                accepted_decision,
                                separators=(",", ":"),
                                sort_keys=True,
                            ),
                            utc_now(),
                            request_id,
                        ),
                    )
                conn.execute("COMMIT")
                result = dict(session_row)
                result["advance_status"] = "already_advanced"
                return result
            cursor_matches = int(session_row["history_count"] or 0) == expected
            incoming_visible_keys = [
                str(value)
                for value in list(
                    dict(context_manifest or {}).get("accepted_visible_message_keys") or []
                )
                if str(value).strip()
            ]
            current_visible_keys = [
                str(value)
                for value in list(current_manifest.get("accepted_visible_message_keys") or [])
                if str(value).strip()
            ]
            effective_target = (
                target
                if cursor_matches
                else max(int(session_row["history_count"] or 0), target)
            )

            next_manifest = {
                **dict(context_manifest or {}),
                **current_manifest,
                "messages": effective_target,
                "accepted_advancement_keys": [*accepted_keys, clean_key][-128:],
                "accepted_visible_message_keys": list(
                    dict.fromkeys([*current_visible_keys, *incoming_visible_keys])
                )[-512:],
                "history_cursor_authority": "stable_message_keys_v1",
                "last_accepted_advancement_key": clean_key,
                "last_accepted_request_id": request_id,
            }
            for monotonic_field in (
                "admission_sequence",
                "context_generation",
                "owner_main_context_version",
            ):
                next_manifest[monotonic_field] = max(
                    int(current_manifest.get(monotonic_field) or 0),
                    int(dict(context_manifest or {}).get(monotonic_field) or 0),
                )
            current_last_decision = current_manifest.get(
                "last_accepted_replay_decision_v1"
            )
            if not isinstance(current_last_decision, dict):
                current_last_decision = {}
            incoming_sequence = max(
                0, int(request_decision.get("admission_sequence") or 0)
            )
            current_last_sequence = max(
                int(current_manifest.get("last_accepted_admission_sequence") or 0),
                int(current_last_decision.get("admission_sequence") or 0),
            )
            if incoming_sequence and incoming_sequence < current_last_sequence:
                for pointer_field in (
                    "last_request_id",
                    "last_accepted_request_id",
                    "last_accepted_advancement_key",
                    "last_accepted_replay_decision_v1",
                ):
                    if pointer_field in current_manifest:
                        next_manifest[pointer_field] = current_manifest[pointer_field]
                    else:
                        next_manifest.pop(pointer_field, None)
            elif incoming_sequence:
                next_manifest["last_request_id"] = request_id
                next_manifest["last_accepted_request_id"] = request_id
                next_manifest["last_accepted_advancement_key"] = clean_key
                incoming_last_decision = dict(context_manifest or {}).get(
                    "last_accepted_replay_decision_v1"
                )
                next_manifest["last_accepted_replay_decision_v1"] = (
                    incoming_last_decision
                    if isinstance(incoming_last_decision, dict)
                    else request_decision
                )
            next_manifest["last_accepted_admission_sequence"] = max(
                current_last_sequence, incoming_sequence
            )
            accepted_at = utc_now()
            conn.executemany(
                """
                INSERT OR IGNORE INTO provider_session_visible_admissions (
                    session_id, message_key, advancement_key, accepted_at
                ) VALUES (?, ?, ?, ?)
                """,
                [
                    (session_id, message_key, clean_key, accepted_at)
                    for message_key in incoming_visible_keys
                    if str(message_key).strip()
                ],
            )
            cursor = conn.execute(
                """
                UPDATE provider_sessions
                SET history_count = ?, context_manifest_json = ?, updated_at = ?
                WHERE session_id = ?
                """,
                (
                    effective_target,
                    json.dumps(next_manifest, sort_keys=True),
                    accepted_at,
                    session_id,
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                raise RuntimeError("Provider session advancement lost its cursor claim")
            accepted_decision = dict(request_decision)
            if isinstance(accepted_decision, dict):
                accepted_decision["admission_state"] = "accepted"
                conn.execute(
                    """
                    UPDATE provider_requests
                    SET replay_decision_json = ?, updated_at = ?
                    WHERE request_id = ? AND restore_hold = 0
                    """,
                    (
                        json.dumps(
                            accepted_decision,
                            separators=(",", ":"),
                            sort_keys=True,
                        ),
                        utc_now(),
                        request_id,
                    ),
                )
            row = conn.execute(
                "SELECT * FROM provider_sessions WHERE session_id = ?",
                (session_id,),
            ).fetchone()
            conn.execute("COMMIT")
        result = dict(row)
        result["advance_status"] = "advanced" if cursor_matches else "reconciled_stale"
        return result

    def get_provider_request_for_run(self, run_id: str) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE run_id = ? LIMIT 1",
                (str(run_id or "").strip(),),
            ).fetchone()
        return self._row(row)

    def list_completed_provider_requests_pending_acceptance(
        self,
        *,
        tenant_id: str = "",
        owner_id: str = "",
        limit: int = 64,
    ) -> list[dict[str, Any]]:
        """Find completed Main requests whose exact accepted-turn commit was interrupted."""

        clauses = [
            "restore_hold = 0",
            "state = 'completed'",
            "json_valid(replay_decision_json)",
            "COALESCE(json_extract(replay_decision_json, '$.main_context_protocol'), '') = 'main_context_v1'",
            "COALESCE(json_extract(replay_decision_json, '$.logical_turn_id'), '') <> ''",
            "COALESCE(json_extract(replay_decision_json, '$.admission_state'), '') <> 'accepted'",
        ]
        params: list[Any] = []
        if str(tenant_id or "").strip():
            clauses.append("tenant_id = ?")
            params.append(str(tenant_id).strip())
        if str(owner_id or "").strip():
            clauses.append("owner_id = ?")
            params.append(str(owner_id).strip())
        params.append(max(1, min(int(limit), 256)))
        with self._connect() as conn:
            rows = conn.execute(
                f"""
                SELECT * FROM provider_requests
                WHERE {' AND '.join(clauses)}
                ORDER BY updated_at ASC, created_at ASC, request_id ASC
                LIMIT ?
                """,
                params,
            ).fetchall()
        return self._rows(rows)

    def get_provider_session_admission_state(
        self,
        session_id: str,
        *,
        candidate_keys: Iterable[str] | None = None,
    ) -> dict[str, Any]:
        """Return accepted and still-reserved visible input keys for one native session.

        The request row is the durable reservation. Queued/running requests own their admitted
        keys; a completed request keeps ownership until its advancement transaction marks the
        decision accepted. Failed or cancelled work releases its keys for a later retry.
        """

        clean_candidates = list(
            dict.fromkeys(
                str(value).strip()
                for value in list(candidate_keys or [])
                if str(value).strip()
            )
        )
        with self._connect() as conn:
            session_row = conn.execute(
                "SELECT context_manifest_json FROM provider_sessions WHERE session_id = ?",
                (session_id,),
            ).fetchone()
            request_rows = conn.execute(
                """
                SELECT state, replay_decision_json
                FROM provider_requests
                WHERE session_id = ? AND restore_hold = 0 AND state IN ('queued', 'running', 'completed')
                ORDER BY created_at, request_id
                """,
                (session_id,),
            ).fetchall()
            if clean_candidates:
                placeholders = ", ".join("?" for _ in clean_candidates)
                accepted_rows = conn.execute(
                    f"""
                    SELECT message_key
                    FROM provider_session_visible_admissions
                    WHERE session_id = ?
                      AND message_key IN ({placeholders})
                    """,
                    (session_id, *clean_candidates),
                ).fetchall()
            else:
                accepted_rows = conn.execute(
                    """
                    SELECT message_key
                    FROM provider_session_visible_admissions
                    WHERE session_id = ?
                    """,
                    (session_id,),
                ).fetchall()
        try:
            manifest = json.loads(str(session_row["context_manifest_json"] or "{}"))
        except (json.JSONDecodeError, TypeError):
            manifest = {}
        if not isinstance(manifest, dict):
            manifest = {}
        accepted = {
            str(value)
            for value in list(manifest.get("accepted_visible_message_keys") or [])
            if str(value).strip()
        }
        accepted.update(
            str(row["message_key"])
            for row in accepted_rows
            if str(row["message_key"] or "").strip()
        )
        accepted_advancements = {
            str(value)
            for value in list(manifest.get("accepted_advancement_keys") or [])
            if str(value).strip()
        }
        reserved: set[str] = set()
        max_sequence = max(0, int(manifest.get("admission_sequence") or 0))
        for row in request_rows:
            try:
                decision = json.loads(str(row["replay_decision_json"] or "{}"))
            except (json.JSONDecodeError, TypeError):
                decision = {}
            if not isinstance(decision, dict):
                continue
            stable_protocol = str(decision.get("main_context_protocol") or "").strip()
            if (
                stable_protocol != "main_context_v1"
                or not str(decision.get("logical_turn_id") or "").strip()
            ):
                continue
            max_sequence = max(max_sequence, int(decision.get("admission_sequence") or 0))
            if (
                str(decision.get("admission_state") or "") == "accepted"
                or str(decision.get("advancement_key") or "") in accepted_advancements
            ):
                continue
            reserved.update(
                str(value)
                for value in list(decision.get("admitted_visible_message_keys") or [])
                if str(value).strip() and str(value) not in accepted
            )
            response_key = str(decision.get("response_message_key") or "").strip()
            if response_key and response_key not in accepted:
                reserved.add(response_key)
        return {
            "accepted_visible_message_keys": sorted(accepted),
            "reserved_visible_message_keys": sorted(reserved),
            "admission_sequence": max_sequence,
        }

    def fail_stale_unassigned_provider_requests(
        self,
        *,
        updated_before: str,
        request_id: str = "",
    ) -> list[dict[str, Any]]:
        """Release durable input reservations abandoned before native-run attachment."""

        params: list[Any] = [utc_now(), str(updated_before or "")]
        request_clause = ""
        if str(request_id or "").strip():
            request_clause = " AND request_id = ?"
            params.append(str(request_id).strip())
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = conn.execute(
                f"""
                SELECT request_id
                FROM provider_requests
                WHERE state = 'queued'
                  AND restore_hold = 0
                  AND (run_id IS NULL OR run_id = '')
                  AND updated_at <= ?
                  {request_clause}
                """,
                params[1:],
            ).fetchall()
            request_ids = [str(row["request_id"]) for row in rows]
            if request_ids:
                placeholders = ", ".join("?" for _ in request_ids)
                conn.execute(
                    f"""
                    UPDATE provider_requests
                    SET state = 'failed',
                        fallback_state = 'admission_interrupted',
                        updated_at = ?
                    WHERE request_id IN ({placeholders})
                      AND state = 'queued'
                      AND restore_hold = 0
                      AND (run_id IS NULL OR run_id = '')
                    """,
                    (params[0], *request_ids),
                )
            current_rows = (
                conn.execute(
                    f"SELECT * FROM provider_requests WHERE request_id IN "
                    f"({', '.join('?' for _ in request_ids)})",
                    request_ids,
                ).fetchall()
                if request_ids
                else []
            )
            conn.execute("COMMIT")
        return [dict(row) for row in current_rows]

    def list_provider_requests_by_idempotency_family(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        base_idempotency_key: str,
    ) -> list[dict[str, Any]]:
        """Return one owner-scoped base request and its graph-execution children."""

        escaped = (
            str(base_idempotency_key or "")
            .replace("\\", "\\\\")
            .replace("%", "\\%")
            .replace("_", "\\_")
        )
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM provider_requests
                WHERE tenant_id = ?
                  AND owner_id = ?
                  AND (
                    idempotency_key = ?
                    OR idempotency_key LIKE ? ESCAPE '\\'
                  )
                ORDER BY created_at DESC, request_id DESC
                """,
                (
                    tenant_id,
                    owner_id,
                    base_idempotency_key,
                    f"{escaped}:graph:%",
                ),
            ).fetchall()
        return [self._row(row) for row in rows if row is not None]

    def upsert_provider_stop_tombstone(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        base_idempotency_key: str,
        ttl_seconds: float,
    ) -> dict[str, Any]:
        now_dt = datetime.now(timezone.utc)
        now = now_dt.isoformat()
        expires_at = (now_dt + timedelta(seconds=max(0.001, float(ttl_seconds)))).isoformat()
        data = {
            "tenant_id": tenant_id or "local",
            "owner_id": owner_id,
            "base_idempotency_key": base_idempotency_key,
            "created_at": now,
            "expires_at": expires_at,
        }
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            conn.execute(
                "DELETE FROM provider_stop_tombstones WHERE expires_at <= ?",
                (now,),
            )
            conn.execute(
                """
                INSERT INTO provider_stop_tombstones (
                    tenant_id, owner_id, base_idempotency_key, created_at, expires_at
                ) VALUES (
                    :tenant_id, :owner_id, :base_idempotency_key, :created_at, :expires_at
                )
                ON CONFLICT (tenant_id, owner_id, base_idempotency_key)
                DO UPDATE SET created_at = excluded.created_at,
                              expires_at = excluded.expires_at
                """,
                data,
            )
            row = conn.execute(
                """
                SELECT * FROM provider_stop_tombstones
                WHERE tenant_id = ? AND owner_id = ? AND base_idempotency_key = ?
                """,
                (data["tenant_id"], owner_id, base_idempotency_key),
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row) or data

    def is_provider_stop_tombstone_active(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        idempotency_keys: tuple[str, ...],
    ) -> bool:
        keys = tuple(dict.fromkeys(str(key).strip() for key in idempotency_keys if str(key).strip()))
        if not keys:
            return False
        placeholders = ", ".join("?" for _ in keys)
        with self._connect() as conn:
            row = conn.execute(
                f"""
                SELECT 1 FROM provider_stop_tombstones
                WHERE tenant_id = ?
                  AND owner_id = ?
                  AND base_idempotency_key IN ({placeholders})
                  AND expires_at > ?
                LIMIT 1
                """,
                (tenant_id or "local", owner_id, *keys, utc_now()),
            ).fetchone()
        return row is not None

    def claim_provider_request_fallback(
        self,
        request_id: str,
        *,
        expected_run_id: str,
    ) -> dict[str, Any] | None:
        """Durably elect one serial-fallback starter across pollers/processes."""

        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE provider_requests
                SET fallback_state = 'claimed',
                    fallback_from_run_id = :expected_run_id,
                    updated_at = :updated_at
                WHERE request_id = :request_id
                  AND run_id = :expected_run_id
                  AND restore_hold = 0
                  AND fallback_state = ''
                  AND state IN ('queued', 'running')
                  AND NOT EXISTS (
                      SELECT 1 FROM runs
                      WHERE runs.run_id = :expected_run_id
                        AND runs.provider_liveness_route_locked = 1
                  )
                """,
                {
                    "request_id": request_id,
                    "expected_run_id": expected_run_id,
                    "updated_at": now,
                },
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
        return self._row(row)

    def claim_provider_request_context_recovery(
        self,
        request_id: str,
        *,
        expected_run_id: str,
    ) -> dict[str, Any] | None:
        """Elect one compact-and-retry starter without consuming the model fallback."""

        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE provider_requests
                SET fallback_state = 'context_recovery_claimed',
                    fallback_from_run_id = :recovery_marker,
                    updated_at = :updated_at
                WHERE request_id = :request_id
                  AND run_id = :expected_run_id
                  AND restore_hold = 0
                  AND fallback_state = ''
                  AND fallback_from_run_id NOT LIKE 'context_recovery:%'
                  AND state IN ('queued', 'running')
                """,
                {
                    "request_id": request_id,
                    "expected_run_id": expected_run_id,
                    "recovery_marker": f"context_recovery:{expected_run_id}",
                    "updated_at": now,
                },
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
        return self._row(row)

