    def fail_stale_provider_request_fallback(
        self,
        request_id: str,
        *,
        claimed_before: str,
    ) -> dict[str, Any] | None:
        """Turn an abandoned fallback claim into an honest terminal failure."""

        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE provider_requests
                SET state = 'failed',
                    fallback_state = 'failed',
                    updated_at = :updated_at
                WHERE request_id = :request_id
                  AND fallback_state = 'claimed'
                  AND restore_hold = 0
                  AND state IN ('queued', 'running')
                  AND updated_at <= :claimed_before
                """,
                {
                    "request_id": request_id,
                    "claimed_before": claimed_before,
                    "updated_at": now,
                },
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
        return self._row(row)

    def claim_provider_request_cancel(self, request_id: str) -> dict[str, Any] | None:
        """Make Stop sticky and cancel its exact pending run in one transaction."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            cursor = conn.execute(
                """
                UPDATE provider_requests
                SET state = 'cancelled',
                    fallback_state = 'cancelled',
                    updated_at = :updated_at
                WHERE request_id = :request_id
                  AND restore_hold = 0
                  AND state IN ('queued', 'running')
                """,
                {"request_id": request_id, "updated_at": now},
            )
            if cursor.rowcount != 1:
                conn.execute("COMMIT")
                return None
            request_row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
            run_id = str(request_row["run_id"] or "") if request_row else ""
            pending_cancelled = 0
            pending_worker_id = ""
            if run_id:
                pending_run = conn.execute(
                    "SELECT worker_id FROM runs WHERE run_id = ?",
                    (run_id,),
                ).fetchone()
                pending_worker_id = (
                    str(pending_run["worker_id"] or "") if pending_run else ""
                )
                run_cursor = conn.execute(
                    """
                    UPDATE runs
                    SET state = 'cancelled',
                        ended_at = ?,
                        error_text = 'Cancelled by operator before execution or resumption',
                        failure_class = '', failure_retryable = 0,
                        failure_structured = 0, failure_user_message = '',
                        failure_recommended_recovery = '',
                        failure_diagnostic_summary = '', retry_after = NULL,
                        retry_attempts = 0, last_retry_class = ''
                    WHERE run_id = ?
                      AND (
                          state = 'queued'
                          OR (
                              state = 'needs_input'
                              AND NOT EXISTS (
                                  SELECT 1 FROM host_run_leases
                                  WHERE host_run_leases.run_id = runs.run_id
                                    AND host_run_leases.status = 'active'
                              )
                          )
                      )
                    """,
                    (now, run_id),
                )
                pending_cancelled = run_cursor.rowcount
            if pending_cancelled:
                conn.execute(
                    """
                    UPDATE scheduled_runs
                    SET state = 'cancelled',
                        last_error = 'Cancelled by operator before execution or resumption',
                        updated_at = ?
                    WHERE queued_run_id = ? AND state IN ('queued', 'running')
                    """,
                    (now, run_id),
                )
                if pending_worker_id:
                    conn.execute(
                        """
                        UPDATE workers
                        SET state = 'ready', last_error = '', updated_at = ?
                        WHERE worker_id = ? AND state = 'needs_input'
                          AND NOT EXISTS (
                              SELECT 1 FROM runs
                              WHERE worker_id = ? AND state IN (
                                  'queued', 'claimed', 'admitted', 'running',
                                  'settling', 'paused', 'needs_input'
                              )
                          )
                        """,
                        (now, pending_worker_id, pending_worker_id),
                    )
                self._record_terminal_artifact_trace_conn(
                    conn,
                    run_id=run_id,
                    observed_at=now,
                )
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def reconcile_cancelled_provider_needs_input_runs_for_worker(
        self, worker_id: str, *, run_id: str = ""
    ) -> list[dict[str, Any]]:
        """Settle legacy provider turns cancelled while their run awaited input."""

        clean_worker_id = str(worker_id or "").strip()
        if not clean_worker_id:
            return []
        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = conn.execute(
                """
                SELECT DISTINCT runs.run_id
                FROM runs
                JOIN provider_requests
                  ON provider_requests.run_id = runs.run_id
                WHERE runs.worker_id = ?
                  AND runs.state = 'needs_input'
                  AND provider_requests.state = 'cancelled'
                  AND (? = '' OR runs.run_id = ?)
                  AND NOT EXISTS (
                      SELECT 1 FROM host_run_leases
                      WHERE host_run_leases.run_id = runs.run_id
                        AND host_run_leases.status = 'active'
                  )
                ORDER BY runs.run_id
                """,
                (clean_worker_id, run_id, run_id),
            ).fetchall()
            run_ids = [str(row["run_id"]) for row in rows]
            if run_ids:
                placeholders = ", ".join("?" for _ in run_ids)
                conn.execute(
                    f"""
                    UPDATE runs
                    SET state = 'cancelled', ended_at = ?,
                        error_text = 'Cancelled provider turn reconciled after awaiting input',
                        failure_class = '', failure_retryable = 0,
                        failure_structured = 0, failure_user_message = '',
                        failure_recommended_recovery = '',
                        failure_diagnostic_summary = '', retry_after = NULL,
                        retry_attempts = 0, last_retry_class = ''
                    WHERE run_id IN ({placeholders}) AND state = 'needs_input'
                    """,
                    (now, *run_ids),
                )
                conn.execute(
                    f"""
                    UPDATE scheduled_runs
                    SET state = 'cancelled',
                        last_error = 'Cancelled provider turn reconciled after awaiting input',
                        updated_at = ?
                    WHERE queued_run_id IN ({placeholders})
                      AND state IN ('queued', 'running')
                    """,
                    (now, *run_ids),
                )
                for run_id in run_ids:
                    self._record_terminal_artifact_trace_conn(
                        conn,
                        run_id=run_id,
                        observed_at=now,
                    )
                conn.execute(
                    """
                    UPDATE workers
                    SET state = 'ready', last_error = '', updated_at = ?
                    WHERE worker_id = ? AND state = 'needs_input'
                      AND NOT EXISTS (
                          SELECT 1 FROM runs
                          WHERE worker_id = ? AND state IN (
                              'claimed', 'admitted', 'running',
                              'settling', 'paused', 'needs_input'
                          )
                      )
                    """,
                    (now, clean_worker_id, clean_worker_id),
                )
            current_rows = (
                conn.execute(
                    f"SELECT * FROM runs WHERE run_id IN ({', '.join('?' for _ in run_ids)}) "
                    "ORDER BY run_id",
                    run_ids,
                ).fetchall()
                if run_ids
                else []
            )
            conn.execute("COMMIT")
        return self._rows(current_rows)

    def claim_provider_request_deadline(self, request_id: str) -> dict[str, Any] | None:
        """Make a provider response deadline terminal before native cleanup begins."""

        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE provider_requests
                SET state = 'failed',
                    fallback_state = 'deadline_exceeded',
                    updated_at = :updated_at
                WHERE request_id = :request_id
                  AND restore_hold = 0
                  AND state IN ('queued', 'running')
                """,
                {"request_id": request_id, "updated_at": now},
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
        return self._row(row)

    def arbitrate_provider_request_deadline(
        self,
        request_id: str,
        *,
        default_timeout_s: float,
        failure_class: str,
        failure_user_message: str,
        failure_recommended_recovery: str,
        failure_diagnostic_summary: str,
    ) -> dict[str, Any]:
        """Atomically accept an on-time terminal run or make its deadline final."""

        now_dt = datetime.now(timezone.utc)
        now = now_dt.isoformat()

        def parsed_timestamp(value: Any) -> datetime | None:
            try:
                parsed = datetime.fromisoformat(str(value or ""))
            except ValueError:
                return None
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.astimezone(timezone.utc)

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            request_row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
            if request_row is None:
                conn.execute("COMMIT")
                return {
                    "request": None,
                    "run": None,
                    "deadline_exceeded": False,
                    "newly_expired": False,
                }

            request = dict(request_row)
            run_id = str(request.get("run_id") or "").strip()
            run_row = (
                conn.execute("SELECT * FROM runs WHERE run_id = ?", (run_id,)).fetchone()
                if run_id
                else None
            )
            run = dict(run_row) if run_row is not None else None
            if bool(request.get("restore_hold")):
                conn.execute("COMMIT")
                return {
                    "request": request,
                    "run": run,
                    "deadline_exceeded": False,
                    "newly_expired": False,
                }

            try:
                stored_timeout = float(request.get("response_timeout_s"))
            except (TypeError, ValueError):
                stored_timeout = 0.0
            if not math.isfinite(stored_timeout) or stored_timeout <= 0:
                stored_timeout = float(default_timeout_s)

            deadline = parsed_timestamp(request.get("response_deadline_at"))
            if deadline is None and str(request.get("state") or "") in {
                "queued",
                "running",
            }:
                created_at = parsed_timestamp(request.get("created_at")) or now_dt
                deadline = created_at + timedelta(seconds=stored_timeout)
                conn.execute(
                    """
                    UPDATE provider_requests
                    SET response_timeout_s = ?, response_deadline_at = ?, updated_at = ?
                    WHERE request_id = ?
                    """,
                    (stored_timeout, deadline.isoformat(), now, request_id),
                )
                request["response_timeout_s"] = stored_timeout
                request["response_deadline_at"] = deadline.isoformat()
                request["updated_at"] = now

            request_state = str(request.get("state") or "")
            run_state = str((run or {}).get("state") or "")
            run_ended_at = parsed_timestamp((run or {}).get("ended_at"))
            run_terminal = run_state in {
                "completed",
                "failed",
                "cancelled",
                "interrupted",
            }
            run_terminal_on_time = bool(
                deadline
                and run_terminal
                and run_ended_at
                and run_ended_at <= deadline
            )
            completed_late = bool(
                deadline
                and request_state == "completed"
                and run_state == "completed"
                and run_ended_at
                and run_ended_at > deadline
            )
            failed_late = bool(
                deadline
                and request_state == "failed"
                and not str(request.get("fallback_state") or "")
                and run_state == "failed"
                and run_ended_at
                and run_ended_at > deadline
            )
            deadline_elapsed = bool(deadline and now_dt >= deadline)
            # A failed native start can be synchronized before a waiter arbitrates the
            # deadline. Its terminal run time still determines the client-visible cause.
            should_expire = completed_late or failed_late or (
                request_state in {"queued", "running"}
                and deadline_elapsed
                and not run_terminal_on_time
            )

            newly_expired = False
            if should_expire:
                conn.execute(
                    """
                    UPDATE provider_requests
                    SET state = 'failed',
                        fallback_state = 'deadline_exceeded',
                        response_json = '',
                        updated_at = ?
                    WHERE request_id = ?
                    """,
                    (now, request_id),
                )
                if run_id:
                    run_cursor = conn.execute(
                        """
                        UPDATE runs
                        SET state = 'failed',
                            ended_at = COALESCE(ended_at, ?),
                            output_text = '',
                            error_text = ?,
                            failure_class = ?,
                            failure_retryable = 1,
                            failure_structured = 1,
                            failure_user_message = ?,
                            failure_recommended_recovery = ?,
                            failure_diagnostic_summary = ?
                        WHERE run_id = ?
                          AND state IN (
                              'queued', 'claimed', 'admitted', 'running',
                              'settling', 'paused', 'needs_input',
                              'completed', 'failed'
                          )
                        """,
                        (
                            now,
                            failure_user_message,
                            failure_class,
                            failure_user_message,
                            failure_recommended_recovery,
                            failure_diagnostic_summary,
                            run_id,
                        ),
                    )
                    attempt_id = str((run or {}).get("active_attempt_id") or "")
                    if run_cursor.rowcount == 1 and attempt_id:
                        attempt_cursor = conn.execute(
                            """
                            UPDATE run_attempts
                            SET state = 'failed', ended_at = COALESCE(ended_at, ?),
                                terminal_reason = ?
                            WHERE attempt_id = ? AND run_id = ?
                              AND state IN (
                                  'claimed', 'admitted', 'running', 'settling',
                                  'paused', 'needs_input'
                              )
                              AND ended_at IS NULL
                            """,
                            (now, failure_class, attempt_id, run_id),
                        )
                        if attempt_cursor.rowcount == 1:
                            self._append_attempt_trace_conn(
                                conn,
                                attempt_id=attempt_id,
                                created_at=now,
                            )
                    if run_cursor.rowcount == 1:
                        self._record_terminal_artifact_trace_conn(
                            conn,
                            run_id=run_id,
                            observed_at=now,
                        )
                # A concurrent observer may have recorded a generic failed event
                # before this transaction established the deadline as the cause.
                # Keep its sequence and other details, but correct the final class.
                failed_events = conn.execute(
                    "SELECT sequence_id, payload_json FROM provider_activity "
                    "WHERE request_id = ? AND event_type = 'failed'",
                    (request_id,),
                ).fetchall()
                for event in failed_events:
                    try:
                        payload = json.loads(str(event["payload_json"] or "{}"))
                    except (TypeError, ValueError):
                        payload = {}
                    if not isinstance(payload, dict):
                        payload = {}
                    payload["failure_class"] = failure_class
                    payload["timeout_seconds"] = stored_timeout
                    conn.execute(
                        "UPDATE provider_activity SET payload_json = ? WHERE sequence_id = ?",
                        (json.dumps(payload, sort_keys=True), event["sequence_id"]),
                    )
                newly_expired = True

            request_row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
            run_row = (
                conn.execute("SELECT * FROM runs WHERE run_id = ?", (run_id,)).fetchone()
                if run_id
                else None
            )
            conn.execute("COMMIT")

        request = self._row(request_row)
        run = self._row(run_row)
        return {
            "request": request,
            "run": run,
            "deadline_exceeded": bool(
                request
                and str(request.get("fallback_state") or "")
                == "deadline_exceeded"
            ),
            "newly_expired": newly_expired,
        }

    def commit_provider_request_terminal(
        self, request_id: str, *, expected_run_id: str, state: str,
        response_json: str = "", summary: str = "", activity_payload: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Commit terminal state and its first canonical artifact against the same run/Stop."""
        if state not in {"completed", "failed", "cancelled"}:
            raise ValueError("Invalid provider terminal state")
        if state == "completed" and not response_json:
            raise ValueError("Completed provider request requires a saved response")
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            changed = conn.execute(
                """
                UPDATE provider_requests SET state = ?, response_json = ?, updated_at = ?
                WHERE request_id = ? AND run_id = ?
                  AND restore_hold = 0
                  AND fallback_state NOT IN ('claimed', 'context_recovery_claimed')
                  AND (state IN ('queued', 'running') OR
                       (state = 'completed' AND ? = 'completed' AND response_json = ''))
                """,
                (state, response_json if state == "completed" else "", utc_now(),
                 request_id, expected_run_id, state),
            ).rowcount
            if changed and summary:
                conn.execute(
                    """
                    INSERT INTO provider_activity(request_id, event_type, summary, payload_json, created_at)
                    SELECT ?, ?, ?, ?, ? WHERE NOT EXISTS (
                        SELECT 1 FROM provider_activity WHERE request_id = ? AND event_type = ?)
                    """,
                    (request_id, state, summary, json.dumps(activity_payload or {}, sort_keys=True),
                     utc_now(), request_id, state),
                )
            row = conn.execute("SELECT * FROM provider_requests WHERE request_id = ?", (request_id,)).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def set_provider_request_response_if_empty(
        self, request_id: str, response_json: str
    ) -> dict[str, Any] | None:
        """Persist and return the first canonical response built for one request."""

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            conn.execute(
                """
                UPDATE provider_requests
                SET response_json = ?, updated_at = ?
                WHERE request_id = ?
                  AND restore_hold = 0
                  AND (response_json IS NULL OR response_json = '')
                """,
                (str(response_json or ""), utc_now(), request_id),
            )
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?", (request_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def update_provider_request_if_state(
        self,
        request_id: str,
        expected_states: tuple[str, ...],
        **fields: Any,
    ) -> dict[str, Any] | None:
        """Update an active provider row without reviving a terminal Stop/deadline."""

        if not fields or not expected_states:
            return None
        fields["updated_at"] = utc_now()
        assignments = ", ".join(f"{key} = :{key}" for key in fields)
        fields["request_id"] = request_id
        expected_parameters = {
            f"expected_state_{index}": state
            for index, state in enumerate(expected_states)
        }
        placeholders = ", ".join(
            f":{key}" for key in expected_parameters
        )
        parameters = {**fields, **expected_parameters}
        with self._connect() as conn:
            cursor = conn.execute(
                f"""
                UPDATE provider_requests
                SET {assignments}
                WHERE request_id = :request_id AND restore_hold = 0 AND state IN ({placeholders})
                """,
                parameters,
            )
            row = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (request_id,),
            ).fetchone()
        return self._row(row) if cursor.rowcount == 1 else None

    def reopen_direct_provider_needs_input(
        self,
        request_id: str,
        *,
        run_id: str,
        response_timeout_s: float | None,
        response_deadline_at: str,
    ) -> dict[str, dict[str, Any]] | None:
        """Atomically reopen one exact direct conversation authorization retry."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            request = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (str(request_id),),
            ).fetchone()
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?",
                (str(run_id),),
            ).fetchone()
            worker = (
                conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?",
                    (str(run["worker_id"]),),
                ).fetchone()
                if run is not None
                else None
            )
            attempt_id = str(run["active_attempt_id"] or "") if run else ""
            attempt = (
                conn.execute(
                    "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                    (attempt_id, str(run_id)),
                ).fetchone()
                if attempt_id
                else None
            )
            active_lease = conn.execute(
                "SELECT 1 FROM host_run_leases WHERE run_id = ? AND status = 'active' LIMIT 1",
                (str(run_id),),
            ).fetchone()
            exact = bool(
                request is not None
                and run is not None
                and worker is not None
                and str(request["run_id"] or "") == str(run_id)
                and str(request["state"] or "") == "failed"
                and not str(request["fallback_state"] or "")
                and not str(request["response_json"] or "")
                and str(run["state"] or "") == "needs_input"
                and str(run["failure_class"] or "")
                == "conversation_capability_grant_required"
                and not bool(run["failure_retryable"])
                and bool(run["failure_structured"])
                and (
                    str(worker["state"] or "") == "needs_input"
                    or (
                        str(worker["state"] or "") in {"ready", "starting", "running"}
                        and json.loads(str(request["replay_decision_json"] or "{}")).get(
                            "provider_session_mode") == "stateless"
                    )
                )
                and not str(worker["compute_release_token"] or "")
                and not conn.execute(
                    "SELECT 1 FROM runs WHERE worker_id = ? AND state = 'paused' LIMIT 1",
                    (worker["worker_id"],),
                ).fetchone()
                and str((conn.execute(
                    "SELECT event_type FROM events WHERE worker_id = ? AND event_type IN "
                    "('worker.paused', 'worker.resumed', 'worker.resumed_by_alias') ORDER BY rowid DESC LIMIT 1",
                    (worker["worker_id"],),
                ).fetchone() or [""])[0]) != "worker.paused"
                and active_lease is None
                and (
                    not attempt_id
                    or (
                        attempt is not None
                        and str(attempt["state"] or "") == "needs_input"
                        and attempt["ended_at"] is not None
                    )
                )
            )
            if not exact:
                conn.execute("COMMIT")
                return None
            self._require_worker_work_admission(worker)
            generation = max(1, int(run["queue_wait_generation"] or 0)) + 1
            queue_deadline = (
                _parse_utc(now) + timedelta(seconds=_queue_wait_timeout_seconds())
            ).isoformat()
            next_status_at = (
                _parse_utc(now)
                + timedelta(seconds=_queue_status_refresh_interval_seconds())
            ).isoformat()
            run_cursor = conn.execute(
                """
                UPDATE runs
                SET state = 'queued', claimed_at = NULL, admitted_at = NULL,
                    runtime_invoked_at = NULL, active_attempt_id = '', ended_at = NULL,
                    retry_after = NULL, error_text = '', failure_class = '',
                    failure_retryable = 0, failure_structured = 0,
                    failure_user_message = '', failure_recommended_recovery = '',
                    failure_diagnostic_summary = '', last_retry_class = '',
                    queue_wait_episode = ?, queue_wait_open = 1,
                    queue_wait_generation = ?, queue_wait_started_at = ?,
                    queue_wait_closed_at = NULL, queue_wait_duration_seconds = NULL,
                    queue_deadline_at = ?, queue_next_status_at = ?,
                    queue_blocker_class = 'admission_pending',
                    queue_transition_emitted = 0, queue_status_sequence = 0,
                    queue_callback_state = 'unknown', queue_terminal_callback_id = ?
                WHERE run_id = ? AND state = 'needs_input'
                  AND failure_class = 'conversation_capability_grant_required'
                  AND failure_retryable = 0 AND failure_structured = 1
                """,
                (
                    generation,
                    generation,
                    now,
                    queue_deadline,
                    next_status_at,
                    _queue_callback_id(
                        "timeout",
                        run_id=str(run_id),
                        generation=generation,
                        deadline=queue_deadline,
                    ),
                    str(run_id),
                ),
            )
            request_cursor = conn.execute(
                """
                UPDATE provider_requests
                SET state = 'queued', response_timeout_s = ?,
                    response_deadline_at = ?, updated_at = ?
                WHERE request_id = ? AND run_id = ? AND state = 'failed'
                  AND restore_hold = 0
                  AND fallback_state = ''
                  AND (response_json IS NULL OR response_json = '')
                """,
                (
                    response_timeout_s,
                    str(response_deadline_at or ""),
                    now,
                    str(request_id),
                    str(run_id),
                ),
            )
            if run_cursor.rowcount != 1 or request_cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            reopened_request = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (str(request_id),),
            ).fetchone()
            reopened_run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?",
                (str(run_id),),
            ).fetchone()
            conn.execute("COMMIT")
        return {
            "request": self._row(reopened_request) or {},
            "run": self._row(reopened_run) or {},
        }

    @staticmethod
    def _provider_health_now(now: datetime | None = None) -> datetime:
        current = now or datetime.now(timezone.utc)
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        return current.astimezone(timezone.utc)

    @staticmethod
    def _provider_health_timestamp(value: str | None) -> datetime | None:
        raw = str(value or "").strip()
        if not raw:
            return None
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except ValueError:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    def record_provider_route_failure(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        profile: str,
        runtime: str,
        model: str,
        failure_class: str,
        failure_structured: bool,
        default_cooldown_s: float,
        retry_at: str | None = None,
        retry_after_s: float | None = None,
        run_id: str = "",
        evidence_id: str = "",
        attempt_id: str = "",
        evidence_kind: str = "",
        now: datetime | None = None,
    ) -> dict[str, Any] | None:
        """Open one owner-scoped route circuit from structured provider pressure."""

        clean_failure = str(failure_class or "").strip()
        if (
            not bool(failure_structured)
            or clean_failure not in PROVIDER_ROUTE_HEALTH_FAILURE_CLASSES
        ):
            return None
        route = {
            "tenant_id": str(tenant_id or "local").strip() or "local",
            "owner_id": str(owner_id or "").strip(),
            "profile": str(profile or "").strip(),
            "runtime": str(runtime or "").strip(),
            "model": str(model or "").strip(),
        }
        if not all(route.values()):
            raise ValueError("Provider route health requires a complete structural route")
        current = self._provider_health_now(now)
        exact_retry = self._provider_health_timestamp(retry_at)
        if exact_retry is not None:
            cooldown_until = exact_retry
            cooldown_source = "provider_exact"
        elif (
            isinstance(retry_after_s, (int, float))
            and not isinstance(retry_after_s, bool)
            and math.isfinite(float(retry_after_s))
            and float(retry_after_s) >= 0
        ):
            cooldown_until = current + timedelta(seconds=float(retry_after_s))
            cooldown_source = "provider_exact"
        else:
            bounded_default = max(1.0, min(float(default_cooldown_s), 86_400.0))
            cooldown_until = current + timedelta(seconds=bounded_default)
            cooldown_source = "default"
        data = {
            **route,
            "failure_class": clean_failure,
            "failed_at": current.isoformat(),
            "cooldown_until": cooldown_until.isoformat(),
            "cooldown_source": cooldown_source,
            "last_run_id": str(run_id or "").strip(),
        }
        clean_evidence_id = str(evidence_id or "").strip()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            if clean_evidence_id:
                inserted = conn.execute(
                    """
                    INSERT OR IGNORE INTO provider_route_health_events (
                        tenant_id, owner_id, profile, runtime, model,
                        evidence_id, run_id, attempt_id, evidence_kind, observed_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        route["tenant_id"],
                        route["owner_id"],
                        route["profile"],
                        route["runtime"],
                        route["model"],
                        clean_evidence_id,
                        str(run_id or "").strip(),
                        str(attempt_id or "").strip(),
                        str(evidence_kind or "").strip(),
                        data["failed_at"],
                    ),
                )
                if inserted.rowcount != 1:
                    row = conn.execute(
                        """
                        SELECT * FROM provider_route_health
                        WHERE tenant_id = :tenant_id AND owner_id = :owner_id
                          AND profile = :profile AND runtime = :runtime
                          AND model = :model
                        """,
                        route,
                    ).fetchone()
                    conn.execute("COMMIT")
                    return self._row(row)
            conn.execute(
                """
                INSERT INTO provider_route_health (
                    tenant_id, owner_id, profile, runtime, model,
                    failure_class, failure_count, failure_generation, first_failed_at,
                    last_failed_at, cooldown_until, cooldown_source,
                    last_run_id, updated_at
                ) VALUES (
                    :tenant_id, :owner_id, :profile, :runtime, :model,
                    :failure_class, 1, 1, :failed_at, :failed_at,
                    :cooldown_until, :cooldown_source, :last_run_id, :failed_at
                )
                ON CONFLICT(tenant_id, owner_id, profile, runtime, model)
                DO UPDATE SET
                    failure_class = excluded.failure_class,
                    failure_count = provider_route_health.failure_count + 1,
                    failure_generation = provider_route_health.failure_generation + 1,
                    last_failed_at = excluded.last_failed_at,
                    cooldown_until = CASE
                        WHEN provider_route_health.cooldown_until >= excluded.cooldown_until
                        THEN provider_route_health.cooldown_until
                        ELSE excluded.cooldown_until
                    END,
                    cooldown_source = CASE
                        WHEN provider_route_health.cooldown_until >= excluded.cooldown_until
                        THEN provider_route_health.cooldown_source
                        ELSE excluded.cooldown_source
                    END,
                    last_run_id = excluded.last_run_id,
                    updated_at = excluded.updated_at
                WHERE excluded.last_failed_at >= provider_route_health.last_failed_at
                """,
                data,
            )
            row = conn.execute(
                """
                SELECT * FROM provider_route_health
                WHERE tenant_id = :tenant_id AND owner_id = :owner_id
                  AND profile = :profile AND runtime = :runtime AND model = :model
                """,
                route,
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row)

    def get_provider_route_health(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        profile: str,
        runtime: str,
        model: str,
        now: datetime | None = None,
    ) -> dict[str, Any] | None:
        route = {
            "tenant_id": str(tenant_id or "local").strip() or "local",
            "owner_id": str(owner_id or "").strip(),
            "profile": str(profile or "").strip(),
            "runtime": str(runtime or "").strip(),
            "model": str(model or "").strip(),
        }
        now_iso = self._provider_health_now(now).isoformat()
        with self._connect() as conn:
            conn.execute(
                "DELETE FROM provider_route_health WHERE cooldown_until <= ?",
                (now_iso,),
            )
            row = conn.execute(
                """
                SELECT * FROM provider_route_health
                WHERE tenant_id = :tenant_id AND owner_id = :owner_id
                  AND profile = :profile AND runtime = :runtime AND model = :model
                """,
                route,
            ).fetchone()
        return self._row(row)

    def list_provider_route_health(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        now: datetime | None = None,
    ) -> list[dict[str, Any]]:
        now_iso = self._provider_health_now(now).isoformat()
        with self._connect() as conn:
            conn.execute(
                "DELETE FROM provider_route_health WHERE cooldown_until <= ?",
                (now_iso,),
            )
            rows = conn.execute(
                """
                SELECT * FROM provider_route_health
                WHERE tenant_id = ? AND owner_id = ?
                ORDER BY updated_at DESC, profile, runtime, model
                """,
                (str(tenant_id or "local").strip() or "local", str(owner_id or "").strip()),
            ).fetchall()
        return self._rows(rows)

    def clear_provider_route_health(
        self,
        *,
        tenant_id: str,
        owner_id: str,
        profile: str,
        runtime: str,
        model: str,
        expected_last_failed_at: str,
        expected_generation: int,
    ) -> bool:
        expected = str(expected_last_failed_at or "").strip()
        if (
            not expected
            or isinstance(expected_generation, bool)
            or int(expected_generation) < 1
        ):
            return False
        with self._connect() as conn:
            cursor = conn.execute(
                """
                DELETE FROM provider_route_health
                WHERE tenant_id = ? AND owner_id = ?
                  AND profile = ? AND runtime = ? AND model = ?
                  AND last_failed_at = ?
                  AND failure_generation = ?
                """,
                (
                    str(tenant_id or "local").strip() or "local",
                    str(owner_id or "").strip(),
                    str(profile or "").strip(),
                    str(runtime or "").strip(),
                    str(model or "").strip(),
                    expected,
                    int(expected_generation),
                ),
            )
        return int(cursor.rowcount or 0) == 1

    def record_run_attempt_provider_health_observation(
        self,
        *,
        run_id: str,
        attempt_id: str,
        observed_last_failed_at: str,
        observed_generation: int,
    ) -> dict[str, Any] | None:
        """Persist the provider-health generation seen by one immutable attempt."""

        observed = str(observed_last_failed_at or "").strip()
        generation = int(observed_generation)
        if (observed and generation < 1) or (not observed and generation != 0):
            raise ValueError("Provider health observation generation is invalid")
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            cursor = conn.execute(
                """
                UPDATE run_attempts
                SET provider_health_observed_last_failed_at = ?,
                    provider_health_observed_generation = ?
                WHERE attempt_id = ? AND run_id = ?
                  AND provider_health_observed_last_failed_at IS NULL
                  AND provider_health_observed_generation IS NULL
                  AND EXISTS (
                      SELECT 1 FROM runs
                      WHERE runs.run_id = run_attempts.run_id
                        AND runs.active_attempt_id = run_attempts.attempt_id
                        AND runs.state IN ('claimed', 'admitted')
                  )
                """,
                (observed, generation, str(attempt_id), str(run_id)),
            )
            if cursor.rowcount == 1:
                self._append_attempt_trace_conn(
                    conn,
                    attempt_id=str(attempt_id),
                    created_at=utc_now(),
                )
            row = conn.execute(
                "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                (str(attempt_id), str(run_id)),
            ).fetchone()
            conn.execute("COMMIT")
        if row is None:
            return None
        persisted = self._row(row)
        if cursor.rowcount == 1 or str(
            persisted.get("provider_health_observed_last_failed_at") or ""
        ) == observed and int(
            persisted.get("provider_health_observed_generation") or 0
        ) == generation:
            return persisted
        return None

    def get_run_attempt(self, attempt_id: str) -> dict[str, Any] | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM run_attempts WHERE attempt_id = ?",
                (str(attempt_id),),
            ).fetchone()
        return self._row(row)





    @staticmethod
    def _lifecycle_event_id(
        *,
        operation_token: str,
        operation_epoch: int,
        operation_kind: str,
        event_type: str,
        worker_id: str,
        run_id: str,
    ) -> str:
        operation_digest = hashlib.sha256(
            str(operation_token).encode("utf-8")
        ).hexdigest()
        material = "\0".join(
            (
                "glasshive.lifecycle-event.v1",
                operation_digest,
                str(int(operation_epoch)),
                str(operation_kind),
                str(event_type),
                str(worker_id),
                str(run_id or ""),
            )
        )
        return "evt_op_" + hashlib.sha256(material.encode("utf-8")).hexdigest()

    @staticmethod
    def _insert_lifecycle_event(
        conn: sqlite3.Connection,
        *,
        operation_token: str,
        operation_epoch: int,
        operation_kind: str,
        worker: sqlite3.Row,
        run_id: str,
        event_type: str,
        message: str,
        payload: dict[str, Any] | None = None,
    ) -> str:
        """Insert one same-transaction event for an exact lifecycle operation."""

        event_id = Store._lifecycle_event_id(
            operation_token=operation_token,
            operation_epoch=operation_epoch,
            operation_kind=operation_kind,
            event_type=event_type,
            worker_id=str(worker["worker_id"]),
            run_id=run_id,
        )
        conn.execute(
            """
            INSERT OR IGNORE INTO events (
                event_id, project_id, worker_id, tenant_id, run_id,
                event_type, message, payload_json, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                event_id,
                str(worker["project_id"]),
                str(worker["worker_id"]),
                str(worker["tenant_id"] or "local"),
                str(run_id or "") or None,
                str(event_type),
                str(message),
                json.dumps(payload or {}, ensure_ascii=False, sort_keys=True),
                utc_now(),
            ),
        )
        return event_id

    def has_lifecycle_operation_event(
        self,
        *,
        operation_id: str,
        operation_kind: str,
        event_type: str,
        worker_id: str,
        run_id: str,
    ) -> bool:
        clean_operation = str(operation_id or "").strip()
        if not clean_operation:
            return False
        event_id = self._lifecycle_event_id(
            operation_token=clean_operation,
            operation_epoch=0,
            operation_kind=str(operation_kind or "").strip().lower(),
            event_type=str(event_type or "").strip(),
            worker_id=str(worker_id or "").strip(),
            run_id=str(run_id or "").strip(),
        )
        with self._connect() as conn:
            return conn.execute(
                "SELECT 1 FROM events WHERE event_id = ? LIMIT 1", (event_id,)
            ).fetchone() is not None

    @staticmethod
    def _accept_cancel_actions_for_runs(
        conn: sqlite3.Connection,
        run_ids: list[str],
        *,
        updated_at: str,
    ) -> int:
        clean_ids = [str(run_id) for run_id in run_ids if str(run_id)]
        if not clean_ids:
            return 0
        placeholders = ", ".join("?" for _ in clean_ids)
        cursor = conn.execute(
            f"""
            UPDATE run_action_uses
            SET status = 'accepted', result_code = 'cancellation_confirmed',
                updated_at = ?
            WHERE source_run_id IN ({placeholders})
              AND action = 'cancel'
              AND status IN ('reserved', 'executing')
            """,
            (updated_at, *clean_ids),
        )
        return int(cursor.rowcount)

    @staticmethod
    def _enqueue_lifecycle_effects(
        conn: sqlite3.Connection,
        *,
        operation_token: str,
        operation_epoch: int,
        operation_kind: str,
        worker_id: str,
        run_id: str = "",
        effect_kinds: tuple[str, ...] | list[str],
    ) -> list[str]:
        """Persist public-safe idempotent effect references in the caller's txn."""

        token = str(operation_token or "")
        kind = str(operation_kind or "").strip().lower()
        clean_run_id = str(run_id or "")
        if not token or kind not in COMPUTE_OPERATION_KINDS:
            raise ValueError("Lifecycle effects require an exact operation identity")
        operation_digest = hashlib.sha256(token.encode("utf-8")).hexdigest()
        now = utc_now()
        effect_ids: list[str] = []
        for effect_kind in effect_kinds:
            clean_effect_kind = str(effect_kind or "").strip().lower()
            if clean_effect_kind not in LIFECYCLE_EFFECT_KINDS:
                raise ValueError(
                    f"Unsupported lifecycle operation effect: {clean_effect_kind}"
                )
            material = "\0".join(
                (
                    "glasshive.lifecycle-effect.v1",
                    operation_digest,
                    str(int(operation_epoch)),
                    kind,
                    clean_effect_kind,
                    str(worker_id),
                    clean_run_id,
                )
            )
            effect_id = "ope_" + hashlib.sha256(
                material.encode("utf-8")
            ).hexdigest()
            conn.execute(
                """
                INSERT OR IGNORE INTO lifecycle_operation_effects (
                    effect_id, operation_digest, operation_epoch, operation_kind,
                    effect_kind, worker_id, run_id, status, lease_owner,
                    lease_epoch, lease_expires_at, attempts, last_error_code,
                    created_at, updated_at, applied_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', '', 0, NULL, 0, '', ?, ?, NULL)
                """,
                (
                    effect_id,
                    operation_digest,
                    int(operation_epoch),
                    kind,
                    clean_effect_kind,
                    str(worker_id),
                    clean_run_id,
                    now,
                    now,
                ),
            )
            effect_ids.append(effect_id)
        return effect_ids

    def enqueue_capability_grant_revocation(
        self, binding: dict[str, str]
    ) -> dict[str, Any]:
        """Persist a secret-free exact grant/generation revocation before projection."""

        expected = {
            "authorizationRef",
            "originRef",
            "workRef",
            "workerId",
            "runId",
            "grantId",
            "containerGenerationId",
        }
        host_expected = (expected - {"containerGenerationId"}) | {"hostStartupLeaseId"}
        if not isinstance(binding, dict) or set(binding) not in (expected, host_expected):
            raise ValueError("Capability revocation requires an exact binding")
        expected = set(binding)
        normalized = {key: str(binding.get(key) or "").strip() for key in expected}
        if any(not value or len(value) > 256 for value in normalized.values()):
            raise ValueError("Capability revocation requires an exact binding")
        material = "\0".join(
            ("glasshive.capability-revocation.v1",)
            + tuple(normalized[key] for key in sorted(expected))
        )
        revocation_id = "cgr_" + hashlib.sha256(material.encode("utf-8")).hexdigest()
        now = utc_now()
        with self._connect() as conn:
            conn.execute(
                """
                INSERT OR IGNORE INTO capability_grant_revocations (
                    revocation_id, authorization_ref, origin_ref, work_ref,
                    worker_id, run_id, grant_id, container_generation_id,
                    host_startup_lease_id, status, lease_owner, lease_epoch, lease_expires_at,
                    next_attempt_at, attempts, last_error_code,
                    created_at, updated_at, applied_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'armed', '', 0, NULL,
                          NULL, 0, '', ?, ?, NULL)
                """,
                (
                    revocation_id,
                    normalized["authorizationRef"],
                    normalized["originRef"],
                    normalized["workRef"],
                    normalized["workerId"],
                    normalized["runId"],
                    normalized["grantId"],
                    normalized.get("containerGenerationId", ""),
                    normalized.get("hostStartupLeaseId", ""),
                    now,
                    now,
                ),
            )
            row = conn.execute(
                "SELECT * FROM capability_grant_revocations WHERE revocation_id = ?",
                (revocation_id,),
            ).fetchone()
        if row is None:
            raise RuntimeError("Capability revocation persistence failed")
        return self._row(row) or {}

    def list_capability_grant_revocations(
        self, *, status: str | None = None
    ) -> list[dict[str, Any]]:
        query = "SELECT * FROM capability_grant_revocations"
        params: list[Any] = []
        if status is not None:
            query += " WHERE status = ?"
            params.append(str(status))
        query += " ORDER BY created_at ASC, revocation_id ASC"
        with self._connect() as conn:
            rows = conn.execute(query, params).fetchall()
        return self._rows(rows)

    def activate_capability_grant_revocation(
        self, revocation_id: str
    ) -> dict[str, Any] | None:
        now = utc_now()
        with self._connect() as conn:
            conn.execute(
                """
                UPDATE capability_grant_revocations
                SET status = 'pending', updated_at = ?
                WHERE revocation_id = ? AND status = 'armed'
                """,
                (now, str(revocation_id or "")),
            )
            row = conn.execute(
                "SELECT * FROM capability_grant_revocations WHERE revocation_id = ?",
                (str(revocation_id or ""),),
            ).fetchone()
        return self._row(row)

    def activate_due_capability_grant_revocations(self) -> int:
        """Arm crash leftovers only after their exact runtime lease is no longer active."""

        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE capability_grant_revocations AS revocation
                SET status = 'pending', updated_at = ?
                WHERE status = 'armed' AND NOT EXISTS (
                    SELECT 1 FROM host_run_leases AS lease
                    WHERE lease.run_id = revocation.run_id AND lease.status = 'active'
                )
                """,
                (now,),
            )
        return int(cursor.rowcount)

    def claim_next_capability_grant_revocation(
        self,
        executor_id: str,
        *,
        ttl_s: float = 60.0,
        now: datetime | None = None,
        created_before: str | None = None,
        revocation_id: str | None = None,
    ) -> dict[str, Any] | None:
        owner = str(executor_id or "").strip()
        if not owner:
            raise ValueError("Capability revocation claims require an executor")
        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
        now_iso = current.isoformat()
        expires_at = (
            current + timedelta(seconds=max(1.0, float(ttl_s)))
        ).isoformat()
        clauses = [
            "((status = 'pending' AND (next_attempt_at IS NULL OR next_attempt_at <= ?))",
            " OR (status = 'applying' AND lease_expires_at IS NOT NULL AND lease_expires_at <= ?))",
        ]
        params: list[Any] = [now_iso, now_iso]
        clean_created_before = str(created_before or "").strip()
        if clean_created_before:
            clauses.append(" AND created_at <= ?")
            params.append(clean_created_before)
        clean_revocation_id = str(revocation_id or "").strip()
        if clean_revocation_id:
            clauses.append(" AND revocation_id = ?")
            params.append(clean_revocation_id)
        where_clause = "".join(clauses)
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                f"""
                SELECT * FROM capability_grant_revocations
                WHERE {where_clause}
                ORDER BY created_at ASC, revocation_id ASC LIMIT 1
                """,
                params,
            ).fetchone()
            if row is None:
                conn.execute("COMMIT")
                return None
            cursor = conn.execute(
                """
                UPDATE capability_grant_revocations
                SET status = 'applying', lease_owner = ?,
                    lease_epoch = lease_epoch + 1, lease_expires_at = ?,
                    next_attempt_at = NULL, attempts = attempts + 1, updated_at = ?
                WHERE revocation_id = ? AND (
                    (status = 'pending' AND (next_attempt_at IS NULL OR next_attempt_at <= ?))
                    OR (status = 'applying' AND lease_expires_at IS NOT NULL
                        AND lease_expires_at <= ?)
                )
                """,
                (owner, expires_at, now_iso, row["revocation_id"], now_iso, now_iso),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            claimed = conn.execute(
                "SELECT * FROM capability_grant_revocations WHERE revocation_id = ?",
                (row["revocation_id"],),
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(claimed)

    def mark_capability_grant_revocation_applied(
        self, revocation_id: str, executor_id: str, *, lease_epoch: int
    ) -> dict[str, Any] | None:
        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE capability_grant_revocations
                SET status = 'applied', lease_owner = '', lease_expires_at = NULL,
                    next_attempt_at = NULL, last_error_code = '',
                    updated_at = ?, applied_at = ?
                WHERE revocation_id = ? AND status = 'applying'
                  AND lease_owner = ? AND lease_epoch = ?
                """,
                (now, now, str(revocation_id or ""), str(executor_id or ""), int(lease_epoch)),
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM capability_grant_revocations WHERE revocation_id = ?",
                (str(revocation_id or ""),),
            ).fetchone()
        return self._row(row)

    def retry_capability_grant_revocation(
        self,
        revocation_id: str,
        executor_id: str,
        *,
        lease_epoch: int,
        error_code: str,
        retry_delay_s: float = 0.0,
    ) -> dict[str, Any] | None:
        clean_code = str(error_code or "").strip().lower()
        if clean_code not in {
            "broker_revocation_rejected",
            "broker_revocation_unavailable",
            "transient_dependency",
            "unknown",
        }:
            raise ValueError("Capability revocation failures require a safe error code")
        delay_s = max(0.0, min(float(retry_delay_s), 24 * 3600.0))
        retry_at = (
            datetime.now(timezone.utc) + timedelta(seconds=delay_s)
        ).isoformat()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE capability_grant_revocations
                SET status = 'pending', lease_owner = '', lease_expires_at = NULL,
                    next_attempt_at = ?, last_error_code = ?, updated_at = ?
                WHERE revocation_id = ? AND status = 'applying'
                  AND lease_owner = ? AND lease_epoch = ?
                """,
                (
                    retry_at if delay_s > 0 else None,
                    clean_code,
                    utc_now(),
                    str(revocation_id or ""),
                    str(executor_id or ""),
                    int(lease_epoch),
                ),
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM capability_grant_revocations WHERE revocation_id = ?",
                (str(revocation_id or ""),),
            ).fetchone()
        return self._row(row)

    def list_lifecycle_operation_effects(
        self,
        *,
        worker_id: str | None = None,
        status: str | None = None,
    ) -> list[dict[str, Any]]:
        query = "SELECT * FROM lifecycle_operation_effects"
        clauses: list[str] = []
        params: list[Any] = []
        if worker_id is not None:
            clauses.append("worker_id = ?")
            params.append(str(worker_id))
        if status is not None:
            clauses.append("status = ?")
            params.append(str(status))
        if clauses:
            query += " WHERE " + " AND ".join(clauses)
        query += " ORDER BY created_at ASC, effect_id ASC"
        with self._connect() as conn:
            rows = conn.execute(query, params).fetchall()
        return self._rows(rows)

    def paired_lifecycle_effect_is_applied(
        self,
        effect: dict[str, Any],
        *,
        required_effect_kind: str,
    ) -> bool:
        """Check the exact operation/worker peer required before a later sink."""

        required_kind = str(required_effect_kind or "").strip().lower()
        if required_kind not in LIFECYCLE_EFFECT_KINDS:
            return False
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT status FROM lifecycle_operation_effects
                WHERE operation_digest = ? AND operation_epoch = ?
                  AND operation_kind = ? AND effect_kind = ?
                  AND worker_id = ? AND run_id = ?
                LIMIT 1
                """,
                (
                    str(effect.get("operation_digest") or ""),
                    int(effect.get("operation_epoch") or 0),
                    str(effect.get("operation_kind") or ""),
                    required_kind,
                    str(effect.get("worker_id") or ""),
                    str(effect.get("run_id") or ""),
                ),
            ).fetchone()
        return bool(row and str(row["status"] or "") == "applied")

    def has_pending_lifecycle_effects(self) -> bool:
        with self._connect() as conn:
            return conn.execute(
                """
                SELECT 1 FROM lifecycle_operation_effects
                WHERE status IN ('pending', 'applying') LIMIT 1
                """
            ).fetchone() is not None

    def claim_next_lifecycle_effect(
        self,
        executor_id: str,
        *,
        ttl_s: float = 60.0,
        now: datetime | None = None,
        effect_kinds: tuple[str, ...] | None = None,
        created_before: str | None = None,
    ) -> dict[str, Any] | None:
        owner = str(executor_id or "").strip()
        if not owner:
            raise ValueError("Lifecycle effect claims require an executor")
        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
        now_iso = current.isoformat()
        expires_at = (
            current + timedelta(seconds=max(1.0, float(ttl_s)))
        ).isoformat()
        clean_kinds = tuple(
            str(item or "").strip().lower()
            for item in (effect_kinds or ())
            if str(item or "").strip()
        )
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            kind_clause = ""
            params: list[Any] = [now_iso, now_iso]
            created_clause = ""
            clean_created_before = str(created_before or "").strip()
            if clean_created_before:
                created_clause = " AND created_at <= ?"
                params.append(clean_created_before)
            if clean_kinds:
                kind_clause = " AND effect_kind IN (" + ",".join(
                    "?" for _ in clean_kinds
                ) + ")"
                params.extend(clean_kinds)
            row = conn.execute(
                f"""
                SELECT * FROM lifecycle_operation_effects
                WHERE ((status = 'pending'
                        AND (next_attempt_at IS NULL OR next_attempt_at <= ?))
                   OR (status = 'applying' AND lease_expires_at IS NOT NULL
                       AND lease_expires_at <= ?))
                  {created_clause}
                  {kind_clause}
                ORDER BY created_at ASC, effect_id ASC
                LIMIT 1
                """,
                params,
            ).fetchone()
            if row is None:
                conn.execute("COMMIT")
                return None
            cursor = conn.execute(
                """
                UPDATE lifecycle_operation_effects
                SET status = 'applying', lease_owner = ?,
                    lease_epoch = lease_epoch + 1, lease_expires_at = ?,
                    next_attempt_at = NULL,
                    attempts = attempts + 1, updated_at = ?
                WHERE effect_id = ? AND (
                    (status = 'pending'
                     AND (next_attempt_at IS NULL OR next_attempt_at <= ?))
                    OR (status = 'applying' AND lease_expires_at IS NOT NULL
                        AND lease_expires_at <= ?)
                )
                """,
                (
                    owner,
                    expires_at,
                    now_iso,
                    row["effect_id"],
                    now_iso,
                    now_iso,
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            claimed = conn.execute(
                "SELECT * FROM lifecycle_operation_effects WHERE effect_id = ?",
                (row["effect_id"],),
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(claimed)

    def mark_lifecycle_effect_applied(
        self, effect_id: str, executor_id: str, *, lease_epoch: int
    ) -> dict[str, Any] | None:
        now = utc_now()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE lifecycle_operation_effects
                SET status = 'applied', lease_owner = '', lease_expires_at = NULL,
                    next_attempt_at = NULL, last_error_code = '',
                    updated_at = ?, applied_at = ?
                WHERE effect_id = ? AND status = 'applying' AND lease_owner = ?
                  AND lease_epoch = ?
                """,
                (now, now, effect_id, str(executor_id or ""), int(lease_epoch)),
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM lifecycle_operation_effects WHERE effect_id = ?",
                (effect_id,),
            ).fetchone()
        return self._row(row)

    def retry_lifecycle_effect(
        self,
        effect_id: str,
        executor_id: str,
        *,
        lease_epoch: int,
        error_code: str,
        retry_delay_s: float = 0.0,
    ) -> dict[str, Any] | None:
        clean_code = str(error_code or "").strip().lower()
        if clean_code not in LIFECYCLE_EFFECT_ERROR_CODES:
            raise ValueError("Lifecycle effect failures require a safe error code")
        delay_s = max(0.0, min(float(retry_delay_s), 24 * 3600.0))
        retry_at = (
            datetime.now(timezone.utc) + timedelta(seconds=delay_s)
        ).isoformat()
        with self._connect() as conn:
            cursor = conn.execute(
                """
                UPDATE lifecycle_operation_effects
                SET status = 'pending', lease_owner = '', lease_expires_at = NULL,
                    next_attempt_at = ?, last_error_code = ?, updated_at = ?
                WHERE effect_id = ? AND status = 'applying' AND lease_owner = ?
                  AND lease_epoch = ?
                """,
                (
                    retry_at if delay_s > 0 else None,
                    clean_code,
                    utc_now(),
                    effect_id,
                    str(executor_id or ""),
                    int(lease_epoch),
                ),
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM lifecycle_operation_effects WHERE effect_id = ?",
                (effect_id,),
            ).fetchone()
        return self._row(row)

    @staticmethod
    def _compute_release_claim_expired(row: sqlite3.Row, now_iso: str) -> bool:
        expires_at = str(row["compute_release_expires_at"] or "").strip()
        return bool(expires_at and expires_at <= now_iso)

    def try_claim_worker_compute_release(
        self,
        worker_id: str,
        *,
        expected_updated_at: str,
        expected_last_run_id: str,
        expected_state: str,
        expected_container_id: str,
        owner: str,
        ttl_s: float,
        kind: str = "idle",
        scope: str = "",
        target_run_id: str = "",
        expected_target_started_at: str = "",
        expected_session_fingerprint: str = "",
        replacement_run: dict[str, Any] | None = None,
        action_use_id: str = "",
        action_executor_id: str = "",
        now: datetime | None = None,
    ) -> dict[str, Any] | None:
        """Fence compute starts before one policy-scoped destructive operation."""

        current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
        now_iso = current.isoformat()
        expires_at = (
            current + timedelta(seconds=max(30.0, float(ttl_s)))
        ).isoformat()
        token = f"release_{uuid.uuid4().hex}"
        requested_kind = str(kind or "idle").strip().lower()
        expected_scope = COMPUTE_OPERATION_SCOPE_BY_KIND.get(requested_kind, "")
        requested_scope = str(scope or expected_scope).strip().lower()
        requested_target = str(target_run_id or "").strip()
        requested_target_started_at = str(expected_target_started_at or "").strip()
        requested_session_fingerprint = str(expected_session_fingerprint or "").strip()
        replacement_data = dict(replacement_run or {})
        requested_replacement = str(replacement_data.get("run_id") or "").strip()
        requested_action_use = str(action_use_id or "").strip()
        requested_action_executor = str(action_executor_id or "").strip()
        if bool(requested_action_use) != bool(requested_action_executor):
            raise ValueError(
                "Lifecycle claim action binding requires both receipt and executor"
            )
        if requested_action_use and requested_kind not in {
            "pause_run",
            "resume_run",
            "steer_run",
            "stop_run",
        }:
            raise ValueError(
                "Only active-work run controls may bind a lifecycle claim receipt"
            )
        if requested_kind != "steer_run" and requested_replacement:
            raise ValueError("Only steer_run may reserve a replacement run")
        if requested_kind == "steer_run" and not requested_replacement:
            raise ValueError("steer_run requires a durable replacement run")
        if requested_kind not in COMPUTE_OPERATION_KINDS:
            raise ValueError(f"Unsupported worker compute operation kind: {requested_kind}")
        if requested_scope not in COMPUTE_OPERATION_SCOPES:
            raise ValueError(f"Unsupported worker compute operation scope: {requested_scope}")
        if requested_scope != expected_scope:
            raise ValueError(
                f"Worker compute operation {requested_kind} requires {expected_scope} scope"
            )
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if worker is None:
                conn.execute("COMMIT")
                return None
            existing_token = str(worker["compute_release_token"] or "").strip()
            if existing_token and not self._compute_release_claim_expired(worker, now_iso):
                conn.execute("COMMIT")
                return None
            persisted_kind = str(worker["compute_release_kind"] or "").strip().lower()
            if existing_token and not persisted_kind:
                persisted_kind = "idle"
            persisted_scope = str(
                worker["compute_release_scope"] or "compute_only"
            ).strip().lower()
            persisted_target = str(worker["compute_release_target_run_id"] or "").strip()
            persisted_target_started_at = str(
                worker["compute_release_target_started_at"] or ""
            ).strip()
            persisted_container = str(worker["compute_release_container_id"] or "").strip()
            persisted_session_fingerprint = str(
                worker["compute_release_session_fingerprint"] or ""
            ).strip()
            persisted_replacement = str(
                worker["compute_release_replacement_run_id"] or ""
            ).strip()
            if existing_token and (
                persisted_kind != requested_kind
                or persisted_scope != requested_scope
                or persisted_target != requested_target
                or persisted_target_started_at != requested_target_started_at
                or persisted_container != str(expected_container_id or "").strip()
                or persisted_session_fingerprint != requested_session_fingerprint
                or persisted_replacement != requested_replacement
            ):
                conn.execute("COMMIT")
                return None

            nonterminal_runs = conn.execute(
                """
                SELECT run_id, state FROM runs
                WHERE worker_id = ?
                  AND state NOT IN ('completed', 'failed', 'cancelled', 'interrupted')
                """,
                (worker_id,),
            ).fetchall()
            active_leases = conn.execute(
                """
                SELECT * FROM host_run_leases
                WHERE worker_id = ? AND status = 'active'
                """,
                (worker_id,),
            ).fetchall()
            target = (
                conn.execute(
                    "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                    (requested_target, worker_id),
                ).fetchone()
                if requested_target
                else None
            )
            if target is not None and requested_target_started_at and (
                str(target["started_at"] or "").strip()
                != requested_target_started_at
            ):
                conn.execute("COMMIT")
                return None
            other_executing = any(
                str(row["run_id"]) != requested_target
                and str(row["state"] or "") in PROCESS_BEARING_RUN_STATES
                for row in nonterminal_runs
            )
            other_active_lease = any(
                str(row["run_id"] or "") != requested_target for row in active_leases
            )
            other_preaccept_only = bool(
                active_leases
                and all(
                    str(row["run_id"] or "") == requested_target
                    or (
                        str(row["startup_state"] or "") == "reserved"
                        and not str(row["attempt_id"] or "")
                        and not int(row["pid"] or 0)
                        and not int(row["process_group"] or 0)
                        and not str(row["process_start_identity"] or "")
                        and not str(row["startup_identity_kind"] or "")
                        and not str(row["startup_container_id"] or "")
                        and not str(row["startup_session_id"] or "")
                    )
                    for row in active_leases
                )
            )

            policy_valid = False
            if requested_kind == "idle":
                queued_capacity_wait = bool(
                    requested_target
                    and target
                    and str(target["state"] or "") == "queued"
                    and nonterminal_runs
                    and all(
                        str(row["state"] or "") == "queued"
                        for row in nonterminal_runs
                    )
                )
                policy_valid = bool(
                    not other_executing
                    and not active_leases
                    and (
                        existing_token
                        or not nonterminal_runs
                        or queued_capacity_wait
                    )
                )
            elif requested_kind == "needs_input":
                needs_input_runs = [
                    row
                    for row in nonterminal_runs
                    if str(row["state"] or "") == "needs_input"
                ]
                policy_valid = bool(
                    target
                    and str(target["state"] or "") == "needs_input"
                    and str(worker["state"] or "") == "needs_input"
                    and len(needs_input_runs) == 1
                    and str(needs_input_runs[0]["run_id"]) == requested_target
                    and not other_executing
                    and not active_leases
                )
            elif requested_kind in {"pause_worker", "resume_worker"}:
                expected_worker_state = (
                    "paused" if requested_kind == "resume_worker" else ""
                )
                current_worker_state = str(worker["state"] or "")
                policy_valid = bool(
                    not nonterminal_runs
                    and not active_leases
                    and current_worker_state not in {"stopping", "terminated"}
                    and (
                        not expected_worker_state
                        or current_worker_state == expected_worker_state
                    )
                )
            elif requested_kind == "paused":
                paused_runs = [
                    row for row in nonterminal_runs if str(row["state"] or "") == "paused"
                ]
                disallowed_runs = [
                    row
                    for row in nonterminal_runs
                    if str(row["state"] or "")
                    in {"running", "settling", "needs_input"}
                ]
                target_state = str(target["state"] or "") if target is not None else ""
                if requested_target:
                    exact_paused_shape = (
                        len(paused_runs) == 1
                        and str(paused_runs[0]["run_id"]) == requested_target
                    )
                    terminal_takeover_shape = bool(
                        existing_token
                        and not paused_runs
                        and target
                        and target_state in TERMINAL_RUN_STATES
                    )
                    lease_shape = (
                        len(active_leases) <= 1
                        and not other_active_lease
                    )
                    policy_valid = bool(
                        str(worker["state"] or "") in {"paused", "stopping"}
                        and not disallowed_runs
                        and (exact_paused_shape or terminal_takeover_shape)
                        and lease_shape
                    )
                else:
                    policy_valid = bool(
                        not existing_token
                        and str(worker["state"] or "") == "paused"
                        and not nonterminal_runs
                        and not active_leases
                    )
            elif requested_kind == "max_duration":
                policy_valid = bool(
                    target
                    and (
                        existing_token
                        or str(target["state"] or "") in {"running", "settling"}
                    )
                    and not other_executing
                    and len(active_leases) <= 1
                    and not other_active_lease
                )
            elif requested_kind in {
                "pause_run",
                "resume_run",
                "interrupt_run",
                "cancel_run",
                "steer_run",
            }:
                target_state = str(target["state"] or "") if target is not None else ""
                allowed_states = {
                    "pause_run": {"queued", "running", "settling"},
                    "resume_run": {"paused"},
                    "interrupt_run": {"running", "settling"},
                    "cancel_run": {"running", "settling"},
                    "steer_run": {"queued", "running", "settling"},
                }[requested_kind]
                policy_valid = bool(
                    target
                    and (
                        existing_token
                        or target_state in allowed_states
                    )
                    and not other_executing
                    and len(active_leases) <= 1
                    and not other_active_lease
                )
            elif requested_kind == "stop_run":
                policy_valid = bool(
                    target
                    and (
                        existing_token
                        or str(target["state"] or "")
                        in {
                            "queued",
                            "claimed",
                            "admitted",
                            "running",
                            "settling",
                            "paused",
                            "needs_input",
                        }
                    )
                    and not other_executing
                    and len(active_leases) <= 1
                    and (not other_active_lease or other_preaccept_only)
                )
            elif requested_kind == "terminate_worker":
                process_runs = [
                    row
                    for row in nonterminal_runs
                    if str(row["state"] or "") in PROCESS_BEARING_RUN_STATES
                ]
                policy_valid = bool(
                    len(process_runs) <= 1
                    and len(active_leases) <= 1
                    and not other_active_lease
                    and (
                        (not requested_target and not process_runs and not active_leases)
                        or (
                            target
                            and (
                                existing_token
                                or str(target["state"] or "") not in TERMINAL_RUN_STATES
                            )
                            and all(
                                str(row["run_id"]) == requested_target
                                for row in process_runs
                            )
                        )
                    )
                )
            if not policy_valid:
                conn.execute("COMMIT")
                return None

            if existing_token:
                if requested_kind == "steer_run":
                    reserved_replacement = conn.execute(
                        "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                        (requested_replacement, worker_id),
                    ).fetchone()
                    if (
                        reserved_replacement is None
                        or str(reserved_replacement["state"] or "")
                        not in ({"queued"} | TERMINAL_RUN_STATES)
                        or str(reserved_replacement["instruction"] or "")
                        != str(replacement_data.get("instruction") or "")
                    ):
                        conn.execute("COMMIT")
                        return None
                cursor = conn.execute(
                    """
                    UPDATE workers SET
                        compute_release_token = ?, compute_release_owner = ?,
                        compute_release_claimed_at = ?, compute_release_expires_at = ?,
                        compute_release_epoch = compute_release_epoch + 1,
                        compute_release_kind = CASE
                            WHEN compute_release_kind = '' THEN ? ELSE compute_release_kind END,
                        state = CASE
                            WHEN ? IN ('max_duration', 'stop_run', 'terminate_worker') THEN 'stopping'
                            ELSE state END,
                        updated_at = ?
                    WHERE worker_id = ? AND compute_release_token = ?
                      AND compute_release_epoch = ?
                    """,
                    (
                        token,
                        str(owner),
                        now_iso,
                        expires_at,
                        requested_kind,
                        requested_kind,
                        now_iso,
                        worker_id,
                        existing_token,
                        int(worker["compute_release_epoch"] or 0),
                    ),
                )
                if cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                claimed = conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
                ).fetchone()
                if requested_action_use and self._bind_active_work_action_lifecycle_in_transaction(
                    conn,
                    action_use_id=requested_action_use,
                    operation_id=str(claimed["compute_release_operation_id"] or ""),
                    operation_kind=requested_kind,
                    target_run_id=requested_target,
                    executor_id=requested_action_executor,
                ) != 1:
                    conn.execute("ROLLBACK")
                    return None
                conn.execute("COMMIT")
                return {
                    "token": token,
                    "epoch": int(claimed["compute_release_epoch"] or 0),
                    "worker": self._row(claimed),
                    "takeover": True,
                }
            if (
                str(worker["updated_at"] or "") != str(expected_updated_at or "")
                or str(worker["last_run_id"] or "") != str(expected_last_run_id or "")
                or str(worker["state"] or "") != str(expected_state or "")
                or (
                    bool(worker["compute_released_at"])
                    and requested_kind
                    not in {
                        "resume_worker",
                        "pause_worker",
                        "resume_run",
                        "stop_run",
                        "terminate_worker",
                    }
                    and not (
                        requested_kind == "steer_run"
                        and target is not None
                        and str(target["state"] or "") == "queued"
                    )
                )
            ):
                conn.execute("COMMIT")
                return None
            if requested_kind == "stop_run" and str(worker["work_stop_id"] or ""):
                conn.execute("COMMIT")
                return None
            if requested_kind == "steer_run":
                if (
                    str(replacement_data.get("worker_id") or "") != worker_id
                    or str(replacement_data.get("project_id") or "")
                    != str(worker["project_id"] or "")
                    or str(replacement_data.get("state") or "") != "queued"
                    or not str(replacement_data.get("instruction") or "")
                ):
                    conn.execute("COMMIT")
                    return None
                existing_replacement = conn.execute(
                    "SELECT 1 FROM runs WHERE run_id = ?", (requested_replacement,)
                ).fetchone()
                if existing_replacement is not None:
                    conn.execute("COMMIT")
                    return None
                self._insert_run_row(conn, replacement_data)
            operation_id = "op_" + uuid.uuid4().hex
            cursor = conn.execute(
                """
                UPDATE workers SET
                    compute_release_token = ?, compute_release_owner = ?,
                    compute_release_claimed_at = ?, compute_release_expires_at = ?,
                    compute_release_epoch = compute_release_epoch + 1,
                    compute_release_kind = ?,
                    compute_release_scope = ?,
                    compute_release_container_id = ?,
                    compute_release_session_fingerprint = ?,
                    compute_release_target_run_id = ?,
                    compute_release_target_started_at = ?,
                    compute_release_terminal_run_id = ?,
                    compute_release_replacement_run_id = ?,
                    compute_release_operation_id = ?,
                    work_stop_id = CASE WHEN ? = 'stop_run' THEN ? ELSE work_stop_id END,
                    work_stop_requested_at = CASE
                        WHEN ? = 'stop_run' THEN ? ELSE work_stop_requested_at END,
                    work_stop_settled_at = CASE
                        WHEN ? = 'stop_run' THEN NULL ELSE work_stop_settled_at END,
                    work_stop_outcome = CASE
                        WHEN ? = 'stop_run' THEN '' ELSE work_stop_outcome END,
                    state = CASE
                        WHEN ? IN ('max_duration', 'stop_run', 'terminate_worker') THEN 'stopping'
                        ELSE state END,
                    updated_at = ?
                WHERE worker_id = ? AND COALESCE(compute_release_token, '') IN ('', ?)
                """,
                (
                    token,
                    str(owner),
                    now_iso,
                    expires_at,
                    requested_kind,
                    requested_scope,
                    str(expected_container_id or ""),
                    requested_session_fingerprint,
                    requested_target,
                    requested_target_started_at,
                    (
                        str(expected_last_run_id or "")
                        if requested_kind == "idle"
                        else ""
                    ),
                    requested_replacement,
                    operation_id,
                    requested_kind,
                    operation_id,
                    requested_kind,
                    now_iso,
                    requested_kind,
                    requested_kind,
                    requested_kind,
                    now_iso,
                    worker_id,
                    existing_token,
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            claimed = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if requested_action_use and self._bind_active_work_action_lifecycle_in_transaction(
                conn,
                action_use_id=requested_action_use,
                operation_id=operation_id,
                operation_kind=requested_kind,
                target_run_id=requested_target,
                executor_id=requested_action_executor,
            ) != 1:
                conn.execute("ROLLBACK")
                return None
            conn.execute("COMMIT")
        return {
            "token": token,
            "epoch": int(claimed["compute_release_epoch"] or 0),
            "worker": self._row(claimed),
            "takeover": False,
        }

    def finalize_worker_compute_release(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        expected_kind: str,
        target_run_id: str = "",
        compute_released_at: str | None,
        runtime_fields: dict[str, Any],
        idle_state: str,
    ) -> dict[str, Any] | None:
        """Publish released compute only for the exact durable release owner."""

        clean_kind = str(expected_kind or "").strip().lower()
        clean_target = str(target_run_id or "").strip()
        if clean_kind not in {
            "idle",
            "needs_input",
            "paused",
            "pause_worker",
            "resume_worker",
        }:
            raise ValueError("Unsupported compute-only finalization kind")
        clean_fields = {
            key: value
            for key, value in runtime_fields.items()
            if key in RUNTIME_INFO_FIELD_NAMES
        }
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "") != clean_kind
                or str(worker["compute_release_scope"] or "") != "compute_only"
                or str(worker["compute_release_target_run_id"] or "") != clean_target
            ):
                conn.execute("COMMIT")
                return None
            if clean_kind == "paused" and clean_target:
                conn.execute(
                    """
                    UPDATE host_run_leases
                    SET status = 'released', released_at = ?,
                        release_reason = 'paused_compute_release_confirmed',
                        reconciled_at = COALESCE(reconciled_at, ?)
                    WHERE worker_id = ? AND run_id = ? AND status = 'active'
                    """,
                    (utc_now(), utc_now(), worker_id, clean_target),
                )
            active = conn.execute(
                """
                SELECT state FROM runs
                WHERE worker_id = ? AND state IN ('running', 'settling')
                LIMIT 1
                """,
                (worker_id,),
            ).fetchone()
            queued = conn.execute(
                "SELECT 1 FROM runs WHERE worker_id = ? AND state = 'queued' LIMIT 1",
                (worker_id,),
            ).fetchone()
            capacity_wait_target = (
                conn.execute(
                    "SELECT 1 FROM runs WHERE run_id = ? AND worker_id = ? "
                    "AND state = 'queued' LIMIT 1",
                    (clean_target, worker_id),
                ).fetchone()
                if clean_kind == "idle" and clean_target
                else None
            )
            current_state = str(worker["state"] or "")
            if current_state in {"terminating", "termination_failed", "terminated"}:
                next_state = current_state
            elif clean_kind == "pause_worker":
                next_state = "paused"
            elif clean_kind == "resume_worker":
                next_state = str(idle_state)
            elif current_state in {"paused", "terminated", "needs_input"}:
                next_state = current_state
            elif active is not None:
                next_state = "running"
            elif capacity_wait_target is not None:
                next_state = "ready"
            elif queued is not None:
                next_state = "starting"
            else:
                next_state = str(idle_state)
            fields: dict[str, Any] = {
                **clean_fields,
                "state": next_state,
                "compute_released_at": compute_released_at,
                **COMPUTE_OPERATION_CLEAR_FIELDS,
                "updated_at": utc_now(),
                "worker_id": worker_id,
                "token": token,
                "epoch": int(epoch),
            }
            if (
                clean_kind in {"pause_worker", "resume_worker"}
                and current_state
                not in {"terminating", "termination_failed", "terminated"}
            ):
                event_type = (
                    "worker.paused"
                    if clean_kind == "pause_worker"
                    else "worker.resumed"
                )
                self._insert_lifecycle_event(
                    conn,
                    operation_token=str(worker["compute_release_operation_id"] or token),
                    operation_epoch=0,
                    operation_kind=clean_kind,
                    worker=worker,
                    run_id="",
                    event_type=event_type,
                    message=(
                        "Worker paused"
                        if clean_kind == "pause_worker"
                        else "Worker resumed"
                    ),
                    payload={"operation_kind": clean_kind},
                )
                self._enqueue_lifecycle_effects(
                    conn,
                    operation_token=str(
                        worker["compute_release_operation_id"] or token
                    ),
                    operation_epoch=0,
                    operation_kind=clean_kind,
                    worker_id=worker_id,
                    effect_kinds=(
                        "callback.worker_paused"
                        if clean_kind == "pause_worker"
                        else "callback.worker_resumed",
                    ),
                )
            assignments = ", ".join(
                f"{key} = :{key}"
                for key in fields
                if key not in {"worker_id", "token", "epoch"}
            )
            cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch",
                fields,
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(updated)

    def confirm_worker_control_runtime_effect(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        kind: str,
        target_run_id: str,
    ) -> dict[str, Any] | None:
        """Bind confirmed runtime postcondition to the exact durable claim."""

        now = utc_now()
        with self._connect() as conn:
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or not str(worker["compute_release_operation_id"] or "")
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "") != str(kind)
                or str(worker["compute_release_target_run_id"] or "")
                != str(target_run_id)
            ):
                return None
            proof_material = "\0".join(
                (
                    "glasshive.control-runtime-proof.v1",
                    str(worker["compute_release_operation_id"] or ""),
                    str(worker["compute_release_kind"] or ""),
                    str(worker["compute_release_scope"] or ""),
                    str(worker["compute_release_target_run_id"] or ""),
                    str(worker["compute_release_target_started_at"] or ""),
                    str(worker["compute_release_container_id"] or ""),
                    str(worker["compute_release_session_fingerprint"] or ""),
                )
            )
            proof_digest = hashlib.sha256(proof_material.encode("utf-8")).hexdigest()
            cursor = conn.execute(
                """
                UPDATE workers
                SET compute_release_runtime_confirmed_at = ?,
                    compute_release_runtime_proof_digest = ?, updated_at = ?
                WHERE worker_id = ? AND compute_release_token = ?
                  AND compute_release_epoch = ? AND compute_release_kind = ?
                  AND compute_release_target_run_id = ?
                """,
                (
                    now,
                    proof_digest,
                    now,
                    worker_id,
                    str(token),
                    int(epoch),
                    str(kind),
                    str(target_run_id),
                ),
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
        return self._row(row)

    @staticmethod
    def worker_control_runtime_proof_matches(worker: dict[str, Any] | sqlite3.Row) -> bool:
        if not str(worker["compute_release_runtime_confirmed_at"] or ""):
            return False
        proof_material = "\0".join(
            (
                "glasshive.control-runtime-proof.v1",
                str(worker["compute_release_operation_id"] or ""),
                str(worker["compute_release_kind"] or ""),
                str(worker["compute_release_scope"] or ""),
                str(worker["compute_release_target_run_id"] or ""),
                str(worker["compute_release_target_started_at"] or ""),
                str(worker["compute_release_container_id"] or ""),
                str(worker["compute_release_session_fingerprint"] or ""),
            )
        )
        return bool(
            str(worker["compute_release_runtime_proof_digest"] or "")
            == hashlib.sha256(proof_material.encode("utf-8")).hexdigest()
        )

    @classmethod
    def _cancellation_claim_owns_run(
        cls,
        worker: sqlite3.Row | None,
        run: sqlite3.Row,
        claim: dict[str, Any],
        state: str,
    ) -> bool:
        """True only for the exact proven cancel_run claim on this generation."""

        return bool(
            state == "cancelled"
            and worker is not None
            and str(worker["compute_release_token"] or "")
            == str(claim.get("token") or "")
            and str(claim.get("token") or "")
            and int(worker["compute_release_epoch"] or 0)
            == int(claim.get("epoch") or 0)
            and str(worker["compute_release_kind"] or "") == "cancel_run"
            and str(worker["compute_release_scope"] or "") == "run"
            and str(worker["compute_release_target_run_id"] or "")
            == str(run["run_id"])
            and str(worker["compute_release_target_started_at"] or "")
            == str(run["started_at"] or "")
            and str(worker["compute_release_operation_id"] or "")
            and cls.worker_control_runtime_proof_matches(worker)
        )

    def _record_claimed_cancellation_conn(
        self,
        conn: sqlite3.Connection,
        worker: sqlite3.Row,
        run_id: str,
        *,
        message: str,
    ) -> None:
        """One idempotent cancellation event and callback per cancel operation."""

        operation_id = str(worker["compute_release_operation_id"] or "")
        self._insert_lifecycle_event(
            conn,
            operation_token=operation_id,
            operation_epoch=0,
            operation_kind="cancel_run",
            worker=worker,
            run_id=run_id,
            event_type="run.cancelled",
            message=message or "Run cancelled",
            payload={"operation_kind": "cancel_run"},
        )
        self._enqueue_lifecycle_effects(
            conn,
            operation_token=operation_id,
            operation_epoch=0,
            operation_kind="cancel_run",
            worker_id=str(worker["worker_id"]),
            run_id=run_id,
            effect_kinds=("callback.run_cancelled",),
        )

    def finalize_worker_operation_claim(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        kind: str,
        target_run_id: str,
        target_expected_states: tuple[str, ...],
        target_state: str,
        target_error_text: str,
        runtime_fields: dict[str, Any],
        idle_state: str,
        compute_released_at: str | None,
    ) -> dict[str, Any] | None:
        """Finalize one exact destructive claim and its target run atomically."""

        clean_kind = str(kind or "").strip().lower()
        clean_target = str(target_run_id or "").strip()
        if clean_kind != "max_duration" or not clean_target:
            raise ValueError("A run-scoped worker operation requires a kind and target run")
        if target_state not in TERMINAL_RUN_STATES:
            raise ValueError("A finalized worker operation requires a terminal run state")
        clean_fields = {
            key: value
            for key, value in runtime_fields.items()
            if key in RUNTIME_INFO_FIELD_NAMES
        }
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "") != clean_kind
                or str(worker["compute_release_scope"] or "") != "run"
                or str(worker["compute_release_target_run_id"] or "") != clean_target
            ):
                conn.execute("COMMIT")
                return None

            transitioned = False
            now = utc_now()
            if target_expected_states:
                placeholders = ", ".join("?" for _ in target_expected_states)
                target_started_at = str(
                    worker["compute_release_target_started_at"] or ""
                )
                cursor = conn.execute(
                    f"""
                    UPDATE runs
                    SET state = ?, ended_at = ?, error_text = ?,
                        failure_class = '', failure_retryable = 0,
                        failure_structured = 0, failure_user_message = '',
                        failure_recommended_recovery = '',
                        failure_diagnostic_summary = '', retry_after = NULL,
                        retry_attempts = 0, last_retry_class = ''
                    WHERE run_id = ? AND worker_id = ?
                      AND COALESCE(started_at, '') = ?
                      AND state IN ({placeholders})
                    """,
                    (
                        target_state,
                        now,
                        target_error_text,
                        clean_target,
                        worker_id,
                        target_started_at,
                        *target_expected_states,
                    ),
                )
                transitioned = cursor.rowcount == 1
            if transitioned:
                conn.execute(
                    """
                    UPDATE scheduled_runs
                    SET state = 'cancelled', last_error = ?, updated_at = ?
                    WHERE queued_run_id = ?
                      AND state NOT IN ('completed', 'cancelled')
                    """,
                    (target_error_text, now, clean_target),
                )
                self._accept_cancel_actions_for_runs(
                    conn, [clean_target], updated_at=now
                )
                self._insert_lifecycle_event(
                    conn,
                    operation_token=str(worker["compute_release_operation_id"] or token),
                    operation_epoch=0,
                    operation_kind=clean_kind,
                    worker=worker,
                    run_id=clean_target,
                    event_type="run.duration_exceeded",
                    message=target_error_text,
                    payload={"operation_kind": clean_kind},
                )
            conn.execute(
                """
                UPDATE host_run_leases
                SET status = 'released', released_at = ?, release_reason = ?,
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE worker_id = ? AND run_id = ? AND status = 'active'
                """,
                (
                    now,
                    f"{clean_kind}_confirmed",
                    now,
                    worker_id,
                    clean_target,
                ),
            )
            effect_ids = (
                self._enqueue_lifecycle_effects(
                    conn,
                    operation_token=str(worker["compute_release_operation_id"] or token),
                    operation_epoch=0,
                    operation_kind=clean_kind,
                    worker_id=worker_id,
                    run_id=clean_target,
                    effect_kinds=("callback.run_cancelled",),
                )
                if transitioned
                else []
            )
            active = conn.execute(
                """
                SELECT 1 FROM runs
                WHERE worker_id = ? AND state IN ('running', 'settling')
                LIMIT 1
                """,
                (worker_id,),
            ).fetchone()
            queued = conn.execute(
                "SELECT 1 FROM runs WHERE worker_id = ? AND state = 'queued' LIMIT 1",
                (worker_id,),
            ).fetchone()
            if active is not None:
                next_state = "running"
            elif queued is not None:
                next_state = "starting"
            else:
                next_state = str(idle_state)
            fields: dict[str, Any] = {
                **clean_fields,
                "state": next_state,
                "compute_released_at": compute_released_at,
                **COMPUTE_OPERATION_CLEAR_FIELDS,
                "updated_at": now,
                "worker_id": worker_id,
                "token": token,
                "epoch": int(epoch),
            }
            assignments = ", ".join(
                f"{key} = :{key}"
                for key in fields
                if key not in {"worker_id", "token", "epoch"}
            )
            cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch",
                fields,
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated_worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            updated_run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_target,)
            ).fetchone()
            if transitioned:
                self._record_terminal_artifact_trace_conn(
                    conn,
                    run_id=clean_target,
                    observed_at=now,
                )
            conn.execute("COMMIT")
        return {
            "worker": self._row(updated_worker),
            "run": self._row(updated_run),
            "target_transitioned": transitioned,
            "effect_ids": effect_ids,
        }

    def finalize_worker_work_stop_claim(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        target_run_id: str,
        runtime_fields: dict[str, Any],
        compute_released_at: str | None,
        error_text: str,
    ) -> dict[str, Any] | None:
        """Settle a public work-scoped Stop without reopening the worker later."""

        clean_target = str(target_run_id or "").strip()
        if not clean_target:
            raise ValueError("A work stop requires an exact runtime target")
        clean_fields = {
            key: value
            for key, value in runtime_fields.items()
            if key in RUNTIME_INFO_FIELD_NAMES
        }
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "") != "stop_run"
                or str(worker["compute_release_scope"] or "") != "work"
                or str(worker["compute_release_target_run_id"] or "") != clean_target
                or not str(worker["work_stop_id"] or "")
            ):
                conn.execute("COMMIT")
                return None
            target = conn.execute(
                "SELECT * FROM runs WHERE worker_id = ? AND run_id = ?",
                (worker_id, clean_target),
            ).fetchone()
            if target is None:
                conn.execute("COMMIT")
                return None
            target_state = str(target["state"] or "")
            target_started_at = str(worker["compute_release_target_started_at"] or "")
            target_matches = (
                str(target["started_at"] or "") == target_started_at
                and target_state in NONTERMINAL_RUN_STATES
            )
            if target_state not in TERMINAL_RUN_STATES and not target_matches:
                conn.execute("COMMIT")
                return None
            now = utc_now()
            outcome = "cancelled" if target_matches else "completion_won"
            cancelled_rows = conn.execute(
                """
                SELECT run_id FROM runs
                WHERE worker_id = ?
                  AND state IN (
                      'queued', 'claimed', 'admitted', 'running',
                      'settling', 'paused', 'needs_input'
                  )
                ORDER BY queued_at ASC, run_id ASC
                """,
                (worker_id,),
            ).fetchall()
            cancelled_run_ids = [str(row["run_id"]) for row in cancelled_rows]
            cancelled_attempts = conn.execute(
                """
                SELECT run_attempts.attempt_id
                FROM run_attempts
                JOIN runs ON runs.run_id = run_attempts.run_id
                WHERE runs.worker_id = ?
                  AND runs.state IN (
                      'queued', 'claimed', 'admitted', 'running',
                      'settling', 'paused', 'needs_input'
                  )
                  AND (
                      run_attempts.ended_at IS NULL
                      OR (
                          run_attempts.state = 'retry_queued'
                          AND run_attempts.attempt_number = (
                              SELECT MAX(latest.attempt_number)
                              FROM run_attempts AS latest
                              WHERE latest.run_id = run_attempts.run_id
                          )
                      )
                  )
                ORDER BY run_attempts.run_id, run_attempts.attempt_number
                """,
                (worker_id,),
            ).fetchall()
            cursor = conn.execute(
                """
                UPDATE runs
                SET state = 'cancelled', ended_at = ?, error_text = ?,
                    failure_class = '', failure_retryable = 0,
                    failure_structured = 0, failure_user_message = '',
                    failure_recommended_recovery = '',
                    failure_diagnostic_summary = '', retry_after = NULL,
                    retry_attempts = 0, capacity_retry_count = 0,
                    last_retry_class = ''
                WHERE worker_id = ?
                  AND state IN (
                      'queued', 'claimed', 'admitted', 'running',
                      'settling', 'paused', 'needs_input'
                  )
                """,
                (now, error_text, worker_id),
            )
            conn.execute(
                """
                UPDATE run_attempts
                SET state = 'cancelled', ended_at = ?,
                    terminal_reason = 'work_stopped'
                WHERE run_id IN (
                    SELECT run_id FROM runs WHERE worker_id = ?
                ) AND (
                    ended_at IS NULL
                    OR (
                        state = 'retry_queued'
                        AND attempt_number = (
                            SELECT MAX(latest.attempt_number)
                            FROM run_attempts AS latest
                            WHERE latest.run_id = run_attempts.run_id
                        )
                    )
                )
                """,
                (now, worker_id),
            )
            for attempt in cancelled_attempts:
                self._append_attempt_trace_conn(
                    conn,
                    attempt_id=str(attempt["attempt_id"]),
                    created_at=now,
                )
            for cancelled_run_id in cancelled_run_ids:
                self._record_terminal_artifact_trace_conn(
                    conn,
                    run_id=cancelled_run_id,
                    observed_at=now,
                )
            conn.execute(
                """
                UPDATE scheduled_runs
                SET state = 'cancelled', last_error = ?, updated_at = ?
                WHERE worker_id = ? AND state NOT IN ('completed', 'cancelled')
                """,
                (error_text, now, worker_id),
            )
            conn.execute(
                """
                UPDATE active_work_action_uses
                SET status = 'failed', last_error = 'work_stopped',
                    lease_expires_at = NULL, updated_at = ?
                WHERE work_ref IN (
                    SELECT work_ref FROM delegations WHERE worker_id = ?
                ) AND status = 'pending' AND action != 'stop'
                """,
                (now, worker_id),
            )
            self._accept_cancel_actions_for_runs(
                conn, cancelled_run_ids, updated_at=now
            )
            conn.execute(
                """
                UPDATE host_run_leases
                SET status = 'released', released_at = ?,
                    release_reason = 'work_stop_confirmed',
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE worker_id = ? AND status = 'active'
                """,
                (now, now, worker_id),
            )
            effect_ids = (
                self._enqueue_lifecycle_effects(
                    conn,
                    operation_token=str(worker["compute_release_operation_id"] or token),
                    operation_epoch=0,
                    operation_kind="stop_run",
                    worker_id=worker_id,
                    run_id=clean_target,
                    effect_kinds=("callback.work_stopped",),
                )
                if target_matches
                else []
            )
            event_id = self._insert_lifecycle_event(
                conn,
                operation_token=str(worker["compute_release_operation_id"] or token),
                operation_epoch=0,
                operation_kind="stop_run",
                worker=worker,
                run_id=clean_target,
                event_type=(
                    "run.cancelled" if target_matches else "work.stop_completion_won"
                ),
                message=(
                    "Run stop confirmed"
                    if target_matches
                    else "Work completed before its stop could cancel the target run"
                ),
                payload={"work_stop_outcome": outcome},
            )
            fields: dict[str, Any] = {
                **clean_fields,
                "state": "ready",
                "compute_released_at": compute_released_at,
                **COMPUTE_OPERATION_CLEAR_FIELDS,
                "work_stop_settled_at": now,
                "work_stop_outcome": outcome,
                "updated_at": now,
                "worker_id": worker_id,
                "token": token,
                "epoch": int(epoch),
            }
            assignments = ", ".join(
                f"{key} = :{key}"
                for key in fields
                if key not in {"worker_id", "token", "epoch"}
            )
            updated_cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch AND compute_release_kind = 'stop_run' "
                "AND compute_release_scope = 'work'",
                fields,
            )
            if updated_cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated_worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            updated_target = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_target,)
            ).fetchone()
            conn.execute("COMMIT")
        return {
            "worker": self._row(updated_worker),
            "run": self._row(updated_target),
            "target_transitioned": target_matches,
            "cancelled_run_count": int(cursor.rowcount),
            "work_stop_outcome": outcome,
            "effect_ids": effect_ids,
            "event_id": event_id,
        }

    def worker_compute_use_allowed(self, worker_id: str) -> dict[str, Any] | None:
        """Return the worker only while no destructive operation owns compute."""

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or str(worker["compute_release_token"] or "").strip()
                or str(worker["state"] or "") in {"stopping", "terminated"}
            ):
                conn.execute("COMMIT")
                return None
            conn.execute("COMMIT")
        return self._row(worker)

    def finalize_worker_run_control_claim(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        kind: str,
        target_run_id: str,
        target_expected_states: tuple[str, ...],
        target_state: str,
        worker_state: str,
        runtime_fields: dict[str, Any],
        error_text: str = "",
        release_lease: bool = False,
    ) -> dict[str, Any] | None:
        """Commit one exact Pause/Resume/Interrupt/Steer control generation.

        A ``cancel_run`` claim is only settled here after its exact
        cancellation CAS has committed terminal truth with its own event and
        callback effect; a non-terminal cancel target keeps the fence.
        """

        clean_kind = str(kind or "").strip().lower()
        clean_target = str(target_run_id or "").strip()
        if clean_kind not in {
            "pause_run",
            "resume_run",
            "interrupt_run",
            "cancel_run",
            "steer_run",
        } or not clean_target:
            raise ValueError("Run control finalization requires an exact operation target")
        if not target_expected_states:
            raise ValueError("Run control finalization requires expected target states")
        clean_fields = {
            key: value
            for key, value in runtime_fields.items()
            if key in RUNTIME_INFO_FIELD_NAMES
        }
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "") != clean_kind
                or str(worker["compute_release_scope"] or "") != "run"
                or str(worker["compute_release_target_run_id"] or "") != clean_target
            ):
                conn.execute("COMMIT")
                return None
            target = conn.execute(
                "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                (clean_target, worker_id),
            ).fetchone()
            if target is None or str(target["started_at"] or "") != str(
                worker["compute_release_target_started_at"] or ""
            ):
                conn.execute("COMMIT")
                return None
            current_target_state = str(target["state"] or "")
            if current_target_state in TERMINAL_RUN_STATES:
                if str(worker["state"] or "") in {
                    "terminating",
                    "termination_failed",
                    "terminated",
                }:
                    # Permanent Close owns this worker generation. A losing
                    # Pause/Resume/Interrupt claim must not reopen it or emit
                    # its stale control effects while Close settles teardown.
                    conn.execute("COMMIT")
                    return {
                        "worker": self._row(worker),
                        "run": self._row(target),
                        "target_transitioned": False,
                        "terminal_won": True,
                        "closed_won": True,
                        "event_ids": [],
                    }
                now = utc_now()
                operation_id = str(worker["compute_release_operation_id"] or token)
                own_cancellation = bool(
                    clean_kind == "cancel_run"
                    and conn.execute(
                        "SELECT 1 FROM events WHERE event_id = ? LIMIT 1",
                        (
                            self._lifecycle_event_id(
                                operation_token=operation_id,
                                operation_epoch=0,
                                operation_kind=clean_kind,
                                event_type="run.cancelled",
                                worker_id=worker_id,
                                run_id=clean_target,
                            ),
                        ),
                    ).fetchone()
                    is not None
                )
                if not own_cancellation:
                    self._insert_lifecycle_event(
                        conn,
                        operation_token=operation_id,
                        operation_epoch=0,
                        operation_kind=clean_kind,
                        worker=worker,
                        run_id=clean_target,
                        event_type="control.terminal_won",
                        message="Terminal run truth won the lifecycle control race",
                        payload={
                            "operation_kind": clean_kind,
                            "terminal_state": current_target_state,
                        },
                    )
                conn.execute(
                    """
                    UPDATE host_run_leases
                    SET status = 'released', released_at = ?,
                        release_reason = ?, reconciled_at = COALESCE(reconciled_at, ?)
                    WHERE worker_id = ? AND run_id = ? AND status = 'active'
                    """,
                    (
                        now,
                        f"{clean_kind}_terminal_won",
                        now,
                        worker_id,
                        clean_target,
                    ),
                )
                fields: dict[str, Any] = {
                    **clean_fields,
                    "state": "ready",
                    **COMPUTE_OPERATION_CLEAR_FIELDS,
                    "updated_at": now,
                    "worker_id": worker_id,
                    "token": token,
                    "epoch": int(epoch),
                }
                assignments = ", ".join(
                    f"{key} = :{key}"
                    for key in fields
                    if key not in {"worker_id", "token", "epoch"}
                )
                cursor = conn.execute(
                    f"UPDATE workers SET {assignments} "
                    "WHERE worker_id = :worker_id AND compute_release_token = :token "
                    "AND compute_release_epoch = :epoch",
                    fields,
                )
                if cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                updated_worker = conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
                ).fetchone()
                conn.execute("COMMIT")
                return {
                    "worker": self._row(updated_worker),
                    "run": self._row(target),
                    "target_transitioned": False,
                    "terminal_won": True,
                    "event_ids": [],
                }
            if clean_kind == "cancel_run":
                conn.execute("COMMIT")
                return None
            if (
                clean_kind in {"resume_run", "interrupt_run"}
                or (clean_kind == "pause_run" and current_target_state != "queued")
            ) and not self.worker_control_runtime_proof_matches(worker):
                conn.execute("COMMIT")
                return None
            now = utc_now()
            if target_state == "running" and not self._running_generation_is_exact_conn(
                conn, clean_target, now=now
            ):
                conn.execute("COMMIT")
                return None
            restart_attempt_id = ""
            if clean_kind == "resume_run" and target_state == "queued":
                restart_attempt_id = str(target["active_attempt_id"] or "").strip()
                if restart_attempt_id:
                    restart_attempt = conn.execute(
                        "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                        (restart_attempt_id, clean_target),
                    ).fetchone()
                    if (
                        restart_attempt is None
                        or restart_attempt["ended_at"] is not None
                        or str(restart_attempt["state"] or "")
                        not in {"claimed", "admitted", "running", "settling"}
                    ):
                        conn.execute("COMMIT")
                        return None
            ended_at = now if target_state in TERMINAL_RUN_STATES else None
            run_update_fields: dict[str, Any] = {
                "state": target_state,
                "ended_at": ended_at,
                "error_text": error_text,
                "retry_after": None,
            }
            if restart_attempt_id:
                # Host Pause terminates the provider generation. Resume keeps
                # the durable run but must close that exact attempt before a
                # fresh pre-accept reservation can mint the next attempt.
                run_update_fields.update(
                    {
                        "claimed_at": None,
                        "admitted_at": None,
                        "runtime_invoked_at": None,
                        "active_attempt_id": "",
                    }
                )
            if (
                clean_kind == "resume_run"
                and target_state == "queued"
                and not bool(target["queue_wait_open"])
            ):
                generation = max(
                    1, int(target["queue_wait_generation"] or 0)
                ) + 1
                deadline = (
                    _parse_utc(now)
                    + timedelta(seconds=_queue_wait_timeout_seconds())
                ).isoformat()
                run_update_fields.update(
                    {
                        "queue_wait_episode": generation,
                        "queue_wait_open": 1,
                        "queue_wait_generation": generation,
                        "queue_wait_started_at": now,
                        "queue_wait_closed_at": None,
                        "queue_wait_duration_seconds": None,
                        "queue_deadline_at": deadline,
                        "queue_next_status_at": (
                            _parse_utc(now)
                            + timedelta(
                                seconds=_queue_status_refresh_interval_seconds()
                            )
                        ).isoformat(),
                        "queue_transition_emitted": 0,
                        "queue_status_sequence": 0,
                        "queue_callback_state": "unknown",
                        "queue_terminal_callback_id": _queue_callback_id(
                            "timeout",
                            run_id=clean_target,
                            generation=generation,
                            deadline=deadline,
                        ),
                    }
                )
            run_update_fields.update(
                {
                    "run_id": clean_target,
                    "worker_id": worker_id,
                }
            )
            run_assignments = ", ".join(
                f"{field} = :{field}"
                for field in run_update_fields
                if field not in {"run_id", "worker_id"}
            )
            expected_state_params = {
                f"expected_state_{index}": state
                for index, state in enumerate(target_expected_states)
            }
            expected_state_placeholders = ", ".join(
                f":expected_state_{index}"
                for index in range(len(target_expected_states))
            )
            cursor = conn.execute(
                f"""
                UPDATE runs
                SET {run_assignments}
                WHERE run_id = :run_id AND worker_id = :worker_id
                  AND state IN ({expected_state_placeholders})
                """,
                {**run_update_fields, **expected_state_params},
            )
            if cursor.rowcount != 1:
                conn.execute("COMMIT")
                return None
            if restart_attempt_id:
                attempt_cursor = conn.execute(
                    """
                    UPDATE run_attempts
                    SET state = 'retry_queued', ended_at = ?,
                        terminal_reason = 'host_pause_resume_restart'
                    WHERE attempt_id = ? AND run_id = ? AND ended_at IS NULL
                      AND state IN ('claimed', 'admitted', 'running', 'settling')
                    """,
                    (now, restart_attempt_id, clean_target),
                )
                if attempt_cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                self._append_attempt_trace_conn(
                    conn,
                    attempt_id=restart_attempt_id,
                    created_at=now,
                )
            if release_lease or restart_attempt_id:
                conn.execute(
                    """
                    UPDATE host_run_leases
                    SET status = 'released', released_at = ?, release_reason = ?,
                        reconciled_at = COALESCE(reconciled_at, ?)
                    WHERE worker_id = ? AND run_id = ? AND status = 'active'
                    """,
                    (
                        now,
                        (
                            "host_pause_resume_restart"
                            if restart_attempt_id
                            else f"{clean_kind}_confirmed"
                        ),
                        now,
                        worker_id,
                        clean_target,
                    ),
                )
            event_specs = {
                "pause_run": (
                    ("run.paused", "Run paused by operator"),
                    ("worker.paused", "Worker paused"),
                ),
                "resume_run": (
                    ("run.resumed", "Paused run resumed"),
                    ("worker.resumed", "Worker resumed"),
                ),
                "interrupt_run": (
                    ("worker.interrupted", "Worker interrupted"),
                    ("run.interrupted", "Run interruption accepted"),
                ),
                "steer_run": (),
            }[clean_kind]
            event_ids = [
                self._insert_lifecycle_event(
                    conn,
                    operation_token=str(worker["compute_release_operation_id"] or token),
                    operation_epoch=0,
                    operation_kind=clean_kind,
                    worker=worker,
                    run_id=clean_target,
                    event_type=event_type,
                    message=message,
                    payload={"operation_kind": clean_kind},
                )
                for event_type, message in event_specs
            ]
            callback_effect = {
                "pause_run": "callback.run_paused",
                "resume_run": (
                    "callback.run_resumed_in_place"
                    if target_state == "running"
                    else "callback.run_resumed_queued"
                ),
                "interrupt_run": "callback.run_interrupted",
                "steer_run": "callback.run_steered",
            }[clean_kind]
            effect_ids = self._enqueue_lifecycle_effects(
                conn,
                operation_token=str(worker["compute_release_operation_id"] or token),
                operation_epoch=0,
                operation_kind=clean_kind,
                worker_id=worker_id,
                run_id=clean_target,
                effect_kinds=(callback_effect,),
            )
            fields: dict[str, Any] = {
                **clean_fields,
                "state": worker_state,
                "compute_released_at": (
                    None
                    if clean_kind == "resume_run"
                    else worker["compute_released_at"]
                ),
                **COMPUTE_OPERATION_CLEAR_FIELDS,
                "updated_at": now,
                "worker_id": worker_id,
                "token": token,
                "epoch": int(epoch),
            }
            assignments = ", ".join(
                f"{key} = :{key}"
                for key in fields
                if key not in {"worker_id", "token", "epoch"}
            )
            updated_cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch",
                fields,
            )
            if updated_cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated_worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            updated_target = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_target,)
            ).fetchone()
            conn.execute("COMMIT")
        return {
            "worker": self._row(updated_worker),
            "run": self._row(updated_target),
            "target_transitioned": True,
            "event_ids": event_ids,
            "effect_ids": effect_ids,
        }

    def abandon_worker_run_control_claim(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        kind: str,
        target_run_id: str,
        worker_state: str,
        last_error: str,
    ) -> dict[str, Any] | None:
        """Release a non-destructive start claim without publishing success."""

        clean_kind = str(kind or "").strip().lower()
        if clean_kind not in {"resume_run", "resume_worker"}:
            raise ValueError("Only a failed resume startup may abandon its claim")
        fields = {
            "state": worker_state,
            "last_error": last_error,
            **COMPUTE_OPERATION_CLEAR_FIELDS,
            "updated_at": utc_now(),
            "worker_id": worker_id,
            "token": token,
            "epoch": int(epoch),
            "kind": clean_kind,
            "target_run_id": str(target_run_id or ""),
        }
        assignments = ", ".join(
            f"{key} = :{key}"
            for key in fields
            if key
            not in {"worker_id", "token", "epoch", "kind", "target_run_id"}
        )
        with self._connect() as conn:
            cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch AND compute_release_kind = :kind "
                "AND compute_release_target_run_id = :target_run_id",
                fields,
            )
            if cursor.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
        return self._row(row)

    def abandon_stale_worker_compute_release_claim(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        kind: str,
    ) -> dict[str, Any] | None:
        """Clear a stale compute-only fence without publishing release success.

        An idle/paused claim can outlive the Docker generation it captured or
        race newly queued work.  In either case the old destructive attempt may
        not be projected onto the newer generation.  Clearing only the exact
        owned fence lets normal admission/reaping re-evaluate current truth.
        """

        clean_kind = str(kind or "").strip().lower()
        if clean_kind not in {"idle", "needs_input", "paused"}:
            raise ValueError(
                "Only stale idle, needs-input, or paused release claims may be abandoned"
            )
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "") != clean_kind
                or str(worker["compute_release_scope"] or "") != "compute_only"
            ):
                conn.execute("COMMIT")
                return None
            active = conn.execute(
                """
                SELECT 1 FROM runs
                WHERE worker_id = ? AND state IN ('running', 'settling')
                LIMIT 1
                """,
                (worker_id,),
            ).fetchone()
            queued = conn.execute(
                "SELECT 1 FROM runs WHERE worker_id = ? AND state = 'queued' LIMIT 1",
                (worker_id,),
            ).fetchone()
            current_state = str(worker["state"] or "")
            next_state = (
                "running"
                if active is not None
                else "starting"
                if queued is not None
                else current_state
            )
            fields: dict[str, Any] = {
                "state": next_state,
                **COMPUTE_OPERATION_CLEAR_FIELDS,
                "updated_at": utc_now(),
                "worker_id": worker_id,
                "token": token,
                "epoch": int(epoch),
                "kind": clean_kind,
            }
            assignments = ", ".join(
                f"{key} = :{key}"
                for key in fields
                if key not in {"worker_id", "token", "epoch", "kind"}
            )
            cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch AND compute_release_kind = :kind",
                fields,
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(updated)

    def rebind_worker_termination_claim_generation(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        container_id: str,
    ) -> dict[str, Any] | None:
        """Move a durable whole-worker tombstone onto the current generation."""

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            cursor = conn.execute(
                """
                UPDATE workers
                SET compute_release_container_id = ?,
                    compute_release_epoch = compute_release_epoch + 1,
                    updated_at = ?
                WHERE worker_id = ?
                  AND compute_release_token = ?
                  AND compute_release_epoch = ?
                  AND compute_release_kind = 'terminate_worker'
                  AND compute_release_scope = 'worker'
                  AND state = 'stopping'
                """,
                (str(container_id or ""), utc_now(), worker_id, token, int(epoch)),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(updated)

    def rebind_worker_compute_release_claim_generation(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        kind: str,
        container_id: str,
    ) -> dict[str, Any] | None:
        """Rebind an idle/paused compute-only claim to the current generation.

        Recovery may observe that Docker recreated an otherwise idle worker
        after the original destructive attempt failed.  When no newer work is
        admissible, the durable operation remains authoritative and can move to
        the freshly observed generation.  The epoch increment fences every
        caller that still holds the prior container receipt.
        """

        clean_kind = str(kind or "").strip().lower()
        if clean_kind not in {"idle", "needs_input", "paused"}:
            raise ValueError(
                "Only idle, needs-input, or paused compute release may change generation"
            )
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            cursor = conn.execute(
                """
                UPDATE workers
                SET compute_release_container_id = ?,
                    compute_release_epoch = compute_release_epoch + 1,
                    updated_at = ?
                WHERE worker_id = ?
                  AND compute_release_token = ?
                  AND compute_release_epoch = ?
                  AND compute_release_kind = ?
                  AND compute_release_scope = 'compute_only'
                """,
                (
                    str(container_id or ""),
                    utc_now(),
                    worker_id,
                    token,
                    int(epoch),
                    clean_kind,
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(updated)

    def finalize_worker_steer_claim(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        target_run_id: str,
        target_expected_state: str,
        replacement_run_id: str,
        replacement_instruction: str,
        runtime_fields: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Interrupt one exact generation and queue its steer replacement atomically."""

        clean_target = str(target_run_id or "")
        clean_replacement = str(replacement_run_id or "")
        clean_instruction = str(replacement_instruction or "")
        if not clean_target or not clean_replacement or not clean_instruction:
            raise ValueError("Steer finalization requires an exact target and replacement")
        clean_fields = {
            key: value
            for key, value in runtime_fields.items()
            if key in RUNTIME_INFO_FIELD_NAMES
        }
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            target = conn.execute(
                "SELECT * FROM runs WHERE run_id = ? AND worker_id = ?",
                (clean_target, worker_id),
            ).fetchone()
            if (
                worker is None
                or target is None
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "") != "steer_run"
                or str(worker["compute_release_scope"] or "") != "run"
                or str(worker["compute_release_target_run_id"] or "") != clean_target
                or str(worker["compute_release_replacement_run_id"] or "")
                != clean_replacement
                or str(target["started_at"] or "")
                != str(worker["compute_release_target_started_at"] or "")
            ):
                conn.execute("COMMIT")
                return None
            existing = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_replacement,)
            ).fetchone()
            if (
                existing is None
                or str(existing["worker_id"] or "") != worker_id
                or str(existing["state"] or "")
                not in ({"queued"} | TERMINAL_RUN_STATES)
                or str(existing["instruction"] or "") != clean_instruction
            ):
                conn.execute("COMMIT")
                return None
            now = utc_now()
            target_state = str(target["state"] or "")
            replacement_state = str(existing["state"] or "")
            if target_state == "interrupted":
                # The runtime/process owner can publish the exact interrupted
                # source before this transaction commits.  That is a partial
                # steer success, not a terminal-winner race.  Preserve the
                # already-created replacement even if it later timed out while
                # the service was down.
                conn.execute(
                    """
                    UPDATE delegations SET current_run_id = ?, updated_at = ?
                    WHERE worker_id = ?
                    """,
                    (clean_replacement, now, worker_id),
                )
                conn.execute(
                    """
                    UPDATE host_run_leases SET status = 'released', released_at = ?,
                        release_reason = 'steer_run_confirmed',
                        reconciled_at = COALESCE(reconciled_at, ?)
                    WHERE worker_id = ? AND run_id = ? AND status = 'active'
                    """,
                    (now, now, worker_id, clean_target),
                )
                operation_token = str(
                    worker["compute_release_operation_id"] or token
                )
                self._insert_lifecycle_event(
                    conn,
                    operation_token=operation_token,
                    operation_epoch=0,
                    operation_kind="steer_run",
                    worker=worker,
                    run_id=clean_target,
                    event_type="run.interrupted",
                    message="Worker interrupted for operator steer",
                )
                self._insert_lifecycle_event(
                    conn,
                    operation_token=operation_token,
                    operation_epoch=0,
                    operation_kind="steer_run",
                    worker=worker,
                    run_id=clean_replacement,
                    event_type="worker.steer",
                    message="Replacement steer instruction preserved",
                )
                effect_ids = (
                    self._enqueue_lifecycle_effects(
                        conn,
                        operation_token=operation_token,
                        operation_epoch=0,
                        operation_kind="steer_run",
                        worker_id=worker_id,
                        run_id=clean_replacement,
                        effect_kinds=("callback.run_steered",),
                    )
                    if replacement_state == "queued"
                    else []
                )
                fields = {
                    **clean_fields,
                    "state": (
                        "starting" if replacement_state == "queued" else "ready"
                    ),
                    "last_run_id": clean_replacement,
                    **COMPUTE_OPERATION_CLEAR_FIELDS,
                    "updated_at": now,
                    "worker_id": worker_id,
                    "token": token,
                    "epoch": int(epoch),
                }
                assignments = ", ".join(
                    f"{key} = :{key}"
                    for key in fields
                    if key not in {"worker_id", "token", "epoch"}
                )
                cursor = conn.execute(
                    f"UPDATE workers SET {assignments} "
                    "WHERE worker_id = :worker_id AND compute_release_token = :token "
                    "AND compute_release_epoch = :epoch",
                    fields,
                )
                if cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                updated_worker = conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
                ).fetchone()
                conn.execute("COMMIT")
                return {
                    "worker": self._row(updated_worker),
                    "target_run": self._row(target),
                    "replacement_run": self._row(existing),
                    "target_transitioned": False,
                    "terminal_won": False,
                    "effect_ids": effect_ids,
                }
            if target_state in TERMINAL_RUN_STATES:
                self._insert_lifecycle_event(
                    conn,
                    operation_token=str(
                        worker["compute_release_operation_id"] or token
                    ),
                    operation_epoch=0,
                    operation_kind="steer_run",
                    worker=worker,
                    run_id=clean_target,
                    event_type="control.terminal_won",
                    message="Terminal run truth suppressed the steer replacement",
                    payload={
                        "operation_kind": "steer_run",
                        "terminal_state": target_state,
                        "replacement_run_id": clean_replacement,
                    },
                )
                conn.execute(
                    """
                    UPDATE runs SET state = 'cancelled', ended_at = ?,
                        error_text = ?
                    WHERE run_id = ? AND worker_id = ? AND state = 'queued'
                    """,
                    (
                        now,
                        STEER_REPLACEMENT_SUPPRESSED_ERROR,
                        clean_replacement,
                        worker_id,
                    ),
                )
                conn.execute(
                    """
                    UPDATE delegations SET current_run_id = ?, updated_at = ?
                    WHERE worker_id = ?
                    """,
                    (clean_target, now, worker_id),
                )
                conn.execute(
                    """
                    UPDATE host_run_leases SET status = 'released', released_at = ?,
                        release_reason = 'steer_run_terminal_won',
                        reconciled_at = COALESCE(reconciled_at, ?)
                    WHERE worker_id = ? AND run_id = ? AND status = 'active'
                    """,
                    (now, now, worker_id, clean_target),
                )
                fields = {
                    **clean_fields,
                    "state": "ready",
                    **COMPUTE_OPERATION_CLEAR_FIELDS,
                    "updated_at": now,
                    "worker_id": worker_id,
                    "token": token,
                    "epoch": int(epoch),
                }
                assignments = ", ".join(
                    f"{key} = :{key}"
                    for key in fields
                    if key not in {"worker_id", "token", "epoch"}
                )
                cursor = conn.execute(
                    f"UPDATE workers SET {assignments} "
                    "WHERE worker_id = :worker_id AND compute_release_token = :token "
                    "AND compute_release_epoch = :epoch",
                    fields,
                )
                if cursor.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None
                updated_worker = conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
                ).fetchone()
                updated_replacement = conn.execute(
                    "SELECT * FROM runs WHERE run_id = ?", (clean_replacement,)
                ).fetchone()
                self._record_terminal_artifact_trace_conn(
                    conn,
                    run_id=clean_replacement,
                    observed_at=now,
                )
                conn.execute("COMMIT")
                return {
                    "worker": self._row(updated_worker),
                    "target_run": self._row(target),
                    "replacement_run": self._row(updated_replacement),
                    "target_transitioned": False,
                    "terminal_won": True,
                    "effect_ids": [],
                }
            if str(target["state"] or "") != str(target_expected_state):
                conn.execute("COMMIT")
                return None
            if (
                str(target_expected_state) != "queued"
                and not self.worker_control_runtime_proof_matches(worker)
            ):
                conn.execute("COMMIT")
                return None
            interrupted_state = (
                "cancelled" if str(target_expected_state) == "queued" else "interrupted"
            )
            conn.execute(
                """
                UPDATE runs
                SET state = ?, ended_at = ?, error_text = ?, retry_after = NULL,
                    failure_class = '', failure_retryable = 0,
                    failure_structured = 0, failure_user_message = '',
                    failure_recommended_recovery = '',
                    failure_diagnostic_summary = '', retry_attempts = 0,
                    last_retry_class = ''
                WHERE run_id = ? AND worker_id = ? AND state = ?
                """,
                (
                    interrupted_state,
                    now,
                    "Replaced by operator steer",
                    clean_target,
                    worker_id,
                    target_expected_state,
                ),
            )
            conn.execute(
                """
                UPDATE delegations SET current_run_id = ?, updated_at = ?
                WHERE worker_id = ?
                """,
                (clean_replacement, now, worker_id),
            )
            conn.execute(
                """
                UPDATE host_run_leases
                SET status = 'released', released_at = ?,
                    release_reason = 'steer_run_confirmed',
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE worker_id = ? AND run_id = ? AND status = 'active'
                """,
                (now, now, worker_id, clean_target),
            )
            self._insert_lifecycle_event(
                conn,
                operation_token=str(worker["compute_release_operation_id"] or token),
                operation_epoch=0,
                operation_kind="steer_run",
                worker=worker,
                run_id=clean_target,
                event_type=f"run.{interrupted_state}",
                message="Run replaced by operator steer",
            )
            self._insert_lifecycle_event(
                conn,
                operation_token=str(worker["compute_release_operation_id"] or token),
                operation_epoch=0,
                operation_kind="steer_run",
                worker=worker,
                run_id=clean_target,
                event_type="worker.interrupted",
                message="Worker interrupted for operator steer",
            )
            self._insert_lifecycle_event(
                conn,
                operation_token=str(worker["compute_release_operation_id"] or token),
                operation_epoch=0,
                operation_kind="steer_run",
                worker=worker,
                run_id=clean_replacement,
                event_type="worker.steer",
                message=(
                    "Replacement steer instruction queued"
                    if replacement_state == "queued"
                    else "Replacement steer instruction preserved"
                ),
            )
            effect_ids = (
                self._enqueue_lifecycle_effects(
                    conn,
                    operation_token=str(
                        worker["compute_release_operation_id"] or token
                    ),
                    operation_epoch=0,
                    operation_kind="steer_run",
                    worker_id=worker_id,
                    run_id=clean_replacement,
                    effect_kinds=("callback.run_steered",),
                )
                if replacement_state == "queued"
                else []
            )
            fields: dict[str, Any] = {
                **clean_fields,
                "state": "starting" if replacement_state == "queued" else "ready",
                "last_run_id": clean_replacement,
                **COMPUTE_OPERATION_CLEAR_FIELDS,
                "updated_at": now,
                "worker_id": worker_id,
                "token": token,
                "epoch": int(epoch),
            }
            assignments = ", ".join(
                f"{key} = :{key}"
                for key in fields
                if key not in {"worker_id", "token", "epoch"}
            )
            cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch",
                fields,
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated_worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            updated_target = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_target,)
            ).fetchone()
            updated_replacement = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_replacement,)
            ).fetchone()
            self._record_terminal_artifact_trace_conn(
                conn,
                run_id=clean_target,
                observed_at=now,
            )
            conn.execute("COMMIT")
        return {
            "worker": self._row(updated_worker),
            "target_run": self._row(updated_target),
            "replacement_run": self._row(updated_replacement),
            "effect_ids": effect_ids,
        }

    def finalize_worker_termination_claim(
        self,
        worker_id: str,
        token: str,
        epoch: int,
        *,
        compute_released_at: str,
        runtime_fields: dict[str, Any],
        error_text: str,
    ) -> dict[str, Any] | None:
        """Cancel all durable work and end a worker for the exact operation owner."""

        clean_fields = {
            key: value
            for key, value in runtime_fields.items()
            if key in RUNTIME_INFO_FIELD_NAMES
        }
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if (
                worker is None
                or str(worker["compute_release_token"] or "") != str(token)
                or int(worker["compute_release_epoch"] or 0) != int(epoch)
                or str(worker["compute_release_kind"] or "")
                != "terminate_worker"
                or str(worker["compute_release_scope"] or "") != "worker"
            ):
                conn.execute("COMMIT")
                return None
            now = utc_now()
            cancelled_rows = conn.execute(
                """
                SELECT run_id FROM runs
                WHERE worker_id = ?
                  AND state IN (
                      'queued', 'claimed', 'admitted', 'running',
                      'settling', 'paused', 'needs_input'
                  )
                ORDER BY queued_at ASC, run_id ASC
                """,
                (worker_id,),
            ).fetchall()
            cancelled_run_ids = [str(row["run_id"]) for row in cancelled_rows]
            cancelled_attempts = conn.execute(
                """
                SELECT run_attempts.attempt_id
                FROM run_attempts
                JOIN runs ON runs.run_id = run_attempts.run_id
                WHERE runs.worker_id = ? AND run_attempts.ended_at IS NULL
                ORDER BY run_attempts.run_id, run_attempts.attempt_number
                """,
                (worker_id,),
            ).fetchall()
            conn.execute(
                """
                UPDATE runs
                SET state = 'cancelled', ended_at = ?, error_text = ?,
                    failure_class = '', failure_retryable = 0,
                    failure_structured = 0, failure_user_message = '',
                    failure_recommended_recovery = '',
                    failure_diagnostic_summary = '', retry_after = NULL,
                    retry_attempts = 0, last_retry_class = ''
                WHERE worker_id = ?
                  AND state IN (
                      'queued', 'claimed', 'admitted', 'running',
                      'settling', 'paused', 'needs_input'
                  )
                """,
                (now, error_text, worker_id),
            )
            conn.execute(
                """
                UPDATE run_attempts
                SET state = 'cancelled', ended_at = ?,
                    terminal_reason = 'worker_terminated'
                WHERE run_id IN (
                    SELECT run_id FROM runs WHERE worker_id = ?
                ) AND ended_at IS NULL
                """,
                (now, worker_id),
            )
            for attempt in cancelled_attempts:
                self._append_attempt_trace_conn(
                    conn,
                    attempt_id=str(attempt["attempt_id"]),
                    created_at=now,
                )
            for cancelled_run_id in cancelled_run_ids:
                self._record_terminal_artifact_trace_conn(
                    conn,
                    run_id=cancelled_run_id,
                    observed_at=now,
                )
            conn.execute(
                """
                UPDATE scheduled_runs
                SET state = 'cancelled', last_error = ?, updated_at = ?
                WHERE worker_id = ? AND state NOT IN ('completed', 'cancelled')
                """,
                (error_text, now, worker_id),
            )
            conn.execute(
                """
                UPDATE active_work_action_uses
                SET status = 'failed', last_error = 'worker_ended',
                    lease_expires_at = NULL, updated_at = ?
                WHERE work_ref IN (
                    SELECT work_ref FROM delegations WHERE worker_id = ?
                ) AND status = 'pending'
                """,
                (now, worker_id),
            )
            self._accept_cancel_actions_for_runs(
                conn, cancelled_run_ids, updated_at=now
            )
            effect_ids = self._enqueue_lifecycle_effects(
                conn,
                operation_token=str(worker["compute_release_operation_id"] or token),
                operation_epoch=0,
                operation_kind="terminate_worker",
                worker_id=worker_id,
                effect_kinds=(
                    "callback.worker_terminated",
                    "signed_links.revoke_worker",
                ),
            )
            event_id = self._insert_lifecycle_event(
                conn,
                operation_token=str(worker["compute_release_operation_id"] or token),
                operation_epoch=0,
                operation_kind="terminate_worker",
                worker=worker,
                run_id="",
                event_type="worker.terminated",
                message="Worker terminated",
                payload={"operation_kind": "terminate_worker"},
            )
            conn.execute(
                """
                UPDATE host_run_leases
                SET status = 'released', released_at = ?,
                    release_reason = 'worker_termination_confirmed',
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE worker_id = ? AND status = 'active'
                """,
                (now, now, worker_id),
            )
            fields: dict[str, Any] = {
                **clean_fields,
                "state": "terminated",
                "compute_released_at": compute_released_at,
                **COMPUTE_OPERATION_CLEAR_FIELDS,
                "updated_at": now,
                "worker_id": worker_id,
                "token": token,
                "epoch": int(epoch),
            }
            assignments = ", ".join(
                f"{key} = :{key}"
                for key in fields
                if key not in {"worker_id", "token", "epoch"}
            )
            cursor = conn.execute(
                f"UPDATE workers SET {assignments} "
                "WHERE worker_id = :worker_id AND compute_release_token = :token "
                "AND compute_release_epoch = :epoch",
                fields,
            )
            if cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            conn.execute("COMMIT")
        result = self._row(updated) or {}
        result["effect_ids"] = effect_ids
        result["event_id"] = event_id
        return result

    def begin_worker_compute_start(self, worker_id: str) -> dict[str, Any] | None:
        """Atomically reject direct compute starts while release owns the worker."""

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            worker = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            if worker is None:
                conn.execute("COMMIT")
                return None
            token = str(worker["compute_release_token"] or "").strip()
            if (
                token
                or str(worker["work_stop_id"] or "")
                or str(worker["state"] or "") in {"stopping", "terminated"}
            ):
                conn.execute("COMMIT")
                return None
            conn.execute(
                """
                UPDATE workers SET state = 'starting', compute_released_at = NULL,
                    updated_at = ?
                WHERE worker_id = ?
                """,
                (utc_now(), worker_id),
            )
            updated = conn.execute(
                "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(updated)

    def list_expired_compute_release_claim_worker_ids(
        self,
        *,
        now: datetime | None = None,
    ) -> list[str]:
        """List takeover candidates without ever removing their compute fence."""

        now_iso = (now or datetime.now(timezone.utc)).astimezone(timezone.utc).isoformat()
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM workers
                WHERE compute_release_token != ''
                  AND compute_release_expires_at IS NOT NULL
                  AND compute_release_expires_at <= ?
                """,
                (now_iso,),
            ).fetchall()
        return [str(row["worker_id"]) for row in rows]

    def has_compute_release_claims(self) -> bool:
        with self._connect() as conn:
            return conn.execute(
                "SELECT 1 FROM workers WHERE compute_release_token != '' LIMIT 1"
            ).fetchone() is not None

    def worker_compute_release_claim_matches(
        self,
        worker_id: str,
        token: str,
        epoch: int,
    ) -> bool:
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT 1 FROM workers
                WHERE worker_id = ? AND compute_release_token = ?
                  AND compute_release_epoch = ?
                LIMIT 1
                """,
                (worker_id, token, int(epoch)),
            ).fetchone()
        return row is not None

    @staticmethod
    def _require_worker_work_admission(
        worker: sqlite3.Row | None,
        *,
        project_id: str | None = None,
    ) -> sqlite3.Row:
        """Validate a work-producing mutation under the caller's write txn."""

        if worker is None:
            raise WorkAdmissionError("worker_not_found", "Worker not found")
        if str(worker["state"] or "") == "terminated":
            raise WorkAdmissionError(
                "worker_terminated", "The workspace has ended"
            )
        if str(worker["work_stop_id"] or ""):
            if worker["work_stop_settled_at"] is None:
                raise WorkAdmissionError(
                    "work_stopping", "A workspace stop operation is in progress"
                )
            raise WorkAdmissionError("work_stopped", "The workspace work has stopped")
        if (
            str(worker["compute_release_token"] or "")
            and str(worker["compute_release_scope"] or "") in {"work", "worker"}
        ):
            raise WorkAdmissionError(
                "work_stopping", "A workspace stop operation is in progress"
            )
        if project_id is not None and str(worker["project_id"] or "") != str(project_id):
            raise WorkAdmissionError(
                "worker_scope_mismatch", "Worker does not belong to the requested project"
            )
        return worker

    def _append_follow_up_origin_trace_conn(
        self,
        conn: sqlite3.Connection,
        *,
        data: dict[str, Any],
    ) -> None:
        source = conn.execute(
            """
            SELECT delegations.work_ref, delegations.tenant_id,
                   delegations.owner_id
            FROM delegations
            WHERE delegations.worker_id = ?
              AND delegations.tenant_id = ?
            ORDER BY delegations.created_at ASC
            LIMIT 1
            """,
            (
                str(data.get("worker_id") or ""),
                str(data.get("tenant_id") or "local"),
            ),
        ).fetchone()
        if source is None:
            return
        run_id = str(data.get("run_id") or "")
        created_at = str(data.get("queued_at") or utc_now())
        raw_trace = data.get("_origin_trace")
        if raw_trace is None:
            raw_trace = {
                "origin_ref": "",
                "source_event_id": f"run-receipt:{run_id}",
                "source_revision": 0,
                "surface": "internal",
                "prompt_layers": {},
            }
        if not isinstance(raw_trace, dict):
            raise ValueError("Follow-up origin trace must be structured")
        allowed = {
            "origin_ref",
            "source_event_id",
            "source_revision",
            "surface",
            "prompt_layers",
        }
        if set(raw_trace) != allowed:
            raise ValueError("Follow-up origin trace fields are invalid")
        origin_ref = raw_trace.get("origin_ref")
        source_event_id = raw_trace.get("source_event_id")
        source_revision = raw_trace.get("source_revision")
        surface = raw_trace.get("surface")
        prompt_layers = raw_trace.get("prompt_layers")
        if (
            not isinstance(origin_ref, str)
            or len(origin_ref) > 512
            or any(ord(character) < 32 or ord(character) == 127 for character in origin_ref)
            or not isinstance(source_event_id, str)
            or not source_event_id
            or len(source_event_id) > 512
            or any(ord(character) < 32 or ord(character) == 127 for character in source_event_id)
            or isinstance(source_revision, bool)
            or not isinstance(source_revision, int)
            or source_revision < 0
            or not isinstance(surface, str)
            or not surface
            or len(surface) > 64
            or any(ord(character) < 32 or ord(character) == 127 for character in surface)
            or not isinstance(prompt_layers, dict)
        ):
            raise ValueError("Follow-up origin trace values are invalid")
        origin_payload: dict[str, Any] = {
            "surface": surface,
            "sourceRevision": source_revision,
            "sourceEventRef": "source_sha256:"
            + hashlib.sha256(source_event_id.encode("utf-8")).hexdigest(),
        }
        if origin_ref:
            origin_payload["originRef"] = "origin_sha256:" + hashlib.sha256(
                origin_ref.encode("utf-8")
            ).hexdigest()
        self._append_work_trace_event_conn(
            conn,
            trace_event_id="trace_origin_"
            + hashlib.sha256(run_id.encode("utf-8")).hexdigest(),
            run_id=run_id,
            work_ref=str(source["work_ref"]),
            tenant_id=str(source["tenant_id"] or "local"),
            owner_id=str(source["owner_id"] or ""),
            event_type="work.origin",
            payload={
                "traceContractVersion": 2,
                "origin": origin_payload,
                "promptLayers": prompt_layers,
            },
            created_at=created_at,
        )

    def _insert_run_row(
        self,
        conn: sqlite3.Connection,
        data: dict[str, Any],
    ) -> None:
        if str(data.get("state") or "") == "running":
            raise ValueError(
                "Running rows require the exact runtime-invocation transaction"
            )
        queue_defaults = _queue_defaults(
            str(data["queued_at"]), run_id=str(data["run_id"])
        )
        data = {
            **queue_defaults,
            "claimed_at": None,
            "admitted_at": None,
            "runtime_invoked_at": None,
            "active_attempt_id": "",
            "capacity_class": "",
            "capacity_available_json": "{}",
            "capacity_required_json": "{}",
            "capacity_shortage_json": "{}",
            "capacity_reservation_json": "{}",
            "capacity_next_retry_at": None,
            "provider_route_profile": "",
            "provider_route_runtime": "",
            "provider_route_model": "",
            "provider_route_decision": "",
            "provider_route_from_profile": "",
            "provider_route_from_runtime": "",
            "provider_route_from_model": "",
            "provider_route_failure_class": "",
            "provider_route_cooldown_until": None,
            "provider_liveness_route_locked": 0,
            "allowed_ai_admission_json": "{}",
            "allowed_ai_connection_receipt_json": "{}",
            "execution_binding_json": "{}",
            "origin_scope_json": "{}",
            "continuation_contract_json": "{}",
            "continuation_context_json": "{}",
            **data,
        }
        worker_liveness = conn.execute(
            "SELECT bootstrap_bundle_json, origin_scope_json FROM workers WHERE worker_id = ?",
            (str(data["worker_id"]),),
        ).fetchone()
        data["liveness_mode"] = _liveness_mode_from_bootstrap_json(
            worker_liveness["bootstrap_bundle_json"]
            if worker_liveness is not None
            else ""
        )
        if (
            str(data.get("origin_scope_json") or "{}") in {"", "{}"}
            and worker_liveness is not None
        ):
            data["origin_scope_json"] = str(
                worker_liveness["origin_scope_json"] or "{}"
            )
        conn.execute(
            """
            INSERT INTO runs (
                run_id, worker_id, project_id, tenant_id, instruction, state, queued_at,
                first_queued_at, queue_deadline_at, queue_blocker_class,
                queue_next_status_at, queue_wait_episode, queue_status_sequence,
                queue_wait_open, queue_wait_generation, queue_wait_started_at,
                queue_wait_closed_at, queue_wait_duration_seconds,
                queue_transition_emitted,
                queue_callback_state, queue_terminal_callback_id,
                claimed_at, admitted_at, started_at, runtime_invoked_at,
                active_attempt_id, ended_at, output_text, error_text, failure_class,
                failure_retryable, failure_structured, failure_user_message, failure_recommended_recovery,
                failure_diagnostic_summary, retry_after, retry_attempts, last_retry_class,
                native_session_id, native_capabilities_json, native_child_summary_json,
                allowed_ai_admission_json, allowed_ai_connection_receipt_json,
                execution_binding_json, origin_scope_json,
                capacity_class,
                capacity_available_json, capacity_required_json,
                capacity_shortage_json, capacity_reservation_json,
                capacity_next_retry_at, provider_route_profile,
                provider_route_runtime, provider_route_model,
                provider_route_decision, provider_route_from_profile,
                provider_route_from_runtime, provider_route_from_model,
                provider_route_failure_class, provider_route_cooldown_until,
                continuation_contract_json, continuation_context_json,
                liveness_mode, provider_liveness_route_locked
            )
                VALUES (
                    :run_id, :worker_id, :project_id, :tenant_id, :instruction, :state,
                    :queued_at, :first_queued_at, :queue_deadline_at,
                :queue_blocker_class, :queue_next_status_at,
                :queue_wait_episode, :queue_status_sequence,
                :queue_wait_open, :queue_wait_generation, :queue_wait_started_at,
                :queue_wait_closed_at, :queue_wait_duration_seconds,
                :queue_transition_emitted,
                :queue_callback_state, :queue_terminal_callback_id,
                :claimed_at, :admitted_at, :started_at,
                :runtime_invoked_at, :active_attempt_id, :ended_at,
                :output_text, :error_text,
                :failure_class, :failure_retryable, :failure_structured, :failure_user_message,
                :failure_recommended_recovery, :failure_diagnostic_summary,
                :retry_after, :retry_attempts, :last_retry_class,
                :native_session_id, :native_capabilities_json, :native_child_summary_json,
                :allowed_ai_admission_json, :allowed_ai_connection_receipt_json,
                :execution_binding_json, :origin_scope_json,
                :capacity_class,
                :capacity_available_json, :capacity_required_json,
                :capacity_shortage_json, :capacity_reservation_json,
                :capacity_next_retry_at, :provider_route_profile,
                :provider_route_runtime, :provider_route_model,
                :provider_route_decision, :provider_route_from_profile,
                :provider_route_from_runtime, :provider_route_from_model,
                :provider_route_failure_class, :provider_route_cooldown_until,
                :continuation_contract_json, :continuation_context_json,
                :liveness_mode, :provider_liveness_route_locked
            )
            """,
            data,
        )
        self._append_follow_up_origin_trace_conn(conn, data=data)

    def create_and_attach_provider_run(
        self,
        *,
        request_id: str,
        worker_id: str,
        project_id: str,
        instruction: str,
    ) -> tuple[dict[str, Any], bool]:
        """Atomically create one queued native run and attach it to its provider request."""

        clean_request_id = str(request_id or "").strip()
        if not clean_request_id:
            raise ValueError("Provider run attachment requires a request ID")
        run_id = (
            "run_"
            + hashlib.sha256(
                f"provider-request\n{clean_request_id}".encode("utf-8")
            ).hexdigest()[:10]
        )
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            request = conn.execute(
                "SELECT * FROM provider_requests WHERE request_id = ?",
                (clean_request_id,),
            ).fetchone()
            if request is None:
                conn.execute("ROLLBACK")
                raise ValueError("Provider run attachment requires an existing request")
            attached_run_id = str(request["run_id"] or "").strip()
            if attached_run_id:
                existing = conn.execute(
                    "SELECT * FROM runs WHERE run_id = ?", (attached_run_id,)
                ).fetchone()
                conn.execute("COMMIT")
                if existing is None:
                    raise ValueError("Provider request references a missing native run")
                if (
                    str(existing["worker_id"] or "") != str(worker_id)
                    or str(existing["project_id"] or "") != str(project_id)
                    or str(existing["instruction"] or "") != str(instruction)
                ):
                    raise ValueError(
                        "Provider request run attachment conflicts with existing authority"
                    )
                return self._row(existing) or {}, False
            if str(request["state"] or "") not in {"queued", "running"}:
                conn.execute("ROLLBACK")
                raise ValueError("Provider request is no longer eligible for run attachment")
            worker = self._require_worker_work_admission(
                conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
                ).fetchone(),
                project_id=project_id,
            )
            now = utc_now()
            data = {
                "run_id": run_id,
                "worker_id": str(worker_id),
                "project_id": str(project_id),
                "tenant_id": str(worker["tenant_id"] or "local"),
                "instruction": str(instruction),
                "state": "queued",
                "queued_at": now,
                "started_at": None,
                "ended_at": None,
                "output_text": "",
                "error_text": "",
                "failure_class": "",
                "failure_retryable": 0,
                "failure_structured": 0,
                "failure_user_message": "",
                "failure_recommended_recovery": "",
                "failure_diagnostic_summary": "",
                "retry_after": None,
                "retry_attempts": 0,
                "last_retry_class": "",
                "native_session_id": "",
                "native_capabilities_json": "{}",
                "native_child_summary_json": "{}",
            }
            existing = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            if existing is None:
                self._insert_run_row(conn, data)
                created = True
            else:
                if (
                    str(existing["worker_id"] or "") != str(worker_id)
                    or str(existing["project_id"] or "") != str(project_id)
                    or str(existing["instruction"] or "") != str(instruction)
                ):
                    conn.execute("ROLLBACK")
                    raise ValueError(
                        "Provider request run identity was reused with different authority"
                    )
                data = dict(existing)
                created = False
            attached = conn.execute(
                """
                UPDATE provider_requests
                SET run_id = ?, state = 'queued', updated_at = ?
                WHERE request_id = ?
                  AND restore_hold = 0
                  AND state IN ('queued', 'running')
                  AND (run_id IS NULL OR run_id = '')
                """,
                (run_id, now, clean_request_id),
            )
            if attached.rowcount != 1:
                conn.execute("ROLLBACK")
                raise ValueError("Provider request lost its native-run attachment claim")
            conn.execute(
                "UPDATE workers SET last_run_id = ?, updated_at = ? WHERE worker_id = ?",
                (run_id, now, worker_id),
            )
            row = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row) or data, created

    def create_idempotent_run(
        self,
        *,
        run_id: str,
        worker_id: str,
        project_id: str,
        instruction: str,
        origin_trace: dict[str, Any] | None = None,
        continuation_contract: dict[str, Any] | None = None,
        continuation_context: dict[str, Any] | None = None,
    ) -> tuple[dict[str, Any], bool]:
        """Return an existing reservation or atomically guard and create it."""

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            guard_peer_run(conn, run_id, worker_id, instruction=instruction)
            existing = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            if existing is not None:
                conn.execute("COMMIT")
                if (
                    str(existing["worker_id"] or "") != str(worker_id)
                    or str(existing["project_id"] or "") != str(project_id)
                    or str(existing["instruction"] or "") != str(instruction)
                ):
                    raise ValueError(
                        "GlassHive idempotency key was reused with a different instruction"
                    )
                return self._row(existing) or {}, False
            worker = self._require_worker_work_admission(
                conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
                ).fetchone(),
                project_id=project_id,
            )
            now = utc_now()
            data = {
                "run_id": str(run_id),
                "worker_id": str(worker_id),
                "project_id": str(project_id),
                "tenant_id": str(worker["tenant_id"] or "local"),
                "instruction": str(instruction),
                "state": "queued",
                "queued_at": now,
                "started_at": None,
                "ended_at": None,
                "output_text": "",
                "error_text": "",
                "failure_class": "",
                "failure_retryable": 0,
                "failure_structured": 0,
                "failure_user_message": "",
                "failure_recommended_recovery": "",
                "failure_diagnostic_summary": "",
                "retry_after": None,
                "retry_attempts": 0,
                "last_retry_class": "",
                "native_session_id": "",
                "native_capabilities_json": "{}",
                "native_child_summary_json": "{}",
                "_origin_trace": origin_trace,
                "continuation_contract_json": json.dumps(
                    continuation_contract if isinstance(continuation_contract, dict) else {},
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
                "continuation_context_json": json.dumps(
                    continuation_context if isinstance(continuation_context, dict) else {},
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            }
            self._insert_run_row(conn, data)
            conn.execute(
                "UPDATE workers SET last_run_id = ?, updated_at = ? WHERE worker_id = ?",
                (run_id, now, worker_id),
            )
            created = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(created) or {}, True

    def replace_queued_run_idempotently(
        self,
        *,
        source_run_id: str,
        replacement_run_id: str,
        worker_id: str,
        project_id: str,
        instruction: str,
        origin_trace: dict[str, Any] | None = None,
        continuation_contract: dict[str, Any] | None = None,
        continuation_context: dict[str, Any] | None = None,
    ) -> tuple[dict[str, Any] | None, bool]:
        """Replace one not-yet-started run without creating a live sibling.

        Active-work Message is non-interrupting.  When its exact source is still
        queued, the safe boundary is already available: atomically retire that
        reservation and carry the original mission plus new guidance into one
        deterministic replacement.  A scheduler/startup race returns ``None``
        so the caller can preserve normal next-boundary delivery instead.
        """

        clean_source = str(source_run_id or "").strip()
        clean_replacement = str(replacement_run_id or "").strip()
        clean_instruction = str(instruction or "")
        if not clean_source or not clean_replacement or not clean_instruction:
            raise ValueError("Queued run replacement requires exact run identities")
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            existing = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_replacement,)
            ).fetchone()
            if existing is not None:
                conn.execute("COMMIT")
                if (
                    str(existing["worker_id"] or "") != str(worker_id)
                    or str(existing["project_id"] or "") != str(project_id)
                    or str(existing["instruction"] or "") != clean_instruction
                ):
                    raise ValueError(
                        "GlassHive idempotency key was reused with a different instruction"
                    )
                return self._row(existing), False

            worker = self._require_worker_work_admission(
                conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (worker_id,)
                ).fetchone(),
                project_id=project_id,
            )
            source = conn.execute(
                "SELECT * FROM runs WHERE run_id = ? AND worker_id = ? AND project_id = ?",
                (clean_source, worker_id, project_id),
            ).fetchone()
            delegation = conn.execute(
                "SELECT 1 FROM delegations WHERE worker_id = ? AND current_run_id = ? LIMIT 1",
                (worker_id, clean_source),
            ).fetchone()
            active_start = conn.execute(
                "SELECT * FROM host_run_leases WHERE worker_id = ? AND run_id = ? "
                "AND status = 'active' LIMIT 1",
                (worker_id, clean_source),
            ).fetchone()
            transferable_preaccept = bool(
                active_start is not None
                and str(active_start["startup_state"] or "") == "reserved"
                and not str(active_start["attempt_id"] or "")
                and not int(active_start["pid"] or 0)
                and not int(active_start["process_group"] or 0)
                and not str(active_start["process_start_identity"] or "")
                and not str(active_start["startup_identity_kind"] or "")
                and not str(active_start["startup_container_id"] or "")
                and not str(active_start["startup_session_id"] or "")
            )
            if (
                source is None
                or str(source["state"] or "") != "queued"
                or delegation is None
                or (active_start is not None and not transferable_preaccept)
            ):
                conn.execute("COMMIT")
                return None, False

            now = utc_now()
            data = {
                "run_id": clean_replacement,
                "worker_id": str(worker_id),
                "project_id": str(project_id),
                "tenant_id": str(worker["tenant_id"] or "local"),
                "instruction": clean_instruction,
                "state": "queued",
                "queued_at": now,
                "started_at": None,
                "ended_at": None,
                "output_text": "",
                "error_text": "",
                "failure_class": "",
                "failure_retryable": 0,
                "failure_structured": 0,
                "failure_user_message": "",
                "failure_recommended_recovery": "",
                "failure_diagnostic_summary": "",
                "retry_after": None,
                "retry_attempts": 0,
                "last_retry_class": "",
                "native_session_id": "",
                "native_capabilities_json": "{}",
                "native_child_summary_json": "{}",
                "_origin_trace": origin_trace,
                "continuation_contract_json": json.dumps(
                    continuation_contract if isinstance(continuation_contract, dict) else {},
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
                "continuation_context_json": json.dumps(
                    continuation_context if isinstance(continuation_context, dict) else {},
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            }
            self._insert_run_row(conn, data)
            if transferable_preaccept:
                transferred = conn.execute(
                    """
                    UPDATE host_run_leases SET run_id = ?
                    WHERE lease_id = ? AND worker_id = ? AND run_id = ?
                      AND status = 'active' AND startup_state = 'reserved'
                      AND attempt_id = '' AND pid IS NULL AND process_group IS NULL
                      AND process_start_identity = ''
                      AND startup_identity_kind = ''
                      AND startup_container_id = ''
                      AND startup_session_id = ''
                    """,
                    (
                        clean_replacement,
                        active_start["lease_id"],
                        worker_id,
                        clean_source,
                    ),
                )
                if transferred.rowcount != 1:
                    conn.execute("ROLLBACK")
                    return None, False
            retired = conn.execute(
                """
                UPDATE runs SET state = 'cancelled', ended_at = ?,
                    error_text = 'Coalesced into queued message guidance',
                    failure_class = '', failure_retryable = 0,
                    failure_structured = 0, retry_after = NULL
                WHERE run_id = ? AND worker_id = ? AND state = 'queued'
                """,
                (now, clean_source, worker_id),
            )
            advanced = conn.execute(
                """
                UPDATE delegations SET current_run_id = ?, updated_at = ?
                WHERE worker_id = ? AND current_run_id = ?
                """,
                (clean_replacement, now, worker_id, clean_source),
            )
            if retired.rowcount != 1 or advanced.rowcount < 1:
                conn.execute("ROLLBACK")
                return None, False
            self._record_terminal_artifact_trace_conn(
                conn,
                run_id=clean_source,
                observed_at=now,
            )
            conn.execute(
                "UPDATE workers SET last_run_id = ?, updated_at = ? WHERE worker_id = ?",
                (clean_replacement, now, worker_id),
            )
            created = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (clean_replacement,)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(created), True


    def list_due_retry_worker_ids(self, now_iso: str | None = None, limit: int = 1000) -> list[str]:
        now_iso = now_iso or utc_now()
        with self._connect() as conn:
            rows = conn.execute(
                """
                WITH due_workers AS (
                    SELECT
                        runs.worker_id,
                        workers.tenant_id,
                        workers.owner_id,
                        MIN(runs.queued_at) AS first_queued_at
                    FROM runs
                    JOIN workers ON workers.worker_id = runs.worker_id
                    WHERE runs.state = 'queued'
                      AND workers.state NOT IN (
                          'paused', 'needs_input', 'stopping', 'terminated'
                      )
                      AND NOT EXISTS (
                          SELECT 1 FROM runs AS active_runs
                          WHERE active_runs.worker_id = runs.worker_id
                            AND active_runs.state IN (
                                'claimed', 'admitted', 'running', 'settling',
                                'paused', 'needs_input'
                            )
                      )
                      AND (runs.retry_after IS NULL OR runs.retry_after = '' OR runs.retry_after <= ?)
                    GROUP BY runs.worker_id, workers.tenant_id, workers.owner_id
                ), ranked AS (
                    SELECT
                        worker_id,
                        tenant_id,
                        owner_id,
                        first_queued_at,
                        ROW_NUMBER() OVER (
                            PARTITION BY tenant_id, owner_id
                            ORDER BY first_queued_at ASC, worker_id ASC
                        ) AS owner_round
                    FROM due_workers
                )
                SELECT worker_id
                FROM ranked
                ORDER BY owner_round ASC, first_queued_at ASC,
                         tenant_id ASC, owner_id ASC, worker_id ASC
                LIMIT ?
                """,
                (now_iso, max(1, int(limit))),
            ).fetchall()
        return [str(row["worker_id"]) for row in rows]

    def next_queued_retry_after(self, now_iso: str | None = None) -> str | None:
        now_iso = now_iso or utc_now()
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT MIN(runs.retry_after) AS retry_after
                FROM runs
                JOIN workers ON workers.worker_id = runs.worker_id
                WHERE runs.state = 'queued'
                  AND workers.state NOT IN (
                      'paused', 'needs_input', 'stopping', 'terminated'
                  )
                  AND runs.retry_after IS NOT NULL
                  AND runs.retry_after != ''
                  AND runs.retry_after > ?
                """,
                (now_iso,),
            ).fetchone()
        if row is None:
            return None
        return str(row["retry_after"] or "") or None

    def list_run_attempts(self, run_id: str) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM run_attempts
                WHERE run_id = ?
                ORDER BY attempt_number ASC
                """,
                (str(run_id),),
            ).fetchall()
        return self._rows(rows)

    def list_due_queue_status(
        self,
        *,
        now: str,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM runs
                WHERE state IN ('queued', 'claimed', 'admitted', 'running')
                  AND queue_wait_open = 1
                  AND queue_next_status_at IS NOT NULL
                  AND queue_next_status_at != ''
                  AND queue_next_status_at <= ?
                  AND queue_deadline_at > ?
                ORDER BY queue_next_status_at ASC, run_id ASC
                LIMIT ?
                """,
                (str(now), str(now), max(1, min(int(limit), 1000))),
            ).fetchall()
        return self._rows(rows)

    def list_due_queue_timeouts(
        self,
        *,
        now: str,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM runs
                WHERE state IN ('queued', 'claimed', 'admitted', 'running')
                  AND queue_wait_open = 1
                  AND queue_deadline_at IS NOT NULL
                  AND queue_deadline_at != ''
                  AND queue_deadline_at <= ?
                ORDER BY queue_deadline_at ASC, run_id ASC
                LIMIT ?
                """,
                (str(now), max(1, min(int(limit), 1000))),
            ).fetchall()
        return self._rows(rows)

    def next_queue_maintenance_at(self, *, now: str | None = None) -> str | None:
        now = str(now or utc_now())
        with self._connect() as conn:
            row = conn.execute(
                """
                SELECT MIN(candidate) AS next_at
                FROM (
                    SELECT queue_deadline_at AS candidate
                    FROM runs
                    WHERE state IN ('queued', 'claimed', 'admitted', 'running')
                      AND queue_wait_open = 1
                      AND queue_deadline_at IS NOT NULL
                      AND queue_deadline_at != ''
                    UNION ALL
                    SELECT queue_next_status_at AS candidate
                    FROM runs
                    WHERE state IN ('queued', 'claimed', 'admitted', 'running')
                      AND queue_wait_open = 1
                      AND queue_next_status_at IS NOT NULL
                      AND queue_next_status_at != ''
                )
                WHERE candidate >= ?
                """,
                (now,),
            ).fetchone()
        return str((row or {})["next_at"] or "") or None

    @staticmethod
    def terminal_callback_id(
        *,
        run_id: str,
        state: str,
        ended_at: str,
        attempt_number: int,
        result_revision: int,
        result_digest: str,
    ) -> str:
        return _terminal_callback_id(
            run_id=run_id,
            state=state,
            ended_at=ended_at,
            attempt_number=attempt_number,
            result_revision=result_revision,
            result_digest=result_digest,
        )

    @staticmethod
    def terminal_callback_wire_state(*, durable_state: str, event_type: str) -> str:
        return _terminal_callback_wire_state(durable_state, event_type)

    @staticmethod
    def terminal_result_digest(run: dict[str, Any]) -> str:
        return _terminal_result_digest(run)

    @staticmethod
    def callback_contract_digest(worker: dict[str, Any]) -> str:
        return _text_sha256(worker.get("bootstrap_bundle_json") or "")

    @staticmethod
    def _callback_attempt_number_conn(
        conn: sqlite3.Connection,
        run_id: str,
    ) -> int:
        row = conn.execute(
            """
            SELECT attempt_number
            FROM run_attempts
            WHERE run_id = ?
            ORDER BY attempt_number DESC
            LIMIT 1
            """,
            (str(run_id),),
        ).fetchone()
        return max(0, int(row["attempt_number"] or 0)) if row is not None else 0

    @staticmethod
    def _strictly_after(value: str, floor: str) -> str:
        try:
            value_at = _parse_utc(str(value))
            floor_at = _parse_utc(str(floor))
        except (TypeError, ValueError):
            return str(value)
        if value_at <= floor_at:
            return (floor_at + timedelta(microseconds=1)).isoformat()
        return value_at.isoformat()

    @staticmethod
    def _prepare_callback_intent_conn(
        conn: sqlite3.Connection,
        intent: dict[str, Any],
    ) -> dict[str, Any]:
        callback_id = str(intent.get("callback_id") or "").strip()
        worker_id = str(intent.get("worker_id") or "").strip()
        run_id = str(intent.get("run_id") or "").strip()
        event_type = str(intent.get("event_type") or "").strip()
        if not callback_id:
            raise ValueError("Callback intent requires a deterministic identity")
        if not worker_id or not event_type:
            raise ValueError("Callback intent requires exact worker and event identity")
        if not run_id:
            if not event_type.startswith("worker."):
                raise ValueError("Run callbacks require exact run identity")
            worker = conn.execute(
                "SELECT project_id, tenant_id FROM workers WHERE worker_id = ?",
                (worker_id,),
            ).fetchone()
            if (
                worker is None
                or str(worker["project_id"] or "")
                != str(intent.get("project_id") or "")
                or str(worker["tenant_id"] or "local")
                != str(intent.get("tenant_id") or "local")
            ):
                raise ValueError("Callback intent worker association is not exact")
            try:
                payload = json.loads(str(intent.get("payload_json") or "{}"))
            except (TypeError, json.JSONDecodeError) as exc:
                raise ValueError("Callback intent payload must be valid JSON") from exc
            if not isinstance(payload, dict):
                raise ValueError("Callback intent payload must be an object")
            if (
                intent.get("attempt_number") not in (None, 0)
                or intent.get("result_revision") not in (None, 0)
                or str(intent.get("result_digest") or "")
            ):
                raise ValueError("Runless callback cannot carry run result identity")
            return {
                **intent,
                "callback_id": callback_id,
                "worker_id": worker_id,
                "run_id": None,
                "event_type": event_type,
                "attempt_number": 0,
                "result_revision": 0,
                "result_digest": "",
                "payload_json": json.dumps(payload, ensure_ascii=False),
            }
        exact_run = conn.execute(
            "SELECT * FROM runs WHERE run_id = ?",
            (run_id,),
        ).fetchone()
        if (
            exact_run is None
            or str(exact_run["worker_id"] or "") != worker_id
            or str(exact_run["project_id"] or "")
            != str(intent.get("project_id") or "")
            or str(exact_run["tenant_id"] or "local")
            != str(intent.get("tenant_id") or "local")
        ):
            raise ValueError("Callback intent run association is not exact")
        try:
            payload = json.loads(str(intent.get("payload_json") or "{}"))
        except (TypeError, json.JSONDecodeError) as exc:
            raise ValueError("Callback intent payload must be valid JSON") from exc
        if not isinstance(payload, dict):
            raise ValueError("Callback intent payload must be an object")

        exact_attempt = Store._callback_attempt_number_conn(conn, run_id)
        supplied_attempt = intent.get("attempt_number")
        payload_attempt = payload.get("attempt_number")
        if exact_attempt > 0:
            if (
                not isinstance(supplied_attempt, int)
                or isinstance(supplied_attempt, bool)
                or supplied_attempt < 1
                or supplied_attempt != exact_attempt
                or payload_attempt != supplied_attempt
            ):
                raise CallbackIntentGenerationConflictError(
                    "Callback intent attempt identity is not exact"
                )
            attempt_number = exact_attempt
        else:
            if (
                supplied_attempt not in (None, 0)
                or isinstance(supplied_attempt, bool)
                or payload_attempt not in (None, 0)
                or isinstance(payload_attempt, bool)
            ):
                raise CallbackIntentGenerationConflictError(
                    "Callback intent attempt identity is not exact"
                )
            attempt_number = 0
            payload["attempt_number"] = None

        supplied_result_revision = intent.get("result_revision")
        payload_result_revision = payload.get("result_revision")
        result_digest = str(intent.get("result_digest") or "").strip()
        payload_result_digest = str(payload.get("result_digest") or "").strip()
        if callback_id.startswith("cb_terminal_"):
            exact_result_revision = int(
                exact_run["terminal_result_revision"] or 0
            )
            exact_result_digest = _terminal_result_digest(exact_run)
            result_state = _terminal_callback_wire_state(
                str(exact_run["state"] or ""), event_type
            )
            expected_callback_id = _terminal_callback_id(
                run_id=run_id,
                state=result_state,
                ended_at=str(exact_run["ended_at"] or ""),
                attempt_number=attempt_number,
                result_revision=exact_result_revision,
                result_digest=exact_result_digest,
            )
            if (
                str(exact_run["state"] or "") not in TERMINAL_RUN_STATES
                or not result_state
                or not str(exact_run["ended_at"] or "")
                or exact_result_revision < 1
                or callback_id != expected_callback_id
                or not isinstance(supplied_result_revision, int)
                or isinstance(supplied_result_revision, bool)
                or supplied_result_revision != exact_result_revision
                or not isinstance(payload_result_revision, int)
                or isinstance(payload_result_revision, bool)
                or payload_result_revision != exact_result_revision
                or result_digest != exact_result_digest
                or payload_result_digest != exact_result_digest
                or str(payload.get("result_state") or "")
                != result_state
                or str(payload.get("result_ended_at") or "")
                != str(exact_run["ended_at"] or "")
            ):
                raise CallbackIntentGenerationConflictError(
                    "Terminal callback result identity is not exact"
                )
            result_revision = exact_result_revision
            payload["result_revision"] = exact_result_revision
            payload["result_digest"] = exact_result_digest
            payload["result_state"] = result_state
            payload["result_ended_at"] = str(exact_run["ended_at"] or "")
        elif (
            supplied_result_revision not in (None, 0)
            or isinstance(supplied_result_revision, bool)
            or payload_result_revision not in (None, 0)
            or isinstance(payload_result_revision, bool)
            or result_digest
            or payload_result_digest
        ):
            raise ValueError(
                "Only canonical terminal callbacks may carry a result revision"
            )
        else:
            result_revision = 0

        if "run_input" in payload:
            # Validate against the same run inside the outbox transaction, so
            # a stale or forged source cannot join an otherwise valid result.
            if (
                str(exact_run["state"] or "") not in TERMINAL_RUN_STATES
                or not str(exact_run["ended_at"] or "")
                or not _terminal_callback_wire_state(str(exact_run["state"] or ""), event_type)
                or json.dumps(payload["run_input"], sort_keys=True, ensure_ascii=False)
                != json.dumps(accepted_run_input(dict(exact_run)), sort_keys=True, ensure_ascii=False)
            ):
                raise CallbackIntentGenerationConflictError(
                    "Callback accepted run input is not exact"
                )

        exact_fields = {
            "callback_id": callback_id,
            "event": event_type,
            "worker_id": worker_id,
            "run_id": run_id,
        }
        for key, expected in exact_fields.items():
            current = str(payload.get(key) or "").strip()
            if current and current != expected:
                raise ValueError(f"Callback intent {key} is not exact")
            payload[key] = expected
        callback_ts = payload.get("callback_ts")
        if (
            isinstance(callback_ts, bool)
            or not isinstance(callback_ts, (int, float))
            or not math.isfinite(float(callback_ts))
            or float(callback_ts) <= 0
        ):
            raise ValueError("Callback intent requires a stable callback timestamp")

        delegation = conn.execute(
            """
            SELECT origin_ref, work_ref, project_id, tenant_id
            FROM delegations
            WHERE worker_id = ?
            LIMIT 1
            """,
            (worker_id,),
        ).fetchone()
        if delegation is not None:
            expected_project = str(delegation["project_id"] or "")
            if str(intent.get("project_id") or "") != expected_project:
                raise ValueError("Callback intent project identity is not exact")
            for key, expected in (
                ("origin_ref", str(delegation["origin_ref"] or "")),
                ("work_ref", str(delegation["work_ref"] or "")),
            ):
                current = str(payload.get(key) or "").strip()
                if current and current != expected:
                    raise ValueError(f"Callback intent {key} is not exact")
                payload[key] = expected

        return {
            **intent,
            "callback_id": callback_id,
            "worker_id": worker_id,
            "run_id": run_id,
            "event_type": event_type,
            "attempt_number": attempt_number,
            "result_revision": result_revision,
            "result_digest": result_digest,
            "payload_json": json.dumps(payload, ensure_ascii=False),
        }

    def _insert_callback_intent_conn(
        self,
        conn: sqlite3.Connection,
        intent: dict[str, Any],
        *,
        now: str,
    ) -> sqlite3.Row:
        intent = Store._prepare_callback_intent_conn(conn, intent)
        callback_id = str(intent["callback_id"])
        run = conn.execute(
            "SELECT ended_at FROM runs WHERE run_id = ?", (str(intent["run_id"]),)
        ).fetchone()
        created_at = str(now)
        if run is not None and str(run["ended_at"] or ""):
            created_at = Store._strictly_after(created_at, str(run["ended_at"]))
        data = {
            "callback_id": callback_id,
            "project_id": str(intent.get("project_id") or ""),
            "worker_id": str(intent.get("worker_id") or ""),
            "tenant_id": str(intent.get("tenant_id") or "local"),
            "run_id": str(intent.get("run_id") or "") or None,
            "attempt_number": int(intent["attempt_number"]),
            "event_type": str(intent.get("event_type") or ""),
            "url": str(intent.get("url") or ""),
            "payload_json": str(intent.get("payload_json") or "{}"),
            "result_revision": int(intent.get("result_revision") or 0),
            "result_digest": str(intent.get("result_digest") or ""),
            "now": created_at,
        }
        conn.execute(
            """
            INSERT OR IGNORE INTO callback_outbox (
                callback_id, project_id, worker_id, tenant_id, run_id,
                attempt_number, event_type, url, payload_json,
                result_revision, result_digest,
                status, attempts, last_error,
                created_at, updated_at, delivered_at, http_accepted_at,
                delivery_lease_token, delivery_generation,
                delivery_lease_expires_at
            ) VALUES (
                :callback_id, :project_id, :worker_id, :tenant_id, :run_id,
                :attempt_number, :event_type, :url, :payload_json,
                :result_revision, :result_digest, 'pending', 0, '',
                :now, :now, NULL, NULL, '', 0, NULL
            )
            """,
            data,
        )
        row = conn.execute(
            "SELECT * FROM callback_outbox WHERE callback_id = ?",
            (callback_id,),
        ).fetchone()
        if row is None:
            raise RuntimeError("Callback intent did not persist")
        immutable_identity = (
            "project_id",
            "worker_id",
            "tenant_id",
            "run_id",
            "attempt_number",
            "event_type",
            "url",
            "payload_json",
            "result_revision",
            "result_digest",
        )
        if any(str(row[key] or "") != str(data[key] or "") for key in immutable_identity):
            raise RuntimeError("Callback identity collision")
        self._append_callback_trace_conn(conn, callback_id=callback_id)
        return row

    def claim_queue_transition(
        self,
        run_id: str,
        *,
        expected_generation: int,
        expected_deadline: str,
        callback_id: str,
        callback_intent: dict[str, Any] | None,
        event_message: str,
        now: str,
    ) -> dict[str, Any] | None:
        deterministic_id = _queue_callback_id(
            "transition",
            run_id=str(run_id),
            generation=int(expected_generation),
            deadline=str(expected_deadline),
        )
        if str(callback_id) != deterministic_id:
            raise ValueError("Queue transition callback identity is not deterministic")
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            cursor = conn.execute(
                """
                UPDATE runs
                SET queue_transition_emitted = 1,
                    queue_callback_state = ?
                WHERE run_id = ?
                  AND state IN ('queued', 'claimed', 'admitted', 'running')
                  AND queue_wait_open = 1
                  AND queue_wait_generation = ?
                  AND queue_deadline_at = ?
                  AND queue_transition_emitted = 0
                  AND queue_deadline_at > ?
                """,
                (
                    "enqueued" if callback_intent is not None else "unavailable",
                    str(run_id),
                    int(expected_generation),
                    str(expected_deadline),
                    str(now),
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("COMMIT")
                return None
            conn.execute(
                """
                INSERT OR IGNORE INTO events (
                    event_id, project_id, worker_id, tenant_id, run_id,
                    event_type, message, payload_json, created_at
                )
                SELECT ?, project_id, worker_id, tenant_id, run_id,
                       'run.waiting_on_capacity', ?, '{}', ?
                FROM runs WHERE run_id = ?
                """,
                (
                    "evt_" + str(callback_id),
                    str(event_message),
                    str(now),
                    str(run_id),
                ),
            )
            callback = None
            if callback_intent is not None:
                if (
                    str(callback_intent.get("callback_id") or "") != str(callback_id)
                    or str(callback_intent.get("run_id") or "") != str(run_id)
                ):
                    conn.execute("ROLLBACK")
                    raise ValueError("Queue transition callback intent is not exact")
                callback = self._insert_callback_intent_conn(
                    conn, callback_intent, now=str(now)
                )
            row = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            conn.execute("COMMIT")
        result = self._row(row)
        if result is not None:
            result["_callback"] = self._row(callback)
        return result

    def advance_queue_status_refresh(
        self,
        run_id: str,
        *,
        expected_next_status_at: str,
        expected_generation: int,
        expected_deadline: str,
        callback_id: str,
        callback_intent: dict[str, Any] | None,
        now: str,
        next_status_at: str,
    ) -> dict[str, Any] | None:
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            current = conn.execute(
                "SELECT queue_status_sequence FROM runs WHERE run_id = ?",
                (str(run_id),),
            ).fetchone()
            expected_sequence = (
                int(current["queue_status_sequence"] or 0) + 1
                if current is not None
                else 1
            )
            deterministic_id = _queue_callback_id(
                "refresh",
                run_id=str(run_id),
                generation=int(expected_generation),
                deadline=str(expected_deadline),
                sequence=expected_sequence,
            )
            if str(callback_id) != deterministic_id:
                conn.execute("ROLLBACK")
                raise ValueError("Queue refresh callback identity is not deterministic")
            cursor = conn.execute(
                """
                UPDATE runs
                SET queue_next_status_at = ?,
                    queue_status_sequence = queue_status_sequence + 1,
                    queue_callback_state = ?
                WHERE run_id = ?
                  AND state IN ('queued', 'claimed', 'admitted', 'running')
                  AND queue_wait_open = 1
                  AND queue_wait_generation = ?
                  AND queue_deadline_at = ?
                  AND queue_next_status_at = ?
                  AND queue_deadline_at > ?
                """,
                (
                    str(next_status_at),
                    "enqueued" if callback_intent is not None else "unavailable",
                    str(run_id),
                    int(expected_generation),
                    str(expected_deadline),
                    str(expected_next_status_at),
                    str(now),
                ),
            )
            if cursor.rowcount != 1:
                conn.execute("COMMIT")
                return None
            callback = None
            if callback_intent is not None:
                if (
                    str(callback_intent.get("callback_id") or "") != str(callback_id)
                    or str(callback_intent.get("run_id") or "") != str(run_id)
                ):
                    conn.execute("ROLLBACK")
                    raise ValueError("Queue refresh callback intent is not exact")
                callback = self._insert_callback_intent_conn(
                    conn, callback_intent, now=str(now)
                )
            row = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            conn.execute("COMMIT")
        result = self._row(row)
        if result is not None:
            result["_callback"] = self._row(callback)
        return result

    def force_queue_deadline_for_local_qa(
        self,
        run_id: str,
        *,
        expected_state: str,
        expected_generation: int,
        expected_deadline: str,
        now: str,
    ) -> dict[str, Any] | None:
        """Move one exact synthetic wait to its deadline without changing run truth."""

        if expected_state not in {"claimed", "admitted"}:
            raise ValueError("Local-QA queue stall state is invalid")
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            updated = conn.execute(
                """
                UPDATE runs
                SET queue_deadline_at = ?, queue_next_status_at = ?
                WHERE run_id = ? AND state = ? AND queue_wait_open = 1
                  AND queue_wait_generation = ? AND queue_deadline_at = ?
                """,
                (
                    str(now),
                    str(now),
                    str(run_id),
                    expected_state,
                    int(expected_generation),
                    str(expected_deadline),
                ),
            ).rowcount
            row = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(row) if updated == 1 else None

    def expire_queued_run_if_due(
        self,
        run_id: str,
        *,
        expected_deadline: str,
        expected_generation: int,
        expected_callback_id: str,
        callback_intent: dict[str, Any] | None,
        now: str,
    ) -> dict[str, Any] | None:
        event_id = "evt_queue_timeout_" + hashlib.sha256(
            f"{run_id}:{expected_generation}:{expected_deadline}".encode("utf-8")
        ).hexdigest()
        message = (
            "This work left the queue after its bounded admission wait expired. "
            "The workspace is preserved and the work can be retried."
        )
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            if (
                run is None
                or str(run["state"] or "")
                not in {"queued", "claimed", "admitted", "running"}
                or not bool(run["queue_wait_open"])
                or int(run["queue_wait_generation"] or 0) != int(expected_generation)
                or str(run["queue_deadline_at"] or "") != str(expected_deadline)
                or str(run["queue_terminal_callback_id"] or "")
                != str(expected_callback_id)
                or str(expected_deadline) > str(now)
            ):
                conn.execute("COMMIT")
                return None
            wait_duration = max(
                0,
                int(
                    (
                        _parse_utc(str(now))
                        - _parse_utc(
                            str(run["queue_wait_started_at"] or run["first_queued_at"])
                        )
                    ).total_seconds()
                ),
            )
            conn.execute(
                """
                UPDATE host_run_leases
                SET status = 'released', released_at = ?,
                    release_reason = 'run_terminal:queue_wait_timeout',
                    reconciled_at = COALESCE(reconciled_at, ?)
                WHERE run_id = ? AND status = 'active'
                """,
                (str(now), str(now), str(run_id)),
            )
            cursor = conn.execute(
                """
                UPDATE runs
                SET state = 'failed', ended_at = ?, retry_after = NULL,
                    failure_class = 'queue_wait_timeout',
                    failure_retryable = 1,
                    failure_structured = 1,
                    failure_user_message = ?,
                    failure_recommended_recovery =
                        'Retry this preserved workspace when launch capacity is available.',
                    failure_diagnostic_summary =
                        'The exact queued run reached its durable queue deadline.',
                    error_text = 'queue_wait_timeout',
                    queue_next_status_at = NULL,
                    queue_wait_open = 0,
                    queue_wait_closed_at = ?,
                    queue_wait_duration_seconds = ?,
                    queue_callback_state = ?
                WHERE run_id = ?
                  AND state IN ('queued', 'claimed', 'admitted', 'running')
                  AND queue_wait_open = 1
                  AND queue_wait_generation = ?
                  AND queue_deadline_at = ?
                  AND queue_terminal_callback_id = ?
                """,
                (
                    str(now),
                    message,
                    str(now),
                    wait_duration,
                    "enqueued" if callback_intent is not None else "unavailable",
                    str(run_id),
                    int(expected_generation),
                    str(expected_deadline),
                    str(expected_callback_id),
                ),
            )
            if not cursor.rowcount:
                conn.execute("COMMIT")
                return None
            attempt_id = str(run["active_attempt_id"] or "")
            if attempt_id:
                attempt_cursor = conn.execute(
                    """
                    UPDATE run_attempts
                    SET state = 'failed', ended_at = ?,
                        terminal_reason = 'queue_wait_timeout'
                    WHERE attempt_id = ? AND ended_at IS NULL
                    """,
                    (str(now), attempt_id),
                )
                if attempt_cursor.rowcount:
                    self._append_attempt_trace_conn(
                        conn, attempt_id=attempt_id, created_at=str(now)
                    )
            self._record_terminal_artifact_trace_conn(
                conn,
                run_id=str(run_id),
                observed_at=str(now),
            )
            conn.execute(
                """
                INSERT OR IGNORE INTO events (
                    event_id, project_id, worker_id, tenant_id, run_id,
                    event_type, message, payload_json, created_at
                ) VALUES (?, ?, ?, ?, ?, 'run.failed', ?, ?, ?)
                """,
                (
                    event_id,
                    run["project_id"],
                    run["worker_id"],
                    run["tenant_id"],
                    run_id,
                    message,
                    json.dumps(
                        {
                            "failureClass": "queue_wait_timeout",
                            "timeoutAt": str(expected_deadline),
                        },
                        sort_keys=True,
                        separators=(",", ":"),
                    ),
                    str(now),
                ),
            )
            callback = None
            if callback_intent is not None:
                if (
                    str(callback_intent.get("callback_id") or "")
                    != str(expected_callback_id)
                    or str(callback_intent.get("run_id") or "") != str(run_id)
                    or str(callback_intent.get("event_type") or "") != "run.failed"
                ):
                    conn.execute("ROLLBACK")
                    raise ValueError("Queue timeout callback intent is not exact")
                terminal_run = conn.execute(
                    "SELECT * FROM runs WHERE run_id = ?",
                    (str(run_id),),
                ).fetchone()
                if terminal_run is None:
                    conn.execute("ROLLBACK")
                    raise RuntimeError("Queue timeout terminal run disappeared")
                result_digest = _terminal_result_digest(terminal_run)
                result_revision = int(
                    terminal_run["terminal_result_revision"] or 0
                )
                attempt_number = self._callback_attempt_number_conn(
                    conn, str(run_id)
                )
                canonical_callback_id = _terminal_callback_id(
                    run_id=str(run_id),
                    state="failed",
                    ended_at=str(terminal_run["ended_at"] or ""),
                    attempt_number=attempt_number,
                    result_revision=result_revision,
                    result_digest=result_digest,
                )
                try:
                    callback_payload = json.loads(
                        str(callback_intent.get("payload_json") or "{}")
                    )
                except (TypeError, json.JSONDecodeError):
                    conn.execute("ROLLBACK")
                    raise ValueError("Queue timeout callback payload is invalid")
                if not isinstance(callback_payload, dict):
                    conn.execute("ROLLBACK")
                    raise ValueError("Queue timeout callback payload is invalid")
                callback_payload["callback_id"] = canonical_callback_id
                callback_payload["result_revision"] = result_revision
                callback_payload["result_digest"] = result_digest
                callback_payload["result_state"] = str(
                    terminal_run["state"] or ""
                )
                callback_payload["result_ended_at"] = str(
                    terminal_run["ended_at"] or ""
                )
                callback_intent = {
                    **callback_intent,
                    "callback_id": canonical_callback_id,
                    "attempt_number": (
                        attempt_number if attempt_number > 0 else None
                    ),
                    "result_revision": result_revision,
                    "result_digest": result_digest,
                    "payload_json": json.dumps(
                        callback_payload, ensure_ascii=False
                    ),
                }
                callback = self._insert_callback_intent_conn(
                    conn, callback_intent, now=str(now)
                )
            row = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            conn.execute("COMMIT")
        result = self._row(row)
        if result is not None:
            result["_callback"] = self._row(callback)
        return result

    def list_queue_timeout_callbacks_pending(
        self,
        *,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM runs
                WHERE state = 'failed'
                  AND failure_class = 'queue_wait_timeout'
                  AND queue_callback_state IN ('pending', 'unknown')
                ORDER BY ended_at ASC, run_id ASC
                LIMIT ?
                """,
                (max(1, min(int(limit), 1000)),),
            ).fetchall()
        return self._rows(rows)

    def mark_queue_callback_state(
        self,
        run_id: str,
        *,
        state: str,
    ) -> dict[str, Any] | None:
        if state not in {"unknown", "pending", "enqueued", "unavailable"}:
            raise ValueError("Invalid queue callback state")
        with self._connect() as conn:
            conn.execute(
                "UPDATE runs SET queue_callback_state = ? WHERE run_id = ?",
                (state, str(run_id)),
            )
            row = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
        return self._row(row)

    def list_callback_outbox_for_run(
        self,
        run_id: str,
        *,
        tenant_id: str,
        owner_id: str,
        limit: int = 50,
    ) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM (
                    SELECT callback_outbox.*
                    FROM callback_outbox
                    JOIN workers
                      ON workers.worker_id = callback_outbox.worker_id
                    WHERE callback_outbox.run_id = ?
                      AND workers.tenant_id = ?
                      AND workers.owner_id = ?
                    ORDER BY callback_outbox.created_at DESC,
                             callback_outbox.callback_id DESC
                    LIMIT ?
                )
                ORDER BY created_at ASC, callback_id ASC
                """,
                (
                    str(run_id),
                    str(tenant_id),
                    str(owner_id),
                    max(1, min(int(limit), 100)),
                ),
            ).fetchall()
        return self._rows(rows)

    def work_trace_detail(
        self,
        *,
        run_id: str,
        tenant_id: str,
        owner_id: str,
        attempt_limit: int = 16,
        capacity_limit: int = 16,
        callback_limit: int = 16,
        artifact_limit: int = 16,
        history_cursor: str | None = None,
    ) -> dict[str, Any] | None:
        attempt_limit = max(1, min(int(attempt_limit), 50))
        capacity_limit = max(1, min(int(capacity_limit), 50))
        callback_limit = max(1, min(int(callback_limit), 50))
        artifact_limit = max(1, min(int(artifact_limit), 50))
        history_offset = 0
        normalized_cursor: str | None = None
        cursor_trace_head = ""
        cursor_trace_count: int | None = None
        cursor_callback_head = ""
        cursor_callback_count: int | None = None
        cursor_attempt_count: int | None = None
        cursor_capacity_count: int | None = None
        cursor_artifact_count: int | None = None
        if history_cursor:
            match = re.fullmatch(
                r"history_([0-9a-f]{64})_([0-9a-f]{1,8})_"
                r"([0-9a-f]{64})_([0-9a-f]{1,8})_([0-9a-f]{1,8})_"
                r"([0-9a-f]{1,8})_([0-9a-f]{1,8})_([0-9a-f]{1,8})",
                str(history_cursor),
            )
            if match is None:
                raise ValueError("Work history cursor is invalid")
            cursor_trace_head = match.group(1)
            cursor_trace_count = int(match.group(2), 16)
            cursor_callback_head = match.group(3)
            cursor_callback_count = int(match.group(4), 16)
            cursor_attempt_count = int(match.group(5), 16)
            cursor_capacity_count = int(match.group(6), 16)
            cursor_artifact_count = int(match.group(7), 16)
            history_offset = int(match.group(8), 16)
            normalized_cursor = str(history_cursor)
        with self._connect() as conn:
            conn.execute("BEGIN DEFERRED")
            scope = conn.execute(
                """
                SELECT runs.run_id
                FROM runs
                JOIN workers ON workers.worker_id = runs.worker_id
                WHERE runs.run_id = ?
                  AND workers.tenant_id = ?
                  AND workers.owner_id = ?
                LIMIT 1
                """,
                (str(run_id), str(tenant_id), str(owner_id)),
            ).fetchone()
            if scope is None:
                return None
            durable_attempt_count = int(
                conn.execute(
                    "SELECT COUNT(*) FROM run_attempts WHERE run_id = ?",
                    (str(run_id),),
                ).fetchone()[0]
            )
            durable_capacity_count = int(
                conn.execute(
                    "SELECT COUNT(*) FROM capacity_attempts WHERE run_id = ?",
                    (str(run_id),),
                ).fetchone()[0]
            )
            durable_callback_count = int(
                conn.execute(
                    "SELECT COUNT(*) FROM callback_outbox WHERE run_id = ?",
                    (str(run_id),),
                ).fetchone()[0]
            )
            trace_rows = conn.execute(
                """
                SELECT * FROM work_trace_events
                WHERE run_id = ? AND tenant_id = ? AND owner_id = ?
                ORDER BY sequence ASC
                """,
                (str(run_id), str(tenant_id), str(owner_id)),
            ).fetchall()
            callback_ledger_rows = conn.execute(
                """
                SELECT callback_trace_events.*
                FROM callback_trace_events
                JOIN callback_outbox
                  ON callback_outbox.callback_id = callback_trace_events.callback_id
                JOIN workers ON workers.worker_id = callback_outbox.worker_id
                WHERE callback_trace_events.run_id = ?
                  AND workers.tenant_id = ?
                  AND workers.owner_id = ?
                ORDER BY callback_trace_events.run_sequence ASC
                """,
                (str(run_id), str(tenant_id), str(owner_id)),
            ).fetchall()

        trace_snapshot_count = (
            len(trace_rows) if cursor_trace_count is None else cursor_trace_count
        )
        callback_snapshot_count = (
            len(callback_ledger_rows)
            if cursor_callback_count is None
            else cursor_callback_count
        )
        if (
            trace_snapshot_count < 1
            or trace_snapshot_count > len(trace_rows)
            or callback_snapshot_count < 0
            or callback_snapshot_count > len(callback_ledger_rows)
        ):
            raise ValueError("Work history cursor is invalid")
        trace_snapshot_head = str(
            trace_rows[trace_snapshot_count - 1]["event_sha256"] or ""
        )
        callback_snapshot_head = (
            str(
                callback_ledger_rows[callback_snapshot_count - 1]["event_sha256"]
                or ""
            )
            if callback_snapshot_count
            else "0" * 64
        )
        if history_cursor and (
            cursor_trace_head != trace_snapshot_head
            or cursor_callback_head != callback_snapshot_head
        ):
            raise ValueError("Work history cursor is invalid")

        origin: dict[str, Any] = {}
        prompt_layers: dict[str, Any] = {}
        trace_contract_version = 1
        provider_attempts: list[dict[str, Any]] = []
        runtime_invocations: list[dict[str, Any]] = []
        provider_authorization_preflights: list[dict[str, Any]] = []
        attempts_by_ref: dict[str, dict[str, Any]] = {}
        capacity_attempts: list[dict[str, Any]] = []
        callbacks_by_ref: dict[str, dict[str, Any]] = {}
        artifact_history: list[dict[str, Any]] = []
        continuity_projections: list[dict[str, Any]] = []
        all_attempt_refs: set[str] = set()
        all_capacity_count = 0
        previous_sha = ""
        for trace_index, row in enumerate(trace_rows, start=1):
            try:
                payload = json.loads(str(row["payload_json"] or "{}"))
            except (TypeError, json.JSONDecodeError) as exc:
                raise RuntimeError("Work trace integrity check failed") from exc
            if not isinstance(payload, dict):
                raise RuntimeError("Work trace integrity check failed")
            expected_sha = self._work_trace_event_sha256(
                trace_event_id=str(row["trace_event_id"]),
                run_id=str(row["run_id"]),
                work_ref=str(row["work_ref"]),
                sequence=int(row["sequence"] or 0),
                event_type=str(row["event_type"]),
                payload=payload,
                previous_event_sha256=str(row["previous_event_sha256"] or ""),
                created_at=str(row["created_at"]),
            )
            if (
                str(row["previous_event_sha256"] or "") != previous_sha
                or str(row["event_sha256"] or "") != expected_sha
            ):
                raise RuntimeError("Work trace integrity check failed")
            previous_sha = expected_sha
            in_snapshot = trace_index <= trace_snapshot_count
            event_type = str(row["event_type"] or "")
            if event_type == "work.origin" and in_snapshot:
                if payload.get("traceContractVersion") == 2:
                    trace_contract_version = 2
                stored_origin = payload.get("origin")
                stored_prompt_layers = payload.get("promptLayers")
                if isinstance(stored_origin, dict):
                    origin = dict(stored_origin)
                if isinstance(stored_prompt_layers, dict):
                    prompt_layers = dict(stored_prompt_layers)
            elif event_type == "continuity.projected" and in_snapshot:
                continuity_projections.append(dict(payload))
            elif event_type == "provider.invoked" and in_snapshot:
                provider_attempts.append(dict(payload))
            elif event_type == "runtime.invoked" and in_snapshot:
                runtime_invocations.append(dict(payload))
            elif event_type == "provider.authorization_preflight" and in_snapshot:
                provider_authorization_preflights.append(dict(payload))
            elif event_type == "lifecycle.attempt":
                attempt_ref = str(payload.get("attemptRef") or "")
                if not attempt_ref.startswith("attempt_sha256:"):
                    raise RuntimeError("Work trace integrity check failed")
                all_attempt_refs.add(attempt_ref)
                attempt_projection = {
                    key: payload.get(key)
                    for key in (
                        "attemptNumber",
                        "state",
                        "claimedAt",
                        "admittedAt",
                        "runtimeInvokedAt",
                        "endedAt",
                        "terminalReason",
                        "providerHealthObservedLastFailedAt",
                        "providerHealthObservedGeneration",
                    )
                }
                if attempt_projection.get("state") == "interrupted":
                    attempt_projection["state"] = "cancelled"
                if in_snapshot:
                    attempts_by_ref[attempt_ref] = attempt_projection
            elif event_type == "capacity.observed":
                all_capacity_count += 1
                if in_snapshot:
                    capacity_attempts.append(dict(payload))
            elif event_type == "callback.delivery":
                callback_ref = str(payload.get("callbackRef") or "")
                if not callback_ref.startswith("callback_sha256:"):
                    raise RuntimeError("Work trace integrity check failed")
                callbacks_by_ref[callback_ref] = dict(payload)
            elif event_type == "artifact.observed":
                refs = payload.get("artifactRefs")
                if not isinstance(refs, dict):
                    raise RuntimeError("Work trace integrity check failed")
                if in_snapshot:
                    artifact_history.append(
                        {
                            "artifactRefs": dict(refs),
                            "observedAt": str(payload.get("observedAt") or ""),
                        }
                    )
        attempts = sorted(
            attempts_by_ref.values(), key=lambda item: int(item.get("attemptNumber") or 0)
        )
        callbacks: list[dict[str, Any]] = []
        verified_snapshots = verified_callback_trace_snapshots(callback_ledger_rows, str(run_id))
        for ledger_index, (row, snapshot) in enumerate(zip(callback_ledger_rows, verified_snapshots, strict=True), start=1):
            callback_id = str(snapshot["callbackId"])
            if ledger_index <= callback_snapshot_count:
                callbacks.append(
                    {
                        "callbackRef": "callback_sha256:"
                        + hashlib.sha256(callback_id.encode("utf-8")).hexdigest(),
                        "callbackRevision": int(row["callback_sequence"] or 0),
                        "ledgerSequence": int(row["run_sequence"] or 0),
                        "previousEventSha256": (
                            "sha256:" + str(row["previous_event_sha256"])
                            if str(row["previous_event_sha256"] or "")
                            else None
                        ),
                        "eventSha256": "sha256:" + str(row["event_sha256"]),
                        "attemptNumber": (
                            int(snapshot["attemptNumber"])
                            if int(snapshot["attemptNumber"] or 0) > 0
                            else None
                        ),
                        "event": str(snapshot["event"] or ""),
                        "status": str(snapshot["status"] or ""),
                        "attempts": int(snapshot["attempts"] or 0),
                        "createdAt": str(snapshot["createdAt"] or ""),
                        "updatedAt": str(snapshot["updatedAt"] or ""),
                        "acceptedAt": str(snapshot["httpAcceptedAt"] or "") or None,
                        "payloadSha256": str(row["payload_sha256"] or ""),
                        "resultRevision": int(snapshot["resultRevision"] or 0),
                        "resultDigest": str(snapshot["resultDigest"] or "") or None,
                        "deliveryGeneration": int(
                            snapshot["deliveryGeneration"] or 0
                        ),
                        "authoritySha256": str(row["authority_sha256"] or ""),
                    }
                )
        if history_cursor and (
            cursor_attempt_count != len(attempts_by_ref)
            or cursor_capacity_count != len(capacity_attempts)
            or cursor_artifact_count != len(artifact_history)
        ):
            raise ValueError("Work history cursor is invalid")

        def history_page(
            values: list[dict[str, Any]], limit: int
        ) -> list[dict[str, Any]]:
            end = max(0, len(values) - history_offset)
            start = max(0, end - limit)
            return values[start:end]

        visible_attempts = history_page(attempts, attempt_limit)
        visible_capacity = history_page(capacity_attempts, capacity_limit)
        visible_callbacks = history_page(callbacks, callback_limit)
        visible_artifacts = history_page(artifact_history, artifact_limit)
        if (
            len(all_attempt_refs) != durable_attempt_count
            or all_capacity_count != durable_capacity_count
            or len(callbacks_by_ref) != durable_callback_count
        ):
            raise RuntimeError("Work trace lifecycle coverage check failed")
        public_origin = {
            "originRef": str(origin.get("originRef") or "") or None,
            "sourceEventRef": str(origin.get("sourceEventRef") or "") or None,
            "sourceRevision": int(origin.get("sourceRevision") or 0),
            "surface": str(origin.get("surface") or "web"),
        }
        traceability: dict[str, Any] = {
            "origin": public_origin,
            "promptLayers": prompt_layers,
            "integrity": {
                "algorithm": "sha256-chain-v1",
                "eventCount": trace_snapshot_count,
                "headSha256": f"sha256:{trace_snapshot_head}",
            },
        }
        if trace_contract_version == 2:
            traceability = {
                "contractVersion": 2,
                "origin": public_origin,
                "promptLayers": prompt_layers,
                "runtimeInvocations": runtime_invocations,
                "providerAuthorizationPreflights": (
                    provider_authorization_preflights
                ),
                "integrity": traceability["integrity"],
            }
        else:
            traceability["providerAttempts"] = provider_attempts
        if continuity_projections:
            traceability["continuityProjections"] = continuity_projections
        totals = (
            len(attempts),
            len(capacity_attempts),
            len(callbacks),
            len(artifact_history),
        )
        visible_counts = (
            len(visible_attempts),
            len(visible_capacity),
            len(visible_callbacks),
            len(visible_artifacts),
        )
        next_offset = history_offset + max(
            attempt_limit, capacity_limit, callback_limit, artifact_limit
        )
        has_older = any(
            total > history_offset + limit
            for total, limit in zip(
                totals,
                (attempt_limit, capacity_limit, callback_limit, artifact_limit),
            )
        )
        snapshot_cursor_prefix = (
            f"history_{trace_snapshot_head}_{trace_snapshot_count:x}_"
            f"{callback_snapshot_head}_{callback_snapshot_count:x}_"
            f"{len(attempts):x}_{len(capacity_attempts):x}_"
            f"{len(artifact_history):x}"
        )
        return {
            "traceability": traceability,
            "attemptHistory": visible_attempts,
            "attemptHistoryOverflowCount": max(0, len(attempts) - len(visible_attempts)),
            "capacityAttempts": visible_capacity,
            "capacityAttemptOverflowCount": max(
                0, len(capacity_attempts) - len(visible_capacity)
            ),
            "callbackDeliveries": visible_callbacks,
            "callbackDeliveryOverflowCount": max(
                0, len(callbacks) - len(visible_callbacks)
            ),
            "artifactHistory": visible_artifacts,
            "artifactHistoryOverflowCount": max(
                0, len(artifact_history) - len(visible_artifacts)
            ),
            "artifactRefs": (
                dict(artifact_history[-1]["artifactRefs"])
                if artifact_history
                else {"available": False, "refs": [], "overflowCount": 0}
            ),
            "historyPage": {
                "cursor": normalized_cursor,
                "nextCursor": (
                    f"{snapshot_cursor_prefix}_{next_offset:x}"
                    if has_older
                    else None
                ),
                "limit": max(
                    attempt_limit, capacity_limit, callback_limit, artifact_limit
                ),
                "total": sum(totals),
                "showing": sum(visible_counts),
                "overflowCount": sum(totals) - sum(visible_counts),
            },
        }

    def admit_claimed_run(
        self,
        run_id: str,
        *,
        lease_id: str,
        executor_id: str,
    ) -> dict[str, Any] | None:
        admitted_at = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            lease = conn.execute(
                """
                SELECT * FROM host_run_leases
                WHERE lease_id = ? AND run_id = ? AND executor_id = ?
                  AND status = 'active' AND expires_at > ?
                """,
                (str(lease_id), str(run_id), str(executor_id), admitted_at),
            ).fetchone()
            attempt_id = (
                str(run["active_attempt_id"] or "") if run is not None else ""
            )
            attempt = (
                conn.execute(
                    "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                    (attempt_id, str(run_id)),
                ).fetchone()
                if attempt_id
                else None
            )
            exact = bool(
                run is not None
                and lease is not None
                and str(run["state"] or "") == "claimed"
                and attempt_id
                and str(lease["attempt_id"] or "") == attempt_id
                and attempt is not None
                and str(attempt["state"] or "") == "claimed"
                and str(attempt["lease_id"] or "") in {"", str(lease_id)}
                and attempt["ended_at"] is None
            )
            if not exact:
                conn.execute("COMMIT")
                return None
            conn.execute(
                """
                UPDATE runs
                SET state = 'admitted', admitted_at = ?
                WHERE run_id = ? AND state = 'claimed' AND active_attempt_id = ?
                """,
                (admitted_at, str(run_id), attempt_id),
            )
            conn.execute(
                """
                UPDATE run_attempts
                SET state = 'admitted', admitted_at = ?, lease_id = ?,
                    capacity_reservation_json = ?
                WHERE attempt_id = ? AND run_id = ? AND state = 'claimed'
                  AND lease_id IN ('', ?) AND ended_at IS NULL
                """,
                (
                    admitted_at,
                    str(lease_id),
                    _capacity_json(
                        {
                            "childProcesses": lease["reserved_child_processes"],
                            "threads": lease["reserved_threads"],
                            "memoryBytes": lease["reserved_memory_bytes"],
                            "diskBytes": lease["reserved_disk_bytes"],
                        }
                    ),
                    attempt_id,
                    str(run_id),
                    str(lease_id),
                ),
            )
            if conn.total_changes < 2:
                conn.execute("ROLLBACK")
                return None
            self._append_attempt_trace_conn(
                conn, attempt_id=attempt_id, created_at=admitted_at
            )
            updated = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            conn.execute("COMMIT")
        return self._row(updated)

    def mark_run_runtime_invoked(
        self,
        run_id: str,
        *,
        lease_id: str,
        executor_id: str,
    ) -> dict[str, Any] | None:
        invoked_at = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            lease = conn.execute(
                """
                SELECT * FROM host_run_leases
                WHERE lease_id = ? AND run_id = ? AND executor_id = ?
                  AND status = 'active' AND expires_at > ?
                """,
                (str(lease_id), str(run_id), str(executor_id), invoked_at),
            ).fetchone()
            if run is None or lease is None:
                conn.execute("COMMIT")
                return None
            attempt_id = str(run["active_attempt_id"] or "")
            attempt = (
                conn.execute(
                    "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
                    (attempt_id, str(run_id)),
                ).fetchone()
                if attempt_id
                else None
            )
            if (
                str(run["state"] or "") == "running"
                and str(run["runtime_invoked_at"] or "")
                and str(lease["attempt_id"] or "") == attempt_id
            ):
                exact_running = self._running_generation_is_exact_conn(
                    conn, str(run_id), now=invoked_at
                )
                conn.execute("COMMIT")
                return self._row(run) if exact_running else None
            exact = bool(
                str(run["state"] or "") == "admitted"
                and attempt_id
                and str(lease["attempt_id"] or "") == attempt_id
                and attempt is not None
                and str(attempt["state"] or "") == "admitted"
                and str(attempt["lease_id"] or "") == str(lease_id)
                and not str(attempt["runtime_invoked_at"] or "")
                and attempt["ended_at"] is None
                and bool(run["queue_wait_open"])
                and str(run["queue_deadline_at"] or "") > invoked_at
            )
            if not exact:
                conn.execute("COMMIT")
                return None
            # The queued Allowed AI snapshot is an immutable admission ceiling.
            # Re-read both scoped revisions inside this same write transaction
            # that turns the run into ``running``. A concurrent policy PUT
            # therefore wins or loses atomically with the native invocation;
            # it cannot slip between a service-side read and this state change.
            raw_allowed_admission = str(run["allowed_ai_admission_json"] or "{}")
            if raw_allowed_admission in {"", "{}"}:
                worker_origin = conn.execute(
                    "SELECT origin_scope_json FROM workers WHERE worker_id = ?",
                    (str(run["worker_id"]),),
                ).fetchone()
                if (
                    str(run["origin_scope_json"] or "{}") not in {"", "{}"}
                    or worker_origin is None
                    or str(worker_origin["origin_scope_json"] or "{}")
                    not in {"", "{}"}
                ):
                    conn.execute("COMMIT")
                    return None
            if raw_allowed_admission not in {"", "{}"}:
                try:
                    allowed_admission = json.loads(raw_allowed_admission)
                except (TypeError, ValueError, json.JSONDecodeError):
                    allowed_admission = None
                if not isinstance(allowed_admission, dict):
                    conn.execute("COMMIT")
                    return None
                project_id = str(run["project_id"] or "")
                tenant_id = str(run["tenant_id"] or "local")
                worker_scope = conn.execute(
                    "SELECT owner_id, project_id, workspace_id, tenant_id "
                    ", origin_scope_json FROM workers WHERE worker_id = ?",
                    (str(run["worker_id"]),),
                ).fetchone()
                if worker_scope is None:
                    conn.execute("COMMIT")
                    return None
                owner_id = str(worker_scope["owner_id"] or "")
                origin_project_id = str(
                    allowed_admission.get("origin_project_id") or ""
                )
                origin_workspace_id = str(
                    allowed_admission.get("origin_workspace_id") or ""
                )
                origin_scope = allowed_admission.get("origin_scope")
                try:
                    worker_origin = json.loads(
                        str(worker_scope["origin_scope_json"] or "{}")
                    )
                except (TypeError, ValueError, json.JSONDecodeError):
                    worker_origin = None
                if not isinstance(worker_origin, dict):
                    conn.execute("COMMIT")
                    return None
                if origin_project_id and (
                    not isinstance(origin_scope, dict)
                    or str(origin_scope.get("project_id") or "") != origin_project_id
                    or str(worker_origin.get("project_id") or "") != origin_project_id
                    or str(worker_origin.get("workspace_id") or "") != origin_workspace_id
                    or str(worker_origin.get("tenant_id") or "local") != tenant_id
                    or str(worker_origin.get("owner_id") or "") != owner_id
                ):
                    conn.execute("COMMIT")
                    return None
                if origin_project_id:
                    origin_project = conn.execute(
                        "SELECT project_id FROM projects WHERE project_id = ? "
                        "AND tenant_id = ? AND owner_id = ?",
                        (origin_project_id, tenant_id, owner_id),
                    ).fetchone()
                    if origin_project is None:
                        conn.execute("COMMIT")
                        return None
                    if origin_workspace_id:
                        origin_workspace = conn.execute(
                            "SELECT workspace_id FROM execution_workspaces "
                            "WHERE workspace_id = ? AND project_id = ? "
                            "AND tenant_id = ? AND owner_id = ?",
                            (
                                origin_workspace_id,
                                origin_project_id,
                                tenant_id,
                                owner_id,
                            ),
                        ).fetchone()
                        if origin_workspace is None:
                            conn.execute("COMMIT")
                            return None
                project_policy = conn.execute(
                    "SELECT revision FROM allowed_ai_policies "
                    "WHERE scope_type = 'project' AND scope_id = ? "
                    "AND tenant_id = ? AND owner_id = ?",
                    (project_id, tenant_id, owner_id),
                ).fetchone()
                workspace_id = str(allowed_admission.get("workspace_id") or "")
                workspace_policy = (
                    conn.execute(
                        "SELECT revision FROM allowed_ai_policies "
                        "WHERE scope_type = 'workspace' AND scope_id = ? "
                        "AND tenant_id = ? AND owner_id = ?",
                        (workspace_id, tenant_id, owner_id),
                    ).fetchone()
                    if workspace_id
                    else None
                )
                origin_project_policy = (
                    conn.execute(
                        "SELECT revision FROM allowed_ai_policies "
                        "WHERE scope_type = 'project' AND scope_id = ? "
                        "AND tenant_id = ? AND owner_id = ?",
                        (origin_project_id, tenant_id, owner_id),
                    ).fetchone()
                    if origin_project_id
                    else None
                )
                origin_workspace_policy = (
                    conn.execute(
                        "SELECT revision FROM allowed_ai_policies "
                        "WHERE scope_type = 'workspace' AND scope_id = ? "
                        "AND tenant_id = ? AND owner_id = ?",
                        (origin_workspace_id, tenant_id, owner_id),
                    ).fetchone()
                    if origin_workspace_id
                    else None
                )
                try:
                    admitted_project_revision = int(
                        allowed_admission.get("project_revision") or 0
                    )
                    admitted_workspace_revision = int(
                        allowed_admission.get("workspace_revision") or 0
                    )
                    admitted_origin_project_revision = int(
                        allowed_admission.get("origin_project_revision") or 0
                    )
                    admitted_origin_workspace_revision = int(
                        allowed_admission.get("origin_workspace_revision") or 0
                    )
                except (TypeError, ValueError):
                    conn.execute("COMMIT")
                    return None
                if (
                    admitted_project_revision
                    != (int(project_policy["revision"]) if project_policy else 0)
                    or admitted_workspace_revision
                    != (int(workspace_policy["revision"]) if workspace_policy else 0)
                    or admitted_origin_project_revision
                    != (
                        int(origin_project_policy["revision"])
                        if origin_project_policy
                        else 0
                    )
                    or admitted_origin_workspace_revision
                    != (
                        int(origin_workspace_policy["revision"])
                        if origin_workspace_policy
                        else 0
                    )
                    or str(allowed_admission.get("project_id") or "") != project_id
                    or str(allowed_admission.get("tenant_id") or "local") != tenant_id
                    or str(allowed_admission.get("owner_id") or "") != owner_id
                    or str(worker_scope["project_id"] or "") != project_id
                    or str(worker_scope["tenant_id"] or "local") != tenant_id
                    or (
                        workspace_id
                        and str(worker_scope["workspace_id"] or "") != workspace_id
                    )
                ):
                    conn.execute("COMMIT")
                    return None
            guard_peer_run(conn, run_id, str(run["worker_id"]), invoked=True)
            guard_coordinator_run(conn, run_id)
            guard_worker_configuration(conn, run_id)
            wait_duration = max(
                0,
                int(
                    (
                        _parse_utc(invoked_at)
                        - _parse_utc(
                            str(run["queue_wait_started_at"] or run["first_queued_at"])
                        )
                    ).total_seconds()
                ),
            )
            attempt_cursor = conn.execute(
                """
                UPDATE run_attempts
                SET state = 'running', runtime_invoked_at = ?
                WHERE attempt_id = ? AND run_id = ? AND state = 'admitted'
                  AND lease_id = ? AND runtime_invoked_at IS NULL
                  AND ended_at IS NULL
                """,
                (invoked_at, attempt_id, str(run_id), str(lease_id)),
            )
            run_cursor = conn.execute(
                """
                UPDATE runs
                SET state = 'running', started_at = COALESCE(started_at, ?),
                    runtime_invoked_at = ?,
                    liveness_started_at = ?, meaningful_progress_at = NULL,
                    meaningful_progress_sequence = 0, internal_retry_count = 0,
                    last_internal_retry_class = '',
                    capacity_retry_count = 0,
                    queue_wait_open = 0, queue_wait_closed_at = ?,
                    queue_wait_duration_seconds = ?, queue_next_status_at = NULL,
                    failure_class = '', failure_retryable = 0,
                    failure_structured = 0, failure_user_message = '',
                    failure_recommended_recovery = '',
                    failure_diagnostic_summary = '', last_retry_class = ''
                WHERE run_id = ? AND state = 'admitted' AND active_attempt_id = ?
                  AND runtime_invoked_at IS NULL
                  AND queue_wait_open = 1 AND queue_deadline_at > ?
                """,
                (
                    invoked_at,
                    invoked_at,
                    invoked_at,
                    invoked_at,
                    wait_duration,
                    str(run_id),
                    attempt_id,
                    invoked_at,
                ),
            )
            if attempt_cursor.rowcount != 1 or run_cursor.rowcount != 1:
                conn.execute("ROLLBACK")
                return None
            updated = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            if updated is None:
                conn.execute("ROLLBACK")
                return None
            self._append_runtime_invocation_trace_conn(
                conn,
                run=updated,
                attempt_id=attempt_id,
                invoked_at=invoked_at,
            )
            self._append_attempt_trace_conn(
                conn, attempt_id=attempt_id, created_at=invoked_at
            )
            conn.execute("COMMIT")
        return self._row(updated)

    @staticmethod
    def _provider_liveness_failure_fields() -> dict[str, object]:
        return {
            "error_text": (
                "The configured provider made no meaningful progress within the "
                "liveness limit. The same workspace and route were preserved."
            ),
            "failure_class": "provider_progress_stalled",
            "failure_retryable": 0,
            "failure_structured": 1,
            "failure_user_message": (
                "This work needs attention because the configured provider stopped "
                "making meaningful progress."
            ),
            "failure_recommended_recovery": (
                "Resume the same work when the configured provider can make progress."
            ),
            "failure_diagnostic_summary": (
                "Provider liveness reached its typed retry or inactivity limit."
            ),
        }

    def _transition_provider_liveness_attention_conn(
        self,
        conn: sqlite3.Connection,
        *,
        run: sqlite3.Row,
        observed_at: str,
        operation_token: str,
    ) -> dict[str, Any] | None:
        run_id = str(run["run_id"] or "")
        attempt_id = str(run["active_attempt_id"] or "")
        if not run_id or not attempt_id or str(run["state"] or "") != "running":
            return None
        attempt = conn.execute(
            "SELECT * FROM run_attempts WHERE attempt_id = ? AND run_id = ?",
            (attempt_id, run_id),
        ).fetchone()
        lease = conn.execute(
            """
            SELECT * FROM host_run_leases
            WHERE run_id = ? AND attempt_id = ? AND status = 'active'
            """,
            (run_id, attempt_id),
        ).fetchone()
        worker = conn.execute(
            "SELECT * FROM workers WHERE worker_id = ?",
            (str(run["worker_id"] or ""),),
        ).fetchone()
        if (
            attempt is None
            or lease is None
            or worker is None
            or str(attempt["state"] or "") != "running"
            or attempt["ended_at"] is not None
            or str(worker["last_run_id"] or "") != run_id
            or str(worker["state"] or "") in {"stopping", "terminated"}
            or str(worker["compute_release_kind"] or "")
            in STOPPING_OPERATION_KINDS
        ):
            return None
        fields = self._provider_liveness_failure_fields()
        run_cursor = conn.execute(
            """
            UPDATE runs
            SET state = 'needs_input', ended_at = NULL, retry_after = NULL,
                error_text = ?, failure_class = ?, failure_retryable = ?,
                failure_structured = ?, failure_user_message = ?,
                failure_recommended_recovery = ?, failure_diagnostic_summary = ?,
                provider_liveness_route_locked = 1
            WHERE run_id = ? AND state = 'running' AND active_attempt_id = ?
            """,
            (
                fields["error_text"],
                fields["failure_class"],
                fields["failure_retryable"],
                fields["failure_structured"],
                fields["failure_user_message"],
                fields["failure_recommended_recovery"],
                fields["failure_diagnostic_summary"],
                run_id,
                attempt_id,
            ),
        )
        if run_cursor.rowcount != 1:
            return None
        attempt_cursor = conn.execute(
            """
            UPDATE run_attempts
            SET state = 'needs_input', ended_at = ?,
                terminal_reason = 'provider_progress_stalled'
            WHERE attempt_id = ? AND run_id = ? AND state = 'running'
              AND ended_at IS NULL
            """,
            (observed_at, attempt_id, run_id),
        )
        lease_cursor = conn.execute(
            """
            UPDATE host_run_leases
            SET status = 'released', released_at = ?,
                release_reason = 'provider_progress_stalled',
                reconciled_at = COALESCE(reconciled_at, ?)
            WHERE lease_id = ? AND run_id = ? AND attempt_id = ?
              AND status = 'active'
            """,
            (observed_at, observed_at, str(lease["lease_id"] or ""), run_id, attempt_id),
        )
        if attempt_cursor.rowcount != 1 or lease_cursor.rowcount != 1:
            raise RuntimeError("Provider liveness generation changed during attention transition")
        worker_cursor = conn.execute(
            """
            UPDATE workers
            SET state = 'needs_input', last_error = ?, last_run_id = ?, updated_at = ?
            WHERE worker_id = ? AND state = ? AND last_run_id = ?
              AND compute_release_kind NOT IN ('max_duration', 'stop_run', 'terminate_worker')
            """,
            (
                fields["error_text"],
                run_id,
                observed_at,
                str(worker["worker_id"] or ""),
                str(worker["state"] or ""),
                run_id,
            ),
        )
        if worker_cursor.rowcount != 1:
            raise RuntimeError("Provider liveness worker ownership changed during attention transition")
        self._append_attempt_trace_conn(
            conn,
            attempt_id=attempt_id,
            created_at=observed_at,
        )
        message = str(fields["failure_user_message"])
        self._insert_lifecycle_event(
            conn,
            operation_token=operation_token,
            operation_epoch=0,
            operation_kind="needs_input",
            worker=worker,
            run_id=run_id,
            event_type="run.needs_input",
            message=message,
            payload={
                "failureCode": "provider_progress_stalled",
                "consecutiveInternalRetries": int(run["internal_retry_count"] or 0),
                "lastMeaningfulProgressAt": str(
                    run["meaningful_progress_at"] or ""
                ),
            },
        )
        self._enqueue_lifecycle_effects(
            conn,
            operation_token=operation_token,
            operation_epoch=0,
            operation_kind="needs_input",
            worker_id=str(worker["worker_id"] or ""),
            run_id=run_id,
            effect_kinds=("callback.run_needs_input",),
        )
        updated = conn.execute(
            "SELECT * FROM runs WHERE run_id = ?", (run_id,)
        ).fetchone()
        return self._row(updated)

    def observe_provider_liveness(
        self,
        *,
        run_id: str,
        expected_attempt_id: str,
        kind: str,
        failure_class: str,
        runtime: str,
        model: str,
        source_sequence: int,
        source_digest: str,
        observed_at: str | None = None,
        retry_limit: int = 3,
    ) -> dict[str, Any] | None:
        clean_kind = str(kind or "").strip().lower()
        if clean_kind not in {"meaningful_progress", "internal_retry"}:
            raise ValueError("Provider liveness kind is invalid")
        clean_failure_class = str(failure_class or "").strip().lower()
        retry_classes = {
            "provider_internal_retry",
            "provider_rate_limited",
            "provider_response_failed",
            "provider_unavailable",
            "provider_upstream_unavailable",
        }
        if clean_kind == "internal_retry" and clean_failure_class not in retry_classes:
            raise ValueError("Provider liveness retry class is invalid")
        if clean_kind == "meaningful_progress" and clean_failure_class:
            raise ValueError("Provider progress cannot carry a failure class")
        clean_source_sequence = int(source_sequence)
        if clean_source_sequence < 1:
            raise ValueError("Provider liveness source sequence is invalid")
        clean_source_digest = str(source_digest or "").strip().lower()
        if not re.fullmatch(r"[0-9a-f]{64}", clean_source_digest):
            raise ValueError("Provider liveness source digest is invalid")
        clean_runtime = str(runtime or "").strip()
        clean_model = str(model or "").strip()
        if not clean_runtime or not clean_model:
            raise ValueError("Provider liveness route is incomplete")
        observed = str(observed_at or utc_now())
        _parse_utc(observed)
        retry_limit = max(1, min(int(retry_limit), 100))

        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            worker = (
                conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (run["worker_id"],)
                ).fetchone()
                if run is not None
                else None
            )
            if run is None or worker is None:
                conn.execute("COMMIT")
                return None
            expected_runtime = str(
                run["provider_route_runtime"] or worker["runtime"] or ""
            ).strip()
            expected_model = str(
                run["provider_route_model"] or worker["model"] or ""
            ).strip()
            attempt_id = str(run["active_attempt_id"] or "")
            exact = bool(
                str(run["state"] or "") == "running"
                and attempt_id == str(expected_attempt_id or "")
                and clean_runtime == expected_runtime
                and clean_model == expected_model
                and str(worker["state"] or "") not in {"stopping", "terminated"}
                and str(worker["compute_release_kind"] or "")
                not in STOPPING_OPERATION_KINDS
                and conn.execute(
                    """
                    SELECT 1 FROM run_attempts
                    WHERE attempt_id = ? AND run_id = ? AND state = 'running'
                      AND ended_at IS NULL
                    """,
                    (attempt_id, str(run_id)),
                ).fetchone()
                is not None
                and conn.execute(
                    """
                    SELECT 1 FROM host_run_leases
                    WHERE run_id = ? AND attempt_id = ? AND status = 'active'
                      AND expires_at > ?
                    """,
                    (str(run_id), attempt_id, utc_now()),
                ).fetchone()
                is not None
            )
            if not exact:
                conn.execute("COMMIT")
                return None
            clean_event_ref = "provider_liveness_sha256:" + hashlib.sha256(
                json.dumps(
                    {
                        "attemptId": attempt_id,
                        "model": clean_model,
                        "runId": str(run_id),
                        "runtime": clean_runtime,
                        "sourceDigest": clean_source_digest,
                        "sourceSequence": clean_source_sequence,
                    },
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            existing = conn.execute(
                "SELECT * FROM provider_liveness_events WHERE event_ref = ?",
                (clean_event_ref,),
            ).fetchone()
            if existing is not None:
                if (
                    str(existing["run_id"] or "") != str(run_id)
                    or str(existing["attempt_id"] or "") != attempt_id
                    or str(existing["kind"] or "") != clean_kind
                    or str(existing["failure_class"] or "")
                    != clean_failure_class
                    or str(existing["runtime"] or "") != clean_runtime
                    or str(existing["model"] or "") != clean_model
                    or int(existing["source_sequence"] or 0)
                    != clean_source_sequence
                    or str(existing["source_digest"] or "")
                    != clean_source_digest
                ):
                    conn.execute("ROLLBACK")
                    raise ValueError("Provider liveness event reference conflicts")
                current = self._row(run) or {}
                current["_inserted"] = False
                current["_applied"] = False
                current["_attention_transitioned"] = False
                conn.execute("COMMIT")
                return current
            source_collision = conn.execute(
                """
                SELECT * FROM provider_liveness_events
                WHERE run_id = ? AND attempt_id = ? AND source_sequence = ?
                """,
                (str(run_id), attempt_id, clean_source_sequence),
            ).fetchone()
            if source_collision is not None:
                conn.execute("ROLLBACK")
                raise ValueError("Provider liveness source sequence conflicts")
            previous_observed = conn.execute(
                """
                SELECT source_sequence FROM provider_liveness_events
                WHERE run_id = ? AND attempt_id = ?
                ORDER BY source_sequence DESC, event_ref DESC LIMIT 1
                """,
                (str(run_id), attempt_id),
            ).fetchone()
            conn.execute(
                """
                INSERT INTO provider_liveness_events (
                    event_ref, run_id, attempt_id, kind, failure_class,
                    runtime, model, source_sequence, source_digest,
                    observed_at, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    clean_event_ref,
                    str(run_id),
                    attempt_id,
                    clean_kind,
                    clean_failure_class,
                    clean_runtime,
                    clean_model,
                    clean_source_sequence,
                    clean_source_digest,
                    observed,
                    utc_now(),
                ),
            )
            applies = bool(
                previous_observed is None
                or clean_source_sequence
                > int(previous_observed["source_sequence"] or 0)
            )
            if applies and clean_kind == "meaningful_progress":
                conn.execute(
                    """
                    UPDATE runs
                    SET meaningful_progress_at = ?,
                        meaningful_progress_sequence = meaningful_progress_sequence + 1,
                        internal_retry_count = 0, last_internal_retry_class = ''
                    WHERE run_id = ? AND state = 'running' AND active_attempt_id = ?
                    """,
                    (observed, str(run_id), attempt_id),
                )
            elif applies:
                conn.execute(
                    """
                    UPDATE runs
                    SET internal_retry_count = internal_retry_count + 1,
                        last_internal_retry_class = ?
                    WHERE run_id = ? AND state = 'running' AND active_attempt_id = ?
                    """,
                    (clean_failure_class, str(run_id), attempt_id),
                )
            current_row = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            transitioned = None
            if (
                applies
                and clean_kind == "internal_retry"
                and current_row is not None
                and int(current_row["internal_retry_count"] or 0) >= retry_limit
            ):
                transitioned = self._transition_provider_liveness_attention_conn(
                    conn,
                    run=current_row,
                    observed_at=observed,
                    operation_token=clean_event_ref,
                )
            current = transitioned or self._row(current_row) or {}
            current["_inserted"] = True
            current["_applied"] = applies
            current["_attention_transitioned"] = transitioned is not None
            conn.execute("COMMIT")
        return current

    def transition_stalled_provider_liveness_runs(
        self,
        *,
        now: str | None = None,
        inactivity_seconds: float = 900.0,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        observed = str(now or utc_now())
        observed_time = _parse_utc(observed)
        inactivity_seconds = max(0.1, min(float(inactivity_seconds), 30 * 24 * 3600.0))
        limit = max(1, min(int(limit), 1000))
        transitioned: list[dict[str, Any]] = []
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = conn.execute(
                """
                SELECT * FROM runs
                WHERE state = 'running'
                  AND COALESCE(
                        meaningful_progress_at, liveness_started_at, runtime_invoked_at
                      ) IS NOT NULL
                ORDER BY COALESCE(
                    meaningful_progress_at, liveness_started_at, runtime_invoked_at
                ) ASC, run_id ASC
                LIMIT ?
                """,
                (limit,),
            ).fetchall()
            for run in rows:
                anchor = str(
                    run["meaningful_progress_at"]
                    or run["liveness_started_at"]
                    or run["runtime_invoked_at"]
                    or ""
                )
                if not anchor or (
                    observed_time - _parse_utc(anchor)
                ).total_seconds() < inactivity_seconds:
                    continue
                attempt_id = str(run["active_attempt_id"] or "")
                event_ref = "provider_liveness_timeout_sha256:" + hashlib.sha256(
                    f"{run['run_id']}:{attempt_id}:{anchor}:{inactivity_seconds:g}".encode()
                ).hexdigest()
                worker = conn.execute(
                    "SELECT * FROM workers WHERE worker_id = ?", (run["worker_id"],)
                ).fetchone()
                if worker is None:
                    continue
                runtime = str(
                    run["provider_route_runtime"] or worker["runtime"] or ""
                )
                model = str(run["provider_route_model"] or worker["model"] or "")
                updated = self._transition_provider_liveness_attention_conn(
                    conn,
                    run=run,
                    observed_at=observed,
                    operation_token=event_ref,
                )
                if updated is not None:
                    conn.execute(
                        """
                        INSERT OR IGNORE INTO provider_liveness_events (
                            event_ref, run_id, attempt_id, kind, failure_class,
                            runtime, model, source_sequence, source_digest,
                            observed_at, created_at
                        ) VALUES (?, ?, ?, 'inactivity_timeout',
                                  'provider_progress_stalled', ?, ?, 0, ?, ?, ?)
                        """,
                        (
                            event_ref,
                            str(run["run_id"]),
                            attempt_id,
                            runtime,
                            model,
                            hashlib.sha256(event_ref.encode("utf-8")).hexdigest(),
                            observed,
                            utc_now(),
                        ),
                    )
                    updated["_attention_transitioned"] = True
                    transitioned.append(updated)
            conn.execute("COMMIT")
        return transitioned

    def list_provider_liveness_events(self, run_id: str) -> list[dict[str, Any]]:
        with self._connect() as conn:
            rows = conn.execute(
                """
                SELECT * FROM provider_liveness_events
                WHERE run_id = ? ORDER BY observed_at ASC, event_ref ASC
                """,
                (str(run_id),),
            ).fetchall()
        return self._rows(rows)

    def clear_run_wait_episode(self, run_id: str) -> dict[str, Any] | None:
        """Reset retry-transition evidence only when execution is truly starting.

        Queue ownership can be claimed before host lease, capacity, and broker
        admission checks finish.  Those checks remain part of one contiguous
        wait episode; clearing at claim time would republish the same user
        transition on every scheduler probe.
        """

        lease = self.get_active_host_run_lease_for_run(str(run_id))
        if not lease:
            return None
        return self.mark_run_runtime_invoked(
            str(run_id),
            lease_id=str(lease.get("lease_id") or ""),
            executor_id=str(lease.get("executor_id") or ""),
        )

















    def rebind_schedule_run(
        self,
        source_run_id: str,
        replacement_run_id: str,
    ) -> dict[str, Any] | None:
        with self._connect() as conn:
            conn.execute(
                """
                UPDATE scheduled_runs
                SET queued_run_id = ?, state = 'queued', last_error = '', updated_at = ?
                WHERE queued_run_id = ? AND state = 'needs_input'
                """,
                (replacement_run_id, utc_now(), source_run_id),
            )
            row = conn.execute(
                "SELECT * FROM scheduled_runs WHERE queued_run_id = ?",
                (replacement_run_id,),
            ).fetchone()
        return self._row(row)



    def insert_terminal_callback_outbox_if_current(
        self,
        *,
        callback_id: str,
        project_id: str,
        worker_id: str,
        run_id: str,
        attempt_number: int | None,
        event_type: str,
        url: str,
        payload_json: str,
        expected_state: str,
        expected_ended_at: str,
        expected_attempt_id: str,
        expected_result_revision: int,
        expected_result_digest: str,
    ) -> dict[str, Any] | None:
        """Insert one terminal sink only for the exact durable run generation."""

        clean_state = str(expected_state or "").strip()
        clean_ended_at = str(expected_ended_at or "").strip()
        clean_attempt_number = max(0, int(attempt_number or 0))
        clean_result_revision = max(0, int(expected_result_revision or 0))
        clean_result_digest = str(expected_result_digest or "").strip()
        result_state = _terminal_callback_wire_state(clean_state, event_type)
        if (
            clean_state not in TERMINAL_RUN_STATES
            or not result_state
            or not clean_ended_at
        ):
            raise ValueError("Terminal callback requires an exact terminal generation")
        if re.fullmatch(r"sha256:[0-9a-f]{64}", clean_result_digest) is None:
            raise ValueError("Terminal callback requires an exact result digest")
        if clean_result_revision < 1:
            raise ValueError("Terminal callback requires a positive result revision")
        deterministic_id = _terminal_callback_id(
            run_id=str(run_id),
            state=result_state,
            ended_at=clean_ended_at,
            attempt_number=clean_attempt_number,
            result_revision=clean_result_revision,
            result_digest=clean_result_digest,
        )
        if str(callback_id or "") != deterministic_id:
            raise ValueError("Terminal callback identity is not deterministic")
        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            run = conn.execute(
                "SELECT * FROM runs WHERE run_id = ?", (str(run_id),)
            ).fetchone()
            if (
                run is None
                or str(run["project_id"] or "") != str(project_id or "")
                or str(run["worker_id"] or "") != str(worker_id or "")
                or str(run["state"] or "") != clean_state
                or str(run["ended_at"] or "") != clean_ended_at
                or str(run["active_attempt_id"] or "")
                != str(expected_attempt_id or "")
                or self._callback_attempt_number_conn(conn, str(run_id))
                != clean_attempt_number
                or int(run["terminal_result_revision"] or 0)
                != clean_result_revision
                or _terminal_result_digest(run) != clean_result_digest
            ):
                conn.execute("COMMIT")
                return None
            existing = conn.execute(
                "SELECT 1 FROM callback_outbox WHERE callback_id = ?",
                (deterministic_id,),
            ).fetchone()
            row = self._insert_callback_intent_conn(
                conn,
                {
                    "callback_id": deterministic_id,
                    "project_id": str(project_id),
                    "worker_id": str(worker_id),
                    "tenant_id": str(run["tenant_id"] or "local"),
                    "run_id": str(run_id),
                    "attempt_number": (
                        clean_attempt_number if clean_attempt_number > 0 else None
                    ),
                    "event_type": str(event_type),
                    "url": str(url),
                    "payload_json": str(payload_json),
                    "result_revision": clean_result_revision,
                    "result_digest": clean_result_digest,
                },
                now=now,
            )
            conn.execute("COMMIT")
        return {**dict(row), "_inserted": existing is None}











    def mark_callback_receiver_superseded(
        self,
        callback_id: str,
        *,
        lease_token: str,
        delivery_generation: int,
        attempts: int,
        current_result_revision: int,
    ) -> dict[str, Any] | None:
        """Settle an exact delivery when the receiver already owns newer truth."""

        now = utc_now()
        with self._connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            current = conn.execute(
                """
                SELECT * FROM callback_outbox
                WHERE callback_id = ? AND status = 'delivering'
                  AND delivery_lease_token = ? AND delivery_generation = ?
                """,
                (
                    str(callback_id),
                    str(lease_token),
                    int(delivery_generation),
                ),
            ).fetchone()
            if (
                current is None
                or not str(current["callback_id"] or "").startswith(
                    "cb_terminal_"
                )
                or int(current_result_revision) <= int(
                    current["result_revision"] or 0
                )
            ):
                conn.execute("COMMIT")
                return None
            row = self._supersede_terminal_callback_conn(
                conn,
                current,
                now=now,
                reason="receiver_result_superseded",
                attempts=attempts,
            )
            conn.execute("COMMIT")
        return self._row(row)

    def accept_cancel_actions_for_run(self, run_id: str) -> int:
        with self._connect() as conn:
            cur = conn.execute(
                """
                UPDATE run_action_uses
                SET status = 'accepted',
                    result_code = 'cancellation_confirmed',
                    updated_at = ?
                WHERE source_run_id = ?
                  AND action = 'cancel'
                  AND status IN ('reserved', 'executing')
                """,
                (utc_now(), run_id),
            )
        return cur.rowcount
